#[derive(Clone, Debug, Deserialize)]
pub struct GifRequest {
    #[serde(default)]
    pub temporal_stability: bool,
    #[serde(default)]
    pub lzw_search: bool,
    #[serde(default)]
    pub smart_lossless: bool,
    #[serde(default)]
    pub smaller_gif: bool,
    #[serde(default)]
    pub index_compression: bool,
    #[serde(default)]
    pub index_compression_gentle: bool,
    #[serde(default)]
    pub gif_merge_frames: bool,
    #[serde(default)]
    pub gif_compact_palette: bool,
    #[serde(default = "default_encode_request_schema_version")]
    pub schema_version: u16,
    #[serde(default)]
    pub task_id: Option<String>,
    pub input_path: String,
    pub output_dir: String,
    pub width: u32,
    pub fps: u32,
    pub colors: u16,
    pub dither: String,
    pub optimize_level: u8,
    pub lossy: u8,
    pub start_seconds: f64,
    pub end_seconds: f64,
    pub encoder: String,
    pub filter_style: String,
    pub loop_output: bool,
    pub crop_enabled: bool,
    pub crop_left: f64,
    pub crop_top: f64,
    pub crop_right: f64,
    pub crop_bottom: f64,
    pub deleted_frames: Vec<f64>,
    #[serde(default)]
    pub deleted_ranges: Vec<DeletedTimelineRange>,
    #[serde(default = "default_frame_timing_mode")]
    pub frame_timing_mode: String,
    #[serde(default = "default_playback_speed")]
    pub playback_speed: f64,
    #[serde(default = "default_output_format")]
    pub output_format: String,
    #[serde(default = "default_generation_mode")]
    pub generation_mode: String,
    #[serde(default)]
    pub target_size_bytes: Option<u64>,
    #[serde(default = "default_target_tolerance_percent")]
    pub target_tolerance_percent: f64,
    #[serde(default = "default_target_max_attempts")]
    pub target_max_attempts: u8,
    #[serde(default = "default_target_preference")]
    pub target_preference: String,
    #[serde(default = "default_target_constraint")]
    pub target_constraint: String,
    #[serde(default)]
    pub fast_baseline_size_bytes: Option<u64>,
    #[serde(default = "default_bayer_scale")]
    pub bayer_scale: u8,
    #[serde(default = "default_alpha_threshold")]
    pub alpha_threshold: u8,
    #[serde(default)]
    pub allow_experimental: bool,
    #[serde(default = "default_perceptual_focus")]
    pub perceptual_focus: String,
    #[serde(default)]
    pub meme_overlay: Option<MemeOverlayRequest>,
    #[serde(default)]
    pub background_removal: Option<BackgroundRemovalRequest>,
    #[serde(default)]
    pub tracked_effects: Vec<TrackedEffectRequest>,
    #[serde(skip)]
    tracked_overlay_ass_path: Option<String>,
    #[serde(skip)]
    tracked_canvas_aspect: Option<f64>,
    #[serde(skip)]
    perceptual_selection: Option<PerceptualSelection>,
    // A Best-mode-only alternate for animated, opaque 256-color exports.
    // It is deliberately kept outside `PerceptualSelection`: the normal
    // selection must continue to describe the encoded transparent-delta
    // baseline until a real serialized rate--distortion comparison promotes
    // this full opaque palette.
    #[serde(skip)]
    perceptual_opaque_palette_candidate: Option<OklabPaletteArtifact>,
}

