impl From<&QuantizationMetrics> for QuantizationMetricsReport {
    fn from(metrics: &QuantizationMetrics) -> Self {
        Self {
            sampled_pixel_count: metrics.sampled_pixel_count,
            sampled_static_pixel_count: metrics.sampled_static_pixel_count,
            mean_oklab_error: metrics.mean_oklab_error,
            p95_oklab_error: metrics.p95_oklab_error,
            edge_weighted_mean_oklab_error: metrics.edge_weighted_mean_oklab_error,
            multiscale_low_frequency_oklab_error: metrics.multiscale_low_frequency_oklab_error,
            multiscale_banding_score: metrics.multiscale_banding_score,
            edge_gradient_error: metrics.edge_gradient_error,
            static_temporal_residual: metrics.static_temporal_residual,
            multiscale_static_temporal_residual: metrics.multiscale_static_temporal_residual,
        }
    }
}

