#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum BestDeliveryGateProfile {
    TextUi,
    SmoothGradient,
    Noisy,
    Static,
    Subject,
    General,
}

impl BestDeliveryGateProfile {
    const fn as_str(self) -> &'static str {
        match self {
            Self::TextUi => "text_ui",
            Self::SmoothGradient => "smooth_gradient",
            Self::Noisy => "noisy",
            Self::Static => "static",
            Self::Subject => "subject",
            Self::General => "general",
        }
    }
}

