#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RustWriterRouteMetadata {
    segment_encoded: bool,
    encoder_used: &'static str,
    palette_strategy: &'static str,
}

fn rust_writer_route_metadata(report: &IndexedGifWriterReport) -> RustWriterRouteMetadata {
    let segment_encoded = report
        .segment_palette_report
        .as_ref()
        .is_some_and(|segment| segment.status == "encoded");
    let regional_encoded = report
        .regional_quantizer_report
        .as_ref()
        .is_some_and(|quantizer| quantizer.status == "encoded");
    let temporal_encoded = report
        .regional_quantizer_report
        .as_ref()
        .is_some_and(|quantizer| {
            quantizer.status == "encoded" && quantizer.selected_route_id == "temporal_hysteresis"
        });
    let phase_locked_pair_encoded =
        report
            .regional_quantizer_report
            .as_ref()
            .is_some_and(|quantizer| {
                quantizer.status == "encoded"
                    && quantizer.selected_route_id == "phase_locked_pair_temporal"
            });
    let error_diffusion_encoded =
        report
            .regional_quantizer_report
            .as_ref()
            .is_some_and(|quantizer| {
                quantizer.status == "encoded"
                    && quantizer.selected_route_id == "error_diffusion_temporal"
            });
    let (encoder_used, palette_strategy) = if segment_encoded {
        (
            "rust_indexed_gif_segment_palette",
            "perceptual_vfr+oklab_segment_local+rust_regional+rust_writer",
        )
    } else if phase_locked_pair_encoded {
        (
            "rust_indexed_gif_phase_locked_pair",
            "perceptual_vfr+oklab_global+rust_phase_locked_pair_temporal+rust_writer",
        )
    } else if error_diffusion_encoded {
        (
            "rust_indexed_gif_error_diffusion",
            "perceptual_vfr+oklab_global+rust_error_diffusion_temporal+rust_writer",
        )
    } else if temporal_encoded {
        (
            "rust_indexed_gif_temporal_quantizer",
            "perceptual_vfr+oklab_global+rust_temporal+rust_writer",
        )
    } else if regional_encoded {
        (
            "rust_indexed_gif_regional_quantizer",
            "perceptual_vfr+oklab_global+rust_regional+rust_writer",
        )
    } else {
        (
            "rust_indexed_gif_ffmpeg_mapper",
            "perceptual_vfr+oklab_global+ffmpeg_map+rust_writer",
        )
    };
    RustWriterRouteMetadata {
        segment_encoded,
        encoder_used,
        palette_strategy,
    }
}

