#[cfg(windows)]
#[derive(Debug)]
struct KillOnCloseJob {
    handle: windows_sys::Win32::Foundation::HANDLE,
}

#[cfg(windows)]
unsafe impl Send for KillOnCloseJob {}
#[cfg(windows)]
unsafe impl Sync for KillOnCloseJob {}

#[cfg(windows)]
impl KillOnCloseJob {
    fn attach(child: &Child) -> io::Result<Self> {
        use std::os::windows::io::AsRawHandle;
        Self::attach_process(child.as_raw_handle() as windows_sys::Win32::Foundation::HANDLE)
    }

    fn attach_current_process() -> io::Result<Self> {
        Self::attach_process(unsafe { windows_sys::Win32::System::Threading::GetCurrentProcess() })
    }

    fn attach_process(process: windows_sys::Win32::Foundation::HANDLE) -> io::Result<Self> {
        use std::mem::size_of;
        use windows_sys::Win32::Foundation::{CloseHandle, INVALID_HANDLE_VALUE};
        use windows_sys::Win32::System::JobObjects::{
            AssignProcessToJobObject, CreateJobObjectW, JobObjectExtendedLimitInformation,
            SetInformationJobObject, JOBOBJECT_EXTENDED_LIMIT_INFORMATION,
            JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
        };

        let handle = unsafe { CreateJobObjectW(std::ptr::null(), std::ptr::null()) };
        if handle.is_null() || handle == INVALID_HANDLE_VALUE {
            return Err(io::Error::last_os_error());
        }

        let mut information = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        information.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        let configured = unsafe {
            SetInformationJobObject(
                handle,
                JobObjectExtendedLimitInformation,
                std::ptr::addr_of!(information).cast(),
                size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
            )
        };
        if configured == 0 {
            let error = io::Error::last_os_error();
            unsafe {
                CloseHandle(handle);
            }
            return Err(error);
        }

        let assigned = unsafe { AssignProcessToJobObject(handle, process) };
        if assigned == 0 {
            let error = io::Error::last_os_error();
            unsafe {
                CloseHandle(handle);
            }
            return Err(error);
        }
        Ok(Self { handle })
    }

    #[cfg(test)]
    fn contains(&self, child: &Child) -> io::Result<bool> {
        use std::os::windows::io::AsRawHandle;
        use windows_sys::Win32::System::JobObjects::IsProcessInJob;

        let mut result = 0;
        let succeeded = unsafe {
            IsProcessInJob(
                child.as_raw_handle() as windows_sys::Win32::Foundation::HANDLE,
                self.handle,
                &mut result,
            )
        };
        if succeeded == 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(result != 0)
    }
}

#[cfg(windows)]
impl Drop for KillOnCloseJob {
    fn drop(&mut self) {
        if !self.handle.is_null() {
            unsafe {
                windows_sys::Win32::Foundation::CloseHandle(self.handle);
            }
            self.handle = std::ptr::null_mut();
        }
    }
}

#[cfg(not(windows))]
#[derive(Debug)]
struct KillOnCloseJob;

#[cfg(not(windows))]
impl KillOnCloseJob {
    fn attach(_child: &Child) -> io::Result<Self> {
        Ok(Self)
    }
}

#[derive(Debug)]
struct OwnedTempDir {
    path: PathBuf,
    required_prefix: String,
    armed: bool,
}

impl OwnedTempDir {
    fn create(prefix: &'static str) -> Result<Self, AppError> {
        Ok(Self {
            path: create_unique_temp_dir(prefix)?,
            required_prefix: format!("{prefix}-"),
            armed: true,
        })
    }

    fn adopt(path: PathBuf, required_prefix: &str) -> Self {
        Self {
            path,
            required_prefix: required_prefix.to_string(),
            armed: true,
        }
    }

    fn path(&self) -> &Path {
        &self.path
    }

    fn into_path(mut self) -> PathBuf {
        self.armed = false;
        std::mem::take(&mut self.path)
    }

    fn cleanup(mut self) -> io::Result<()> {
        let result = remove_owned_temp_dir(&self.path, &self.required_prefix);
        if result.is_ok() {
            self.armed = false;
        }
        result
    }
}

impl Drop for OwnedTempDir {
    fn drop(&mut self) {
        if self.armed {
            let _ = remove_owned_temp_dir(&self.path, &self.required_prefix);
        }
    }
}

/// A same-volume staging directory used for multi-file outputs. Unlike
/// `OwnedTempDir`, this directory lives beside the final output so the last
/// rename publishes the whole resource pair atomically.
#[derive(Debug)]
struct OwnedPublishDir {
    path: PathBuf,
    parent: PathBuf,
    required_prefix: String,
    armed: bool,
}

impl OwnedPublishDir {
    fn create(parent: &Path, prefix: &str) -> Result<Self, AppError> {
        if prefix.is_empty()
            || prefix == "."
            || prefix == ".."
            || prefix.chars().any(|value| value == '/' || value == '\\')
        {
            return Err(AppError::Internal(format!(
                "Refusing unsafe paired-output staging prefix {prefix:?}"
            )));
        }
        cleanup_stale_publish_dirs_once(parent, prefix);
        for _ in 0..64 {
            let name = format!("{prefix}{}", unique_output_token());
            let path = parent.join(name);
            match fs::create_dir(&path) {
                Ok(()) => {
                    return Ok(Self {
                        path,
                        parent: parent.to_path_buf(),
                        required_prefix: prefix.to_string(),
                        armed: true,
                    });
                }
                Err(error) if error.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(error) => {
                    return Err(AppError::Internal(format!(
                        "Create paired-output staging directory {}: {error}",
                        path.display()
                    )))
                }
            }
        }
        Err(AppError::Internal(
            "Could not allocate a paired-output staging directory after 64 attempts".to_string(),
        ))
    }

    fn path(&self) -> &Path {
        &self.path
    }

    fn publish(mut self, final_path: &Path) -> Result<(), AppError> {
        if final_path.parent() != Some(self.parent.as_path()) {
            return Err(AppError::Internal(format!(
                "Refusing to publish paired output outside its staging parent: {}",
                final_path.display()
            )));
        }
        finish_final_directory_publish(&self.path, final_path).map_err(|error| {
            let error = if error.kind() == io::ErrorKind::AlreadyExists || final_path.exists() {
                io::Error::new(
                    io::ErrorKind::AlreadyExists,
                    format!(
                        "refusing to overwrite existing paired output {}",
                        final_path.display()
                    ),
                )
            } else {
                error
            };
            AppError::Internal(format!(
                "Publish paired output {} atomically: {error}",
                final_path.display()
            ))
        })?;
        self.armed = false;
        Ok(())
    }

    fn cleanup_path(&self) -> io::Result<()> {
        remove_owned_publish_dir(&self.path, &self.parent, &self.required_prefix)
    }
}

impl Drop for OwnedPublishDir {
    fn drop(&mut self) {
        if self.armed {
            let _ = self.cleanup_path();
        }
    }
}

