struct ActiveConversionGuard;

#[derive(Debug)]
struct ConversionTaskState {
    id: String,
    cancelled: AtomicBool,
    phase: Mutex<ConversionTaskPhase>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ConversionTaskPhase {
    Running,
    Cancelled,
    Committing,
    Finished,
}

struct ConversionTaskScope {
    state: Option<Arc<ConversionTaskState>>,
}

impl ConversionTaskScope {
    fn register(task_id: Option<&str>) -> Result<Self, AppError> {
        let Some(task_id) = task_id.map(str::trim).filter(|value| !value.is_empty()) else {
            return Ok(Self { state: None });
        };
        if task_id.len() > 160 {
            return Err(AppError::InvalidInput(
                "Conversion task id exceeds 160 characters".to_string(),
            ));
        }
        if !task_id.bytes().all(|value| {
            value.is_ascii_alphanumeric() || matches!(value, b'.' | b'_' | b':' | b'-')
        }) {
            return Err(AppError::InvalidInput(
                "Conversion task id contains unsupported characters".to_string(),
            ));
        }
        let state = Arc::new(ConversionTaskState {
            id: task_id.to_string(),
            cancelled: AtomicBool::new(false),
            phase: Mutex::new(ConversionTaskPhase::Running),
        });
        let mut tasks = CONVERSION_TASKS
            .get_or_init(|| Mutex::new(HashMap::new()))
            .lock()
            .map_err(|_| AppError::Internal("Conversion task registry is poisoned".to_string()))?;
        if tasks.contains_key(task_id) {
            return Err(AppError::InvalidInput(format!(
                "Conversion task id is already active: {task_id}"
            )));
        }
        tasks.insert(task_id.to_string(), Arc::clone(&state));
        Ok(Self { state: Some(state) })
    }

    fn activate(&self) {
        CURRENT_CONVERSION_TASK.with(|slot| *slot.borrow_mut() = self.state.clone());
    }
}

impl Drop for ConversionTaskScope {
    fn drop(&mut self) {
        CURRENT_CONVERSION_TASK.with(|slot| *slot.borrow_mut() = None);
        let Some(state) = self.state.as_ref() else {
            return;
        };
        if let Ok(mut tasks) = CONVERSION_TASKS
            .get_or_init(|| Mutex::new(HashMap::new()))
            .lock()
        {
            if tasks
                .get(&state.id)
                .is_some_and(|registered| Arc::ptr_eq(registered, state))
            {
                tasks.remove(&state.id);
            }
        }
    }
}

fn current_conversion_task() -> Option<Arc<ConversionTaskState>> {
    CURRENT_CONVERSION_TASK.with(|slot| slot.borrow().clone())
}

fn check_conversion_cancelled() -> Result<(), AppError> {
    if let Some(state) = current_conversion_task() {
        if state.cancelled.load(Ordering::Acquire) {
            return Err(AppError::Cancelled(state.id.clone()));
        }
    }
    Ok(())
}

fn cancelled_command_error(task_id: &str) -> io::Error {
    io::Error::new(
        io::ErrorKind::Interrupted,
        format!("GIFP_TASK_CANCELLED:{task_id}"),
    )
}

pub(crate) trait ConversionCommandExt {
    fn output_for_conversion_task(&mut self) -> io::Result<Output>;
}

impl ConversionCommandExt for Command {
    fn output_for_conversion_task(&mut self) -> io::Result<Output> {
        let Some(task) = current_conversion_task() else {
            return Command::output(self);
        };
        if task.cancelled.load(Ordering::Acquire) {
            return Err(cancelled_command_error(&task.id));
        }

        self.stdout(Stdio::piped()).stderr(Stdio::piped());
        let mut child = self.spawn()?;
        // FFmpeg occasionally delegates work to helper processes. On Windows,
        // closing this job handle terminates the complete descendant tree.
        let process_tree_job = match KillOnCloseJob::attach(&child) {
            Ok(job) => job,
            Err(error) => {
                let _ = child.kill();
                let _ = child.wait();
                return Err(io::Error::other(format!(
                    "Could not attach conversion process cleanup job: {error}"
                )));
            }
        };
        let mut stdout = child.stdout.take();
        let mut stderr = child.stderr.take();
        let stdout_reader = std::thread::spawn(move || {
            let mut bytes = Vec::new();
            if let Some(stream) = stdout.as_mut() {
                stream.read_to_end(&mut bytes)?;
            }
            Ok::<Vec<u8>, io::Error>(bytes)
        });
        let stderr_reader = std::thread::spawn(move || {
            let mut bytes = Vec::new();
            if let Some(stream) = stderr.as_mut() {
                stream.read_to_end(&mut bytes)?;
            }
            Ok::<Vec<u8>, io::Error>(bytes)
        });

        let status = loop {
            if task.cancelled.load(Ordering::Acquire) {
                drop(process_tree_job);
                let _ = child.kill();
                let _ = child.wait();
                let _ = stdout_reader.join();
                let _ = stderr_reader.join();
                return Err(cancelled_command_error(&task.id));
            }
            match child.try_wait() {
                Ok(Some(status)) => break status,
                Ok(None) => std::thread::sleep(Duration::from_millis(20)),
                Err(error) => {
                    drop(process_tree_job);
                    let _ = child.kill();
                    let _ = child.wait();
                    let _ = stdout_reader.join();
                    let _ = stderr_reader.join();
                    return Err(error);
                }
            }
        };
        drop(process_tree_job);
        let stdout = stdout_reader
            .join()
            .map_err(|_| io::Error::other("conversion stdout reader panicked"))??;
        let stderr = stderr_reader
            .join()
            .map_err(|_| io::Error::other("conversion stderr reader panicked"))??;
        Ok(Output {
            status,
            stdout,
            stderr,
        })
    }
}

#[tauri::command]
pub fn cancel_conversion_task(task_id: String) -> Result<bool, AppError> {
    let task_id = task_id.trim();
    if task_id.is_empty() {
        return Ok(false);
    }
    let tasks = CONVERSION_TASKS
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
        .map_err(|_| AppError::Internal("Conversion task registry is poisoned".to_string()))?;
    let Some(state) = tasks.get(task_id) else {
        return Ok(false);
    };
    let mut phase = state
        .phase
        .lock()
        .map_err(|_| AppError::Internal("Conversion task phase is poisoned".to_string()))?;
    match *phase {
        ConversionTaskPhase::Running | ConversionTaskPhase::Cancelled => {
            *phase = ConversionTaskPhase::Cancelled;
            state.cancelled.store(true, Ordering::Release);
            Ok(true)
        }
        ConversionTaskPhase::Committing | ConversionTaskPhase::Finished => Ok(false),
    }
}

impl ActiveConversionGuard {
    fn start() -> Self {
        ACTIVE_CONVERSION_JOBS.fetch_add(1, Ordering::Relaxed);
        Self
    }
}

impl Drop for ActiveConversionGuard {
    fn drop(&mut self) {
        ACTIVE_CONVERSION_JOBS.fetch_sub(1, Ordering::Relaxed);
    }
}

struct RuntimeResourceSampler {
    system: System,
    nvidia_smi_available: Option<bool>,
}

impl RuntimeResourceSampler {
    fn new() -> Self {
        Self {
            system: System::new_all(),
            nvidia_smi_available: None,
        }
    }

    fn sample(&mut self) -> RuntimeResourceSnapshot {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        let pid = Pid::from_u32(std::process::id());
        self.system.refresh_processes_specifics(
            ProcessesToUpdate::Some(&[pid]),
            false,
            ProcessRefreshKind::nothing().with_cpu().with_memory(),
        );

        let logical_cpu_count = self.system.cpus().len().max(1);
        let (app_cpu_usage_percent, app_memory_bytes) = self
            .system
            .process(pid)
            .map(|process| {
                (
                    (process.cpu_usage() / logical_cpu_count as f32).clamp(0.0, 100.0),
                    process.memory(),
                )
            })
            .unwrap_or((0.0, 0));
        let (gpu_backend, gpus, gpu_unavailable_reason) = self.sample_gpus();

        RuntimeResourceSnapshot {
            sampled_at_ms: unix_time_millis().min(u128::from(u64::MAX)) as u64,
            cpu_usage_percent: self.system.global_cpu_usage().clamp(0.0, 100.0),
            app_cpu_usage_percent,
            logical_cpu_count,
            physical_cpu_count: System::physical_core_count(),
            total_memory_bytes: self.system.total_memory(),
            used_memory_bytes: self.system.used_memory(),
            app_memory_bytes,
            active_conversion_jobs: ACTIVE_CONVERSION_JOBS.load(Ordering::Relaxed),
            gpu_backend,
            gpus,
            gpu_unavailable_reason,
        }
    }

    fn sample_gpus(&mut self) -> (String, Vec<GpuResourceSample>, Option<String>) {
        if self.nvidia_smi_available == Some(false) {
            return (
                "unavailable".to_string(),
                Vec::new(),
                Some("未检测到 NVIDIA 驱动采样接口；不会用估算值代替 GPU 占用。".to_string()),
            );
        }

        match query_nvidia_gpu_usage() {
            Ok(gpus) => {
                self.nvidia_smi_available = Some(true);
                ("nvidia_smi".to_string(), gpus, None)
            }
            Err(reason) => {
                if reason.starts_with("not_found:") {
                    self.nvidia_smi_available = Some(false);
                }
                (
                    "unavailable".to_string(),
                    Vec::new(),
                    Some(reason.trim_start_matches("not_found:").trim().to_string()),
                )
            }
        }
    }
}

fn unix_time_millis() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|value| value.as_millis())
        .unwrap_or(0)
}

fn parse_gpu_percentage(value: &str) -> Option<f32> {
    let normalized = value.trim().trim_end_matches('%').trim();
    normalized
        .parse::<f32>()
        .ok()
        .filter(|value| value.is_finite())
        .map(|value| value.clamp(0.0, 100.0))
}

fn parse_nvidia_smi_output(output: &str) -> Vec<GpuResourceSample> {
    output
        .lines()
        .filter_map(|line| {
            let mut fields = line.split(',').map(str::trim);
            let name = fields.next()?.to_string();
            let usage_percent = parse_gpu_percentage(fields.next()?)?;
            let encoder_usage_percent = fields.next().and_then(parse_gpu_percentage);
            (!name.is_empty()).then_some(GpuResourceSample {
                name,
                usage_percent,
                encoder_usage_percent,
            })
        })
        .collect()
}

fn query_nvidia_gpu_usage() -> Result<Vec<GpuResourceSample>, String> {
    let mut command = Command::new("nvidia-smi");
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
        command.creation_flags(CREATE_NO_WINDOW);
    }
    let result = command
        .args([
            "--query-gpu=name,utilization.gpu,utilization.encoder",
            "--format=csv,noheader,nounits",
        ])
        .output_for_conversion_task()
        .map_err(|error| {
            if error.kind() == io::ErrorKind::NotFound {
                "not_found: 未检测到 NVIDIA 驱动采样接口；Intel/AMD 设备当前显示为不可用。"
                    .to_string()
            } else {
                format!("GPU 采样启动失败：{error}")
            }
        })?;
    if !result.status.success() {
        let reason = String::from_utf8_lossy(&result.stderr).trim().to_string();
        return Err(if reason.is_empty() {
            "NVIDIA GPU 采样命令执行失败。".to_string()
        } else {
            format!("NVIDIA GPU 采样失败：{reason}")
        });
    }
    let gpus = parse_nvidia_smi_output(&String::from_utf8_lossy(&result.stdout));
    if gpus.is_empty() {
        Err("NVIDIA GPU 采样未返回可解析的设备数据。".to_string())
    } else {
        Ok(gpus)
    }
}
const MAX_MEDIA_THUMBNAIL_TIMES: usize = 20;
const MAX_FRAME_PAGE_SIZE: u32 = 60;
// FFmpeg's expression parser recursively builds long `a+b+c` select expressions.
// Current Windows builds fail with ENOMEM at roughly one hundred `eq(n, ...)`
// terms, so keep each filter comfortably below that parser limit.
const MAX_FRAME_DROPS_PER_SELECT_FILTER: usize = 32;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AnimationFormat {
    Gif,
    Webp,
    Avif,
    Apng,
    Mp4,
    Webm,
    LivePhoto,
}

impl AnimationFormat {
    fn parse(value: &str) -> Result<Self, AppError> {
        match value.trim().to_ascii_lowercase().as_str() {
            "" | "gif" => Ok(Self::Gif),
            "webp" => Ok(Self::Webp),
            "avif" => Ok(Self::Avif),
            "apng" | "png" => Ok(Self::Apng),
            "mp4" => Ok(Self::Mp4),
            "webm" => Ok(Self::Webm),
            "live_photo" | "livephoto" | "live" => Ok(Self::LivePhoto),
            other => Err(AppError::InvalidInput(format!(
                "Unsupported output format '{other}'. Choose gif, webp, avif, apng, mp4, webm, or live_photo."
            ))),
        }
    }

    fn wire_name(self) -> &'static str {
        match self {
            Self::Gif => "gif",
            Self::Webp => "webp",
            Self::Avif => "avif",
            Self::Apng => "apng",
            Self::Mp4 => "mp4",
            Self::Webm => "webm",
            Self::LivePhoto => "live_photo",
        }
    }

    fn extension(self) -> &'static str {
        match self {
            Self::LivePhoto => "pvt",
            _ => self.wire_name(),
        }
    }

    fn codec_name(self) -> &'static str {
        match self {
            Self::Gif => "gif",
            Self::Webp => "webp_anim",
            Self::Avif => "av1",
            Self::Apng => "apng",
            Self::Mp4 => "h264",
            Self::Webm => "vp9",
            Self::LivePhoto => "h264+jpeg",
        }
    }

    fn accepts_codec(self, codec: &str) -> bool {
        match self {
            // libwebp_anim may legally collapse a visually identical timeline
            // to a static WebP bitstream. FFprobe names those two valid forms
            // `webp_anim` and `webp`, respectively.
            Self::Webp => matches!(codec, "webp_anim" | "webp"),
            Self::LivePhoto => false,
            _ => codec == self.codec_name(),
        }
    }

    fn supports_alpha(self) -> bool {
        matches!(self, Self::Gif | Self::Webp | Self::Apng | Self::Webm)
    }
}

fn normalized_background_key_color(value: &str) -> Option<([u8; 3], String)> {
    let trimmed = value.trim();
    let hex = trimmed
        .strip_prefix('#')
        .or_else(|| trimmed.strip_prefix("0x"))
        .or_else(|| trimmed.strip_prefix("0X"))
        .unwrap_or(trimmed);
    if hex.len() != 6 || !hex.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return None;
    }
    let red = u8::from_str_radix(&hex[0..2], 16).ok()?;
    let green = u8::from_str_radix(&hex[2..4], 16).ok()?;
    let blue = u8::from_str_radix(&hex[4..6], 16).ok()?;
    Some(([red, green, blue], hex.to_ascii_uppercase()))
}

fn active_background_removal(request: &GifRequest) -> Option<&BackgroundRemovalRequest> {
    request
        .background_removal
        .as_ref()
        .filter(|settings| settings.mode.trim().eq_ignore_ascii_case("color_key"))
}

fn validate_background_removal(
    request: &GifRequest,
    output_format: AnimationFormat,
) -> Result<(), AppError> {
    let Some(settings) = request.background_removal.as_ref() else {
        return Ok(());
    };
    match settings.mode.trim().to_ascii_lowercase().as_str() {
        "" | "off" => return Ok(()),
        "color_key" => {}
        other => {
            return Err(AppError::InvalidInput(format!(
                "Unsupported background removal mode '{other}'."
            )));
        }
    }
    if !output_format.supports_alpha() {
        return Err(AppError::InvalidInput(format!(
            "{} does not preserve the transparent background produced by character cutout. Choose GIF, Animated WebP, APNG, or WebM.",
            output_format.wire_name().to_ascii_uppercase()
        )));
    }
    validate_background_removal_settings(settings)
}

fn validate_tracked_effects(request: &GifRequest) -> Result<(), AppError> {
    if request.tracked_effects.len() > 8 {
        return Err(AppError::InvalidInput(
            "A single export can contain at most 8 tracked effects".to_string(),
        ));
    }
    for effect in &request.tracked_effects {
        if !matches!(
            effect.kind.trim().to_ascii_lowercase().as_str(),
            "label" | "highlight" | "soft_blur" | "blackout"
        ) {
            return Err(AppError::InvalidInput(format!(
                "Unsupported tracked effect: {}",
                effect.kind
            )));
        }
        if effect.effect_id.trim().is_empty() || effect.effect_id.chars().count() > 80 {
            return Err(AppError::InvalidInput(
                "Tracked effects need a stable identifier of at most 80 characters".to_string(),
            ));
        }
        if effect.label.chars().count() > 60 {
            return Err(AppError::InvalidInput(
                "Tracked labels are limited to 60 characters".to_string(),
            ));
        }
        if !effect.start_seconds.is_finite()
            || !effect.end_seconds.is_finite()
            || effect.start_seconds < 0.0
            || effect.end_seconds <= effect.start_seconds
        {
            return Err(AppError::InvalidInput(
                "Tracked effect ranges must have a finite start and a later end".to_string(),
            ));
        }
        if effect.keyframes.is_empty() || effect.keyframes.len() > 32 {
            return Err(AppError::InvalidInput(
                "Tracked effects require between 1 and 32 editable keyframes".to_string(),
            ));
        }
        let mut previous_time = f64::NEG_INFINITY;
        for keyframe in &effect.keyframes {
            let values = [
                keyframe.time_seconds,
                keyframe.x_percent,
                keyframe.y_percent,
                keyframe.width_percent,
                keyframe.height_percent,
                keyframe.confidence,
            ];
            if values.iter().any(|value| !value.is_finite())
                || keyframe.time_seconds < previous_time
                || keyframe.width_percent < 2.0
                || keyframe.height_percent < 2.0
                || keyframe.x_percent < 0.0
                || keyframe.y_percent < 0.0
                || keyframe.x_percent + keyframe.width_percent > 100.001
                || keyframe.y_percent + keyframe.height_percent > 100.001
                || !(0.0..=1.0).contains(&keyframe.confidence)
            {
                return Err(AppError::InvalidInput(
                    "Tracked keyframes must be ordered and remain inside the visible frame"
                        .to_string(),
                ));
            }
            previous_time = keyframe.time_seconds;
        }
    }
    Ok(())
}

fn validate_background_removal_settings(
    settings: &BackgroundRemovalRequest,
) -> Result<(), AppError> {
    normalized_background_key_color(&settings.key_color).ok_or_else(|| {
        AppError::InvalidInput(
            "Background key color must be a six-digit RGB value such as #00FF00.".to_string(),
        )
    })?;
    if !settings.similarity.is_finite() || !(0.01..=1.0).contains(&settings.similarity) {
        return Err(AppError::InvalidInput(
            "Background color tolerance must be between 0.01 and 1.0.".to_string(),
        ));
    }
    if !settings.edge_blend.is_finite() || !(0.0..=1.0).contains(&settings.edge_blend) {
        return Err(AppError::InvalidInput(
            "Background edge blend must be between 0 and 1.".to_string(),
        ));
    }
    if !settings.despill.is_finite() || !(0.0..=1.0).contains(&settings.despill) {
        return Err(AppError::InvalidInput(
            "Background despill must be between 0 and 1.".to_string(),
        ));
    }
    Ok(())
}

fn background_removal_filters_for(settings: &BackgroundRemovalRequest) -> Vec<String> {
    let Some((rgb, hex)) = normalized_background_key_color(&settings.key_color) else {
        return Vec::new();
    };
    let similarity = settings.similarity.clamp(0.01, 1.0);
    let edge_blend = settings.edge_blend.clamp(0.0, 1.0);
    let mut filters = vec![
        "format=rgba".to_string(),
        format!("colorkey=0x{hex}:{similarity:.4}:{edge_blend:.4}"),
    ];
    let dominant_channel =
        if rgb[1] > rgb[0].saturating_add(24) && rgb[1] > rgb[2].saturating_add(24) {
            Some("green")
        } else if rgb[2] > rgb[0].saturating_add(24) && rgb[2] > rgb[1].saturating_add(24) {
            Some("blue")
        } else {
            None
        };
    if let Some(channel) = dominant_channel.filter(|_| settings.despill > f64::EPSILON) {
        let amount = settings.despill.clamp(0.0, 1.0);
        filters.push(format!(
            "despill=type={channel}:mix={amount:.4}:expand={amount:.4}:alpha=0"
        ));
    }
    filters
}

fn background_removal_filters(request: &GifRequest) -> Vec<String> {
    let Some(settings) = active_background_removal(request) else {
        return Vec::new();
    };
    background_removal_filters_for(settings)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum H264Usage {
    Delivery { lossy: u8 },
    Recording { media_foundation_hardware: bool },
}

fn required_h264_encoder(ffmpeg: &Path) -> Result<FfmpegH264Encoder, AppError> {
    probe_h264_encoder(ffmpeg).ok_or_else(|| {
        AppError::MissingDependency(
            "The discovered FFmpeg build has neither libx264 nor the Windows Media Foundation h264_mf encoder."
                .to_string(),
        )
    })
}

fn h264_encoder_args(encoder: FfmpegH264Encoder, usage: H264Usage) -> Vec<String> {
    let mut args = vec!["-c:v".to_string(), encoder.ffmpeg_name().to_string()];
    match (encoder, usage) {
        (FfmpegH264Encoder::Libx264, H264Usage::Delivery { lossy }) => {
            let crf = (18_i32 + i32::from(lossy.min(100)) / 6).clamp(17, 34);
            args.extend([
                "-preset".to_string(),
                "medium".to_string(),
                "-crf".to_string(),
                crf.to_string(),
            ]);
        }
        (FfmpegH264Encoder::Libx264, H264Usage::Recording { .. }) => {
            args.extend([
                "-preset".to_string(),
                "ultrafast".to_string(),
                "-crf".to_string(),
                "18".to_string(),
            ]);
        }
        (FfmpegH264Encoder::MediaFoundation, H264Usage::Delivery { lossy }) => {
            let quality = (92_i32 - i32::from(lossy.min(100)) * 45 / 100).clamp(47, 92);
            args.extend([
                "-rate_control".to_string(),
                "quality".to_string(),
                "-quality".to_string(),
                quality.to_string(),
                "-hw_encoding".to_string(),
                "0".to_string(),
            ]);
        }
        (
            FfmpegH264Encoder::MediaFoundation,
            H264Usage::Recording {
                media_foundation_hardware,
            },
        ) => {
            args.extend([
                "-rate_control".to_string(),
                "quality".to_string(),
                "-quality".to_string(),
                "88".to_string(),
                "-hw_encoding".to_string(),
                if media_foundation_hardware { "1" } else { "0" }.to_string(),
            ]);
        }
    }
    args
}

fn recording_h264_usage(ffmpeg: &Path, encoder: FfmpegH264Encoder) -> H264Usage {
    H264Usage::Recording {
        media_foundation_hardware: encoder == FfmpegH264Encoder::MediaFoundation
            && probe_h264_media_foundation_hardware(ffmpeg),
    }
}

fn generation_mode_for(request: &GifRequest) -> Result<GifGenerationMode, AppError> {
    match request.generation_mode.trim().to_ascii_lowercase().as_str() {
        "fast_gif" | "fast" => Ok(GifGenerationMode::Fast),
        "best_gif" | "best" => Ok(GifGenerationMode::Best),
        "target_size" | "exact_size" | "target" => Ok(GifGenerationMode::Target),
        "" => match request.encoder.as_str() {
            "ffmpeg_fast" => Ok(GifGenerationMode::Fast),
            "pngquant_opt" | "clean_opt" | "hybrid" => Ok(GifGenerationMode::Best),
            other => Err(AppError::InvalidInput(format!(
                "Unknown legacy encoder '{other}'. Choose fast_gif, best_gif, or target_size."
            ))),
        },
        other => Err(AppError::InvalidInput(format!(
            "Unknown generation mode '{other}'. Choose fast_gif, best_gif, or target_size."
        ))),
    }
}

fn classify_content(probe: &QuickContentProbe) -> ContentProfile {
    if probe.sampled_frames < 2 {
        return ContentProfile::Unknown;
    }
    if !probe.scene_cut_times.is_empty() || probe.scene_cut_ratio >= 0.03 {
        return ContentProfile::FrequentSceneChanges;
    }
    if probe.static_frame_ratio >= 0.45 || probe.mean_changed_area <= 0.30 {
        return ContentProfile::StaticOrSmallChanges;
    }
    if probe.mean_changed_area >= 0.55 || probe.median_frame_delta >= 0.045 {
        return ContentProfile::StableFullFrameMotion;
    }
    ContentProfile::Unknown
}

fn append_reason(current: Option<String>, reason: &str) -> Option<String> {
    Some(match current {
        Some(current) if !current.is_empty() => format!("{current}; {reason}"),
        _ => reason.to_string(),
    })
}

fn available_backend_executable(
    backends: &[BackendCapability],
    backend_id: &str,
) -> Option<(PathBuf, Option<String>)> {
    let backend = backends.iter().find(|backend| backend.id == backend_id)?;
    if !backend.status.is_available() {
        return None;
    }
    match &backend.status {
        BackendStatus::Available {
            executable_path: Some(path),
            version,
        } => Some((PathBuf::from(path), version.clone())),
        _ => None,
    }
}

fn single_encode_outcome(output: &Path, request: &GifRequest) -> EncodeOutcome {
    EncodeOutcome {
        output_path: output.to_path_buf(),
        size_bytes: fs::metadata(output)
            .map(|metadata| metadata.len())
            .unwrap_or(0),
        attempts: 1,
        width: request.width,
        fps: request.fps,
        colors: palette_color_count(request.colors),
        target_fit: None,
        target_optimizer_report: None,
        target_perceptual_artifacts: None,
    }
}

fn target_fit_label(fit: TargetFit) -> &'static str {
    match fit {
        TargetFit::Exact => "target_exact",
        TargetFit::Under => "target_under",
        TargetFit::Over => "target_over",
        TargetFit::Unreachable => "target_unreachable",
    }
}

fn ffmpeg_version(ffmpeg: &Path) -> Option<String> {
    let output = Command::new(ffmpeg)
        .arg("-version")
        .output_for_conversion_task()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8_lossy(&output.stdout)
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .map(|line| line.chars().take(240).collect())
}

pub(crate) fn inspect_media_file(
    ffprobe: &Path,
    input: &Path,
) -> Result<MediaInspection, AppError> {
    // FFprobe follows the GIF loop while `-count_frames` is active. A normal
    // loop-forever GIF can therefore make inspection (and delivery
    // verification) never return. Parse the finite container timeline in
    // process instead; this also preserves exact GIF delays and frame count.
    if input
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("gif"))
    {
        return inspect_gif_file(input);
    }
    if let Some(inspection) = inspect_animated_webp_file(input) {
        return Ok(inspection);
    }

    let output = Command::new(ffprobe)
        .arg("-v")
        .arg("error")
        .arg("-select_streams")
        .arg("v")
        .arg("-count_frames")
        .arg("-show_streams")
        .arg("-show_format")
        .arg("-of")
        .arg("json")
        .arg(input)
        .output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(
            String::from_utf8_lossy(&output.stderr).to_string(),
        ));
    }
    parse_media_inspection(&output.stdout)
}

fn inspect_media_file_fast(ffprobe: &Path, input: &Path) -> Result<MediaInspection, AppError> {
    // Keep interactive inspection bounded for long sources. GIFs retain their
    // exact in-process parser; other containers use metadata and may estimate
    // frame count from duration and average FPS when it is not stored.
    if input
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("gif"))
    {
        return inspect_gif_file(input);
    }
    if let Some(inspection) = inspect_animated_webp_file(input) {
        return Ok(inspection);
    }

    let output = Command::new(ffprobe)
        .arg("-v")
        .arg("error")
        .arg("-select_streams")
        .arg("v")
        .arg("-show_streams")
        .arg("-show_format")
        .arg("-of")
        .arg("json")
        .arg(input)
        .output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(
            String::from_utf8_lossy(&output.stderr).to_string(),
        ));
    }
    parse_media_inspection(&output.stdout)
}

fn inspect_animated_webp_file(input: &Path) -> Option<MediaInspection> {
    if !input
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("webp"))
    {
        return None;
    }
    let summary = inspect_webp_animation_path(input).ok()??;
    Some(MediaInspection {
        codec: "webp_anim".to_string(),
        width: summary.canvas_width,
        height: summary.canvas_height,
        duration: summary.playback_total_duration_ms as f64 / 1_000.0,
        frame_count: summary.frame_count,
        animated: true,
        has_alpha: summary.has_alpha,
    })
}

fn parse_media_inspection(bytes: &[u8]) -> Result<MediaInspection, AppError> {
    let root: Value = serde_json::from_slice(bytes)
        .map_err(|error| AppError::DecodeFailed(format!("Invalid ffprobe JSON: {error}")))?;
    let streams = root
        .get("streams")
        .and_then(Value::as_array)
        .ok_or_else(|| AppError::UnsupportedVideo("No video stream was found".to_string()))?;
    let stream = streams
        .iter()
        .max_by_key(|stream| media_stream_frame_count(stream, &root))
        .ok_or_else(|| AppError::UnsupportedVideo("No video stream was found".to_string()))?;
    let codec = stream
        .get("codec_name")
        .and_then(Value::as_str)
        .unwrap_or("unknown")
        .to_string();
    let width = stream.get("width").and_then(Value::as_u64).unwrap_or(0) as u32;
    let height = stream.get("height").and_then(Value::as_u64).unwrap_or(0) as u32;
    let duration = json_f64(stream.get("duration"))
        .or_else(|| json_f64(root.get("format").and_then(|format| format.get("duration"))))
        .unwrap_or(0.0)
        .max(0.0);
    let frame_count = media_stream_frame_count(stream, &root);
    let pixel_format = stream
        .get("pix_fmt")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_ascii_lowercase();
    let container_alpha = stream
        .get("tags")
        .and_then(|tags| tags.get("alpha_mode"))
        .and_then(Value::as_str)
        == Some("1");
    let has_alpha = pixel_format_has_alpha(&pixel_format) || container_alpha;
    let animated = frame_count > 1
        || matches!(
            codec.as_str(),
            "h264" | "hevc" | "av1" | "vp8" | "vp9" | "mpeg4" | "gif" | "webp_anim" | "apng"
        );

    Ok(MediaInspection {
        codec,
        width,
        height,
        duration,
        frame_count,
        animated,
        has_alpha,
    })
}

fn media_stream_frame_count(stream: &Value, root: &Value) -> u64 {
    json_u64(stream.get("nb_read_frames"))
        .or_else(|| json_u64(stream.get("nb_frames")))
        .or_else(|| {
            let duration = json_f64(stream.get("duration")).or_else(|| {
                json_f64(root.get("format").and_then(|format| format.get("duration")))
            })?;
            let fps = parse_fraction(stream.get("avg_frame_rate").and_then(Value::as_str)?)?;
            Some((duration * fps).round().max(1.0) as u64)
        })
        .unwrap_or(1)
}

fn verify_delivery_output(
    output: &Path,
    expected_format: AnimationFormat,
) -> Result<MediaInspection, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Validation);
    let metadata = fs::metadata(output).map_err(|error| {
        AppError::DecodeFailed(format!(
            "Encoded {} output is missing at {}: {error}",
            expected_format.wire_name().to_ascii_uppercase(),
            output.display()
        ))
    })?;
    if !metadata.is_file() || metadata.len() < 32 {
        return Err(AppError::DecodeFailed(format!(
            "Encoded {} output is incomplete ({} bytes)",
            expected_format.wire_name().to_ascii_uppercase(),
            metadata.len()
        )));
    }
    if expected_format == AnimationFormat::Gif {
        let mut file = File::open(output)
            .map_err(|error| AppError::DecodeFailed(format!("Open GIF output: {error}")))?;
        let mut header = [0_u8; 6];
        file.read_exact(&mut header)
            .map_err(|error| AppError::DecodeFailed(format!("Read GIF header: {error}")))?;
        file.seek(io::SeekFrom::End(-1))
            .map_err(|error| AppError::DecodeFailed(format!("Seek GIF trailer: {error}")))?;
        let mut trailer = [0_u8; 1];
        file.read_exact(&mut trailer)
            .map_err(|error| AppError::DecodeFailed(format!("Read GIF trailer: {error}")))?;
        if !matches!(&header, b"GIF87a" | b"GIF89a") || trailer[0] != 0x3b {
            return Err(AppError::DecodeFailed(
                "Encoded GIF is missing a valid header or final trailer".to_string(),
            ));
        }
    }
    let ffprobe = locate_ffprobe().map_err(|error| {
        AppError::MissingDependency(format!(
            "FFprobe is required to verify {} delivery before publishing: {error}",
            expected_format.wire_name().to_ascii_uppercase()
        ))
    })?;
    let inspection = inspect_media_file(&ffprobe, output)?;
    if !expected_format.accepts_codec(&inspection.codec)
        || inspection.width == 0
        || inspection.height == 0
        || inspection.frame_count == 0
    {
        return Err(AppError::DecodeFailed(format!(
            "Encoded {} failed delivery verification: codec {}, dimensions {}x{}, frames {}",
            expected_format.wire_name().to_ascii_uppercase(),
            inspection.codec,
            inspection.width,
            inspection.height,
            inspection.frame_count
        )));
    }
    Ok(inspection)
}

fn pixel_format_has_alpha(pixel_format: &str) -> bool {
    let pixel_format = pixel_format.to_ascii_lowercase();
    pixel_format.starts_with("yuva")
        || pixel_format.starts_with("gbrap")
        || matches!(
            pixel_format.as_str(),
            "rgba" | "bgra" | "argb" | "abgr" | "ya8" | "ya16le" | "ya16be"
        )
}

/// Return whether sampled decoded pixels actually use transparency. Pixel
/// formats such as BGRA may carry a fully opaque alpha plane, which must not
/// disable the Rust perceptual RGB scheduler unnecessarily.
fn source_uses_transparency(
    ffmpeg: &Path,
    input: &Path,
    source_args: &[String],
) -> Result<bool, AppError> {
    scan_source_transparency(ffmpeg, input, source_args, &[])
}

fn source_uses_transparency_after_timeline(
    ffmpeg: &Path,
    input: &Path,
    request: &GifRequest,
) -> Result<bool, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Probe);
    let source_args = source_time_args(request);
    let mut filters = timeline_filters(request);
    filters.extend(background_removal_filters(request));
    scan_source_transparency(ffmpeg, input, &source_args, &filters)
}

fn gif_timeline_uses_transparency(ffmpeg: &Path, input: &Path, request: &GifRequest) -> bool {
    let _pipeline_stage = export_pipeline::stage(Phase::Probe);
    let may_have_alpha = active_background_removal(request).is_some()
        || locate_ffprobe()
            .and_then(|ffprobe| fast_source_has_alpha_plane(&ffprobe, input))
            .unwrap_or(true);
    may_have_alpha
        && source_uses_transparency_after_timeline(ffmpeg, input, request).unwrap_or(true)
}

fn scan_source_transparency(
    ffmpeg: &Path,
    input: &Path,
    source_args: &[String],
    prefix_filters: &[String],
) -> Result<bool, AppError> {
    let mut command = Command::new(ffmpeg);
    command.arg("-v").arg("error");
    command.args(source_args);
    if input
        .extension()
        .and_then(|value| value.to_str())
        .is_some_and(|value| value.eq_ignore_ascii_case("webm"))
    {
        // FFmpeg's native VP9 decoder does not expose WebM's BlockAdditional
        // alpha plane. libvpx does, and is already required by GIFP's WebM
        // capability probe.
        command.arg("-c:v").arg("libvpx-vp9");
    }
    command.args(animation_demux_args(input));
    let filter = transparency_scan_filter(prefix_filters);
    let output = command
        .arg("-i")
        .arg(input)
        .arg("-an")
        .arg("-sn")
        .arg("-vf")
        .arg(filter)
        .arg("-f")
        .arg("null")
        .arg("-")
        .output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(
            String::from_utf8_lossy(&output.stderr).to_string(),
        ));
    }
    let minima = String::from_utf8_lossy(&output.stdout)
        .lines()
        .filter_map(|line| line.trim().strip_prefix("lavfi.signalstats.YMIN="))
        .filter_map(|value| value.parse::<u16>().ok())
        .collect::<Vec<_>>();
    if minima.is_empty() {
        return Err(AppError::DecodeFailed(
            "FFmpeg produced no alpha-plane statistics".to_string(),
        ));
    }
    Ok(minima
        .into_iter()
        .any(|minimum| minimum < u16::from(u8::MAX)))
}

fn transparency_scan_filter(prefix_filters: &[String]) -> String {
    let mut filters = prefix_filters.to_vec();
    filters.push("format=rgba".to_string());
    filters.push("alphaextract".to_string());
    filters.push("signalstats".to_string());
    filters.push("metadata=mode=print:key=lavfi.signalstats.YMIN:file=-".to_string());
    filters.join(",")
}

fn perceptual_scheduler_config(
    focus: PerceptualFocus,
    summary: PerceptualSummary,
    base_retention: f32,
    lossy: u8,
) -> SchedulerConfig {
    let baseline = (base_retention - f32::from(lossy.min(100)) * 0.001).clamp(0.42, 0.82);
    let resolved_focus = summary.resolve_focus(focus);
    let (retention_floor, duplicate_motion_threshold, low_value_threshold) = match resolved_focus {
        PerceptualFocus::Motion => {
            let floor = if summary.mean_changed_area >= 0.06 || summary.mean_motion >= 0.025 {
                1.0
            } else {
                0.82
            };
            (floor, 0.003, 0.035)
        }
        PerceptualFocus::TextUi
            if summary.mean_changed_area >= 0.008 || summary.mean_motion >= 0.002 =>
        {
            (1.0, 0.003, 0.11)
        }
        PerceptualFocus::Auto => unreachable!("Auto focus must resolve before scheduling"),
        PerceptualFocus::Subject | PerceptualFocus::TextUi | PerceptualFocus::FlatArt => {
            (baseline, 0.012, 0.16)
        }
    };
    SchedulerConfig {
        focus,
        retention_ratio: baseline.max(retention_floor),
        scene_change_threshold: 0.42,
        duplicate_motion_threshold,
        low_value_threshold,
        fill_target_with_subtle_changes: resolved_focus == PerceptualFocus::Motion
            && retention_floor >= 1.0,
        ..SchedulerConfig::default()
    }
}

fn neutral_motion_filter_recommended(
    resolved_focus: PerceptualFocus,
    summary: PerceptualSummary,
) -> bool {
    resolved_focus == PerceptualFocus::Motion
        && summary.mean_changed_area >= 0.06
        && summary.mean_noise >= 0.045
}

fn perceptual_color_eq_recommended(resolved_focus: PerceptualFocus) -> bool {
    resolved_focus == PerceptualFocus::Motion
}

fn perceptual_bayer_dither_scale(
    resolved_focus: PerceptualFocus,
    summary: PerceptualSummary,
) -> Option<u8> {
    (resolved_focus == PerceptualFocus::FlatArt
        && summary.mean_motion <= 0.0003
        && summary.mean_changed_area <= 0.0002
        && summary.mean_edge_text <= 0.01
        && summary.mean_noise <= 0.012)
        .then_some(3)
}

fn perceptual_floyd_dither_recommended(
    requested_focus: PerceptualFocus,
    summary: PerceptualSummary,
) -> bool {
    matches!(
        requested_focus,
        PerceptualFocus::Auto | PerceptualFocus::FlatArt
    ) && summary.mean_smooth_gradient_ratio >= 0.40
        && (0.003..=0.03).contains(&summary.mean_changed_area)
        && (0.001..=0.012).contains(&summary.mean_motion)
        && summary.mean_edge_text <= 0.12
        && summary.mean_noise <= 0.03
}

fn static_gradient_writer_recommended(summary: PerceptualSummary) -> bool {
    summary.mean_smooth_gradient_ratio >= 0.25
        && summary.mean_motion <= 0.00005
        && summary.mean_changed_area <= 0.00005
        && summary.mean_edge_text <= 0.09
        && summary.mean_noise <= 0.03
}

fn structured_ui_mapper_candidate(summary: PerceptualSummary) -> bool {
    summary.mean_smooth_gradient_ratio >= 0.40
        && (0.0003..=0.0012).contains(&summary.mean_motion)
        && (0.0015..=0.003).contains(&summary.mean_changed_area)
        && (0.12..=0.19).contains(&summary.mean_edge_text)
        && summary.mean_noise <= 0.035
        && summary.mean_skin_ratio <= 0.02
}

fn perceptual_palette_histogram_precision(
    request: &GifRequest,
    summary: PerceptualSummary,
    preserve_smooth_gradient_floyd: bool,
    enable_static_gradient_writer: bool,
) -> PaletteHistogramPrecision {
    if (request.allow_experimental || enable_static_gradient_writer)
        && !preserve_smooth_gradient_floyd
        && summary.mean_smooth_gradient_ratio >= 0.18
        && summary.mean_noise <= 0.035
    {
        PaletteHistogramPrecision::Fine6Bit
    } else {
        PaletteHistogramPrecision::Standard5Bit
    }
}

fn ffmpeg_palette_recommended(resolved_focus: PerceptualFocus, summary: PerceptualSummary) -> bool {
    resolved_focus == PerceptualFocus::Motion
        || (resolved_focus == PerceptualFocus::TextUi
            && (summary.mean_changed_area >= 0.008 || summary.mean_motion >= 0.002))
}

fn perceptual_palette_reserves_transparency(selected_frame_count: usize) -> bool {
    // `build_perceptual_timeline` has already rejected sources with alpha.
    // One selected frame cannot benefit from temporal GIF deltas, whereas an
    // animated timeline needs the reserved entry for `transdiff`.
    selected_frame_count > 1
}

fn build_perceptual_timeline(
    ffmpeg: &Path,
    input: &Path,
    request: &GifRequest,
    source_uses_transparency: bool,
    plan_color_artifacts: bool,
) -> Result<PerceptualTimelineArtifacts, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::FrameAnalysis);
    check_conversion_cancelled()?;
    if let Ok(duration) = locate_ffprobe().and_then(|ffprobe| fast_media_duration(&ffprobe, input))
    {
        if let Some(estimated_frames) = estimated_perceptual_frame_count(duration, request) {
            if estimated_frames > MAX_PERCEPTUAL_FRAMES {
                return Err(AppError::DecodeFailed(format!(
                    "Perceptual preflight estimated {estimated_frames} frames after trim and speed, above the {MAX_PERCEPTUAL_FRAMES}-frame Alpha limit; skipped analysis before decoding the long clip"
                )));
            }
        }
    }
    let source_args = source_time_args(request);
    if source_uses_transparency {
        return Err(AppError::DecodeFailed(
            "The 3.2 Alpha RGB scheduler is disabled for sources that use transparency; preserved alpha with the FFmpeg quality baseline instead"
                .to_string(),
        ));
    }
    let filter = perceptual_analysis_filter(request);
    let frame_limit = (MAX_PERCEPTUAL_FRAMES + 1).to_string();
    let _decode_stage = export_pipeline::stage(Phase::DecodeTransform);
    let output = Command::new(ffmpeg)
        .arg("-hide_banner")
        .arg("-loglevel")
        .arg("error")
        .args(&source_args)
        .args(animation_demux_args(input))
        .arg("-i")
        .arg(input)
        .arg("-an")
        .arg("-sn")
        .arg("-vf")
        .arg(filter)
        .arg("-frames:v")
        .arg(frame_limit)
        .arg("-pix_fmt")
        .arg("rgb24")
        .arg("-fps_mode")
        .arg("passthrough")
        .arg("-f")
        .arg("rawvideo")
        .arg("pipe:1")
        .output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(format!(
            "Perceptual sample decode failed: {}",
            String::from_utf8_lossy(&output.stderr)
        )));
    }

    drop(_decode_stage);
    let side = PERCEPTUAL_ANALYSIS_SIDE as usize;
    let frame_bytes = side
        .checked_mul(side)
        .and_then(|pixels| pixels.checked_mul(3))
        .ok_or_else(|| AppError::Internal("Perceptual frame size overflow".to_string()))?;
    if output.stdout.len() % frame_bytes != 0 {
        return Err(AppError::DecodeFailed(format!(
            "Perceptual decoder returned an incomplete RGB24 frame ({} bytes)",
            output.stdout.len() % frame_bytes
        )));
    }
    let decoded_frame_count = output.stdout.len() / frame_bytes;
    if decoded_frame_count == 0 {
        return Err(AppError::DecodeFailed(
            "Perceptual analysis decoded no frames".to_string(),
        ));
    }
    if decoded_frame_count > MAX_PERCEPTUAL_FRAMES {
        let fps = request.fps.clamp(1, 60);
        let seconds = MAX_PERCEPTUAL_FRAMES as f64 / f64::from(fps);
        return Err(AppError::DecodeFailed(format!(
            "Perceptual analysis is limited to {MAX_PERCEPTUAL_FRAMES} frames ({seconds:.1}s at {fps} FPS); used the FFmpeg quality baseline for this longer clip"
        )));
    }

    let fps = u64::from(request.fps.clamp(1, 60));
    let timestamp_us = |index: usize| -> u64 {
        ((index as u64)
            .saturating_mul(1_000_000)
            .saturating_add(fps / 2))
            / fps
    };
    let mut frames = Vec::with_capacity(decoded_frame_count);
    for (index, pixels) in output.stdout.chunks_exact(frame_bytes).enumerate() {
        if index % 16 == 0 {
            check_conversion_cancelled()?;
        }
        let pts_us = timestamp_us(index);
        let next_pts_us = timestamp_us(index + 1);
        let pts_us = i64::try_from(pts_us)
            .map_err(|_| AppError::Internal("Perceptual timestamp overflow".to_string()))?;
        frames.push(Rgb24Frame::new(
            pixels.to_vec(),
            pts_us,
            next_pts_us.saturating_sub(pts_us as u64).max(1),
        ));
    }
    drop(output);
    check_conversion_cancelled()?;
    let analysis = analyze_rgb_frames(PERCEPTUAL_ANALYSIS_SIDE, PERCEPTUAL_ANALYSIS_SIDE, &frames)
        .map_err(|error| AppError::DecodeFailed(format!("Perceptual analysis failed: {error}")))?;
    drop(frames);
    let summary = analysis.summary();
    let focus = PerceptualFocus::parse(&request.perceptual_focus)
        .map_err(|error| AppError::InvalidInput(error.to_string()))?;
    let base_retention: f32 = match request.optimize_level.clamp(1, 4) {
        1 => 0.78,
        2 => 0.69,
        3 => 0.61,
        _ => 0.54,
    };
    let scheduler = perceptual_scheduler_config(focus, summary, base_retention, request.lossy);
    let schedule = schedule_frames(&analysis, &scheduler).map_err(|error| {
        AppError::DecodeFailed(format!("Perceptual scheduling failed: {error}"))
    })?;
    if schedule.input_truncated {
        return Err(AppError::DecodeFailed(
            "Perceptual timeline was truncated; used the FFmpeg quality baseline".to_string(),
        ));
    }

    let nominal_delay_cs = ((100.0 / fps as f64).round() as u32).max(1);
    let scheduled_pts = schedule
        .frames
        .iter()
        .map(|frame| frame.pts_us)
        .collect::<Vec<_>>();
    let actual_delays_cs = gif_timeline_delays_cs(schedule.quantized_duration_cs, &scheduled_pts)?;
    let variable_delay_frames = actual_delays_cs
        .iter()
        .filter(|delay| **delay != nominal_delay_cs)
        .count() as u32;
    let analysis_frame_count = analysis.frames.len() as u32;
    let kept_frame_count = schedule.frames.len() as u32;
    let denominator = f64::from(analysis_frame_count.max(1));
    let scene_boundary_count = analysis
        .frames
        .iter()
        .filter(|frame| frame.scene_change >= scheduler.scene_change_threshold)
        .count() as u32;
    let final_delay_cs = actual_delays_cs
        .last()
        .copied()
        .ok_or_else(|| AppError::DecodeFailed("Perceptual schedule is empty".to_string()))?;
    let frame_delays_cs = actual_delays_cs
        .iter()
        .copied()
        .map(|delay| {
            u16::try_from(delay).map_err(|_| {
                AppError::DecodeFailed(format!(
                    "Perceptual frame delay {delay} does not fit the Rust GIF writer"
                ))
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let mut selection = PerceptualSelection {
        keep_indices: schedule
            .kept_indices()
            .into_iter()
            .map(|index| index as u32)
            .collect(),
        source_frame_count: analysis_frame_count,
        final_delay_cs,
        frame_delays_cs,
        palette: None,
        structured_ui_standard_palette: None,
        palette_sequence: None,
        region_dither: None,
        color_eq_recommended: perceptual_color_eq_recommended(schedule.resolved_focus),
        bayer_dither_scale: perceptual_bayer_dither_scale(schedule.resolved_focus, summary),
        floyd_dither_recommended: perceptual_floyd_dither_recommended(focus, summary),
        structured_ui_mapper_candidate: structured_ui_mapper_candidate(summary),
        neutral_filter_recommended: neutral_motion_filter_recommended(
            schedule.resolved_focus,
            summary,
        ),
    };
    let enable_static_gradient_writer = static_gradient_writer_recommended(summary);
    // Caption colors are semantic UI tokens rather than merely sampled image
    // colors. When the Rust palette route is available, keep those exact
    // tokens as fixed centers instead of allowing the adaptive FFmpeg route to
    // approximate them away on a busy frame.
    let protected_palette_colors = protected_overlay_palette_anchors(request);
    let use_ffmpeg_palette = !plan_color_artifacts
        || (protected_palette_colors.is_empty()
            && ffmpeg_palette_recommended(schedule.resolved_focus, summary));
    let (palette_report, region_dither_report, opaque_global_candidate) = if use_ffmpeg_palette {
        (None, None, None)
    } else {
        let frame_weights = schedule
            .frames
            .iter()
            .zip(actual_delays_cs.iter())
            .map(|(frame, delay_cs)| {
                f64::from(*delay_cs) * (0.5 + f64::from(frame.importance.max(0.0)))
            })
            .collect::<Vec<_>>();
        let segmentation =
            plan_palette_segments(&analysis, &schedule).map_err(|error| error.to_string());
        let histogram_precision = perceptual_palette_histogram_precision(
            request,
            summary,
            selection.floyd_dither_recommended,
            enable_static_gradient_writer,
        );
        // The perceptual timeline rejects alpha sources above. A one-frame
        // opaque GIF has no inter-frame delta to encode, so its final palette
        // may use all 256 entries; animated timelines retain the transparent
        // slot for differential-frame compression.
        let reserve_transparent = perceptual_palette_reserves_transparency(frame_weights.len());
        let palette_plan = build_perceptual_palette(
            ffmpeg,
            input,
            request,
            PerceptualPaletteBuildContext {
                selection: &selection,
                frame_weights: &frame_weights,
                histogram_precision,
                segmentation,
                protected_palette_colors: &protected_palette_colors,
                reserve_transparent,
            },
        )?;
        let candidate_segment_count = palette_plan
            .segmentation
            .as_ref()
            .map_or(0, |artifact| artifact.segments.len())
            as u16;
        let candidate_boundary_reasons = palette_plan
            .segmentation
            .as_ref()
            .map(|artifact| {
                artifact
                    .segments
                    .iter()
                    .filter_map(|segment| segment.boundary_before)
                    .map(|reason| reason.as_str().to_string())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let candidate_artifact_hashes = palette_plan
            .sequence
            .as_ref()
            .map(|sequence| {
                sequence
                    .segments
                    .iter()
                    .map(|segment| segment.palette.sha256.clone())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let candidate_weighted_mean_oklab_error = palette_plan.sequence.as_ref().map(|sequence| {
            let weighted_sample_mass = sequence
                .segments
                .iter()
                .map(|segment| segment.palette.weighted_sample_mass)
                .sum::<f64>();
            if weighted_sample_mass <= 0.0 {
                0.0
            } else {
                sequence
                    .segments
                    .iter()
                    .map(|segment| {
                        segment.palette.weighted_histogram_mean_oklab_error
                            * segment.palette.weighted_sample_mass
                    })
                    .sum::<f64>()
                    / weighted_sample_mass
            }
        });
        let candidate_worst_segment_p95_oklab_error =
            palette_plan.sequence.as_ref().map(|sequence| {
                sequence
                    .segments
                    .iter()
                    .map(|segment| segment.palette.weighted_histogram_p95_oklab_error)
                    .fold(0.0_f64, f64::max)
            });
        let palette = &palette_plan.global;
        let report = PaletteReport {
            planner_id: "rust.oklab.stable_sequence".to_string(),
            planner_version: env!("CARGO_PKG_VERSION").to_string(),
            color_space: "oklab".to_string(),
            strategy: "global".to_string(),
            requested_colors: palette_color_count(request.colors),
            emitted_colors: palette.emitted_colors,
            histogram_precision_bits: histogram_precision.bits(),
            reserved_transparent: oklab_palette_reserves_transparency(palette),
            segment_count: 1,
            artifact_hashes: vec![palette.sha256.clone()],
            sampled_frame_count: palette.sampled_frame_count,
            sampled_pixel_count: palette.sampled_pixel_count,
            weighted_histogram_mean_oklab_error: palette.weighted_histogram_mean_oklab_error,
            weighted_histogram_p95_oklab_error: palette.weighted_histogram_p95_oklab_error,
            global_color_table_verified: false,
            candidate_status: palette_plan.candidate_status.clone(),
            candidate_fallback_reason: palette_plan.candidate_failure.clone(),
            candidate_segment_count,
            candidate_boundary_reasons,
            candidate_artifact_hashes,
            shared_anchor_count: palette_plan
                .sequence
                .as_ref()
                .map_or(0, |sequence| sequence.shared_anchors_rgb.len())
                as u16,
            shared_anchor_sha256: palette_plan
                .sequence
                .as_ref()
                .map(|sequence| sequence.shared_anchor_sha256.clone()),
            segmentation_sha256: palette_plan
                .segmentation
                .as_ref()
                .map(|artifact| artifact.sha256.clone()),
            palette_sequence_sha256: palette_plan
                .sequence
                .as_ref()
                .map(|sequence| sequence.sha256.clone()),
            candidate_weighted_mean_oklab_error,
            candidate_worst_segment_p95_oklab_error,
        };
        let region_report = build_region_dither_report(&palette_plan);
        selection.structured_ui_standard_palette =
            palette_plan.structured_ui_standard_palette.clone();
        selection.palette_sequence = palette_plan.sequence.clone();
        selection.region_dither = palette_plan.region_dither.clone();
        selection.palette = Some(palette_plan.global);
        (
            Some(report),
            Some(region_report),
            palette_plan.opaque_global_candidate,
        )
    };
    let filter_strategy = perceptual_filter_strategy(request, &selection);
    let requested_dither = dither_for(request);
    let adaptive_dither = adaptive_perceptual_dither(request, &selection);
    let effective_dither = adaptive_dither
        .map(|(dither, _)| dither)
        .unwrap_or(requested_dither);
    let effective_bayer_scale = (effective_dither == "bayer").then(|| {
        adaptive_dither
            .and_then(|(_, scale)| scale)
            .unwrap_or(request.bayer_scale.min(5))
    });
    let report = PerceptualReport {
        analysis_frame_count,
        kept_frame_count,
        dropped_frame_count: analysis_frame_count.saturating_sub(kept_frame_count),
        kept_ratio: f64::from(kept_frame_count) / denominator,
        variable_delay_frames,
        source_duration_ms: schedule.source_duration_us.saturating_add(500) / 1_000,
        output_duration_ms: schedule.quantized_duration_cs.saturating_mul(10),
        scene_boundary_count,
        mean_motion: f64::from(summary.mean_motion),
        mean_changed_area: f64::from(summary.mean_changed_area),
        mean_edge_text: f64::from(summary.mean_edge_text),
        mean_noise: f64::from(summary.mean_noise),
        mean_smooth_gradient_ratio: f64::from(summary.mean_smooth_gradient_ratio),
        mean_subject_saliency: f64::from(summary.mean_subject_saliency),
        mean_skin_ratio: f64::from(summary.mean_skin_ratio),
        focus: schedule.resolved_focus.as_str().to_string(),
        filter_strategy: filter_strategy.to_string(),
        experimental_dither_candidate: selection
            .floyd_dither_recommended
            .then(|| "floyd_steinberg".to_string()),
        effective_dither: effective_dither.to_string(),
        effective_bayer_scale,
        static_gradient_writer_recommended: enable_static_gradient_writer,
        structured_ui_mapper_candidate: selection.structured_ui_mapper_candidate,
        truncated: schedule.input_truncated,
        aggregate_timeline_verified: false,
    };
    Ok((
        selection,
        report,
        palette_report,
        region_dither_report,
        opaque_global_candidate,
    ))
}

fn build_perceptual_palette(
    ffmpeg: &Path,
    input: &Path,
    request: &GifRequest,
    context: PerceptualPaletteBuildContext<'_>,
) -> Result<PerceptualPalettePlan, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Palette);
    let PerceptualPaletteBuildContext {
        selection,
        frame_weights,
        histogram_precision,
        segmentation,
        protected_palette_colors,
        reserve_transparent,
    } = context;
    if frame_weights.is_empty() {
        return Err(AppError::DecodeFailed(
            "Perceptual palette sampling received no scheduled frames".to_string(),
        ));
    }
    let mut palette_request = request.clone();
    palette_request.perceptual_selection = Some(selection.clone());
    let filter = perceptual_palette_sample_filter(&palette_request, choose_encoder(request));
    let _decode_stage = export_pipeline::stage(Phase::DecodeTransform);
    let output = Command::new(ffmpeg)
        .arg("-hide_banner")
        .arg("-loglevel")
        .arg("error")
        .args(source_time_args(request))
        .args(animation_demux_args(input))
        .arg("-i")
        .arg(input)
        .arg("-an")
        .arg("-sn")
        .arg("-vf")
        .arg(filter)
        .arg("-pix_fmt")
        .arg("rgb24")
        .arg("-fps_mode")
        .arg("passthrough")
        .arg("-f")
        .arg("rawvideo")
        .arg("pipe:1")
        .output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(format!(
            "Perceptual palette sample decode failed: {}",
            String::from_utf8_lossy(&output.stderr)
        )));
    }
    drop(_decode_stage);
    let side = PERCEPTUAL_PALETTE_SAMPLE_SIDE as usize;
    let frame_bytes = side
        .checked_mul(side)
        .and_then(|pixels| pixels.checked_mul(3))
        .ok_or_else(|| AppError::Internal("Palette sample frame size overflow".to_string()))?;
    if output.stdout.len() % frame_bytes != 0 {
        return Err(AppError::DecodeFailed(format!(
            "Palette sample decoder returned an incomplete RGB24 frame ({} bytes)",
            output.stdout.len() % frame_bytes
        )));
    }
    let decoded_count = output.stdout.len() / frame_bytes;
    if decoded_count != frame_weights.len() {
        return Err(AppError::DecodeFailed(format!(
            "Palette sampling expected {} scheduled frames but decoded {decoded_count}",
            frame_weights.len()
        )));
    }
    let palette_options = PaletteBuildOptions {
        // Differential GIF frames use the transparent entry for temporal
        // compression. Releasing it is a separate rate--distortion decision;
        // template lock colors must not change that behavior implicitly.
        reserve_transparent,
        protected_rgb: protected_palette_colors.to_vec(),
    };
    let global = build_oklab_palette_from_contiguous_rgb24_with_precision_and_options(
        &output.stdout,
        frame_weights,
        PERCEPTUAL_PALETTE_SAMPLE_SIDE,
        PERCEPTUAL_PALETTE_SAMPLE_SIDE,
        palette_color_count(request.colors),
        histogram_precision,
        &palette_options,
    )
    .map_err(|error| AppError::DecodeFailed(format!("OKLab palette planning failed: {error}")))?;
    // Do not guess whether a 256th color is worth losing `transdiff` for. The
    // second artifact is sampled identically and is only eligible for a
    // later, real encoded-file comparison on opaque animated timelines.
    let opaque_global_candidate = (reserve_transparent
        && palette_color_count(request.colors) == 256)
        .then(|| {
            let opaque_options = PaletteBuildOptions {
                reserve_transparent: false,
                protected_rgb: protected_palette_colors.to_vec(),
            };
            build_oklab_palette_from_contiguous_rgb24_with_precision_and_options(
                &output.stdout,
                frame_weights,
                PERCEPTUAL_PALETTE_SAMPLE_SIDE,
                PERCEPTUAL_PALETTE_SAMPLE_SIDE,
                palette_color_count(request.colors),
                histogram_precision,
                &opaque_options,
            )
            .map_err(|error| {
                AppError::DecodeFailed(format!(
                    "Opaque 256-color OKLab candidate planning failed: {error}"
                ))
            })
        })
        .transpose()?;
    let structured_ui_standard_palette = (request.allow_experimental
        && selection.structured_ui_mapper_candidate
        && histogram_precision == PaletteHistogramPrecision::Fine6Bit)
        .then(|| {
            build_oklab_palette_from_contiguous_rgb24_with_precision_and_options(
                &output.stdout,
                frame_weights,
                PERCEPTUAL_PALETTE_SAMPLE_SIDE,
                PERCEPTUAL_PALETTE_SAMPLE_SIDE,
                palette_color_count(request.colors),
                PaletteHistogramPrecision::Standard5Bit,
                &palette_options,
            )
            .map_err(|error| {
                AppError::DecodeFailed(format!(
                    "Structured UI standard palette planning failed: {error}"
                ))
            })
        })
        .transpose()?;

    let (sequence, candidate_status, candidate_failure) = match segmentation.as_ref() {
        Err(reason) => (
            None,
            "segmentation_failed".to_string(),
            Some(reason.clone()),
        ),
        Ok(artifact) if artifact.segments.len() <= 1 => (None, "not_needed".to_string(), None),
        Ok(artifact)
            if artifact.hard_cut_count == 0
                && global.weighted_histogram_p95_oklab_error < SEGMENT_PALETTE_P95_GATE =>
        {
            (None, "fit_gate_not_met".to_string(), None)
        }
        Ok(artifact) => {
            let ranges = artifact
                .frame_ranges()
                .into_iter()
                .map(|(start, end_exclusive)| PaletteFrameRange {
                    start,
                    end_exclusive,
                })
                .collect::<Vec<_>>();
            match build_oklab_segment_palette_sequence_from_contiguous_rgb24_with_precision_and_options(
                &output.stdout,
                frame_weights,
                PERCEPTUAL_PALETTE_SAMPLE_SIDE,
                PERCEPTUAL_PALETTE_SAMPLE_SIDE,
                palette_color_count(request.colors),
                &global,
                &ranges,
                histogram_precision,
                &palette_options,
            ) {
                Ok(sequence) => (Some(sequence), "planned_not_encoded".to_string(), None),
                Err(error) => (None, "planning_failed".to_string(), Some(error.to_string())),
            }
        }
    };
    let (region_dither, region_dither_failure) =
        match build_region_dither_plan_from_contiguous_rgb24(
            &output.stdout,
            frame_weights,
            PERCEPTUAL_PALETTE_SAMPLE_SIDE,
            PERCEPTUAL_PALETTE_SAMPLE_SIDE,
            REGION_DITHER_GRID_SIDE,
            REGION_DITHER_GRID_SIDE,
        ) {
            Ok(artifact) => (Some(artifact), None),
            Err(error) => (None, Some(error.to_string())),
        };
    Ok(PerceptualPalettePlan {
        global,
        opaque_global_candidate,
        structured_ui_standard_palette,
        segmentation: segmentation.ok(),
        sequence,
        candidate_status,
        candidate_failure,
        region_dither,
        region_dither_failure,
    })
}

fn build_region_dither_report(plan: &PerceptualPalettePlan) -> RegionDitherReport {
    match plan.region_dither.as_ref() {
        Some(artifact) => RegionDitherReport {
            planner_id: "rust.region_dither.v1".to_string(),
            planner_version: env!("CARGO_PKG_VERSION").to_string(),
            status: "planned_not_encoded".to_string(),
            fallback_reason: None,
            grid_width: artifact.grid_width,
            grid_height: artifact.grid_height,
            sampled_frame_count: artifact.sampled_frame_count,
            sampled_pixel_count: artifact.sampled_pixel_count,
            weighted_sample_mass: Some(artifact.weighted_sample_mass),
            class_counts: RegionClassCounts {
                flat: artifact.class_counts[0],
                text_edge: artifact.class_counts[1],
                skin_subject: artifact.class_counts[2],
                texture: artifact.class_counts[3],
            },
            mean_dither_strength: Some(artifact.mean_dither_strength),
            mean_spatial_std: Some(artifact.mean_spatial_std),
            mean_edge: Some(artifact.mean_edge),
            mean_skin_ratio: Some(artifact.mean_skin_ratio),
            mean_temporal_delta: Some(artifact.mean_temporal_delta),
            mean_high_frequency_noise: Some(artifact.mean_high_frequency_noise),
            class_map_sha256: Some(artifact.class_map_sha256.clone()),
            strength_map_sha256: Some(artifact.strength_map_sha256.clone()),
            artifact_sha256: Some(artifact.sha256.clone()),
        },
        None => RegionDitherReport {
            planner_id: "rust.region_dither.v1".to_string(),
            planner_version: env!("CARGO_PKG_VERSION").to_string(),
            status: "planning_failed".to_string(),
            fallback_reason: plan.region_dither_failure.clone(),
            grid_width: REGION_DITHER_GRID_SIDE,
            grid_height: REGION_DITHER_GRID_SIDE,
            sampled_frame_count: 0,
            sampled_pixel_count: 0,
            weighted_sample_mass: None,
            class_counts: RegionClassCounts::default(),
            mean_dither_strength: None,
            mean_spatial_std: None,
            mean_edge: None,
            mean_skin_ratio: None,
            mean_temporal_delta: None,
            mean_high_frequency_noise: None,
            class_map_sha256: None,
            strength_map_sha256: None,
            artifact_sha256: None,
        },
    }
}

fn source_probe_json(ffprobe: &Path, input: &Path) -> Result<Value, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Probe);
    check_conversion_cancelled()?;
    let key = if export_pipeline::source_probe_cache_enabled() {
        fs::metadata(input)
            .and_then(|metadata| {
                metadata
                    .modified()
                    .map(|modified| (metadata.len(), modified))
            })
            .ok()
            .map(|stamp| {
                vec![
                    ffprobe.as_os_str().to_owned(),
                    input.as_os_str().to_owned(),
                    format!("{stamp:?}").into(),
                    "source-v0-metadata-v1".into(),
                ]
            })
    } else {
        None
    };
    if let Some(value) = key.as_ref().and_then(export_pipeline::cached_source_probe) {
        check_conversion_cancelled()?;
        return Ok(value);
    }
    // Query only finite metadata, never count/decode all frames here. The
    // three consumers keep their existing field validation and fallbacks.
    let output = Command::new(ffprobe)
        .args(["-v", "error", "-select_streams", "v:0", "-show_entries",
            "stream=width,height,pix_fmt,duration:stream_tags=rotate:stream_side_data=rotation:format=duration",
            "-of", "json"])
        .arg(input).output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    check_conversion_cancelled()?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(
            String::from_utf8_lossy(&output.stderr).to_string(),
        ));
    }
    let root: Value = serde_json::from_slice(&output.stdout)
        .map_err(|error| AppError::DecodeFailed(format!("Invalid FFprobe JSON: {error}")))?;
    if let Some(key) = key {
        if root
            .get("streams")
            .and_then(Value::as_array)
            .is_some_and(|streams| !streams.is_empty())
        {
            export_pipeline::retain_source_probe(key, root.clone());
        }
    }
    Ok(root)
}

fn fast_media_duration(ffprobe: &Path, input: &Path) -> Result<f64, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Probe);
    if let Some(inspection) = inspect_animated_webp_file(input) {
        return Ok(inspection.duration);
    }
    let root = source_probe_json(ffprobe, input)?;
    let stream_duration = root
        .get("streams")
        .and_then(Value::as_array)
        .and_then(|streams| streams.first())
        .and_then(|stream| json_f64(stream.get("duration")));
    let duration = stream_duration
        .or_else(|| json_f64(root.get("format").and_then(|format| format.get("duration"))))
        .filter(|duration| duration.is_finite() && *duration > 0.0)
        .ok_or_else(|| AppError::DecodeFailed("FFprobe reported no media duration".to_string()))?;
    Ok(duration)
}

fn fast_source_has_alpha_plane(ffprobe: &Path, input: &Path) -> Result<bool, AppError> {
    if let Some(inspection) = inspect_animated_webp_file(input) {
        return Ok(inspection.has_alpha);
    }
    let root = source_probe_json(ffprobe, input)?;
    let pixel_format = root
        .get("streams")
        .and_then(Value::as_array)
        .and_then(|streams| streams.first())
        .and_then(|stream| stream.get("pix_fmt"))
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| AppError::DecodeFailed("FFprobe reported no pixel format".to_string()))?;
    Ok(pixel_format_has_alpha(pixel_format))
}

fn estimated_perceptual_frame_count(source_duration: f64, request: &GifRequest) -> Option<usize> {
    if !source_duration.is_finite() || source_duration <= 0.0 {
        return None;
    }
    let start = request.start_seconds.max(0.0).min(source_duration);
    let end = if request.end_seconds > start {
        request.end_seconds.min(source_duration)
    } else {
        source_duration
    };
    let output_duration =
        ((end - start).max(0.0) / request.playback_speed.clamp(1.0, 3.0)).max(0.0);
    let fps = request.fps.clamp(1, 60);
    let estimate = (output_duration * f64::from(fps)).ceil();
    if !(estimate.is_finite() && estimate >= 0.0 && estimate <= usize::MAX as f64) {
        return None;
    }
    let estimate = estimate as usize;
    let deleted = deleted_frame_indices(request, fps)
        .into_iter()
        .filter(|index| (*index as usize) < estimate)
        .count();
    Some(estimate.saturating_sub(deleted))
}

fn gif_timeline_delays_cs(
    total_duration_cs: u64,
    frame_pts_us: &[i64],
) -> Result<Vec<u32>, AppError> {
    if frame_pts_us.is_empty() {
        return Err(AppError::Internal(
            "Perceptual GIF timeline has no frame timestamps".to_string(),
        ));
    }
    let mut quantized_pts = Vec::with_capacity(frame_pts_us.len());
    for pts_us in frame_pts_us {
        let pts_us = u64::try_from(*pts_us).map_err(|_| {
            AppError::Internal("Perceptual timeline has a negative PTS".to_string())
        })?;
        quantized_pts.push(pts_us.saturating_add(5_000) / 10_000);
    }
    let mut delays = Vec::with_capacity(quantized_pts.len());
    for pair in quantized_pts.windows(2) {
        let delay = pair[1]
            .checked_sub(pair[0])
            .filter(|delay| *delay > 0)
            .ok_or_else(|| {
                AppError::Internal(
                    "Perceptual frame timestamps collapse at GIF centisecond precision".to_string(),
                )
            })?;
        if delay > GIF_MAX_DELAY_CS {
            return Err(AppError::DecodeFailed(format!(
                "Perceptual hold of {delay} centiseconds exceeds GIF's {GIF_MAX_DELAY_CS}-centisecond frame-delay limit; used the CFR fallback"
            )));
        }
        delays.push(
            u32::try_from(delay)
                .map_err(|_| AppError::Internal("Perceptual frame delay overflow".to_string()))?,
        );
    }
    let final_delay = total_duration_cs
        .checked_sub(*quantized_pts.last().unwrap_or(&0))
        .filter(|delay| *delay > 0)
        .ok_or_else(|| {
            AppError::Internal(
                "Perceptual final delay does not fit the quantized GIF timeline".to_string(),
            )
        })?;
    if final_delay > GIF_MAX_DELAY_CS {
        return Err(AppError::DecodeFailed(format!(
            "Perceptual final hold of {final_delay} centiseconds exceeds GIF's {GIF_MAX_DELAY_CS}-centisecond frame-delay limit; used the CFR fallback"
        )));
    }
    delays.push(
        u32::try_from(final_delay)
            .map_err(|_| AppError::Internal("Perceptual final delay overflow".to_string()))?,
    );
    Ok(delays)
}

fn perceptual_analysis_filter(request: &GifRequest) -> String {
    let mut filters = timeline_filters(request);
    filters.push(format!(
        "scale={side}:{side}:force_original_aspect_ratio=decrease:flags=bilinear",
        side = PERCEPTUAL_ANALYSIS_SIDE
    ));
    filters.push(format!(
        "pad={side}:{side}:(ow-iw)/2:(oh-ih)/2:color=black",
        side = PERCEPTUAL_ANALYSIS_SIDE
    ));
    filters.push("format=rgb24".to_string());
    filters.join(",")
}

fn perceptual_palette_sample_filter(request: &GifRequest, encoder: &str) -> String {
    format!(
        "{},scale={side}:{side}:flags=area,format=rgb24",
        video_filter(request, encoder),
        side = PERCEPTUAL_PALETTE_SAMPLE_SIDE,
    )
}

fn json_f64(value: Option<&Value>) -> Option<f64> {
    value.and_then(|value| match value {
        Value::Number(number) => number.as_f64(),
        Value::String(text) => text.parse().ok(),
        _ => None,
    })
}

fn json_u64(value: Option<&Value>) -> Option<u64> {
    value.and_then(|value| match value {
        Value::Number(number) => number.as_u64(),
        Value::String(text) => text.parse().ok(),
        _ => None,
    })
}

fn parse_fraction(value: &str) -> Option<f64> {
    let (numerator, denominator) = value.split_once('/')?;
    let numerator: f64 = numerator.parse().ok()?;
    let denominator: f64 = denominator.parse().ok()?;
    (denominator.abs() > f64::EPSILON).then_some(numerator / denominator)
}

fn recording_state() -> &'static Mutex<RecordingState> {
    RECORDING.get_or_init(|| Mutex::new(RecordingState::Idle))
}

pub(crate) fn initialize_application_process_job() -> Result<(), AppError> {
    #[cfg(windows)]
    {
        let _initialization = APPLICATION_PROCESS_JOB_INIT.lock().map_err(|_| {
            AppError::Internal("Application process-job initialization is locked".to_string())
        })?;
        if APPLICATION_PROCESS_JOB.get().is_some() {
            return Ok(());
        }
        let job = KillOnCloseJob::attach_current_process().map_err(|error| {
            AppError::Internal(format!(
                "Could not place GIFP in its application process job: {error}"
            ))
        })?;
        if let Err(unexpected_job) = APPLICATION_PROCESS_JOB.set(job) {
            // Dropping a KILL_ON_JOB_CLOSE job containing the current process
            // would terminate this process. The mutex makes this unreachable,
            // but leaking is the only safe recovery if external initialization
            // ever races this path.
            std::mem::forget(unexpected_job);
        }
    }
    Ok(())
}

#[tauri::command]
pub async fn select_videos(window: tauri::Window) -> Result<Vec<String>, AppError> {
    project::select_media(window).await
}

#[tauri::command]
pub async fn open_directory(path: String) -> Result<(), AppError> {
    let target_text = path.trim().trim_matches(|ch| ch == '"' || ch == '\'');
    if target_text.is_empty() {
        return Ok(());
    }
    let target = Path::new(target_text);
    let dir = if target.is_file() {
        target.parent().unwrap_or_else(|| Path::new("."))
    } else {
        target
    };
    if !dir.exists() {
        return Err(AppError::InvalidInput(format!(
            "Directory does not exist: {}",
            dir.display()
        )));
    }
    Command::new("explorer")
        .arg(dir)
        .spawn()
        .map_err(|err| AppError::Internal(err.to_string()))?;
    Ok(())
}

#[tauri::command]
pub async fn select_output_dir(window: tauri::Window) -> Result<Option<String>, AppError> {
    project::select_directory(window).await
}

#[tauri::command]
pub async fn select_screen_region() -> Result<Option<ScreenRegion>, AppError> {
    if !cfg!(windows) {
        return Ok(None);
    }

    tauri::async_runtime::spawn_blocking(select_screen_region_inner)
        .await
        .map_err(|error| {
            AppError::Internal(format!("Screen region selector worker failed: {error}"))
        })?
}

fn select_screen_region_inner() -> Result<Option<ScreenRegion>, AppError> {
    let script = r#"
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class GifPDpi {
  [DllImport("Shcore.dll")]
  public static extern int SetProcessDpiAwareness(int value);
  [DllImport("user32.dll")]
  public static extern bool SetProcessDPIAware();
}
"@
try {
  [GifPDpi]::SetProcessDpiAwareness(2) | Out-Null
} catch {
  try { [GifPDpi]::SetProcessDPIAware() | Out-Null } catch {}
}
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()

$bounds = [System.Windows.Forms.SystemInformation]::VirtualScreen
$desktop = New-Object System.Drawing.Bitmap($bounds.Width, $bounds.Height)
$desktopGraphics = [System.Drawing.Graphics]::FromImage($desktop)
$desktopGraphics.CopyFromScreen($bounds.Location, [System.Drawing.Point]::Empty, $bounds.Size)
$dimmedDesktop = $desktop.Clone()
$dimGraphics = [System.Drawing.Graphics]::FromImage($dimmedDesktop)
$shade = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(112, 14, 22, 26))
$dimGraphics.FillRectangle($shade, 0, 0, $bounds.Width, $bounds.Height)
$shade.Dispose()
$dimGraphics.Dispose()
$desktopGraphics.Dispose()

$form = New-Object System.Windows.Forms.Form
$doubleBufferedProperty = [System.Windows.Forms.Control].GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic)
if ($doubleBufferedProperty) {
  $doubleBufferedProperty.SetValue($form, $true, $null)
}
$form.FormBorderStyle = 'None'
$form.StartPosition = 'Manual'
$form.Bounds = $bounds
$form.TopMost = $true
$form.Opacity = 1
$form.BackgroundImage = $dimmedDesktop
$form.BackgroundImageLayout = 'None'
$form.Cursor = [System.Windows.Forms.Cursors]::Cross
$form.KeyPreview = $true
$form.ShowInTaskbar = $false
$form.AutoScaleMode = 'None'

$script:start = $null
$script:current = $null
$script:done = $false
$script:cancel = $false
$script:selectionReady = $false
$script:dragging = $false
$script:paintPending = $false
$script:pendingPaintBounds = [System.Drawing.Rectangle]::Empty

function Get-GifPSelectionPaintBounds($startPoint, $endPoint) {
  if ($startPoint -eq $null -or $endPoint -eq $null) {
    return [System.Drawing.Rectangle]::Empty
  }
  $x = [Math]::Min($startPoint.X, $endPoint.X)
  $y = [Math]::Min($startPoint.Y, $endPoint.Y)
  $w = [Math]::Max(1, [Math]::Abs($startPoint.X - $endPoint.X))
  $h = [Math]::Max(1, [Math]::Abs($startPoint.Y - $endPoint.Y))
  $left = [Math]::Max(0, $x - 340)
  $top = [Math]::Max(0, $y - 56)
  $right = [Math]::Min($bounds.Width, $x + $w + 340)
  $bottom = [Math]::Min($bounds.Height, $y + $h + 56)
  return [System.Drawing.Rectangle]::FromLTRB($left, $top, $right, $bottom)
}

$hint = New-Object System.Windows.Forms.Label
$hint.AutoSize = $false
$hint.Width = 520
$hint.Height = 42
$hint.Left = [Math]::Max(16, [Math]::Floor(($bounds.Width - $hint.Width) / 2))
$hint.Top = 20
$hint.TextAlign = 'MiddleCenter'
$hint.Text = '拖拽选择录制范围 · 松开后确认 · Esc 取消'
$hint.ForeColor = [System.Drawing.Color]::FromArgb(255, 48, 72, 70)
$hint.BackColor = [System.Drawing.Color]::FromArgb(245, 255, 252, 245)
$hint.Font = New-Object System.Drawing.Font('Microsoft YaHei UI', 11, [System.Drawing.FontStyle]::Bold)
$form.Controls.Add($hint)

function New-GifPRegionButton([string]$text, [int]$left, [System.Drawing.Color]$backColor, [System.Drawing.Color]$foreColor) {
  $button = New-Object System.Windows.Forms.Button
  $button.Width = 112
  $button.Height = 42
  $button.Left = $left
  $button.Top = [Math]::Max(76, $bounds.Height - 68)
  $button.Text = $text
  $button.FlatStyle = 'Flat'
  $button.FlatAppearance.BorderSize = 0
  $button.BackColor = $backColor
  $button.ForeColor = $foreColor
  $button.Font = New-Object System.Drawing.Font('Microsoft YaHei UI', 10, [System.Drawing.FontStyle]::Bold)
  $button.Cursor = [System.Windows.Forms.Cursors]::Hand
  $button.Visible = $false
  $form.Controls.Add($button)
  return $button
}

$buttonStart = [Math]::Max(16, [Math]::Floor(($bounds.Width - 356) / 2))
$confirmButton = New-GifPRegionButton '确认范围' $buttonStart ([System.Drawing.Color]::FromArgb(255, 67, 166, 157)) ([System.Drawing.Color]::White)
$retryButton = New-GifPRegionButton '重新框选' ($buttonStart + 122) ([System.Drawing.Color]::FromArgb(255, 255, 252, 244)) ([System.Drawing.Color]::FromArgb(255, 69, 68, 62))
$cancelButton = New-GifPRegionButton '取消' ($buttonStart + 244) ([System.Drawing.Color]::FromArgb(255, 247, 224, 220)) ([System.Drawing.Color]::FromArgb(255, 142, 72, 68))

$selectionBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(38, 79, 183, 174))
$validPen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(255, 79, 183, 174), 4)
$invalidPen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(255, 236, 126, 118), 4)
$labelFont = New-Object System.Drawing.Font('Microsoft YaHei UI', 10, [System.Drawing.FontStyle]::Bold)
$labelBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(238, 26, 48, 50))
$labelTextBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)

$confirmButton.Add_Click({
  if ($script:selectionReady) {
    $script:done = $true
    $form.Close()
  }
})
$retryButton.Add_Click({
  $script:dragging = $false
  $form.Capture = $false
  $script:start = $null
  $script:current = $null
  $script:selectionReady = $false
  $confirmButton.Visible = $false
  $retryButton.Visible = $false
  $cancelButton.Visible = $false
  $hint.Text = '拖拽选择录制范围 · 松开后确认 · Esc 取消'
  $script:paintPending = $false
  $script:pendingPaintBounds = [System.Drawing.Rectangle]::Empty
  $form.Invalidate()
})
$cancelButton.Add_Click({
  $script:cancel = $true
  $form.Close()
})

$form.Add_KeyDown({
  if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape) {
    $script:cancel = $true
    $form.Close()
  } elseif ($_.KeyCode -eq [System.Windows.Forms.Keys]::Enter -and $script:selectionReady) {
    $script:done = $true
    $form.Close()
  }
})
$form.Add_MouseDown({
  if ($_.Button -ne [System.Windows.Forms.MouseButtons]::Left) { return }
  $script:dragging = $true
  $form.Capture = $true
  $script:start = New-Object System.Drawing.Point($_.X, $_.Y)
  $script:current = $script:start
  $script:selectionReady = $false
  $confirmButton.Visible = $false
  $retryButton.Visible = $false
  $cancelButton.Visible = $false
  $hint.Text = '正在框选…'
  $script:pendingPaintBounds = [System.Drawing.Rectangle]::Empty
  $script:paintPending = $true
})
$form.Add_MouseMove({
  if ($script:dragging -and $script:start -ne $null) {
    $oldPaintBounds = Get-GifPSelectionPaintBounds $script:start $script:current
    $nextPoint = [System.Drawing.Point]::new($_.X, $_.Y)
    $nextPaintBounds = Get-GifPSelectionPaintBounds $script:start $nextPoint
    $dirtyBounds = [System.Drawing.Rectangle]::Union($oldPaintBounds, $nextPaintBounds)
    if (-not $script:pendingPaintBounds.IsEmpty) {
      $dirtyBounds = [System.Drawing.Rectangle]::Union($script:pendingPaintBounds, $dirtyBounds)
    }
    $script:current = $nextPoint
    $script:pendingPaintBounds = $dirtyBounds
    $script:paintPending = $true
  }
})
$form.Add_MouseUp({
  if ($_.Button -ne [System.Windows.Forms.MouseButtons]::Left) { return }
  if ($script:dragging -and $script:start -ne $null) {
    $script:current = New-Object System.Drawing.Point($_.X, $_.Y)
    $script:dragging = $false
    $form.Capture = $false
    $w = [Math]::Abs($script:start.X - $script:current.X)
    $h = [Math]::Abs($script:start.Y - $script:current.Y)
    $script:selectionReady = $w -ge 120 -and $h -ge 120
    if ($script:selectionReady) {
      $hint.Text = "已选 $w × $h · Enter 确认，或重新框选"
      $confirmButton.Visible = $true
      $retryButton.Visible = $true
      $cancelButton.Visible = $true
      $confirmButton.Focus()
    } else {
      $hint.Text = '范围至少需要 120 × 120，请重新框选'
      $retryButton.Visible = $true
      $cancelButton.Visible = $true
    }
    $script:paintPending = $false
    $script:pendingPaintBounds = [System.Drawing.Rectangle]::Empty
    $form.Invalidate()
  }
})
$form.Add_Paint({
  if ($script:start -ne $null -and $script:current -ne $null) {
    $x = [Math]::Min($script:start.X, $script:current.X)
    $y = [Math]::Min($script:start.Y, $script:current.Y)
    $w = [Math]::Abs($script:start.X - $script:current.X)
    $h = [Math]::Abs($script:start.Y - $script:current.Y)
    $rect = New-Object System.Drawing.Rectangle($x, $y, $w, $h)
    if ($w -gt 0 -and $h -gt 0) {
      $_.Graphics.DrawImage($desktop, $rect, $rect, [System.Drawing.GraphicsUnit]::Pixel)
    }
    $pen = if ($script:selectionReady -or ($w -ge 120 -and $h -ge 120)) { $validPen } else { $invalidPen }
    $_.Graphics.FillRectangle($selectionBrush, $rect)
    $_.Graphics.DrawRectangle($pen, $rect)
    if ($w -gt 0 -and $h -gt 0) {
      $absoluteX = $x + $bounds.X
      $absoluteY = $y + $bounds.Y
      $labelText = "$w × $h   X $absoluteX   Y $absoluteY"
      $labelSize = $_.Graphics.MeasureString($labelText, $labelFont)
      $labelX = [Math]::Max(8, [Math]::Min($x, $bounds.Width - [Math]::Ceiling($labelSize.Width) - 22))
      $labelY = if ($y - 38 -ge 8) { $y - 38 } else { [Math]::Min($bounds.Height - 42, $y + 8) }
      $labelRect = New-Object System.Drawing.RectangleF($labelX, $labelY, $labelSize.Width + 18, 30)
      $_.Graphics.FillRectangle($labelBrush, $labelRect)
      $_.Graphics.DrawString($labelText, $labelFont, $labelTextBrush, $labelX + 9, $labelY + 5)
    }
  }
})

$paintTimer = New-Object System.Windows.Forms.Timer
$paintTimer.Interval = 16
$paintTimer.Add_Tick({
  if ($script:paintPending) {
    $script:paintPending = $false
    $dirtyBounds = $script:pendingPaintBounds
    $script:pendingPaintBounds = [System.Drawing.Rectangle]::Empty
    if ($dirtyBounds.IsEmpty) {
      $form.Invalidate()
    } else {
      $form.Invalidate($dirtyBounds)
    }
  }
})
$paintTimer.Start()

[void]$form.ShowDialog()
$paintTimer.Stop()
$paintTimer.Dispose()
$selectionBrush.Dispose()
$validPen.Dispose()
$invalidPen.Dispose()
$labelFont.Dispose()
$labelBrush.Dispose()
$labelTextBrush.Dispose()
$form.BackgroundImage = $null
$form.Dispose()
$dimmedDesktop.Dispose()
$desktop.Dispose()
if (-not $script:cancel -and $script:done -and $script:start -ne $null -and $script:current -ne $null) {
  $x = [Math]::Min($script:start.X, $script:current.X) + $bounds.X
  $y = [Math]::Min($script:start.Y, $script:current.Y) + $bounds.Y
  $w = [Math]::Abs($script:start.X - $script:current.X)
  $h = [Math]::Abs($script:start.Y - $script:current.Y)
  if ($w -ge 120 -and $h -ge 120) {
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
    Write-Output "$x,$y,$w,$h,$($bounds.X),$($bounds.Y),$($bounds.Width),$($bounds.Height)"
  }
}
"#;

    let output = Command::new("powershell")
        .arg("-NoProfile")
        .arg("-STA")
        .arg("-Command")
        .arg(script)
        .output_for_conversion_task()
        .map_err(|err| AppError::Internal(err.to_string()))?;

    if !output.status.success() {
        return Err(AppError::Internal(
            String::from_utf8_lossy(&output.stderr).to_string(),
        ));
    }

    let text = String::from_utf8_lossy(&output.stdout);
    let Some(line) = text.lines().map(str::trim).find(|line| !line.is_empty()) else {
        return Ok(None);
    };
    let values: Vec<i32> = line
        .split(',')
        .filter_map(|part| part.trim().parse::<i32>().ok())
        .collect();
    if values.len() != 8 {
        return Ok(None);
    }

    Ok(Some(ScreenRegion {
        x: values[0],
        y: values[1],
        width: values[2].max(0) as u32,
        height: values[3].max(0) as u32,
        screen_x: values[4],
        screen_y: values[5],
        screen_width: values[6].max(0) as u32,
        screen_height: values[7].max(0) as u32,
    }))
}

