#[tauri::command]
pub async fn generate_cutout_preview(
    request: CutoutPreviewRequest,
) -> Result<CutoutPreviewResult, AppError> {
    tauri::async_runtime::spawn_blocking(move || generate_cutout_preview_inner(request))
        .await
        .map_err(|error| AppError::Internal(format!("Cutout preview worker failed: {error}")))?
}

fn generate_cutout_preview_inner(
    request: CutoutPreviewRequest,
) -> Result<CutoutPreviewResult, AppError> {
    let input_text = request
        .input_path
        .trim()
        .trim_matches(|character| character == '"' || character == '\'');
    let input = Path::new(input_text);
    if !input.exists() || !input.is_file() {
        return Err(AppError::InvalidInput(format!(
            "Input file does not exist: {}",
            input.display()
        )));
    }
    if !is_media_source(input) {
        return Err(AppError::UnsupportedVideo(format!(
            "Unsupported cutout preview media: {}",
            input.display()
        )));
    }
    if !request.time_seconds.is_finite() || request.time_seconds < 0.0 {
        return Err(AppError::InvalidInput(
            "Cutout preview time must be a finite non-negative value.".to_string(),
        ));
    }
    if !request
        .settings
        .mode
        .trim()
        .eq_ignore_ascii_case("color_key")
    {
        return Err(AppError::InvalidInput(
            "Cutout preview currently supports color-key settings only.".to_string(),
        ));
    }
    validate_background_removal_settings(&request.settings)?;
    let (_, normalized_key) = normalized_background_key_color(&request.settings.key_color)
        .ok_or_else(|| AppError::InvalidInput("Invalid cutout key color.".to_string()))?;
    let preview_root = env::temp_dir().join("gifp-cutout-previews");
    fs::create_dir_all(&preview_root).map_err(|error| {
        AppError::Internal(format!(
            "Could not create cutout preview directory: {error}"
        ))
    })?;
    let now = SystemTime::now();
    if let Ok(entries) = fs::read_dir(&preview_root) {
        for entry in entries.flatten() {
            let path = entry.path();
            let stale = entry
                .metadata()
                .ok()
                .and_then(|metadata| metadata.modified().ok())
                .and_then(|modified| now.duration_since(modified).ok())
                .is_some_and(|age| age > Duration::from_secs(24 * 60 * 60));
            if stale && path.extension().and_then(|value| value.to_str()) == Some("png") {
                let _ = fs::remove_file(path);
            }
        }
    }
    let output = preview_root.join(format!(
        "cutout-{}-{}.png",
        std::process::id(),
        unique_output_token()
    ));
    let max_width = request.max_width.clamp(160, 1280);
    let mut filters = background_removal_filters_for(&request.settings);
    filters.push(format!(
        "scale={max_width}:-2:flags=lanczos:force_original_aspect_ratio=decrease"
    ));
    let command_output = Command::new(locate_ffmpeg()?)
        .args(["-hide_banner", "-loglevel", "error", "-ss"])
        .arg(format!("{:.6}", request.time_seconds))
        .args(animation_demux_args(input))
        .arg("-i")
        .arg(input)
        .args(["-frames:v", "1", "-vf"])
        .arg(filters.join(","))
        .args(["-c:v", "png", "-update", "1", "-y"])
        .arg(&output)
        .output()
        .map_err(|error| {
            AppError::EncodeFailed(format!("Could not start cutout preview: {error}"))
        })?;
    if !command_output.status.success() || !output.is_file() {
        let message = String::from_utf8_lossy(&command_output.stderr)
            .trim()
            .to_string();
        return Err(AppError::EncodeFailed(if message.is_empty() {
            "FFmpeg did not create a cutout preview.".to_string()
        } else {
            format!("Cutout preview failed: {message}")
        }));
    }
    Ok(CutoutPreviewResult {
        path: output.display().to_string(),
        time_seconds: request.time_seconds,
        key_color: format!("#{normalized_key}"),
    })
}

#[tauri::command]
pub async fn inspect_media(input_path: String) -> Result<MediaInspection, AppError> {
    tauri::async_runtime::spawn_blocking(move || {
        let input_text = input_path
            .trim()
            .trim_matches(|character| character == '"' || character == '\'');
        let input = Path::new(input_text);
        if !input.exists() || !input.is_file() {
            return Err(AppError::InvalidInput(format!(
                "Input file does not exist: {}",
                input.display()
            )));
        }
        let mut inspection = inspect_media_file_fast(&locate_ffprobe()?, input)?;
        if inspection.has_alpha {
            inspection.has_alpha =
                source_uses_transparency(&locate_ffmpeg()?, input, &[]).unwrap_or(true);
        }
        Ok(inspection)
    })
    .await
    .map_err(|error| AppError::Internal(format!("Media inspection worker failed: {error}")))?
}

#[tauri::command]
pub async fn evaluate_output_quality(
    request: OutputQualityRequest,
) -> Result<OutputQualityReport, AppError> {
    let task_scope = ConversionTaskScope::register(request.encode_request.task_id.as_deref())?;
    tauri::async_runtime::spawn_blocking(move || {
        task_scope.activate();
        evaluate_output_quality_inner_active(request)
    })
    .await
    .map_err(|error| AppError::Internal(format!("Quality scoring worker failed: {error}")))?
}

#[cfg(test)]
fn evaluate_output_quality_inner(
    request: OutputQualityRequest,
) -> Result<OutputQualityReport, AppError> {
    let task_scope = ConversionTaskScope::register(request.encode_request.task_id.as_deref())?;
    task_scope.activate();
    evaluate_output_quality_inner_active(request)
}

fn evaluate_output_quality_inner_active(
    request: OutputQualityRequest,
) -> Result<OutputQualityReport, AppError> {
    const MAX_QUALITY_SAMPLE_SECONDS: f64 = 30.0;
    check_conversion_cancelled()?;
    let started = Instant::now();
    let input = Path::new(request.encode_request.input_path.trim());
    let output = Path::new(request.output_path.trim());
    if !input.is_file() || !output.is_file() {
        return Err(AppError::InvalidInput(
            "Quality scoring requires existing source and output files".to_string(),
        ));
    }
    let ffmpeg = locate_ffmpeg()?;
    let ffprobe = locate_ffprobe()?;
    let temp = OwnedTempDir::create("gif-p-quality-stamp")?;
    let reference = temp.path().join("reference.mkv");
    let filter = video_filter(&request.encode_request, "modern");
    let reference_args = vec![
        "-vf".to_string(),
        filter,
        "-an".to_string(),
        "-sn".to_string(),
        "-t".to_string(),
        MAX_QUALITY_SAMPLE_SECONDS.to_string(),
        "-c:v".to_string(),
        "ffv1".to_string(),
        "-level".to_string(),
        "3".to_string(),
        "-pix_fmt".to_string(),
        "bgra".to_string(),
    ];
    if let Err(error) = run_ffmpeg_owned(
        &ffmpeg,
        input,
        &source_time_args(&request.encode_request),
        &reference_args,
        &reference,
    ) {
        check_conversion_cancelled()?;
        return Ok(unavailable_quality_report(started, error.to_string()));
    }
    let reference_inspection = match inspect_media_file(&ffprobe, &reference) {
        Ok(inspection) => inspection,
        Err(error) => {
            check_conversion_cancelled()?;
            return Ok(unavailable_quality_report(started, error.to_string()));
        }
    };
    let output_inspection = match inspect_media_file(&ffprobe, output) {
        Ok(inspection) => inspection,
        Err(error) => {
            check_conversion_cancelled()?;
            return Ok(unavailable_quality_report(started, error.to_string()));
        }
    };
    let duration_seconds = reference_inspection
        .duration
        .min(output_inspection.duration)
        .min(MAX_QUALITY_SAMPLE_SECONDS);
    let objective = match evaluate_quality(
        &ffmpeg,
        &reference,
        output,
        &reference_inspection,
        &output_inspection,
        duration_seconds,
        temp.path(),
    ) {
        Ok(metrics) => metrics,
        Err(error) => {
            check_conversion_cancelled()?;
            return Ok(unavailable_quality_report(started, error));
        }
    };
    Ok(OutputQualityReport {
        status: "measured".to_string(),
        metric_model: "VMAF NEG v0.6.1 · float SSIM".to_string(),
        sample_duration_seconds: duration_seconds,
        compared_frames: objective.compared_frames,
        vmaf_mean: Some(objective.vmaf_neg_mean),
        vmaf_p05: Some(objective.vmaf_neg_p05),
        ssim_mean: Some(objective.ssim_mean),
        ms_ssim_mean: objective.ms_ssim_mean,
        elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
        message: None,
    })
}

fn unavailable_quality_report(started: Instant, message: String) -> OutputQualityReport {
    OutputQualityReport {
        status: "unavailable".to_string(),
        metric_model: "VMAF NEG v0.6.1 · float SSIM".to_string(),
        sample_duration_seconds: 0.0,
        compared_frames: 0,
        vmaf_mean: None,
        vmaf_p05: None,
        ssim_mean: None,
        ms_ssim_mean: None,
        elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
        message: Some(message.chars().take(600).collect()),
    }
}

#[tauri::command]
pub async fn convert_gif(mut request: GifRequest) -> Result<GifResult, AppError> {
    request.output_format = "gif".to_string();
    let task_scope = ConversionTaskScope::register(request.task_id.as_deref())?;
    tauri::async_runtime::spawn_blocking(move || {
        task_scope.activate();
        convert_animation_inner_active(request)
    })
    .await
    .map_err(|error| AppError::Internal(format!("Encoding worker failed: {error}")))?
}

#[tauri::command]
pub async fn convert_animation(request: GifRequest) -> Result<GifResult, AppError> {
    let task_scope = ConversionTaskScope::register(request.task_id.as_deref())?;
    tauri::async_runtime::spawn_blocking(move || {
        task_scope.activate();
        convert_animation_inner_active(request)
    })
    .await
    .map_err(|error| AppError::Internal(format!("Encoding worker failed: {error}")))?
}

pub(crate) fn convert_animation_inner(request: GifRequest) -> Result<GifResult, AppError> {
    let task_scope = ConversionTaskScope::register(request.task_id.as_deref())?;
    task_scope.activate();
    convert_animation_inner_active(request)
}

fn convert_animation_inner_active(request: GifRequest) -> Result<GifResult, AppError> {
    let cache_limit = palette_cache_limit_for(&request);
    convert_animation_with_cache_limit(request, cache_limit)
}

fn palette_cache_limit_for(request: &GifRequest) -> usize {
    // Repeat palettes were measured in target-size search. Other modes do not
    // retain speculative artifacts.
    if request.output_format.eq_ignore_ascii_case("gif") && request.generation_mode == "target_size"
    {
        PALETTE_CACHE_LIMIT_BYTES
    } else {
        0
    }
}

fn convert_animation_with_cache_limit(
    request: GifRequest,
    cache_limit: usize,
) -> Result<GifResult, AppError> {
    convert_animation_with_probe_policy(request, cache_limit, true)
}

fn convert_animation_with_probe_policy(
    request: GifRequest,
    cache_limit: usize,
    reuse_probes: bool,
) -> Result<GifResult, AppError> {
    let pipeline = PipelineScope::start(cache_limit);
    if !reuse_probes {
        pipeline.disable_source_probe_cache();
    }
    let mut result = convert_animation_unprofiled(request)?;
    result.pipeline_profile = Some(pipeline.report());
    Ok(result)
}

fn convert_animation_unprofiled(mut request: GifRequest) -> Result<GifResult, AppError> {
    let _active_conversion = ActiveConversionGuard::start();
    check_conversion_cancelled()?;
    let started = Instant::now();
    if request.schema_version != ENCODE_REQUEST_SCHEMA_VERSION {
        return Err(AppError::InvalidInput(format!(
            "Unsupported encode request schema {}. GIFP 5.0 Preview accepts schema {}.",
            request.schema_version, ENCODE_REQUEST_SCHEMA_VERSION
        )));
    }
    let output_format = AnimationFormat::parse(&request.output_format)?;
    if (request.temporal_stability
        || request.lzw_search
        || request.smart_lossless
        || request.index_compression
        || request.index_compression_gentle
        || request.gif_merge_frames
        || request.gif_compact_palette)
        && output_format != AnimationFormat::Gif
    {
        return Err(AppError::InvalidInput("压缩工具仅支持 GIF 输出".into()));
    }
    if request.smaller_gif && output_format != AnimationFormat::Gif {
        return Err(AppError::InvalidInput("更小优先仅支持 GIF 输出".into()));
    }
    if request.index_compression_gentle && !request.index_compression {
        return Err(AppError::InvalidInput("温和模式需要开启索引压缩".into()));
    }
    validate_background_removal(&request, output_format)?;
    validate_tracked_effects(&request)?;
    let input_text = request
        .input_path
        .trim()
        .trim_matches(|ch| ch == '"' || ch == '\'')
        .to_string();
    let input_path = PathBuf::from(&input_text);
    let input = input_path.as_path();
    if !input.exists() || !input.is_file() {
        return Err(AppError::InvalidInput(format!(
            "Input file does not exist: {}",
            input.display()
        )));
    }
    if !is_media_source(input) {
        return Err(AppError::UnsupportedVideo(format!(
            "Unsupported media: {}",
            input.display()
        )));
    }

    let output_dir = if request.output_dir.trim().is_empty() {
        input
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .to_path_buf()
    } else {
        PathBuf::from(request.output_dir.trim())
    };
    prepare_writable_output_directory(&output_dir, "export")?;

    let backends = discover_backends();
    let ffmpeg_capability = backends
        .iter()
        .find(|backend| backend.id == "ffmpeg.animation")
        .ok_or_else(|| {
            AppError::MissingDependency("FFmpeg capability discovery failed".to_string())
        })?;
    let ffmpeg_features = ffmpeg_capability.features;
    let (ffmpeg, discovered_ffmpeg_version) =
        available_backend_executable(&backends, "ffmpeg.animation").ok_or_else(|| {
            let reason = match &ffmpeg_capability.status {
                BackendStatus::Unavailable { reason } | BackendStatus::Planned { reason } => {
                    reason.as_str()
                }
                BackendStatus::Available { .. } => "the executable path was not reported",
            };
            AppError::MissingDependency(format!("FFmpeg is not usable: {reason}"))
        })?;
    if !ffmpeg_features.production_filter_chain || !ffmpeg_features.production_io_chain {
        return Err(AppError::MissingDependency(
            "The discovered FFmpeg build is missing part of GIFP's production filter or media I/O closure (filters, protocols, parsers, demuxers, decoders, encoders, muxers, or lavfi). Use the bundled GIFP FFmpeg runtime."
                .to_string(),
        ));
    }
    if !matches!(request.frame_timing_mode.as_str(), "compact" | "preserve") {
        return Err(AppError::InvalidInput(
            "Frame timing mode must be compact or preserve".to_string(),
        ));
    }
    if deletions_cover_requested_timeline(&request, request.fps.clamp(1, 60)) {
        return Err(AppError::InvalidInput(
            "Frame deletion must keep at least one playable output frame".to_string(),
        ));
    }
    if request.frame_timing_mode == "preserve"
        && preserve_timing_deletes_boundary(&request, request.fps.clamp(1, 60))
    {
        return Err(AppError::InvalidInput(
            "Duration-preserving frame deletion must retain the first and final output frames"
                .to_string(),
        ));
    }
    let required_capability_format = match output_format {
        AnimationFormat::Gif => CapabilityOutputFormat::Gif,
        AnimationFormat::Webp => CapabilityOutputFormat::Webp,
        AnimationFormat::Avif => CapabilityOutputFormat::Avif,
        AnimationFormat::Apng => CapabilityOutputFormat::Apng,
        AnimationFormat::Mp4 => CapabilityOutputFormat::Mp4,
        AnimationFormat::Webm => CapabilityOutputFormat::Webm,
        AnimationFormat::LivePhoto => CapabilityOutputFormat::LivePhoto,
    };
    if !ffmpeg_capability
        .formats
        .contains(&required_capability_format)
    {
        let runtime_hint = if output_format == AnimationFormat::Mp4 {
            " The FFmpeg build must include libx264 or h264_mf, and Windows N/KN/Server systems may need the Media Feature Pack before Media Foundation can encode."
        } else {
            ""
        };
        return Err(AppError::MissingDependency(format!(
            "The discovered FFmpeg build does not provide the encoder and muxer required for {} output.{runtime_hint}",
            output_format.wire_name().to_ascii_uppercase(),
        )));
    }
    let meme_overlay_requested = request.meme_overlay.as_ref().is_some_and(|overlay| {
        !overlay.top_text.trim().is_empty() || !overlay.bottom_text.trim().is_empty()
    });
    let tracked_label_requested = request
        .tracked_effects
        .iter()
        .any(|effect| effect.kind.eq_ignore_ascii_case("label") && !effect.label.trim().is_empty());
    if (meme_overlay_requested || tracked_label_requested) && !ffmpeg_features.subtitle_overlay {
        return Err(AppError::MissingDependency(
            "The discovered FFmpeg build cannot burn captions because its libass `ass` filter with alpha processing is unavailable. Use the bundled GIFP FFmpeg build or install an FFmpeg build with libass."
                .to_string(),
        ));
    }
    if active_background_removal(&request).is_some() && !ffmpeg_features.background_keying {
        return Err(AppError::MissingDependency(
            "The discovered FFmpeg build does not provide the colorkey and despill filters required for character cutout. Use the bundled GIFP FFmpeg runtime."
                .to_string(),
        ));
    }
    let tracked_effects_requested = !request.tracked_effects.is_empty();
    let needs_overlay_dimensions =
        meme_overlay_requested || tracked_label_requested || tracked_effects_requested;
    let source_dimensions = if needs_overlay_dimensions {
        Some(probe_display_dimensions(&locate_ffprobe()?, input)?)
    } else {
        None
    };
    let meme_play_resolution = source_dimensions.map_or((420, 236), |(width, height)| {
        meme_overlay_play_resolution_for_dimensions(width, height, &request)
    });
    if tracked_effects_requested {
        request.tracked_canvas_aspect = source_dimensions
            .map(|(width, height)| cropped_source_aspect_for_dimensions(width, height, &request));
    }
    let _meme_overlay_file = prepare_meme_overlay(&output_dir, &mut request, meme_play_resolution)?;
    let _tracked_overlay_file =
        prepare_tracked_overlay(&output_dir, &mut request, meme_play_resolution)?;
    if output_format == AnimationFormat::LivePhoto {
        return convert_live_photo_animation(
            started,
            &ffmpeg,
            discovered_ffmpeg_version,
            input,
            &output_dir,
            &request,
        );
    }
    if output_format != AnimationFormat::Gif {
        return convert_modern_animation(
            started,
            &ffmpeg,
            discovered_ffmpeg_version,
            input,
            &output_dir,
            &request,
            output_format,
        );
    }
    let generation_mode = generation_mode_for(&request)?;
    let source_args = source_time_args(&request);
    let mut warnings = Vec::new();
    let _probe_stage = export_pipeline::stage(Phase::Probe);
    let content_probe = match probe_content(&ffmpeg, input, &source_args) {
        Ok(probe) => probe,
        Err(error) => {
            check_conversion_cancelled()?;
            warnings.push(format!(
                "Quick content classification failed ({error}); used conservative FFmpeg defaults."
            ));
            QuickContentProbe::fallback()
        }
    };
    drop(_probe_stage);
    let content_profile = classify_content(&content_probe);
    let requested_legacy_encoder = choose_encoder(&request);
    let needs_alpha_classification = active_background_removal(&request).is_some()
        || matches!(
            generation_mode,
            GifGenerationMode::Best | GifGenerationMode::Target
        )
        || requested_legacy_encoder != "ffmpeg_fast";
    let source_uses_transparency =
        needs_alpha_classification && gif_timeline_uses_transparency(&ffmpeg, input, &request);
    let mut effective_request = request.clone();
    let legacy_encoder = if source_uses_transparency {
        if requested_legacy_encoder != "ffmpeg_fast" {
            warnings.push(
                "Disabled RGB cleanup filters because they do not preserve the source alpha plane; used the FFmpeg alpha-safe filter chain."
                    .to_string(),
            );
        }
        if !style_filters(&effective_request.filter_style).is_empty() {
            warnings.push(
                "Disabled the selected visual style because its RGB filters do not preserve the source alpha plane."
                    .to_string(),
            );
            effective_request.filter_style = "original".to_string();
        }
        "ffmpeg_fast"
    } else {
        requested_legacy_encoder
    };
    let mut perceptual_report = None;
    let mut palette_report = None;
    let mut region_dither_report = None;
    let mut indexed_gif_writer_report = None;
    let mut motion_delivery_selection_report = None;
    let mut palette_reservation_selection_report = None;
    let mut perceptual_failure = None;
    let quick_smooth_gradient_quality_floor = generation_mode == GifGenerationMode::Best
        && !source_uses_transparency
        && dither_for(&request) == "sierra2_4a"
        && quick_probe_prefers_smooth_gradient_quality_floor(content_profile, &content_probe);
    if generation_mode == GifGenerationMode::Best {
        PerceptualFocus::parse(&request.perceptual_focus)
            .map_err(|error| AppError::InvalidInput(error.to_string()))?;
        if !source_uses_transparency && !quick_smooth_gradient_quality_floor {
            match build_perceptual_timeline(
                &ffmpeg,
                input,
                &request,
                source_uses_transparency,
                true,
            ) {
                Ok((
                    selection,
                    report,
                    planned_palette,
                    planned_regions,
                    opaque_palette_candidate,
                )) => {
                    effective_request.perceptual_selection = Some(selection);
                    effective_request.perceptual_opaque_palette_candidate =
                        opaque_palette_candidate;
                    perceptual_report = Some(report);
                    palette_report = planned_palette;
                    region_dither_report = planned_regions;
                }
                Err(error) => {
                    check_conversion_cancelled()?;
                    perceptual_failure = Some(error.to_string());
                }
            }
        }
    }

    let smooth_gradient_quality_floor_selected = quick_smooth_gradient_quality_floor
        || perceptual_report
            .as_ref()
            .is_some_and(|report| prefer_smooth_gradient_quality_floor(content_profile, report));
    let smooth_gradient_opaque_route_selected = smooth_gradient_quality_floor_selected
        && !source_uses_transparency
        && dither_for(&request) == "sierra2_4a";
    let smooth_gradient_frame_palette_selected = smooth_gradient_opaque_route_selected
        && smooth_gradient_frame_palette_is_affordable(&effective_request);
    if smooth_gradient_quality_floor_selected {
        // The animated smooth-gradient pilot showed that the global OKLab
        // candidate could materially raise presentation error. Use the
        // verified Sierra Best floor directly, avoiding both that dominated
        // encode and the later comparison encode. Static gradients keep their
        // internally Pareto-verified indexed-writer route.
        effective_request.perceptual_selection = None;
        effective_request.perceptual_opaque_palette_candidate = None;
        perceptual_report = None;
        palette_report = None;
        region_dither_report = None;
    }

    let plan = plan_ffmpeg_gif(&StrategyInput {
        mode: generation_mode,
        content_profile,
        bayer_scale: i32::from(request.bayer_scale),
        alpha_threshold: i32::from(request.alpha_threshold),
        allow_single_palette: effective_request.perceptual_selection.is_none()
            && request.allow_experimental
            && request.optimize_level >= 4,
        supports_single_palette: ffmpeg_features.per_frame_palettes,
        supports_diff_rectangle: ffmpeg_features.partial_frame_rectangles,
    });
    let baseline_segment_cuts = if generation_mode == GifGenerationMode::Best
        && content_profile == ContentProfile::FrequentSceneChanges
        && !plan.requires_frame_synchronized_palette()
    {
        normalized_segment_cuts(&request, &content_probe)
    } else {
        Vec::new()
    };
    let active_segment_cuts = if effective_request.perceptual_selection.is_some() {
        Vec::new()
    } else {
        baseline_segment_cuts.clone()
    };
    let final_output = next_output_path(input, &output_dir);
    let export_temp = Some(OwnedTempDir::create("gif-p-export")?);
    let output = export_temp
        .as_ref()
        .map(|temp| temp.path().join("candidate.gif"))
        .unwrap_or_else(|| final_output.clone());
    if generation_mode == GifGenerationMode::Best
        && content_profile == ContentProfile::FrequentSceneChanges
        && (!request.deleted_frames.is_empty() || !request.deleted_ranges.is_empty())
        && baseline_segment_cuts.is_empty()
    {
        warnings.push(
            "Segment palettes were disabled because manual frame deletion changes scene timing."
                .to_string(),
        );
    }
    let mut fallback_reason = plan.fallback_reason.clone();
    if let Some(reason) = perceptual_failure.as_deref() {
        fallback_reason = append_reason(
            fallback_reason,
            &format!(
                "rust.perceptual analysis failed ({reason}); used the FFmpeg quality baseline."
            ),
        );
    }
    let mut backend_id = "ffmpeg.animation".to_string();
    let ffmpeg_backend_version = discovered_ffmpeg_version.or_else(|| ffmpeg_version(&ffmpeg));
    let mut backend_version = ffmpeg_backend_version.clone();
    let mut encoder_used = legacy_encoder.to_string();
    // Track the actual prequantization filter chain through every fallback.
    // Route names and the originally requested encoder are not sufficient.
    let mut reference_filter_encoder = legacy_encoder;
    let mut reference_is_segmented = !baseline_segment_cuts.is_empty();
    let baseline_palette_strategy = if baseline_segment_cuts.is_empty() {
        plan.stats_mode.as_ffmpeg_value().to_string()
    } else {
        "segmented_full".to_string()
    };
    let mut palette_strategy = if active_segment_cuts.is_empty() {
        plan.stats_mode.as_ffmpeg_value().to_string()
    } else {
        "segmented_full".to_string()
    };

    let mut perceptual_outcome = None;
    if generation_mode == GifGenerationMode::Best
        && effective_request.perceptual_selection.is_some()
    {
        let perceptual_encoder = perceptual_filter_encoder(&effective_request, legacy_encoder);
        let writer_artifact = effective_request
            .perceptual_selection
            .as_ref()
            .and_then(|selection| selection.palette.clone());
        let uses_oklab_palette = writer_artifact.is_some();
        let default_static_gradient_writer = perceptual_report
            .as_ref()
            .is_some_and(|report| report.static_gradient_writer_recommended);
        let writer_requested = (request.allow_experimental || default_static_gradient_writer)
            && !source_uses_transparency
            // The indexed writer's temporal and regional paths intentionally
            // reserve index 255. A one-frame full-256 palette is encoded by
            // the verified FFmpeg global-palette path below instead.
            && writer_artifact
                .as_ref()
                .is_some_and(oklab_palette_reserves_transparency);
        let mut writer_succeeded = false;
        if let Some(artifact) = writer_artifact.as_ref().filter(|_| writer_requested) {
            match encode_with_rust_indexed_writer(
                &ffmpeg,
                input,
                &output,
                &effective_request,
                perceptual_encoder,
                &plan,
                artifact,
            ) {
                Ok(report) => {
                    let route_metadata = rust_writer_route_metadata(&report);
                    if let (Some(region_report), Some(quantizer)) = (
                        region_dither_report.as_mut(),
                        report.regional_quantizer_report.as_ref(),
                    ) {
                        region_report.status = quantizer.status.clone();
                        region_report.fallback_reason = quantizer.fallback_reason.clone();
                    }
                    if let (Some(palette_report), Some(mapper)) = (
                        palette_report.as_mut(),
                        report.palette_mapper_selection_report.as_ref(),
                    ) {
                        let selected = if mapper.selected_histogram_precision_bits == 5 {
                            &mapper.baseline
                        } else {
                            &mapper.candidate
                        };
                        palette_report.histogram_precision_bits = selected.histogram_precision_bits;
                        palette_report.artifact_hashes = vec![selected.palette_sha256.clone()];
                        palette_report.emitted_colors = selected.emitted_colors;
                        palette_report.weighted_histogram_mean_oklab_error =
                            selected.weighted_histogram_mean_oklab_error;
                        palette_report.weighted_histogram_p95_oklab_error =
                            selected.weighted_histogram_p95_oklab_error;
                    }
                    if let (Some(palette_report), Some(segment)) = (
                        palette_report.as_mut(),
                        report.segment_palette_report.as_ref(),
                    ) {
                        palette_report.candidate_status = segment.status.clone();
                        palette_report.candidate_fallback_reason = segment.fallback_reason.clone();
                        if route_metadata.segment_encoded {
                            palette_report.strategy = "segmented_local".to_string();
                            palette_report.segment_count = segment.segment_count;
                        }
                    }
                    if route_metadata.segment_encoded {
                        if let Some(region_report) = region_dither_report.as_mut() {
                            region_report.status = "encoded".to_string();
                            region_report.fallback_reason = None;
                        }
                    }
                    backend_id = if request.allow_experimental {
                        "rust.indexed_gif.experimental"
                    } else {
                        "rust.indexed_gif"
                    }
                    .to_string();
                    backend_version = Some(env!("CARGO_PKG_VERSION").to_string());
                    encoder_used = route_metadata.encoder_used.to_string();
                    reference_filter_encoder = perceptual_encoder;
                    reference_is_segmented = route_metadata.segment_encoded;
                    palette_strategy = route_metadata.palette_strategy.to_string();
                    indexed_gif_writer_report = Some(report);
                    perceptual_outcome = Some(single_encode_outcome(&output, &effective_request));
                    writer_succeeded = true;
                }
                Err(error) => {
                    check_conversion_cancelled()?;
                    let reason = error.to_string();
                    fallback_reason = append_reason(
                        fallback_reason,
                        &format!(
                            "rust.indexed_gif writer failed ({reason}); used the verified FFmpeg GIF writer."
                        ),
                    );
                    indexed_gif_writer_report = Some(failed_indexed_writer_report(reason));
                }
            }
        }
        if !writer_succeeded {
            match encode_ffmpeg_with_strategy(
                &ffmpeg,
                input,
                &output,
                &effective_request,
                perceptual_encoder,
                &plan,
                &active_segment_cuts,
            ) {
                Ok(()) => {
                    backend_id = "rust.perceptual".to_string();
                    reference_filter_encoder = perceptual_encoder;
                    reference_is_segmented = !active_segment_cuts.is_empty();
                    backend_version = Some(env!("CARGO_PKG_VERSION").to_string());
                    if uses_oklab_palette {
                        encoder_used = "rust_perceptual_oklab_ffmpeg".to_string();
                        palette_strategy = "perceptual_vfr+oklab_global+ffmpeg".to_string();
                    } else {
                        encoder_used = if perceptual_encoder == "ffmpeg_fast"
                            && legacy_encoder != "ffmpeg_fast"
                        {
                            "rust_perceptual_neutral_ffmpeg".to_string()
                        } else {
                            "rust_perceptual_ffmpeg".to_string()
                        };
                        palette_strategy = format!(
                            "perceptual_vfr+ffmpeg_{}",
                            plan.stats_mode.as_ffmpeg_value()
                        );
                    }
                    let motion_report = if request.allow_experimental
                        && !source_uses_transparency
                        && !uses_oklab_palette
                    {
                        perceptual_report
                            .as_ref()
                            .filter(|report| report.focus == "motion")
                            .cloned()
                    } else {
                        None
                    };
                    if let Some(motion_report) = motion_report.as_ref() {
                        match attempt_motion_delivery_selection(
                            &ffmpeg,
                            input,
                            &output,
                            &effective_request,
                            perceptual_encoder,
                            motion_report,
                            &plan,
                        ) {
                            Ok(selection_report) => {
                                if selection_report.status == "candidate_selected" {
                                    if let (Some(report), Some(candidate)) = (
                                        perceptual_report.as_mut(),
                                        selection_report.candidate.as_ref(),
                                    ) {
                                        report.filter_strategy = candidate.filter_strategy.clone();
                                        report.effective_dither = candidate.dither.clone();
                                        report.effective_bayer_scale = candidate.bayer_scale;
                                    }
                                    backend_id =
                                        "rust.perceptual.motion_selector.experimental".to_string();
                                    backend_version = Some(env!("CARGO_PKG_VERSION").to_string());
                                    encoder_used =
                                        "rust_perceptual_motion_neutral_bayer".to_string();
                                    reference_filter_encoder = "ffmpeg_fast";
                                    palette_strategy = format!(
                                        "perceptual_vfr+ffmpeg_{}+motion_neutral_bayer",
                                        plan.stats_mode.as_ffmpeg_value()
                                    );
                                }
                                motion_delivery_selection_report = Some(selection_report);
                            }
                            Err(error) => {
                                check_conversion_cancelled()?;
                                motion_delivery_selection_report = Some(
                                    failed_motion_delivery_selection_report(error.to_string()),
                                );
                            }
                        }
                    }
                    perceptual_outcome = Some(single_encode_outcome(&output, &effective_request));
                }
                Err(error) => {
                    check_conversion_cancelled()?;
                    fallback_reason = append_reason(
                        fallback_reason,
                        &format!(
                            "rust.perceptual VFR encode failed ({error}); used the FFmpeg quality baseline."
                        ),
                    );
                    effective_request.perceptual_selection = None;
                    effective_request.perceptual_opaque_palette_candidate = None;
                    perceptual_report = None;
                    palette_report = None;
                }
            }
        }
    }

    let mut outcome = if let Some(outcome) = perceptual_outcome {
        outcome
    } else if generation_mode == GifGenerationMode::Target {
        encode_to_target_size(
            &ffmpeg,
            input,
            &output,
            &effective_request,
            legacy_encoder,
            &plan,
            source_uses_transparency,
        )?
    } else {
        if smooth_gradient_opaque_route_selected {
            if smooth_gradient_frame_palette_selected {
                encode_with_opaque_frame_palettes(
                    &ffmpeg,
                    input,
                    &output,
                    &effective_request,
                    legacy_encoder,
                )?;
                palette_strategy = "best_smooth_gradient_opaque_single_floyd_steinberg".to_string();
            } else {
                encode_with_opaque_palette(
                    &ffmpeg,
                    input,
                    &output,
                    &effective_request,
                    legacy_encoder,
                    &plan,
                    PaletteStatsMode::Diff,
                )?;
                palette_strategy = format!(
                    "best_smooth_gradient_opaque_diff_{}",
                    dither_for_plan(&effective_request, legacy_encoder, &plan)
                );
            }
        } else {
            palette_strategy = baseline_palette_strategy;
            encode_ffmpeg_with_strategy(
                &ffmpeg,
                input,
                &output,
                &effective_request,
                legacy_encoder,
                &plan,
                &baseline_segment_cuts,
            )?;
        }
        single_encode_outcome(&output, &effective_request)
    };

    if smooth_gradient_quality_floor_selected {
        reference_filter_encoder = legacy_encoder;
        reference_is_segmented =
            !smooth_gradient_opaque_route_selected && !baseline_segment_cuts.is_empty();
        encoder_used = if smooth_gradient_opaque_route_selected {
            if smooth_gradient_frame_palette_selected {
                "ffmpeg_best_smooth_gradient_frame_palette"
            } else {
                "ffmpeg_best_smooth_gradient_opaque"
            }
        } else {
            "ffmpeg_best_smooth_gradient"
        }
        .to_string();
        if !smooth_gradient_opaque_route_selected {
            palette_strategy = format!(
                "best_smooth_gradient_{}_{}",
                plan.stats_mode.as_ffmpeg_value(),
                plan.dither.as_ffmpeg_value()
            );
        }
    }

    if generation_mode == GifGenerationMode::Target {
        if let Some(artifacts) = outcome.target_perceptual_artifacts.as_ref() {
            effective_request.perceptual_selection = Some(artifacts.selection.clone());
            perceptual_report = Some(artifacts.report.clone());
            backend_id = "rust.perceptual".to_string();
            backend_version = Some(env!("CARGO_PKG_VERSION").to_string());
        }
        reference_filter_encoder = perceptual_filter_encoder(&effective_request, legacy_encoder);
        reference_is_segmented = false;
        if let Some(report) = outcome.target_optimizer_report.as_ref() {
            if let Some(route) = report
                .route_observations
                .iter()
                .find(|route| route.selected)
            {
                palette_strategy = if route.timeline == "perceptual_drop_hold" {
                    format!(
                        "target_perceptual_vfr_{}_{}",
                        route.palette_stats_mode, route.dither
                    )
                } else {
                    format!("target_{}_{}", route.palette_stats_mode, route.dither)
                };
                encoder_used = format!("ffmpeg_target_{}", route.route_id);
            }
        }
    }

    // An opaque animated 256-color export has two materially different GIF
    // encodings: the normal 255-color table with transparent frame deltas and
    // a full opaque 256-color table without `transdiff`. Encode and compare
    // both before the broader Best/Fast delivery guard so a real Pareto win
    // can keep the extra color without weakening any later fallback.
    if generation_mode == GifGenerationMode::Best
        && !source_uses_transparency
        && indexed_gif_writer_report.is_none()
        && palette_color_count(effective_request.colors) == 256
        && effective_request
            .perceptual_selection
            .as_ref()
            .is_some_and(|selection| {
                selection.frame_delays_cs.len() > 1
                    && selection
                        .palette
                        .as_ref()
                        .is_some_and(oklab_palette_reserves_transparency)
            })
    {
        if let Some(opaque_artifact) = effective_request.perceptual_opaque_palette_candidate.take()
        {
            let perceptual_encoder =
                perceptual_filter_encoder(&effective_request, legacy_encoder).to_string();
            outcome.attempts = outcome.attempts.saturating_add(1);
            match attempt_opaque_palette_reservation_selection(
                &ffmpeg,
                input,
                &outcome.output_path,
                &effective_request,
                &perceptual_encoder,
                &plan,
                &opaque_artifact,
            ) {
                Ok(selection_outcome) => {
                    palette_reservation_selection_report = Some(selection_outcome.report);
                    // Keep the recorded byte count accurate even when the
                    // transparent baseline wins. This also makes the chosen
                    // route visible without changing legacy strategy labels.
                    outcome.size_bytes = selection_outcome.transparent_bytes;
                    if selection_outcome.opaque_selected {
                        if let Some(selection) = effective_request.perceptual_selection.as_mut() {
                            selection.palette = Some(opaque_artifact.clone());
                            selection.structured_ui_standard_palette = None;
                            selection.palette_sequence = None;
                            selection.region_dither = None;
                        }
                        if let Some(report) = palette_report.as_mut() {
                            report.emitted_colors = opaque_artifact.emitted_colors;
                            report.reserved_transparent = false;
                            report.artifact_hashes = vec![opaque_artifact.sha256.clone()];
                            report.weighted_histogram_mean_oklab_error =
                                opaque_artifact.weighted_histogram_mean_oklab_error;
                            report.weighted_histogram_p95_oklab_error =
                                opaque_artifact.weighted_histogram_p95_oklab_error;
                            report.global_color_table_verified = true;
                        }
                        outcome.size_bytes = selection_outcome.opaque_bytes;
                        backend_id = "rust.perceptual".to_string();
                        backend_version = Some(env!("CARGO_PKG_VERSION").to_string());
                        encoder_used = "rust_perceptual_oklab_ffmpeg_opaque_palette".to_string();
                        reference_filter_encoder =
                            perceptual_filter_encoder(&effective_request, legacy_encoder);
                        reference_is_segmented = false;
                        palette_strategy =
                            "perceptual_vfr+oklab_global+ffmpeg+opaque_256_no_transdiff"
                                .to_string();
                    }
                }
                Err(error) => {
                    check_conversion_cancelled()?;
                    let reason = error.to_string();
                    palette_reservation_selection_report =
                        Some(failed_palette_reservation_selection_report(reason.clone()));
                    warnings.push(format!(
                        "Full 256-color opaque palette candidate could not be compared ({reason}); kept the verified transparent-delta GIF."
                    ));
                }
            }
        }
    }

    let default_writer_has_internal_pareto_evidence = indexed_gif_writer_report
        .as_ref()
        .is_some_and(default_indexed_writer_has_internal_pareto_evidence);
    if generation_mode == GifGenerationMode::Best
        && !source_uses_transparency
        && effective_request.perceptual_selection.is_some()
        && !default_writer_has_internal_pareto_evidence
        // A verified single-frame opaque palette deliberately consumes all
        // 256 entries. The Fast baseline always reserves one for `transdiff`,
        // so it is not an equivalent candidate for that output contract.
        && effective_request
            .perceptual_selection
            .as_ref()
            .and_then(|selection| selection.palette.as_ref())
            .is_none_or(oklab_palette_reserves_transparency)
        // The Fast baseline is an FFmpeg adaptive palette with no way to
        // carry the template's fixed caption colors. Do not replace an
        // explicitly color-locked meme export with that semantically weaker
        // baseline merely because a global image metric prefers it.
        && protected_overlay_palette_anchors(&effective_request).is_empty()
    {
        let gate_profile = best_delivery_gate_profile(content_profile, perceptual_report.as_ref());
        let baseline_plan = plan_ffmpeg_gif(&StrategyInput {
            mode: best_delivery_baseline_mode(gate_profile),
            content_profile,
            bayer_scale: i32::from(request.bayer_scale),
            alpha_threshold: i32::from(request.alpha_threshold),
            allow_single_palette: false,
            supports_single_palette: ffmpeg_features.per_frame_palettes,
            supports_diff_rectangle: ffmpeg_features.partial_frame_rectangles,
        });
        match attempt_best_delivery_guard(
            &ffmpeg,
            input,
            &outcome.output_path,
            &effective_request,
            &baseline_plan,
            gate_profile,
        ) {
            Ok(guard) => {
                outcome.attempts = outcome.attempts.saturating_add(1);
                if guard.baseline_selected {
                    let reason = guard
                        .fallback_reason
                        .as_deref()
                        .unwrap_or("the Best candidate did not improve delivery quality or size");
                    warnings.push(format!(
                        "Best delivery guard rejected the candidate ({reason}); used the stable Fast GIF baseline."
                    ));
                    fallback_reason = append_reason(
                        fallback_reason,
                        &format!("best.delivery_guard.v1 rejected the candidate ({reason})"),
                    );
                    effective_request.perceptual_selection = None;
                    effective_request.perceptual_opaque_palette_candidate = None;
                    perceptual_report = None;
                    palette_report = None;
                    region_dither_report = None;
                    indexed_gif_writer_report = None;
                    motion_delivery_selection_report = None;
                    palette_reservation_selection_report = None;
                    backend_id = "ffmpeg.animation".to_string();
                    backend_version = ffmpeg_backend_version.clone();
                    encoder_used = "ffmpeg_best_guard_baseline".to_string();
                    reference_filter_encoder = "ffmpeg_fast";
                    reference_is_segmented = false;
                    palette_strategy = format!(
                        "best_guard_{}_{}",
                        baseline_plan.stats_mode.as_ffmpeg_value(),
                        baseline_plan.dither.as_ffmpeg_value()
                    );
                    outcome.size_bytes = fs::metadata(&outcome.output_path)
                        .map_err(|error| {
                            AppError::DecodeFailed(format!(
                                "Read Best delivery baseline size: {error}"
                            ))
                        })?
                        .len();
                }
            }
            Err(error) => {
                check_conversion_cancelled()?;
                warnings.push(format!(
                    "Best delivery guard could not encode its stable comparison baseline ({error}); kept the verified Best candidate."
                ));
            }
        }
    }

    if generation_mode == GifGenerationMode::Best
        && source_uses_transparency
        && indexed_gif_writer_report.is_none()
    {
        match postprocess_transparent_gif_with_rust(
            &ffmpeg,
            &outcome.output_path,
            request.loop_output,
        ) {
            Ok(postprocess) => {
                if postprocess.published {
                    outcome.size_bytes = fs::metadata(&outcome.output_path)
                        .map(|metadata| metadata.len())
                        .unwrap_or(outcome.size_bytes);
                    backend_id = "rust.indexed_gif.transparent".to_string();
                    backend_version = Some(env!("CARGO_PKG_VERSION").to_string());
                    encoder_used = "rust_transparent_disposal_postprocess".to_string();
                    palette_strategy =
                        "ffmpeg_alpha_map+rust_timed_coalesce+disposal_byte_search".to_string();
                }
                indexed_gif_writer_report = Some(postprocess.report);
            }
            Err(error) => {
                check_conversion_cancelled()?;
                let reason = error.to_string();
                fallback_reason = append_reason(
                    fallback_reason,
                    &format!(
                        "rust.indexed_gif transparent postprocessor failed ({reason}); kept the verified FFmpeg alpha baseline."
                    ),
                );
                indexed_gif_writer_report = Some(failed_transparent_writer_report(reason));
            }
        }
    }

    let mut target_deviation_percent = request.target_size_bytes.map(|target| {
        if target == 0 {
            0.0
        } else {
            ((outcome.size_bytes as f64 - target as f64) / target as f64) * 100.0
        }
    });
    let mut output_inspection = Some(verify_delivery_output(
        &outcome.output_path,
        AnimationFormat::Gif,
    )?);
    outcome.size_bytes = fs::metadata(&outcome.output_path)
        .map_err(|error| AppError::DecodeFailed(format!("Read verified GIF size: {error}")))?
        .len();
    let output_inspection_error: Option<String> = None;
    let mut output_frame_count = output_inspection
        .as_ref()
        .map(|inspection| inspection.frame_count)
        .unwrap_or(0);
    let mut effective_output_fps = output_inspection.as_ref().and_then(|inspection| {
        (inspection.duration > f64::EPSILON)
            .then_some(inspection.frame_count as f64 / inspection.duration)
    });
    if let Some(report) = perceptual_report.as_mut() {
        if let Some(inspection) = output_inspection.as_ref() {
            let frame_count_matches = inspection.frame_count == u64::from(report.kept_frame_count);
            if !frame_count_matches {
                warnings.push(format!(
                    "VFR verification expected {} frames but FFprobe reported {}.",
                    report.kept_frame_count, inspection.frame_count
                ));
            }
            let expected_seconds = report.output_duration_ms as f64 / 1_000.0;
            let expected_duration_cs = report.output_duration_ms / 10;
            let observed_duration_cs = (inspection.duration * 100.0).round().max(0.0) as u64;
            let duration_matches = observed_duration_cs == expected_duration_cs;
            if !duration_matches {
                warnings.push(format!(
                    "VFR duration verification expected {expected_seconds:.3}s but FFprobe reported {:.3}s.",
                    inspection.duration
                ));
            }
            report.aggregate_timeline_verified = frame_count_matches && duration_matches;
        } else {
            warnings.push(format!(
                "VFR output could not be verified with FFprobe: {}",
                output_inspection_error
                    .as_deref()
                    .unwrap_or("unknown inspection error")
            ));
        }
    }
    if let Some(report) = palette_report.as_mut() {
        let local_palette_verified = indexed_gif_writer_report.as_ref().is_some_and(|writer| {
            writer.local_palette_frame_count > 0
                && writer.decoded_pixel_parity_verified
                && writer
                    .segment_palette_report
                    .as_ref()
                    .is_some_and(|segment| segment.status == "encoded")
        });
        if local_palette_verified {
            report.global_color_table_verified = true;
        } else {
            let selected_precision = indexed_gif_writer_report
                .as_ref()
                .and_then(|writer| writer.palette_mapper_selection_report.as_ref())
                .map(|mapper| mapper.selected_histogram_precision_bits);
            let artifact = effective_request
                .perceptual_selection
                .as_ref()
                .and_then(|selection| {
                    if selected_precision == Some(5) {
                        selection.structured_ui_standard_palette.as_ref()
                    } else {
                        selection.palette.as_ref()
                    }
                });
            match artifact {
                Some(artifact) => match verify_gif_global_palette(&outcome.output_path, artifact) {
                    Ok(verified) => {
                        report.global_color_table_verified = verified;
                        if !verified {
                            warnings.push(
                                "The output GIF did not preserve the Rust OKLab palette contract (artifact SHA, global table, local-table exclusion, transparency index, and trailer)."
                                    .to_string(),
                            );
                        }
                    }
                    Err(error) => {
                        check_conversion_cancelled()?;
                        warnings.push(format!(
                            "The output GIF palette could not be verified: {error}"
                        ));
                    }
                },
                None => warnings.push(
                    "The OKLab palette report was present without an encoder artifact.".to_string(),
                ),
            }
        }
    }
    let ffmpeg_engine_version = (backend_id != "ffmpeg.animation")
        .then(|| ffmpeg_backend_version.clone())
        .flatten();

    // Run before any frame coalescing: source frames must correspond by ordinal,
    // not by guessing original samples from centisecond GIF delays.
    let advanced_compression_report = if request.temporal_stability || request.lzw_search {
        let mut reference_request = effective_request.clone();
        reference_request.width = outcome.width;
        reference_request.fps = outcome.fps;
        reference_request.colors = outcome.colors;
        let reference = (!reference_is_segmented).then_some(advanced_compression::ReferenceSpec {
            input,
            request: &reference_request,
            encoder: reference_filter_encoder,
        });
        let report = advanced_compression::optional(
            &ffmpeg,
            &outcome.output_path,
            request.target_size_bytes,
            request.temporal_stability,
            request.lzw_search,
            reference,
        )?;
        if report.adopted && report.verified {
            let inspection = verify_delivery_output(&outcome.output_path, AnimationFormat::Gif)?;
            outcome.size_bytes = report.after_bytes;
            outcome.width = inspection.width;
            output_frame_count = inspection.frame_count;
            effective_output_fps = (inspection.duration > f64::EPSILON)
                .then_some(inspection.frame_count as f64 / inspection.duration);
            output_inspection = Some(inspection);
            target_deviation_percent = request
                .target_size_bytes
                .map(|target| (outcome.size_bytes as f64 / target.max(1) as f64 - 1.0) * 100.0);
            if request.target_size_bytes.is_some() {
                outcome.target_fit = Some(TargetFit::Under);
            }
            perceptual_report = None;
            palette_report = None;
            region_dither_report = None;
            indexed_gif_writer_report = None;
            motion_delivery_selection_report = None;
            palette_reservation_selection_report = None;
            outcome.target_optimizer_report = None;
            encoder_used.push_str("+source_checked_compression");
            palette_strategy.push_str("+low_error_search");
        }
        Some(report)
    } else {
        None
    };

    let gif_cleanup_report = if request.gif_merge_frames || request.gif_compact_palette {
        let report = gif_cleanup::optional(
            &ffmpeg,
            &outcome.output_path,
            request.target_size_bytes,
            request.gif_merge_frames,
            request.gif_compact_palette,
        )?;
        if report.verified {
            let inspection = verify_delivery_output(&outcome.output_path, AnimationFormat::Gif)?;
            outcome.size_bytes = report.after_bytes;
            outcome.width = inspection.width;
            output_frame_count = inspection.frame_count;
            effective_output_fps = (inspection.duration > f64::EPSILON)
                .then_some(inspection.frame_count as f64 / inspection.duration);
            output_inspection = Some(inspection);
            target_deviation_percent = request
                .target_size_bytes
                .map(|target| (outcome.size_bytes as f64 / target.max(1) as f64 - 1.0) * 100.0);
            if request.target_size_bytes.is_some() {
                outcome.target_fit = Some(TargetFit::Under);
            }
            perceptual_report = None;
            palette_report = None;
            region_dither_report = None;
            indexed_gif_writer_report = None;
            motion_delivery_selection_report = None;
            palette_reservation_selection_report = None;
            outcome.target_optimizer_report = None;
            encoder_used.push_str("+native_gif_cleanup");
            palette_strategy.push_str("+lossless_cleanup");
        }
        Some(report)
    } else {
        None
    };

    let structure_optimization_report = if request.smart_lossless {
        let report = structure_optimization::optional(
            &ffmpeg,
            &outcome.output_path,
            request.target_size_bytes,
        )?;
        if report.adopted && report.verified {
            let inspection = verify_delivery_output(&outcome.output_path, AnimationFormat::Gif)?;
            outcome.size_bytes = report.after_bytes;
            outcome.width = inspection.width;
            output_frame_count = inspection.frame_count;
            effective_output_fps = (inspection.duration > f64::EPSILON)
                .then_some(inspection.frame_count as f64 / inspection.duration);
            output_inspection = Some(inspection);
            target_deviation_percent = request
                .target_size_bytes
                .map(|target| (outcome.size_bytes as f64 / target.max(1) as f64 - 1.0) * 100.0);
            if request.target_size_bytes.is_some() {
                outcome.target_fit = Some(TargetFit::Under);
            }
            perceptual_report = None;
            palette_report = None;
            region_dither_report = None;
            indexed_gif_writer_report = None;
            motion_delivery_selection_report = None;
            palette_reservation_selection_report = None;
            outcome.target_optimizer_report = None;
            encoder_used.push_str("+smart_lossless_structure");
            palette_strategy.push_str("+verified_structure_search");
        }
        Some(report)
    } else {
        None
    };

    let index_compression_report = if request.index_compression
        && advanced_compression_report
            .as_ref()
            .is_some_and(|report| report.adopted)
    {
        // A second lossy stage would invalidate the new route's frozen quality
        // envelope. Keep the user's legacy option as fallback when new search
        // cannot adopt, but never stack it after an accepted new candidate.
        Some(IndexCompressionReport {
            gentle: request.index_compression_gentle,
            algorithm: "index_reuse_v1",
            status: "retained".into(),
            before_bytes: outcome.size_bytes,
            after_bytes: outcome.size_bytes,
            verified: false,
            threshold: 0,
            max_channel_error: 0,
            worst_frame_rmse: 0.0,
            candidates_tested: 0,
            elapsed_ms: 0,
            reason: Some("已采用通过统一质量检查的新路线，未叠加旧有损索引压缩".into()),
        })
    } else if request.index_compression {
        let report = index_compression::optional(
            &ffmpeg,
            &outcome.output_path,
            request.target_size_bytes,
            request.index_compression_gentle,
        )?;
        if report.status == "optimized" {
            let inspection = verify_delivery_output(&outcome.output_path, AnimationFormat::Gif)?;
            outcome.size_bytes = report.after_bytes;
            outcome.width = inspection.width;
            output_frame_count = inspection.frame_count;
            effective_output_fps = (inspection.duration > f64::EPSILON)
                .then_some(inspection.frame_count as f64 / inspection.duration);
            output_inspection = Some(inspection);
            target_deviation_percent = request
                .target_size_bytes
                .map(|target| (outcome.size_bytes as f64 / target.max(1) as f64 - 1.0) * 100.0);
            if request.target_size_bytes.is_some() {
                outcome.target_fit = Some(TargetFit::Under);
            }
            perceptual_report = None;
            palette_report = None;
            region_dither_report = None;
            indexed_gif_writer_report = None;
            motion_delivery_selection_report = None;
            palette_reservation_selection_report = None;
            outcome.target_optimizer_report = None;
            encoder_used.push_str("+index_reuse_v1");
            palette_strategy.push_str("+bounded_lossy_index_reuse");
        }
        Some(report)
    } else {
        None
    };

    let postprocess_report = if request.smaller_gif {
        let tool = available_backend_executable(&backends, "gif.optimizer.external");
        let report = gifsicle_adapter::optional(
            &ffmpeg,
            tool.as_ref().map(|(path, _)| path.as_path()),
            &outcome.output_path,
            request.target_size_bytes,
        )?;
        if report.status == "optimized" {
            let inspection = verify_delivery_output(&outcome.output_path, AnimationFormat::Gif)?;
            outcome.size_bytes = report.after_bytes;
            outcome.width = inspection.width;
            output_frame_count = inspection.frame_count;
            effective_output_fps = (inspection.duration > f64::EPSILON)
                .then_some(inspection.frame_count as f64 / inspection.duration);
            output_inspection = Some(inspection);
            target_deviation_percent = request
                .target_size_bytes
                .map(|target| (outcome.size_bytes as f64 / target.max(1) as f64 - 1.0) * 100.0);
            if request.target_size_bytes.is_some() {
                outcome.target_fit = Some(TargetFit::Under);
            }
            // These describe upstream artifacts, whose tables/frame counts may
            // have changed. Never present them as verification of the final file.
            perceptual_report = None;
            palette_report = None;
            region_dither_report = None;
            indexed_gif_writer_report = None;
            motion_delivery_selection_report = None;
            palette_reservation_selection_report = None;
            outcome.target_optimizer_report = None;
            encoder_used.push_str("+gifsicle_o3");
            palette_strategy.push_str("+lossless_postprocess");
        }
        Some(report)
    } else {
        None
    };

    if let Some(export_temp) = export_temp {
        let verified_output = outcome.output_path.clone();
        publish_file_after_owned_temp_cleanup(&verified_output, export_temp, &final_output, false)?;
        outcome.output_path = final_output;
    }

    Ok(GifResult {
        advanced_compression_report,
        gif_cleanup_report,
        structure_optimization_report,
        index_compression_report,
        postprocess_report,
        pipeline_profile: None,
        input_path: input.to_string_lossy().to_string(),
        output_path: outcome.output_path.to_string_lossy().to_string(),
        size_bytes: outcome.size_bytes,
        encoder_used,
        status: outcome
            .target_fit
            .map(target_fit_label)
            .unwrap_or("done")
            .to_string(),
        backend_id,
        backend_version,
        ffmpeg_engine_version,
        fallback_reason,
        palette_strategy,
        attempts: outcome.attempts,
        elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
        output_width: outcome.width,
        output_fps: outcome.fps,
        effective_output_fps,
        output_frame_count,
        output_colors: outcome.colors,
        output_format: output_format.wire_name().to_string(),
        output_codec: output_format.codec_name().to_string(),
        output_has_alpha: output_inspection
            .as_ref()
            .is_some_and(|inspection| inspection.has_alpha),
        target_size_bytes: request.target_size_bytes,
        target_deviation_percent,
        warnings,
        perceptual_report,
        palette_report,
        region_dither_report,
        indexed_gif_writer_report,
        motion_delivery_selection_report,
        palette_reservation_selection_report,
        target_optimizer_report: outcome.target_optimizer_report,
        live_photo: None,
    })
}

fn convert_live_photo_animation(
    started: Instant,
    ffmpeg: &Path,
    discovered_ffmpeg_version: Option<String>,
    input: &Path,
    output_dir: &Path,
    request: &GifRequest,
) -> Result<GifResult, AppError> {
    const STAGING_PREFIX: &str = ".gifp-live-stage-";

    let final_bundle = next_animation_output_path(input, output_dir, AnimationFormat::LivePhoto);
    let staging = OwnedPublishDir::create(output_dir, STAGING_PREFIX)?;
    let asset_identifier = uuid::Uuid::new_v4()
        .hyphenated()
        .to_string()
        .to_ascii_uppercase();
    let short_identifier = asset_identifier
        .split('-')
        .next()
        .unwrap_or("GIFP")
        .to_ascii_uppercase();
    let resource_stem = format!("IMG_{short_identifier}");
    let raw_motion = staging.path().join(".gifp-unpaired.mov");
    let still_name = format!("{resource_stem}.JPG");
    let motion_name = format!("{resource_stem}.MOV");
    let still = staging.path().join(&still_name);
    let motion = staging.path().join(&motion_name);
    let metadata_plist = staging.path().join("metadata.plist");

    let source_has_alpha = match source_uses_transparency_after_timeline(ffmpeg, input, request) {
        Ok(value) => value,
        Err(_) => {
            check_conversion_cancelled()?;
            false
        }
    };
    let wants_audio = (request.playback_speed - 1.0).abs() <= 0.0001
        && request.deleted_frames.is_empty()
        && request.deleted_ranges.is_empty();
    let audio_fallback_reason = if wants_audio {
        match encode_live_photo_motion(
            ffmpeg,
            input,
            &raw_motion,
            request,
            &asset_identifier,
            source_has_alpha,
            true,
        ) {
            Ok(()) => None,
            Err(audio_error) => {
                check_conversion_cancelled()?;
                let _ = fs::remove_file(&raw_motion);
                encode_live_photo_motion(
                    ffmpeg,
                    input,
                    &raw_motion,
                    request,
                    &asset_identifier,
                    source_has_alpha,
                    false,
                )
                .map_err(|silent_error| {
                    AppError::EncodeFailed(format!(
                        "Live Photo encode failed with optional audio ({audio_error}); silent retry also failed ({silent_error})"
                    ))
                })?;
                Some(format!(
                    "Audio could not be encoded by this FFmpeg build; GIFP retried silently ({audio_error})"
                ))
            }
        }
    } else {
        encode_live_photo_motion(
            ffmpeg,
            input,
            &raw_motion,
            request,
            &asset_identifier,
            source_has_alpha,
            false,
        )?;
        None
    };

    let raw_inspection = verify_delivery_output(&raw_motion, AnimationFormat::Mp4)?;
    if raw_inspection.frame_count < 2 || raw_inspection.duration < 0.08 {
        return Err(AppError::InvalidInput(
            "Live Photo needs at least two encoded motion frames; use an animated source or a longer selected range."
                .to_string(),
        ));
    }
    let still_time_ms = ((raw_inspection.duration * 500.0).round() as u64).clamp(
        1,
        (raw_inspection.duration * 1_000.0).ceil().max(1.0) as u64,
    );
    extract_live_photo_still(ffmpeg, &raw_motion, &still, still_time_ms)?;
    stamp_jpeg_asset_identifier(&still, &asset_identifier).map_err(|error| {
        AppError::EncodeFailed(format!("Stamp Live Photo JPEG metadata: {error}"))
    })?;
    let _finalization_report =
        finalize_mov_live_photo(&raw_motion, &motion, &asset_identifier, still_time_ms).map_err(
            |error| AppError::EncodeFailed(format!("Finalize Live Photo MOV metadata: {error}")),
        )?;
    let verification_report =
        verify_live_photo_pair(&still, &motion, &asset_identifier).map_err(|error| {
            AppError::DecodeFailed(format!("Verify Live Photo resource pair: {error}"))
        })?;
    write_live_photo_metadata_plist(&metadata_plist)?;
    fs::remove_file(&raw_motion).map_err(|error| {
        AppError::Internal(format!(
            "Remove unpaired Live Photo staging movie {}: {error}",
            raw_motion.display()
        ))
    })?;

    let still_size_bytes = fs::metadata(&still)
        .map_err(|error| AppError::DecodeFailed(format!("Read Live Photo still size: {error}")))?
        .len();
    let motion_size_bytes = fs::metadata(&motion)
        .map_err(|error| AppError::DecodeFailed(format!("Read Live Photo movie size: {error}")))?
        .len();
    let plist_size_bytes = fs::metadata(&metadata_plist)
        .map_err(|error| {
            AppError::DecodeFailed(format!("Read Live Photo package metadata: {error}"))
        })?
        .len();
    let final_inspection = verify_delivery_output(&motion, AnimationFormat::Mp4)?;
    let effective_output_fps = (final_inspection.duration > f64::EPSILON)
        .then_some(final_inspection.frame_count as f64 / final_inspection.duration);

    staging.publish(&final_bundle)?;
    let final_still = final_bundle.join(still_name);
    let final_motion = final_bundle.join(motion_name);
    let mut warnings = vec![
        "GIFP verified the paired JPEG/MOV identifiers and timed metadata locally; Apple Photos or PHLivePhoto device validation remains a release gate."
            .to_string(),
        "Live Photo output is a paired .pvt directory; keep the JPEG and MOV together when transferring or importing."
            .to_string(),
        "Live Photo import does not guarantee eligibility as an iPhone animated wallpaper."
            .to_string(),
    ];
    if request.target_size_bytes.is_some() || request.generation_mode == "target_size" {
        warnings.push(
            "Exact-size search currently applies to GIF only; this Live Photo used quality-based H.264 encoding."
                .to_string(),
        );
    }
    if source_has_alpha {
        warnings.push(
            "Live Photo JPEG/H.264 resources do not preserve alpha; transparent pixels were explicitly premultiplied onto black before encoding."
                .to_string(),
        );
    }
    if !wants_audio {
        warnings.push(
            "Audio was omitted because speed changes or manual frame deletion would desynchronize it from the edited motion timeline."
                .to_string(),
        );
    } else if let Some(reason) = audio_fallback_reason {
        warnings.push(reason);
    }

    Ok(GifResult {
        gif_cleanup_report: None,
        advanced_compression_report: None,
        structure_optimization_report: None,
        index_compression_report: None,
        postprocess_report: None,
        pipeline_profile: None,
        input_path: input.to_string_lossy().to_string(),
        output_path: final_bundle.to_string_lossy().to_string(),
        size_bytes: still_size_bytes
            .saturating_add(motion_size_bytes)
            .saturating_add(plist_size_bytes),
        encoder_used: "ffmpeg_h264+gifp_live_photo_metadata".to_string(),
        status: "done".to_string(),
        backend_id: "gifp.live_photo".to_string(),
        backend_version: Some(env!("CARGO_PKG_VERSION").to_string()),
        ffmpeg_engine_version: discovered_ffmpeg_version.or_else(|| ffmpeg_version(ffmpeg)),
        fallback_reason: None,
        palette_strategy: "not_applicable".to_string(),
        attempts: 1,
        elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
        output_width: final_inspection.width,
        output_fps: request.fps,
        effective_output_fps,
        output_frame_count: final_inspection.frame_count,
        output_colors: 0,
        output_format: AnimationFormat::LivePhoto.wire_name().to_string(),
        output_codec: AnimationFormat::LivePhoto.codec_name().to_string(),
        output_has_alpha: false,
        target_size_bytes: request.target_size_bytes,
        target_deviation_percent: None,
        warnings,
        perceptual_report: None,
        palette_report: None,
        region_dither_report: None,
        indexed_gif_writer_report: None,
        motion_delivery_selection_report: None,
        palette_reservation_selection_report: None,
        target_optimizer_report: None,
        live_photo: Some(LivePhotoResult {
            still_path: final_still.to_string_lossy().to_string(),
            motion_path: final_motion.to_string_lossy().to_string(),
            still_size_bytes: Some(still_size_bytes),
            motion_size_bytes: Some(motion_size_bytes),
            asset_identifier: Some(asset_identifier),
            asset_identifier_verified: verification_report.pair_verified,
            metadata_pairing_verified: verification_report.pair_verified,
            compatibility_status: "locally_verified".to_string(),
            validation_scope: "local_contract".to_string(),
            validation_message: Some(
                "GIFP local pairing verification passed. Final Apple Photos acceptance still requires the macOS/iPhone release gate."
                    .to_string(),
            ),
            report_schema_version: verification_report.schema_version,
            still_time_movie_units: verification_report.still_time_movie_units,
            movie_timescale: verification_report.movie_timescale,
            video_track_id: verification_report.video_track_id,
            metadata_track_id: verification_report.metadata_track_id,
            metadata_sample_offset: verification_report.metadata_sample_offset,
            jpeg_sha256: verification_report.jpeg_sha256,
            mov_sha256: verification_report.mov_sha256,
            contract_sha256: verification_report.contract_sha256,
        }),
    })
}

fn encode_live_photo_motion(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    asset_identifier: &str,
    composite_alpha: bool,
    preserve_audio: bool,
) -> Result<(), AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Encode);
    let source_args = source_time_args(request);
    let mut filter = video_filter(request, "modern");
    if composite_alpha {
        // Premultiplication followed by dropping alpha is an explicit black
        // background composite. This prevents hidden RGB in transparent
        // pixels from becoming opaque fringes in JPEG/H.264.
        filter.push_str(",premultiply=inplace=1:planes=7");
    }
    filter.push_str(",format=yuv420p,pad=ceil(iw/2)*2:ceil(ih/2)*2");
    let crf_h264 = (18_i32 + i32::from(request.lossy.min(100)) / 6).clamp(17, 34);
    let mut output_args = vec![
        "-map".to_string(),
        "0:v:0".to_string(),
        "-sn".to_string(),
        "-map_metadata".to_string(),
        "-1".to_string(),
        "-map_chapters".to_string(),
        "-1".to_string(),
        "-vf".to_string(),
        filter,
        "-c:v".to_string(),
        "libx264".to_string(),
        "-tag:v".to_string(),
        "avc1".to_string(),
        "-preset".to_string(),
        "medium".to_string(),
        "-crf".to_string(),
        crf_h264.to_string(),
        "-pix_fmt".to_string(),
        "yuv420p".to_string(),
        "-fps_mode".to_string(),
        "cfr".to_string(),
        // The core API expresses the cover point in movie time units. A
        // 1000-unit movie timescale makes that value exactly milliseconds.
        "-movie_timescale".to_string(),
        "1000".to_string(),
    ];
    if preserve_audio {
        output_args.extend([
            "-map".to_string(),
            "0:a?".to_string(),
            "-c:a".to_string(),
            "aac".to_string(),
            "-b:a".to_string(),
            "128k".to_string(),
        ]);
    } else {
        output_args.push("-an".to_string());
    }
    output_args.extend([
        "-movflags".to_string(),
        "+use_metadata_tags".to_string(),
        "-metadata".to_string(),
        format!("com.apple.quicktime.content.identifier={asset_identifier}"),
        "-f".to_string(),
        "mov".to_string(),
    ]);
    run_ffmpeg_owned(ffmpeg, input, &source_args, &output_args, output)
}

fn extract_live_photo_still(
    ffmpeg: &Path,
    motion: &Path,
    still: &Path,
    still_time_ms: u64,
) -> Result<(), AppError> {
    let output_args = vec![
        "-ss".to_string(),
        format!("{:.6}", still_time_ms as f64 / 1_000.0),
        "-map".to_string(),
        "0:v:0".to_string(),
        "-frames:v".to_string(),
        "1".to_string(),
        "-an".to_string(),
        "-sn".to_string(),
        "-map_metadata".to_string(),
        "-1".to_string(),
        "-c:v".to_string(),
        "mjpeg".to_string(),
        "-q:v".to_string(),
        "2".to_string(),
        "-update".to_string(),
        "1".to_string(),
        "-f".to_string(),
        "image2".to_string(),
    ];
    run_ffmpeg_owned(ffmpeg, motion, &[], &output_args, still)
}

fn write_live_photo_metadata_plist(path: &Path) -> Result<(), AppError> {
    const PLIST: &str = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\
<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n\
<plist version=\"1.0\">\n\
<dict>\n\
  <key>PFVideoComplementMetadataVersionKey</key>\n\
  <string>1</string>\n\
</dict>\n\
</plist>\n";
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .map_err(|error| {
            AppError::Internal(format!(
                "Create Live Photo package metadata {}: {error}",
                path.display()
            ))
        })?;
    file.write_all(PLIST.as_bytes()).map_err(|error| {
        AppError::Internal(format!(
            "Write Live Photo package metadata {}: {error}",
            path.display()
        ))
    })?;
    file.flush().map_err(|error| {
        AppError::Internal(format!(
            "Flush Live Photo package metadata {}: {error}",
            path.display()
        ))
    })?;
    file.sync_all().map_err(|error| {
        AppError::Internal(format!(
            "Sync Live Photo package metadata {}: {error}",
            path.display()
        ))
    })
}

fn convert_modern_animation(
    started: Instant,
    ffmpeg: &Path,
    discovered_ffmpeg_version: Option<String>,
    input: &Path,
    output_dir: &Path,
    request: &GifRequest,
    format: AnimationFormat,
) -> Result<GifResult, AppError> {
    let (source_has_alpha, source_alpha_known) =
        match source_uses_transparency_after_timeline(ffmpeg, input, request) {
            Ok(value) => (value, true),
            Err(error) if format == AnimationFormat::Avif => {
                return Err(AppError::InvalidInput(format!(
                "无法可靠确认素材透明度，已停止 Animated AVIF 导出，避免静默丢失 alpha：{error}"
            )));
            }
            // WebP's alpha-safe path is preferable to silently discarding unknown
            // transparency. The finished output is decoded again below, so the
            // report still reflects actual pixels rather than this assumption.
            Err(_) if format == AnimationFormat::Webp => (true, false),
            Err(_) => (false, false),
        };
    if format == AnimationFormat::Avif && source_has_alpha {
        return Err(AppError::InvalidInput(
            "Animated AVIF 当前仅支持不透明素材；检测到实际透明像素。请改用 Animated WebP / APNG，或先为素材设置不透明背景。"
                .to_string(),
        ));
    }
    let final_output = next_animation_output_path(input, output_dir, format);
    let export_temp = OwnedTempDir::create("gif-p-modern")?;
    let output = export_temp
        .path()
        .join(format!("candidate.{}", format.extension()));
    let mut warnings = Vec::new();
    if format == AnimationFormat::Webp && !source_alpha_known {
        warnings.push(
            "素材透明度检测未完成；Animated WebP 已保守使用带 Alpha 的像素路径，避免静默丢失透明度。"
                .to_string(),
        );
    }
    if request.target_size_bytes.is_some() || request.generation_mode == "target_size" {
        warnings.push(
            "Exact-size search currently applies to GIF only; this delivery used quality-based encoding."
                .to_string(),
        );
    }
    if format == AnimationFormat::Mp4 && source_has_alpha {
        warnings.push(
            "MP4/H.264 does not preserve alpha; transparent pixels were composited by FFmpeg."
                .to_string(),
        );
    }
    if matches!(format, AnimationFormat::Mp4 | AnimationFormat::Webm) && request.loop_output {
        warnings.push(
            "Video files do not embed GIF-style loop behavior; the player or target platform controls looping."
                .to_string(),
        );
    }
    if format == AnimationFormat::Avif {
        warnings.push(
            "Animated AVIF 面向现代浏览器和解码器；发布到未知环境时建议同时提供 Animated WebP 回退。"
                .to_string(),
        );
    }

    let encoder_used =
        encode_modern_format(ffmpeg, input, &output, request, format, source_has_alpha)?;
    let size_bytes = fs::metadata(&output)
        .map_err(|error| AppError::DecodeFailed(format!("Read encoded output size: {error}")))?
        .len();
    let inspection = Some(verify_delivery_output(&output, format)?);
    let output_frame_count = inspection
        .as_ref()
        .map(|value| value.frame_count)
        .unwrap_or(0);
    let effective_output_fps = inspection.as_ref().and_then(|value| {
        (value.duration > f64::EPSILON).then_some(value.frame_count as f64 / value.duration)
    });
    let output_has_alpha =
        format.supports_alpha() && source_uses_transparency(ffmpeg, &output, &[]).unwrap_or(false);
    if source_alpha_known && source_has_alpha && format.supports_alpha() && !output_has_alpha {
        warnings.push(format!(
            "{} output was expected to preserve alpha, but decoded-pixel verification did not find transparency.",
            format.wire_name().to_ascii_uppercase()
        ));
    }
    publish_file_after_owned_temp_cleanup(&output, export_temp, &final_output, false)?;

    Ok(GifResult {
        gif_cleanup_report: None,
        advanced_compression_report: None,
        structure_optimization_report: None,
        index_compression_report: None,
        postprocess_report: None,
        pipeline_profile: None,
        input_path: input.to_string_lossy().to_string(),
        output_path: final_output.to_string_lossy().to_string(),
        size_bytes,
        encoder_used,
        status: "done".to_string(),
        backend_id: "ffmpeg.animation".to_string(),
        backend_version: discovered_ffmpeg_version.or_else(|| ffmpeg_version(ffmpeg)),
        ffmpeg_engine_version: None,
        fallback_reason: None,
        palette_strategy: "not_applicable".to_string(),
        attempts: 1,
        elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
        output_width: inspection
            .as_ref()
            .map(|value| value.width)
            .unwrap_or(request.width),
        output_fps: request.fps,
        effective_output_fps,
        output_frame_count,
        output_colors: 0,
        output_format: format.wire_name().to_string(),
        output_codec: inspection
            .as_ref()
            .map(|value| value.codec.clone())
            .unwrap_or_else(|| format.codec_name().to_string()),
        output_has_alpha,
        target_size_bytes: request.target_size_bytes,
        target_deviation_percent: None,
        warnings,
        perceptual_report: None,
        palette_report: None,
        region_dither_report: None,
        indexed_gif_writer_report: None,
        motion_delivery_selection_report: None,
        palette_reservation_selection_report: None,
        target_optimizer_report: None,
        live_photo: None,
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct WebpEncodePlan {
    pixel_format: &'static str,
    lossless: bool,
    quality: u8,
    compression_level: u8,
    loop_count: u8,
}

fn webp_encode_plan(
    lossy: u8,
    optimize_level: u8,
    loop_output: bool,
    source_has_alpha: bool,
) -> WebpEncodePlan {
    let lossy = lossy.min(100);
    let lossless = lossy == 0;
    let quality = if lossless { 100 } else { 100 - lossy / 2 };
    let compression_level = match optimize_level.clamp(1, 4) {
        1 => 2,
        2 => 4,
        3 => 5,
        _ => 6,
    };
    WebpEncodePlan {
        pixel_format: if lossless {
            "bgra"
        } else if source_has_alpha {
            "yuva420p"
        } else {
            "yuv420p"
        },
        lossless,
        quality,
        compression_level,
        loop_count: if loop_output { 0 } else { 1 },
    }
}

fn encode_modern_format(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    format: AnimationFormat,
    source_has_alpha: bool,
) -> Result<String, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Encode);
    let source_args = source_time_args(request);
    let mut filter = video_filter(request, "modern");
    let crf_avif = (20_i32 + i32::from(request.lossy.min(100)) / 5).clamp(20, 40);
    let cpu_used_avif = match request.optimize_level {
        0..=1 => 8,
        2 => 7,
        3 => 6,
        4 => 5,
        _ => 4,
    };
    let crf_vp9 = (18_i32 + i32::from(request.lossy.min(100)) / 4).clamp(16, 42);
    let mut output_args = vec!["-an".to_string(), "-sn".to_string()];
    let encoder_used;

    match format {
        AnimationFormat::Webp => {
            encoder_used = "libwebp_anim".to_string();
            let plan = webp_encode_plan(
                request.lossy,
                request.optimize_level,
                request.loop_output,
                source_has_alpha,
            );
            filter.push_str(&format!(",format={}", plan.pixel_format));
            output_args.extend([
                "-vf".to_string(),
                filter,
                "-c:v".to_string(),
                "libwebp_anim".to_string(),
                "-quality".to_string(),
                plan.quality.to_string(),
                "-lossless".to_string(),
                u8::from(plan.lossless).to_string(),
                "-compression_level".to_string(),
                plan.compression_level.to_string(),
                "-loop".to_string(),
                plan.loop_count.to_string(),
            ]);
        }
        AnimationFormat::Avif => {
            encoder_used = "libaom_av1".to_string();
            filter.push_str(",format=yuv420p,pad=ceil(iw/2)*2:ceil(ih/2)*2");
            output_args.extend([
                "-vf".to_string(),
                filter,
                "-c:v".to_string(),
                "libaom-av1".to_string(),
                "-b:v".to_string(),
                "0".to_string(),
                "-crf".to_string(),
                crf_avif.to_string(),
                "-cpu-used".to_string(),
                cpu_used_avif.to_string(),
                "-row-mt".to_string(),
                "1".to_string(),
                "-still-picture".to_string(),
                "0".to_string(),
                "-f".to_string(),
                "avif".to_string(),
                "-loop".to_string(),
                (if request.loop_output { "0" } else { "1" }).to_string(),
            ]);
        }
        AnimationFormat::Apng => {
            encoder_used = "ffmpeg_apng".to_string();
            filter.push_str(",format=rgba");
            output_args.extend([
                "-vf".to_string(),
                filter,
                "-c:v".to_string(),
                "apng".to_string(),
                "-f".to_string(),
                "apng".to_string(),
                "-pred".to_string(),
                "mixed".to_string(),
                "-plays".to_string(),
                (if request.loop_output { "0" } else { "1" }).to_string(),
            ]);
        }
        AnimationFormat::Mp4 => {
            let h264_encoder = required_h264_encoder(ffmpeg)?;
            encoder_used = h264_encoder.ffmpeg_name().to_string();
            filter.push_str(",format=yuv420p,pad=ceil(iw/2)*2:ceil(ih/2)*2");
            output_args.extend(["-vf".to_string(), filter]);
            output_args.extend(h264_encoder_args(
                h264_encoder,
                H264Usage::Delivery {
                    lossy: request.lossy,
                },
            ));
            output_args.extend(["-movflags".to_string(), "+faststart".to_string()]);
        }
        AnimationFormat::Webm => {
            encoder_used = "libvpx_vp9".to_string();
            filter.push_str(if source_has_alpha {
                ",format=yuva420p"
            } else {
                ",format=yuv420p"
            });
            output_args.extend([
                "-vf".to_string(),
                filter,
                "-c:v".to_string(),
                "libvpx-vp9".to_string(),
                "-b:v".to_string(),
                "0".to_string(),
                "-crf".to_string(),
                crf_vp9.to_string(),
                "-deadline".to_string(),
                "good".to_string(),
                "-row-mt".to_string(),
                "1".to_string(),
                "-auto-alt-ref".to_string(),
                "0".to_string(),
            ]);
        }
        AnimationFormat::Gif => unreachable!("GIF uses the perceptual GIF pipeline"),
        AnimationFormat::LivePhoto => {
            unreachable!("Live Photo uses the paired-resource pipeline")
        }
    }

    run_ffmpeg_owned(ffmpeg, input, &source_args, &output_args, output)?;
    Ok(encoder_used)
}

#[tauri::command]
pub async fn generate_media_thumbnails(
    request: MediaThumbnailRequest,
) -> Result<Vec<MediaThumbnailFrame>, AppError> {
    tauri::async_runtime::spawn_blocking(move || generate_media_thumbnails_inner(request))
        .await
        .map_err(|error| AppError::Internal(format!("Thumbnail worker failed: {error}")))?
}

fn generate_media_thumbnails_inner(
    request: MediaThumbnailRequest,
) -> Result<Vec<MediaThumbnailFrame>, AppError> {
    let input_text = request
        .input_path
        .trim()
        .trim_matches(|ch| ch == '"' || ch == '\'');
    let input = Path::new(input_text);
    if !input.exists() || !input.is_file() {
        return Err(AppError::InvalidInput(format!(
            "Input file does not exist: {}",
            input.display()
        )));
    }
    if !is_media_source(input) {
        return Err(AppError::UnsupportedVideo(format!(
            "Unsupported media: {}",
            input.display()
        )));
    }

    let times = normalize_thumbnail_times(request.times);
    if times.is_empty() {
        return Err(AppError::InvalidInput(
            "At least one thumbnail time is required".to_string(),
        ));
    }

    let ffmpeg = locate_ffmpeg()?;
    let preview_root = std::env::temp_dir().join("GIFP_thumbnails");
    fs::create_dir_all(&preview_root).map_err(|err| AppError::Internal(err.to_string()))?;
    cleanup_old_preview_dirs(&preview_root);
    let output_dir = preview_root.join(unique_output_token());
    fs::create_dir_all(&output_dir).map_err(|err| AppError::Internal(err.to_string()))?;

    generate_thumbnail_files(&ffmpeg, input, &output_dir, &times)
}

#[tauri::command]
pub async fn generate_frame_page(request: FramePageRequest) -> Result<FramePageResult, AppError> {
    tauri::async_runtime::spawn_blocking(move || generate_frame_page_inner(request))
        .await
        .map_err(|error| AppError::Internal(format!("Frame page worker failed: {error}")))?
}

fn generate_frame_page_inner(request: FramePageRequest) -> Result<FramePageResult, AppError> {
    let input_text = request
        .input_path
        .trim()
        .trim_matches(|ch| ch == '"' || ch == '\'');
    let input = Path::new(input_text);
    if !input.exists() || !input.is_file() {
        return Err(AppError::InvalidInput(format!(
            "Input file does not exist: {}",
            input.display()
        )));
    }
    if !is_media_source(input) {
        return Err(AppError::UnsupportedVideo(format!(
            "Unsupported media: {}",
            input.display()
        )));
    }

    let start = if request.start_seconds.is_finite() {
        request.start_seconds.max(0.0)
    } else {
        0.0
    };
    let end = request.end_seconds;
    if !end.is_finite() || end <= start {
        return Err(AppError::InvalidInput(
            "Frame editor requires a finite non-empty trim range".to_string(),
        ));
    }
    let playback_speed = request.playback_speed.clamp(1.0, 3.0);
    let fps = request.fps.clamp(1, 60);
    let total_frames = (((end - start) / playback_speed) * f64::from(fps)).round() as u64;
    if total_frames == 0 {
        return Err(AppError::InvalidInput(
            "Frame editor range contains no output frames".to_string(),
        ));
    }
    let page_start = request.page_start.min(total_frames);
    let requested_page_size = request.page_size.clamp(1, MAX_FRAME_PAGE_SIZE);
    let page_size = u32::try_from((total_frames - page_start).min(u64::from(requested_page_size)))
        .unwrap_or(requested_page_size);
    if page_size == 0 {
        return Ok(FramePageResult {
            frames: Vec::new(),
            total_frames,
            page_start,
            page_size: 0,
        });
    }

    let ffmpeg = locate_ffmpeg()?;
    let preview_root = std::env::temp_dir().join("GIFP_frame_pages");
    fs::create_dir_all(&preview_root).map_err(|error| AppError::Internal(error.to_string()))?;
    cleanup_old_preview_dirs(&preview_root);
    let output_dir = preview_root.join(unique_output_token());
    fs::create_dir_all(&output_dir).map_err(|error| AppError::Internal(error.to_string()))?;
    let page_end = page_start + u64::from(page_size) - 1;
    let mut filters = Vec::new();
    if playback_speed > 1.0001 {
        filters.push(format!("setpts=PTS/{playback_speed:.6}"));
    }
    // Passing the final sampled frame keeps the page count aligned with the
    // editor's round(duration / speed * fps) grid, including short or sped-up
    // clips whose final source PTS falls just before the nominal duration.
    filters.push(format!("fps=fps={fps}:start_time=0:eof_action=pass"));
    filters.push(format!("select='between(n\\,{page_start}\\,{page_end})'"));
    let max_width = request.max_width.clamp(96, 360);
    filters.push(format!("scale={max_width}:-2:flags=lanczos"));
    // FFmpeg 9 rejects non-full-range YUV for MJPEG unless the JPEG pixel
    // format is explicit. Keep exact-frame pages compatible with the bundled
    // runtime instead of relying on the encoder's legacy implicit conversion.
    filters.push("format=yuvj420p".to_string());
    let output_pattern = output_dir.join("frame-%06d.jpg");
    let result = Command::new(&ffmpeg)
        .arg("-hide_banner")
        .arg("-loglevel")
        .arg("error")
        .arg("-ss")
        .arg(format!("{start:.6}"))
        .args(animation_demux_args(input))
        .arg("-i")
        .arg(input)
        .arg("-t")
        .arg(format!("{:.6}", end - start))
        .arg("-an")
        .arg("-vf")
        .arg(filters.join(","))
        .arg("-fps_mode")
        .arg("vfr")
        .arg("-frames:v")
        .arg(page_size.to_string())
        .arg("-q:v")
        .arg("4")
        .arg("-y")
        .arg(&output_pattern)
        .output_for_conversion_task()
        .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    if !result.status.success() {
        let _ = fs::remove_dir_all(&output_dir);
        return Err(AppError::EncodeFailed(format!(
            "Frame page extraction failed: {}",
            String::from_utf8_lossy(&result.stderr)
        )));
    }

    let mut paths = fs::read_dir(&output_dir)
        .map_err(|error| AppError::Internal(error.to_string()))?
        .flatten()
        .map(|entry| entry.path())
        .filter(|path| {
            path.extension()
                .is_some_and(|extension| extension.eq_ignore_ascii_case("jpg"))
        })
        .collect::<Vec<_>>();
    paths.sort();
    let frames = paths
        .into_iter()
        .take(page_size as usize)
        .enumerate()
        .map(|(offset, path)| {
            let index = page_start + offset as u64;
            FramePageThumbnail {
                index,
                time: start + (index as f64 * playback_speed) / f64::from(fps),
                path: path.to_string_lossy().to_string(),
            }
        })
        .collect::<Vec<_>>();
    if frames.is_empty() {
        let _ = fs::remove_dir_all(&output_dir);
        return Err(AppError::EncodeFailed(
            "FFmpeg did not create any exact frame thumbnails".to_string(),
        ));
    }
    Ok(FramePageResult {
        frames,
        total_frames,
        page_start,
        page_size,
    })
}

fn normalize_thumbnail_times(times: Vec<f64>) -> Vec<f64> {
    let mut times: Vec<f64> = times
        .into_iter()
        .filter(|time| time.is_finite() && *time >= 0.0)
        .take(MAX_MEDIA_THUMBNAIL_TIMES)
        .collect();
    times.sort_by(|left, right| left.total_cmp(right));
    times.dedup_by(|left, right| (*left - *right).abs() < 0.001);
    times
}

#[tauri::command]
pub async fn track_media_region(
    request: TrackMediaRegionRequest,
) -> Result<TrackMediaRegionResult, AppError> {
    tauri::async_runtime::spawn_blocking(move || track_media_region_inner(request))
        .await
        .map_err(|error| AppError::Internal(format!("Object tracking worker failed: {error}")))?
}

fn track_media_region_inner(
    request: TrackMediaRegionRequest,
) -> Result<TrackMediaRegionResult, AppError> {
    let input_text = request
        .input_path
        .trim()
        .trim_matches(|ch| ch == '"' || ch == '\'');
    let input = Path::new(input_text);
    if !input.is_file() || !is_media_source(input) {
        return Err(AppError::InvalidInput(format!(
            "Unsupported tracking source: {}",
            input.display()
        )));
    }
    let coordinates = [
        request.x_percent,
        request.y_percent,
        request.width_percent,
        request.height_percent,
    ];
    if coordinates.iter().any(|value| !value.is_finite())
        || request.width_percent < 2.0
        || request.height_percent < 2.0
        || request.x_percent < 0.0
        || request.y_percent < 0.0
        || request.x_percent + request.width_percent > 100.001
        || request.y_percent + request.height_percent > 100.001
    {
        return Err(AppError::InvalidInput(
            "Tracking region must stay inside the source frame and be at least 2% wide and high"
                .to_string(),
        ));
    }
    if !request.start_seconds.is_finite()
        || !request.end_seconds.is_finite()
        || request.start_seconds < 0.0
        || request.end_seconds <= request.start_seconds
    {
        return Err(AppError::InvalidInput(
            "Tracking range must have a finite start and a later end".to_string(),
        ));
    }

    let duration = (request.end_seconds - request.start_seconds).max(0.1);
    let max_frames = request.max_frames.clamp(2, 240);
    let sample_fps = tracking_sample_fps_for_range(duration, request.sample_fps, max_frames)?;
    let (source_width, source_height) = probe_display_dimensions(&locate_ffprobe()?, input)?;
    if source_width < 8 || source_height < 8 {
        return Err(AppError::InvalidInput(
            "Tracking requires a source frame of at least 8 × 8 pixels".to_string(),
        ));
    }
    let proxy_width = 320_u32.min(source_width.max(8)) & !1;
    let proxy_height = ((f64::from(proxy_width) * f64::from(source_height)
        / f64::from(source_width.max(1)))
    .round() as u32)
        .clamp(8, 720)
        & !1;
    let frame_size =
        usize::try_from(u64::from(proxy_width) * u64::from(proxy_height)).map_err(|_| {
            AppError::InvalidInput("Tracking proxy dimensions are too large".to_string())
        })?;

    let ffmpeg = locate_ffmpeg()?;
    let output = Command::new(ffmpeg)
        .arg("-hide_banner")
        .arg("-loglevel")
        .arg("error")
        .arg("-ss")
        .arg(format!("{:.6}", request.start_seconds))
        .arg("-t")
        .arg(format!("{duration:.6}"))
        .arg("-i")
        .arg(input)
        .arg("-vf")
        .arg(format!(
            "fps={sample_fps},scale={proxy_width}:{proxy_height}:flags=bilinear,format=gray"
        ))
        .arg("-frames:v")
        .arg(max_frames.to_string())
        .arg("-an")
        .arg("-sn")
        .arg("-f")
        .arg("rawvideo")
        .arg("-pix_fmt")
        .arg("gray")
        .arg("-")
        .output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(
            String::from_utf8_lossy(&output.stderr).to_string(),
        ));
    }
    let frames = output.stdout.chunks_exact(frame_size).collect::<Vec<_>>();
    if frames.len() < 2 {
        return Err(AppError::DecodeFailed(
            "The selected range did not produce enough frames for tracking".to_string(),
        ));
    }
    let covered_duration = frames.len() as f64 / f64::from(sample_fps);
    if covered_duration + 1.0 / f64::from(sample_fps) + 0.001 < duration {
        return Err(AppError::DecodeFailed(format!(
            "Tracking covered {:.2} of {:.2} seconds; shorten the selected range or verify the source duration",
            covered_duration, duration
        )));
    }

    let proxy_width_usize = proxy_width as usize;
    let proxy_height_usize = proxy_height as usize;
    let box_width = ((request.width_percent / 100.0 * f64::from(proxy_width)).round() as usize)
        .clamp(6, proxy_width_usize.saturating_sub(1).max(6));
    let box_height = ((request.height_percent / 100.0 * f64::from(proxy_height)).round() as usize)
        .clamp(6, proxy_height_usize.saturating_sub(1).max(6));
    let mut x = ((request.x_percent / 100.0 * f64::from(proxy_width)).round() as usize)
        .min(proxy_width_usize.saturating_sub(box_width));
    let mut y = ((request.y_percent / 100.0 * f64::from(proxy_height)).round() as usize)
        .min(proxy_height_usize.saturating_sub(box_height));
    let mut template = copy_gray_patch(frames[0], proxy_width_usize, x, y, box_width, box_height);
    let mut keyframes = Vec::with_capacity(frames.len());
    let mut confidence_total = 0.0;
    let mut low_confidence_frames = 0_u32;

    for (index, frame) in frames.iter().enumerate() {
        let confidence = if index == 0 {
            1.0
        } else {
            let tracked = track_gray_patch(
                &template,
                frame,
                (proxy_width_usize, proxy_height_usize),
                x,
                y,
                box_width,
                box_height,
            );
            x = tracked.0;
            y = tracked.1;
            if tracked.2 >= 0.72 && index % 3 == 0 {
                update_gray_template(
                    &mut template,
                    frame,
                    proxy_width_usize,
                    x,
                    y,
                    box_width,
                    box_height,
                );
            }
            tracked.2
        };
        if confidence < 0.55 {
            low_confidence_frames = low_confidence_frames.saturating_add(1);
        }
        confidence_total += confidence;
        keyframes.push(TrackMediaRegionKeyframe {
            time_seconds: request.start_seconds + index as f64 / f64::from(sample_fps),
            x_percent: x as f64 / f64::from(proxy_width) * 100.0,
            y_percent: y as f64 / f64::from(proxy_height) * 100.0,
            width_percent: box_width as f64 / f64::from(proxy_width) * 100.0,
            height_percent: box_height as f64 / f64::from(proxy_height) * 100.0,
            confidence,
        });
    }
    let frames_analyzed = keyframes.len() as u32;
    Ok(TrackMediaRegionResult {
        model_id: "gifp.zero-mean-template.v1".to_string(),
        frames_analyzed,
        average_confidence: confidence_total / f64::from(frames_analyzed.max(1)),
        low_confidence_frames,
        keyframes,
    })
}

fn tracking_sample_fps_for_range(
    duration_seconds: f64,
    requested_sample_fps: u32,
    max_frames: u32,
) -> Result<u32, AppError> {
    let duration = duration_seconds.max(0.1);
    let frame_budget = max_frames.clamp(2, 240);
    if duration * 2.0 > f64::from(frame_budget) + 0.001 {
        return Err(AppError::InvalidInput(format!(
            "Object tracking supports up to {:.0} seconds per range; select a shorter continuous segment",
            f64::from(frame_budget) / 2.0
        )));
    }
    let requested = requested_sample_fps.clamp(2, 12);
    let capacity = (f64::from(frame_budget) / duration)
        .floor()
        .clamp(2.0, 12.0) as u32;
    Ok(requested.min(capacity))
}

fn copy_gray_patch(
    frame: &[u8],
    stride: usize,
    x: usize,
    y: usize,
    width: usize,
    height: usize,
) -> Vec<u8> {
    let mut patch = Vec::with_capacity(width.saturating_mul(height));
    for row in 0..height {
        let start = (y + row).saturating_mul(stride).saturating_add(x);
        let end = start.saturating_add(width).min(frame.len());
        patch.extend_from_slice(&frame[start..end]);
    }
    patch
}

fn tracking_patch_score(
    template: &[u8],
    frame: &[u8],
    stride: usize,
    x: usize,
    y: usize,
    width: usize,
    height: usize,
) -> f64 {
    let sample_step = if width.saturating_mul(height) > 4_000 {
        3
    } else {
        2
    };
    let mut template_sum = 0.0;
    let mut candidate_sum = 0.0;
    let mut count = 0.0;
    for row in (0..height).step_by(sample_step) {
        for column in (0..width).step_by(sample_step) {
            let template_index = row * width + column;
            let frame_index = (y + row) * stride + x + column;
            if template_index >= template.len() || frame_index >= frame.len() {
                continue;
            }
            template_sum += f64::from(template[template_index]);
            candidate_sum += f64::from(frame[frame_index]);
            count += 1.0;
        }
    }
    if count < 4.0 {
        return 0.0;
    }
    let template_mean = template_sum / count;
    let candidate_mean = candidate_sum / count;
    let mut error = 0.0;
    let mut variance = 0.0;
    for row in (0..height).step_by(sample_step) {
        for column in (0..width).step_by(sample_step) {
            let template_index = row * width + column;
            let frame_index = (y + row) * stride + x + column;
            if template_index >= template.len() || frame_index >= frame.len() {
                continue;
            }
            let template_value = f64::from(template[template_index]) - template_mean;
            let candidate_value = f64::from(frame[frame_index]) - candidate_mean;
            let difference = template_value - candidate_value;
            error += difference * difference;
            variance += template_value * template_value;
        }
    }
    let normalized_error = error / (variance * 2.0 + count * 180.0);
    (1.0 - normalized_error).clamp(0.0, 1.0)
}

fn track_gray_patch(
    template: &[u8],
    frame: &[u8],
    frame_size: (usize, usize),
    previous_x: usize,
    previous_y: usize,
    box_width: usize,
    box_height: usize,
) -> (usize, usize, f64) {
    let (frame_width, frame_height) = frame_size;
    let radius_x = (box_width / 2).clamp(8, 64);
    let radius_y = (box_height / 2).clamp(8, 64);
    let min_x = previous_x.saturating_sub(radius_x);
    let min_y = previous_y.saturating_sub(radius_y);
    let max_x = previous_x
        .saturating_add(radius_x)
        .min(frame_width.saturating_sub(box_width));
    let max_y = previous_y
        .saturating_add(radius_y)
        .min(frame_height.saturating_sub(box_height));
    let mut best = (previous_x, previous_y, 0.0_f64);
    for y in (min_y..=max_y).step_by(2) {
        for x in (min_x..=max_x).step_by(2) {
            let similarity =
                tracking_patch_score(template, frame, frame_width, x, y, box_width, box_height);
            let distance = (((x as f64 - previous_x as f64).powi(2)
                + (y as f64 - previous_y as f64).powi(2))
            .sqrt()
                / f64::from(radius_x.max(radius_y) as u32))
            .min(1.0);
            let score = similarity - distance * 0.035;
            if score > best.2 {
                best = (x, y, score);
            }
        }
    }
    let refine_min_x = best.0.saturating_sub(2);
    let refine_max_x = best
        .0
        .saturating_add(2)
        .min(frame_width.saturating_sub(box_width));
    let refine_min_y = best.1.saturating_sub(2);
    let refine_max_y = best
        .1
        .saturating_add(2)
        .min(frame_height.saturating_sub(box_height));
    for y in refine_min_y..=refine_max_y {
        for x in refine_min_x..=refine_max_x {
            let score =
                tracking_patch_score(template, frame, frame_width, x, y, box_width, box_height);
            if score > best.2 {
                best = (x, y, score);
            }
        }
    }
    (best.0, best.1, best.2.clamp(0.0, 1.0))
}

fn update_gray_template(
    template: &mut [u8],
    frame: &[u8],
    stride: usize,
    x: usize,
    y: usize,
    width: usize,
    height: usize,
) {
    for row in 0..height {
        for column in 0..width {
            let template_index = row * width + column;
            let frame_index = (y + row) * stride + x + column;
            if template_index >= template.len() || frame_index >= frame.len() {
                continue;
            }
            template[template_index] = ((u16::from(template[template_index]) * 7
                + u16::from(frame[frame_index]))
                / 8) as u8;
        }
    }
}

#[tauri::command]
pub async fn merge_gif(request: MergeGifRequest) -> Result<GifResult, AppError> {
    tauri::async_runtime::spawn_blocking(move || merge_gif_inner(request))
        .await
        .map_err(|error| AppError::Internal(format!("GIF merge worker failed: {error}")))?
}

#[tauri::command]
pub async fn render_dynamic_poster(
    request: DynamicPosterRequest,
) -> Result<DynamicPosterResult, AppError> {
    tauri::async_runtime::spawn_blocking(move || render_dynamic_poster_inner(request))
        .await
        .map_err(|error| AppError::Internal(format!("Dynamic poster worker failed: {error}")))?
}

fn render_dynamic_poster_inner(
    request: DynamicPosterRequest,
) -> Result<DynamicPosterResult, AppError> {
    let started = Instant::now();
    if request.slots.is_empty() || request.slots.len() > 2 {
        return Err(AppError::InvalidInput(
            "Dynamic poster needs one or two motion slots".to_string(),
        ));
    }
    let width = request.width.clamp(320, 2160);
    let height = request.height.clamp(320, 3840);
    let fps = request.fps.clamp(8, 30);
    let duration = request.duration_seconds.clamp(0.5, 30.0);
    if request.title.chars().count() > 36 || request.subtitle.chars().count() > 72 {
        return Err(AppError::InvalidInput(
            "Dynamic poster copy is longer than the editor limit".to_string(),
        ));
    }
    if !matches!(request.export_mode.as_str(), "gif_webp" | "gif" | "webp") {
        return Err(AppError::InvalidInput(format!(
            "Unsupported dynamic poster export mode: {}",
            request.export_mode
        )));
    }

    let slots: Vec<(PathBuf, u32, u32, u32, u32)> = request
        .slots
        .iter()
        .map(|slot| {
            let path = PathBuf::from(
                slot.input_path
                    .trim()
                    .trim_matches(|character| character == '"' || character == '\''),
            );
            if !path.is_file() || !is_media_source(&path) {
                return Err(AppError::InvalidInput(format!(
                    "Unsupported dynamic poster motion source: {}",
                    path.display()
                )));
            }
            for (name, value) in [
                ("x", slot.x_percent),
                ("y", slot.y_percent),
                ("width", slot.width_percent),
                ("height", slot.height_percent),
            ] {
                if !value.is_finite() || !(0.0..=100.0).contains(&value) {
                    return Err(AppError::InvalidInput(format!(
                        "Dynamic poster slot {name} must be between 0 and 100"
                    )));
                }
            }
            let slot_width = (f64::from(width) * slot.width_percent / 100.0)
                .round()
                .clamp(16.0, f64::from(width)) as u32;
            let slot_height = (f64::from(height) * slot.height_percent / 100.0)
                .round()
                .clamp(16.0, f64::from(height)) as u32;
            let x = (f64::from(width) * slot.x_percent / 100.0)
                .round()
                .clamp(0.0, f64::from(width.saturating_sub(slot_width))) as u32;
            let y = (f64::from(height) * slot.y_percent / 100.0)
                .round()
                .clamp(0.0, f64::from(height.saturating_sub(slot_height)))
                as u32;
            Ok((path, x, y, slot_width, slot_height))
        })
        .collect::<Result<_, AppError>>()?;

    let background = request.background_path.as_ref().and_then(|value| {
        let trimmed = value
            .trim()
            .trim_matches(|character| character == '"' || character == '\'');
        (!trimmed.is_empty()).then(|| PathBuf::from(trimmed))
    });
    if let Some(path) = background.as_ref() {
        if !path.is_file() || !is_merge_source(path) {
            return Err(AppError::InvalidInput(format!(
                "Unsupported dynamic poster background: {}",
                path.display()
            )));
        }
    }

    let output_dir = if request.output_dir.trim().is_empty() {
        slots[0]
            .0
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .to_path_buf()
    } else {
        PathBuf::from(request.output_dir.trim())
    };
    prepare_writable_output_directory(&output_dir, "dynamic poster")?;
    let ffmpeg = locate_ffmpeg()?;
    let temp = OwnedTempDir::create("gif-p-dynamic-poster")?;
    let ass_path = temp.path().join("poster-copy.ass");
    fs::write(
        &ass_path,
        build_dynamic_poster_ass(
            &request.title,
            &request.subtitle,
            width,
            height,
            &request.accent,
        ),
    )
    .map_err(|error| AppError::Internal(format!("Write dynamic poster copy: {error}")))?;

    let mut outputs = Vec::new();
    let formats: Vec<&str> = match request.export_mode.as_str() {
        "gif" => vec!["gif"],
        "webp" => vec!["webp"],
        _ => vec!["gif", "webp"],
    };
    for format in formats {
        let candidate = temp.path().join(format!("poster.{format}"));
        encode_dynamic_poster(
            &ffmpeg,
            background.as_deref(),
            &slots,
            &ass_path,
            width,
            height,
            fps,
            duration,
            format,
            &request.accent,
            &candidate,
        )?;
        let final_path = output_dir.join(format!(
            "dynamic-poster-gifp-{}.{}",
            unique_output_token(),
            format
        ));
        let size_bytes = fs::metadata(&candidate)
            .map_err(|error| AppError::DecodeFailed(format!("Read dynamic poster size: {error}")))?
            .len();
        fs::copy(&candidate, &final_path)
            .map_err(|error| AppError::Internal(format!("Publish dynamic poster: {error}")))?;
        outputs.push(DynamicPosterOutput {
            format: format.to_string(),
            path: final_path.to_string_lossy().to_string(),
            size_bytes,
        });
    }
    Ok(DynamicPosterResult {
        outputs,
        elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
    })
}

#[allow(clippy::too_many_arguments)]
fn encode_dynamic_poster(
    ffmpeg: &Path,
    background: Option<&Path>,
    slots: &[(PathBuf, u32, u32, u32, u32)],
    ass_path: &Path,
    width: u32,
    height: u32,
    fps: u32,
    duration: f64,
    format: &str,
    accent: &str,
    output: &Path,
) -> Result<(), AppError> {
    let background_color = match accent {
        "mint" => "182926",
        "coral" => "2b1d1d",
        _ => "1b1726",
    };
    let mut command = Command::new(ffmpeg);
    command
        .arg("-y")
        .arg("-hide_banner")
        .arg("-loglevel")
        .arg("error");
    if let Some(path) = background {
        let demux_args = animation_demux_args(path);
        if demux_args.is_empty() {
            command
                .arg("-loop")
                .arg("1")
                .arg("-framerate")
                .arg(fps.to_string());
        } else {
            command.arg("-stream_loop").arg("-1");
        }
        command.args(demux_args).arg("-i").arg(path);
    } else {
        command.arg("-f").arg("lavfi").arg("-i").arg(format!(
            "color=c=0x{background_color}:s={width}x{height}:r={fps}:d={duration:.3}"
        ));
    }
    for (path, ..) in slots {
        command
            .arg("-stream_loop")
            .arg("-1")
            .args(animation_demux_args(path))
            .arg("-i")
            .arg(path);
    }

    let mut filters = vec![format!(
        "[0:v]scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},fps={fps},trim=duration={duration:.3},setpts=PTS-STARTPTS[poster0]"
    )];
    let mut previous = "poster0".to_string();
    for (index, (_, x, y, slot_width, slot_height)) in slots.iter().enumerate() {
        let input_index = index + 1;
        let slot_label = format!("slot{input_index}");
        let next = format!("poster{input_index}");
        filters.push(format!(
            "[{input_index}:v]scale={slot_width}:{slot_height}:force_original_aspect_ratio=increase,crop={slot_width}:{slot_height},fps={fps},trim=duration={duration:.3},setpts=PTS-STARTPTS[{slot_label}]"
        ));
        filters.push(format!(
            "[{previous}][{slot_label}]overlay=x={x}:y={y}:shortest=1:format=auto[{next}]"
        ));
        previous = next;
    }
    filters.push(format!(
        "[{previous}]ass=filename='{}':alpha=1,format=rgba[composite]",
        ffmpeg_filter_path(&ass_path.to_string_lossy())
    ));
    let webp_plan = webp_encode_plan(48, 4, true, false);
    if format == "gif" {
        filters.push("[composite]split[gifbase][palettebase]".to_string());
        filters.push(
            "[palettebase]palettegen=max_colors=256:reserve_transparent=0:stats_mode=diff[palette]"
                .to_string(),
        );
        filters.push(
            "[gifbase][palette]paletteuse=dither=sierra2_4a:diff_mode=rectangle[encoded]"
                .to_string(),
        );
    } else {
        filters.push(format!(
            "[composite]format={}[encoded]",
            webp_plan.pixel_format
        ));
    }
    command
        .arg("-filter_complex")
        .arg(filters.join(";"))
        .arg("-map")
        .arg("[encoded]")
        .arg("-an")
        .arg("-t")
        .arg(format!("{duration:.3}"));
    if format == "gif" {
        command.arg("-loop").arg("0");
    } else {
        command
            .arg("-c:v")
            .arg("libwebp_anim")
            .arg("-lossless")
            .arg(u8::from(webp_plan.lossless).to_string())
            .arg("-quality")
            .arg(webp_plan.quality.to_string())
            .arg("-compression_level")
            .arg(webp_plan.compression_level.to_string())
            .arg("-loop")
            .arg(webp_plan.loop_count.to_string());
    }
    let result = command
        .arg(output)
        .output_for_conversion_task()
        .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    if !result.status.success() {
        return Err(AppError::EncodeFailed(
            String::from_utf8_lossy(&result.stderr).to_string(),
        ));
    }
    Ok(())
}

fn build_dynamic_poster_ass(
    title: &str,
    subtitle: &str,
    width: u32,
    height: u32,
    accent: &str,
) -> String {
    let accent_color = match accent {
        "mint" => "&H00A9B746",
        "coral" => "&H006F80EE",
        _ => "&H00D26786",
    };
    let title_size = (f64::from(width) * 0.061).round().clamp(32.0, 110.0) as u32;
    let subtitle_size = (f64::from(width) * 0.025).round().clamp(18.0, 48.0) as u32;
    let x = (f64::from(width) * 0.08).round() as u32;
    let title_y = (f64::from(height) * 0.075).round() as u32;
    let subtitle_y = (f64::from(height) * 0.155).round() as u32;
    format!(
        "[Script Info]\nScriptType: v4.00+\nPlayResX: {width}\nPlayResY: {height}\nScaledBorderAndShadow: yes\nWrapStyle: 2\n\n[V4+ Styles]\nFormat: Name,Fontname,Fontsize,PrimaryColour,SecondaryColour,OutlineColour,BackColour,Bold,Italic,Underline,StrikeOut,ScaleX,ScaleY,Spacing,Angle,BorderStyle,Outline,Shadow,Alignment,MarginL,MarginR,MarginV,Encoding\nStyle: Title,Microsoft YaHei,{title_size},&H00FFFFFF,&H000000FF,&H80000000,&H00000000,-1,0,0,0,100,100,0,0,1,2,1,7,0,0,0,1\nStyle: Subtitle,Microsoft YaHei,{subtitle_size},&H00FFFFFF,&H000000FF,{accent_color},&H00000000,0,0,0,0,100,100,0,0,1,1,0,7,0,0,0,1\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\nDialogue: 0,0:00:00.00,9:59:59.00,Title,,0,0,0,,{{\\pos({x},{title_y})}}{}\nDialogue: 0,0:00:00.00,9:59:59.00,Subtitle,,0,0,0,,{{\\pos({x},{subtitle_y})}}{}\n",
        escape_ass_text(title.trim()),
        escape_ass_text(subtitle.trim())
    )
}

fn merge_gif_inner(request: MergeGifRequest) -> Result<GifResult, AppError> {
    let started = Instant::now();
    let inputs: Vec<PathBuf> = request
        .input_paths
        .iter()
        .map(|path| PathBuf::from(path.trim().trim_matches(|ch| ch == '"' || ch == '\'')))
        .collect();
    if inputs.len() < 2 {
        return Err(AppError::InvalidInput(
            "GIF merge needs at least two GIF/image files".to_string(),
        ));
    }
    for input in &inputs {
        if !input.exists() || !input.is_file() || !is_merge_source(input) {
            return Err(AppError::InvalidInput(format!(
                "Unsupported merge item: {}",
                input.display()
            )));
        }
    }

    let output_dir = if request.output_dir.trim().is_empty() {
        inputs[0]
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .to_path_buf()
    } else {
        PathBuf::from(request.output_dir.trim())
    };
    prepare_writable_output_directory(&output_dir, "merged GIF")?;
    let ffmpeg = locate_ffmpeg()?;
    let final_output = next_merge_output_path(&output_dir);
    let export_temp = OwnedTempDir::create("gif-p-merge")?;
    let output = export_temp.path().join("candidate.gif");
    encode_merged_gif(&ffmpeg, &inputs, &output, &request)?;
    let size_bytes = fs::metadata(&output)
        .map_err(|error| AppError::DecodeFailed(format!("Read merged GIF size: {error}")))?
        .len();
    let output_inspection = Some(verify_delivery_output(&output, AnimationFormat::Gif)?);
    let output_frame_count = output_inspection
        .as_ref()
        .map(|inspection| inspection.frame_count)
        .unwrap_or(0);
    let effective_output_fps = output_inspection.as_ref().and_then(|inspection| {
        (inspection.duration > f64::EPSILON)
            .then_some(inspection.frame_count as f64 / inspection.duration)
    });
    publish_file_after_owned_temp_cleanup(&output, export_temp, &final_output, false)?;

    Ok(GifResult {
        gif_cleanup_report: None,
        advanced_compression_report: None,
        structure_optimization_report: None,
        index_compression_report: None,
        postprocess_report: None,
        pipeline_profile: None,
        input_path: inputs
            .iter()
            .map(|path| path.to_string_lossy().to_string())
            .collect::<Vec<_>>()
            .join(";"),
        output_path: final_output.to_string_lossy().to_string(),
        size_bytes,
        encoder_used: "gif_merge".to_string(),
        status: "done".to_string(),
        backend_id: "ffmpeg.animation".to_string(),
        backend_version: ffmpeg_version(&ffmpeg),
        ffmpeg_engine_version: None,
        fallback_reason: None,
        palette_strategy: "full".to_string(),
        attempts: 1,
        elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
        output_width: request.width,
        output_fps: request.fps,
        effective_output_fps,
        output_frame_count,
        output_colors: palette_color_count(request.colors),
        output_format: "gif".to_string(),
        output_codec: "gif".to_string(),
        output_has_alpha: output_inspection
            .as_ref()
            .is_some_and(|inspection| inspection.has_alpha),
        target_size_bytes: None,
        target_deviation_percent: None,
        warnings: Vec::new(),
        perceptual_report: None,
        palette_report: None,
        region_dither_report: None,
        indexed_gif_writer_report: None,
        motion_delivery_selection_report: None,
        palette_reservation_selection_report: None,
        target_optimizer_report: None,
        live_photo: None,
    })
}

#[tauri::command]
pub async fn start_screen_recording(request: ScreenRecordRequest) -> Result<String, AppError> {
    tauri::async_runtime::spawn_blocking(move || start_screen_recording_inner(request))
        .await
        .map_err(|error| AppError::Internal(format!("Recording worker failed: {error}")))?
}

fn start_screen_recording_inner(request: ScreenRecordRequest) -> Result<String, AppError> {
    let mut state = recording_state()
        .lock()
        .map_err(|_| AppError::Internal("Recording state is locked".to_string()))?;
    if !matches!(*state, RecordingState::Idle) {
        return Err(AppError::InvalidInput(
            "Screen recording is already running".to_string(),
        ));
    }

    let ffmpeg = locate_ffmpeg()?;
    if request.capture_backend != "psgrab" && !probe_screen_capture_chain(&ffmpeg) {
        return Err(AppError::MissingDependency(
            "The discovered FFmpeg build is missing the Windows screen-capture closure (gdigrab, ddagrab, d3d11va, or their required filters). Choose the screenshot fallback or use the bundled GIFP runtime."
                .to_string(),
        ));
    }
    let h264_encoder = required_h264_encoder(&ffmpeg)?;
    let _ = recording_h264_usage(&ffmpeg, h264_encoder);
    let output_dir = if request.output_dir.trim().is_empty() {
        std::env::temp_dir().join("GIF_P_recordings")
    } else {
        PathBuf::from(request.output_dir.trim())
    };
    prepare_writable_output_directory(&output_dir, "screen recording")?;
    let now = unique_output_token();
    let final_output_path = output_dir.join(format!("gifp-record-{now}.mp4"));
    let recording_temp = OwnedTempDir::create("gif-p-screen")?;
    let temp_dir = recording_temp.path().to_path_buf();
    let output_path = temp_dir.join("candidate.mp4");
    let fps_value = request.fps.clamp(5, 30);
    let fps = fps_value.to_string();

    if request.capture_backend == "psgrab" {
        let stop_path = temp_dir.join("stop.txt");
        let stderr_path = temp_dir.join("backend.stderr.log");
        let stderr_file = File::create(&stderr_path)
            .map_err(|error| AppError::Internal(format!("Create recording log: {error}")))?;
        let frame_pattern = temp_dir.join("frame_{0:D6}.jpg");
        let region_enabled = if request.region_enabled {
            "$true"
        } else {
            "$false"
        };
        let width = request.width.clamp(120, 3840);
        let height = request.height.clamp(120, 2160);
        let script = format!(
            r#"
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class GifPDpi {{
  [DllImport("Shcore.dll")]
  public static extern int SetProcessDpiAwareness(int value);
  [DllImport("user32.dll")]
  public static extern bool SetProcessDPIAware();
}}
"@
try {{
  [GifPDpi]::SetProcessDpiAwareness(2) | Out-Null
}} catch {{
  try {{ [GifPDpi]::SetProcessDPIAware() | Out-Null }} catch {{}}
}}
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
$ErrorActionPreference = 'Stop'
$dir = '{}'
$stop = '{}'
$pattern = '{}'
$fps = {}
$region = {}
$x = {}
$y = {}
$w = {}
$h = {}
$bounds = [System.Windows.Forms.SystemInformation]::VirtualScreen
if (-not $region) {{
  $x = $bounds.X
  $y = $bounds.Y
  $w = $bounds.Width
  $h = $bounds.Height
}}
$delay = [Math]::Max(1, [int](1000 / $fps))
$i = 0
while (-not (Test-Path -LiteralPath $stop)) {{
  $bmp = New-Object Drawing.Bitmap $w, $h
  $g = [Drawing.Graphics]::FromImage($bmp)
  try {{
    $g.CopyFromScreen($x, $y, 0, 0, $bmp.Size)
    $name = [String]::Format($pattern, $i)
    $bmp.Save($name, [Drawing.Imaging.ImageFormat]::Jpeg)
  }} finally {{
    $g.Dispose()
    $bmp.Dispose()
  }}
  $i += 1
  Start-Sleep -Milliseconds $delay
}}
"#,
            escape_ps_path(&temp_dir),
            escape_ps_path(&stop_path),
            escape_ps_path(&frame_pattern),
            fps_value,
            region_enabled,
            request.x,
            request.y,
            width,
            height,
        );

        let child_result = Command::new("powershell")
            .arg("-NoProfile")
            .arg("-STA")
            .arg("-ExecutionPolicy")
            .arg("Bypass")
            .arg("-Command")
            .arg(script)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::from(stderr_file))
            .spawn();
        let mut child = match child_result {
            Ok(child) => child,
            Err(error) => {
                return Err(AppError::EncodeFailed(format!(
                    "Failed to start screenshot recording: {error}"
                )));
            }
        };
        let job = match attach_recording_job(&mut child) {
            Ok(job) => job,
            Err(failure) if failure.reaped => return Err(failure.error),
            Err(failure) => {
                *state = RecordingState::Running(RecordingSession {
                    child,
                    job: None,
                    auxiliary: None,
                    output_path: output_path.clone(),
                    final_output_path: final_output_path.clone(),
                    stderr_path,
                    temp_dir: Some(recording_temp.into_path()),
                    stop_path: Some(stop_path),
                    fps: fps_value,
                    backend: "psgrab".to_string(),
                });
                return Err(failure.error);
            }
        };
        std::thread::sleep(std::time::Duration::from_millis(450));
        if let Ok(Some(status)) = child.try_wait() {
            let detail = recording_backend_error_detail(&stderr_path);
            return Err(AppError::EncodeFailed(format!(
                "Screenshot recording backend exited immediately ({status}){detail}."
            )));
        }
        *state = RecordingState::Running(RecordingSession {
            child,
            job: Some(job),
            auxiliary: None,
            output_path: output_path.clone(),
            final_output_path: final_output_path.clone(),
            stderr_path,
            temp_dir: Some(recording_temp.into_path()),
            stop_path: Some(stop_path),
            fps: fps_value,
            backend: "psgrab".to_string(),
        });
        return Ok(final_output_path.to_string_lossy().to_string());
    }

    let mut command = Command::new(&ffmpeg);
    let stderr_path = temp_dir.join("backend.stderr.log");
    let stderr_file = File::create(&stderr_path)
        .map_err(|error| AppError::Internal(format!("Create recording log: {error}")))?;
    command.arg("-y").arg("-hide_banner");
    if request.capture_backend == "ddagrab" {
        let mut source = format!("ddagrab=framerate={fps}");
        if request.region_enabled {
            let width = request.width.clamp(120, 3840);
            let height = request.height.clamp(120, 2160);
            source.push_str(&format!(
                ":offset_x={}:offset_y={}:video_size={}x{}",
                request.x, request.y, width, height
            ));
        }
        command
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg(source)
            .arg("-vf")
            .arg("hwdownload,format=bgra");
    } else {
        command.arg("-f").arg("gdigrab").arg("-framerate").arg(&fps);
        if request.region_enabled {
            let width = request.width.clamp(120, 3840).to_string();
            let height = request.height.clamp(120, 2160).to_string();
            command
                .arg("-offset_x")
                .arg(request.x.to_string())
                .arg("-offset_y")
                .arg(request.y.to_string())
                .arg("-video_size")
                .arg(format!("{width}x{height}"));
        }
        command.arg("-i").arg("desktop");
    }

    let h264_encoder = required_h264_encoder(&ffmpeg)?;
    command.arg("-an");
    command.args(h264_encoder_args(
        h264_encoder,
        recording_h264_usage(&ffmpeg, h264_encoder),
    ));
    command
        .arg("-pix_fmt")
        .arg("yuv420p")
        .arg(&output_path)
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::from(stderr_file));

    let mut child = command.spawn().map_err(|err| {
        AppError::EncodeFailed(format!("Failed to start screen recording: {err}"))
    })?;
    let job = match attach_recording_job(&mut child) {
        Ok(job) => job,
        Err(failure) if failure.reaped => return Err(failure.error),
        Err(failure) => {
            *state = RecordingState::Running(RecordingSession {
                child,
                job: None,
                auxiliary: None,
                output_path: output_path.clone(),
                final_output_path: final_output_path.clone(),
                stderr_path,
                temp_dir: Some(recording_temp.into_path()),
                stop_path: None,
                fps: fps_value,
                backend: request.capture_backend,
            });
            return Err(failure.error);
        }
    };
    std::thread::sleep(std::time::Duration::from_millis(450));
    if let Ok(Some(status)) = child.try_wait() {
        let detail = recording_backend_error_detail(&stderr_path);
        return Err(AppError::EncodeFailed(format!(
            "Screen recording backend exited immediately ({status}){detail}. Try another recording backend."
        )));
    }
    *state = RecordingState::Running(RecordingSession {
        child,
        job: Some(job),
        auxiliary: None,
        output_path: output_path.clone(),
        final_output_path: final_output_path.clone(),
        stderr_path,
        temp_dir: Some(recording_temp.into_path()),
        stop_path: None,
        fps: fps_value,
        backend: request.capture_backend,
    });
    Ok(final_output_path.to_string_lossy().to_string())
}

#[tauri::command]
pub async fn stop_screen_recording() -> Result<String, AppError> {
    tauri::async_runtime::spawn_blocking(stop_screen_recording_inner)
        .await
        .map_err(|error| AppError::Internal(format!("Recording worker failed: {error}")))?
}

pub(crate) fn shutdown_screen_recording() {
    let mut session = {
        let Ok(mut state) = recording_state().lock() else {
            return;
        };
        match std::mem::replace(&mut *state, RecordingState::Idle) {
            RecordingState::Running(session) => session,
            RecordingState::Idle => return,
            RecordingState::Stopping => {
                // The blocking stop worker owns the session. Its Job Object is
                // still the process-exit safety net, so do not fabricate or
                // overwrite state here.
                *state = RecordingState::Stopping;
                return;
            }
        }
    };

    if let Some(stop_path) = session.stop_path.as_deref() {
        let _ = fs::write(stop_path, "stop");
    } else if let Some(stdin) = session.child.stdin.as_mut() {
        let _ = stdin.write_all(b"q");
        let _ = stdin.flush();
    }

    let primary_reaped = shutdown_managed_child(&mut session.child, &mut session.job);
    let auxiliary_reaped = session
        .auxiliary
        .as_mut()
        .map(|auxiliary| shutdown_managed_child(&mut auxiliary.child, &mut auxiliary.job))
        .unwrap_or(true);
    if primary_reaped && auxiliary_reaped {
        if let Some(temp_dir) = session.temp_dir.take() {
            let _ = OwnedTempDir::adopt(temp_dir, "gif-p-screen-").cleanup();
        }
    }
}

fn shutdown_managed_child(child: &mut Child, job: &mut Option<KillOnCloseJob>) -> bool {
    let mut reaped = wait_for_child_exit(child, Duration::from_millis(200))
        .ok()
        .flatten()
        .is_some();
    if !reaped {
        // Closing the Job Object terminates the whole process tree instead of
        // only the direct child.
        drop(job.take());
        reaped = wait_for_child_exit(child, Duration::from_millis(800))
            .ok()
            .flatten()
            .is_some();
    }
    if !reaped {
        reaped = terminate_and_reap_child(child).is_ok();
    }
    reaped
}

fn stop_screen_recording_inner() -> Result<String, AppError> {
    let mut session = {
        let mut state = recording_state()
            .lock()
            .map_err(|_| AppError::Internal("Recording state is locked".to_string()))?;
        match std::mem::replace(&mut *state, RecordingState::Stopping) {
            RecordingState::Running(session) => session,
            RecordingState::Idle => {
                *state = RecordingState::Idle;
                return Err(AppError::InvalidInput(
                    "No screen recording is running".to_string(),
                ));
            }
            RecordingState::Stopping => {
                *state = RecordingState::Stopping;
                return Err(AppError::InvalidInput(
                    "Screen recording is already stopping".to_string(),
                ));
            }
        }
    };

    let mut failure_stage = RecordingStopStage::StopBackend;
    let result = (|| -> Result<String, AppError> {
        if session.backend == "psgrab" {
            stop_psgrab_process(&mut session)?;
            failure_stage = RecordingStopStage::EncodeScreenshots;
            encode_screenshot_sequence(&mut session)?;
        } else {
            if let Some(stdin) = session.child.stdin.as_mut() {
                let _ = stdin.write_all(b"q");
                let _ = stdin.flush();
            }
            let deadline = Instant::now() + Duration::from_secs(10);
            let status = loop {
                match session.child.try_wait() {
                    Ok(Some(status)) => break status,
                    Ok(None) if Instant::now() < deadline => {
                        std::thread::sleep(Duration::from_millis(25));
                    }
                    Ok(None) => {
                        terminate_and_reap_child(&mut session.child).map_err(|error| {
                            AppError::EncodeFailed(format!(
                                "Screen recording backend did not stop within 10 seconds and could not be terminated: {error}"
                            ))
                        })?;
                        return Err(AppError::EncodeFailed(
                            "Screen recording backend did not stop within 10 seconds; the incomplete recording was discarded."
                                .to_string(),
                        ));
                    }
                    Err(wait_error) => {
                        let terminate_error = terminate_and_reap_child(&mut session.child).err();
                        let terminate_suffix = terminate_error
                            .map(|error| format!("; forced termination also failed: {error}"))
                            .unwrap_or_default();
                        return Err(AppError::EncodeFailed(format!(
                            "Could not poll screen recording backend: {wait_error}{terminate_suffix}"
                        )));
                    }
                }
            };
            if !status.success() {
                let detail = recording_backend_error_detail(&session.stderr_path);
                return Err(AppError::EncodeFailed(format!(
                    "Screen recording backend exited with {status}{detail}; the incomplete recording was discarded."
                )));
            }
        }
        failure_stage = RecordingStopStage::VerifyOutput;
        let size = fs::metadata(&session.output_path)
            .map(|meta| meta.len())
            .unwrap_or(0);
        if !session.output_path.exists() || size < 2048 {
            return Err(AppError::EncodeFailed(
                "Screen recording did not create a usable video file. Try another recording backend."
                    .to_string(),
            ));
        }
        verify_recording_output(&mut session)?;
        // Keep the verified source and its task workspace intact until the final
        // atomic publication succeeds. A retry can therefore recover from a
        // transient destination/permission failure without losing the capture.
        failure_stage = RecordingStopStage::PublishOutput;
        let destination_dir = session.final_output_path.parent().ok_or_else(|| {
            AppError::InvalidInput(
                "The screen recording destination does not have a parent folder. Choose another output folder."
                    .to_string(),
            )
        })?;
        prepare_writable_output_directory(destination_dir, "screen recording")?;
        publish_file_atomically(&session.output_path, &session.final_output_path, false)?;
        Ok(session.final_output_path.to_string_lossy().to_string())
    })();

    match result {
        Ok(output_path) => {
            let temp_dir = session.temp_dir.take();
            session.job.take();
            let mut state = recording_state()
                .lock()
                .map_err(|_| AppError::Internal("Recording state is locked".to_string()))?;
            *state = RecordingState::Idle;
            drop(state);
            if let Some(temp_dir) = temp_dir {
                // A published, verified recording is a success even if Windows
                // temporarily holds a thumbnail/log handle. Startup stale-task
                // cleanup will retry any directory that cannot be removed now.
                let _ = OwnedTempDir::adopt(temp_dir, "gif-p-screen-").cleanup();
            }
            Ok(output_path)
        }
        Err(error) => {
            let auxiliary_may_be_running = session
                .auxiliary
                .as_mut()
                .is_some_and(|auxiliary| recording_child_may_be_running(&mut auxiliary.child));
            let retryable = auxiliary_may_be_running
                || match failure_stage {
                    RecordingStopStage::StopBackend => {
                        recording_child_may_be_running(&mut session.child)
                    }
                    RecordingStopStage::EncodeScreenshots => {
                        can_retry_screenshot_encoding(&session)
                    }
                    RecordingStopStage::VerifyOutput => {
                        session.backend == "psgrab" && can_retry_screenshot_encoding(&session)
                    }
                    RecordingStopStage::PublishOutput => true,
                };
            let mut state = recording_state()
                .lock()
                .map_err(|_| AppError::Internal("Recording state is locked".to_string()))?;
            if retryable {
                *state = RecordingState::Running(session);
            } else {
                *state = RecordingState::Idle;
                drop(state);
                session.job.take();
                if let Some(temp_dir) = session.temp_dir.take() {
                    let _ = OwnedTempDir::adopt(temp_dir, "gif-p-screen-").cleanup();
                }
            }
            Err(recording_stop_error(error, retryable))
        }
    }
}

fn recording_stop_error(error: AppError, retryable: bool) -> AppError {
    if retryable {
        let marked = AppError::RetryableRecording(error.to_string());
        debug_assert!(is_retryable_recording_error(&marked));
        marked
    } else {
        error
    }
}

fn is_retryable_recording_error(error: &AppError) -> bool {
    matches!(error, AppError::RetryableRecording(_))
        && error
            .to_string()
            .starts_with(RETRYABLE_RECORDING_ERROR_PREFIX)
}

fn recording_child_may_be_running(child: &mut Child) -> bool {
    !matches!(child.try_wait(), Ok(Some(_)))
}

fn can_retry_screenshot_encoding(session: &RecordingSession) -> bool {
    session
        .temp_dir
        .as_deref()
        .and_then(|temp_dir| screenshot_frame_count(temp_dir).ok())
        .is_some_and(|frame_count| frame_count >= 2)
}

fn recording_backend_error_detail(path: &Path) -> String {
    let detail = fs::read_to_string(path)
        .ok()
        .map(|value| value.trim().chars().take(2_000).collect::<String>())
        .filter(|value| !value.is_empty());
    detail.map(|value| format!(": {value}")).unwrap_or_default()
}

fn attach_recording_job(child: &mut Child) -> Result<KillOnCloseJob, JobAttachmentFailure> {
    match KillOnCloseJob::attach(child) {
        Ok(job) => Ok(job),
        Err(job_error) => {
            let terminate_result = terminate_and_reap_child(child);
            let reaped = terminate_result.is_ok();
            let terminate_suffix = terminate_result
                .err()
                .map(|error| {
                    format!(
                        "; child termination also failed: {error}; the live process remains tracked for retry and application-exit cleanup"
                    )
                })
                .unwrap_or_default();
            Err(JobAttachmentFailure {
                error: AppError::EncodeFailed(format!(
                    "Could not secure the recording process in a kill-on-close job: {job_error}{terminate_suffix}"
                )),
                reaped,
            })
        }
    }
}

fn terminate_and_reap_child(child: &mut Child) -> io::Result<()> {
    let mut last_error = None;
    for _ in 0..3 {
        match child.try_wait() {
            Ok(Some(_)) => return Ok(()),
            Ok(None) => {}
            Err(error) => last_error = Some(error),
        }

        if let Err(kill_error) = child.kill() {
            // The process can exit between try_wait and TerminateProcess. Poll
            // once more before treating that expected race as a failure.
            match child.try_wait() {
                Ok(Some(_)) => return Ok(()),
                Ok(None) => last_error = Some(kill_error),
                Err(wait_error) => {
                    last_error = Some(io::Error::new(
                        wait_error.kind(),
                        format!("terminate failed: {kill_error}; poll failed: {wait_error}"),
                    ))
                }
            }
        }

        let deadline = Instant::now() + Duration::from_secs(1);
        loop {
            match child.try_wait() {
                Ok(Some(_)) => return Ok(()),
                Ok(None) if Instant::now() < deadline => {
                    std::thread::sleep(Duration::from_millis(10));
                }
                Ok(None) => break,
                Err(error) => {
                    last_error = Some(error);
                    break;
                }
            }
        }
    }
    Err(last_error.unwrap_or_else(|| {
        io::Error::new(
            io::ErrorKind::TimedOut,
            "recording child did not exit after three termination attempts",
        )
    }))
}

fn stop_psgrab_process(session: &mut RecordingSession) -> Result<(), AppError> {
    let signal_sent = session
        .stop_path
        .as_deref()
        .is_some_and(|stop_path| fs::write(stop_path, "stop").is_ok());
    if !signal_sent {
        return terminate_and_reap_child(&mut session.child).map_err(|error| {
            AppError::EncodeFailed(format!(
                "Could not signal or terminate screenshot recording backend: {error}"
            ))
        });
    }

    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        match session.child.try_wait() {
            Ok(Some(status)) if status.success() => return Ok(()),
            Ok(Some(status)) => {
                let detail = recording_backend_error_detail(&session.stderr_path);
                return Err(AppError::EncodeFailed(format!(
                    "Screenshot recording backend exited with {status}{detail}; the incomplete recording was discarded."
                )));
            }
            Ok(None) if Instant::now() < deadline => {
                std::thread::sleep(Duration::from_millis(25));
            }
            Ok(None) => {
                return terminate_and_reap_child(&mut session.child).map_err(|error| {
                    AppError::EncodeFailed(format!(
                        "Screenshot recording backend did not stop within 5 seconds and could not be terminated: {error}"
                    ))
                });
            }
            Err(wait_error) => {
                let terminate_error = terminate_and_reap_child(&mut session.child).err();
                let terminate_suffix = terminate_error
                    .map(|error| format!("; forced termination also failed: {error}"))
                    .unwrap_or_default();
                return Err(AppError::EncodeFailed(format!(
                    "Could not poll screenshot recording backend: {wait_error}{terminate_suffix}"
                )));
            }
        }
    }
}

fn encode_screenshot_sequence(session: &mut RecordingSession) -> Result<(), AppError> {
    reap_auxiliary_child(session)?;
    let Some(temp_dir) = &session.temp_dir else {
        return Ok(());
    };
    let frame_count = screenshot_frame_count(temp_dir).map_err(AppError::Internal)?;
    if frame_count < 2 {
        return Err(AppError::EncodeFailed(
            "Screenshot recording did not capture enough frames.".to_string(),
        ));
    }

    let ffmpeg = locate_ffmpeg()?;
    let pattern = temp_dir.join("frame_%06d.jpg");
    let stderr_path = temp_dir.join("sequence-encode.stderr.log");
    let stderr_file = File::create(&stderr_path)
        .map_err(|error| AppError::Internal(format!("Create screenshot encoder log: {error}")))?;
    let mut encoder = Command::new(&ffmpeg);
    let h264_encoder = required_h264_encoder(&ffmpeg)?;
    encoder
        .arg("-y")
        .arg("-hide_banner")
        .arg("-framerate")
        .arg(session.fps.to_string())
        .arg("-i")
        .arg(pattern)
        .arg("-vf")
        .arg("scale=trunc(iw/2)*2:trunc(ih/2)*2")
        .arg("-an");
    encoder.args(h264_encoder_args(
        h264_encoder,
        recording_h264_usage(&ffmpeg, h264_encoder),
    ));
    encoder
        .arg("-pix_fmt")
        .arg("yuv420p")
        .arg(&session.output_path)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::from(stderr_file));
    let status = run_recording_helper_bounded(
        session,
        encoder,
        Duration::from_secs(120),
        "screenshot sequence encoder",
    )?;
    if !status.success() {
        let detail = recording_backend_error_detail(&stderr_path);
        return Err(AppError::EncodeFailed(format!(
            "Failed to encode screenshot sequence ({status}){detail}; captured frames were kept for retry."
        )));
    }
    Ok(())
}

fn screenshot_frame_count(temp_dir: &Path) -> Result<usize, String> {
    Ok(fs::read_dir(temp_dir)
        .map_err(|err| err.to_string())?
        .filter_map(Result::ok)
        .filter(|entry| {
            entry
                .path()
                .extension()
                .and_then(|value| value.to_str())
                .map(|value| value.eq_ignore_ascii_case("jpg"))
                .unwrap_or(false)
        })
        .count())
}

fn reap_auxiliary_child(session: &mut RecordingSession) -> Result<(), AppError> {
    let Some(mut auxiliary) = session.auxiliary.take() else {
        return Ok(());
    };
    if let Ok(Some(_)) = auxiliary.child.try_wait() {
        return Ok(());
    }
    if let Err(error) = terminate_and_reap_child(&mut auxiliary.child) {
        session.auxiliary = Some(auxiliary);
        return Err(AppError::EncodeFailed(format!(
            "A previous recording helper is still running and could not be reaped: {error}"
        )));
    }
    Ok(())
}

fn wait_for_child_exit(
    child: &mut Child,
    timeout: Duration,
) -> io::Result<Option<std::process::ExitStatus>> {
    let deadline = Instant::now() + timeout;
    loop {
        match child.try_wait()? {
            Some(status) => return Ok(Some(status)),
            None if Instant::now() < deadline => {
                std::thread::sleep(Duration::from_millis(25));
            }
            None => return Ok(None),
        }
    }
}

fn run_recording_helper_bounded(
    session: &mut RecordingSession,
    mut command: Command,
    timeout: Duration,
    label: &str,
) -> Result<std::process::ExitStatus, AppError> {
    reap_auxiliary_child(session)?;
    let mut child = command
        .spawn()
        .map_err(|error| AppError::EncodeFailed(format!("Start {label}: {error}")))?;
    let job = match attach_recording_job(&mut child) {
        Ok(job) => job,
        Err(failure) if failure.reaped => return Err(failure.error),
        Err(failure) => {
            session.auxiliary = Some(ManagedChild { child, job: None });
            return Err(failure.error);
        }
    };
    match wait_for_child_exit(&mut child, timeout) {
        Ok(Some(status)) => {
            drop(job);
            Ok(status)
        }
        Ok(None) => {
            let termination = terminate_and_reap_child(&mut child);
            if let Err(error) = termination {
                session.auxiliary = Some(ManagedChild {
                    child,
                    job: Some(job),
                });
                return Err(AppError::EncodeFailed(format!(
                    "{label} exceeded its {:.1}s safety limit and could not be reaped: {error}",
                    timeout.as_secs_f64()
                )));
            }
            drop(job);
            Err(AppError::EncodeFailed(format!(
                "{label} exceeded its {:.1}s safety limit and was terminated",
                timeout.as_secs_f64()
            )))
        }
        Err(wait_error) => {
            let termination = terminate_and_reap_child(&mut child);
            if let Err(terminate_error) = termination {
                session.auxiliary = Some(ManagedChild {
                    child,
                    job: Some(job),
                });
                return Err(AppError::EncodeFailed(format!(
                    "Could not poll {label}: {wait_error}; termination also failed: {terminate_error}"
                )));
            }
            drop(job);
            Err(AppError::EncodeFailed(format!(
                "Could not poll {label}: {wait_error}; the helper was terminated and reaped"
            )))
        }
    }
}

fn verify_recording_output(session: &mut RecordingSession) -> Result<MediaInspection, AppError> {
    let metadata = fs::metadata(&session.output_path).map_err(|error| {
        AppError::DecodeFailed(format!(
            "Recorded MP4 is missing at {}: {error}",
            session.output_path.display()
        ))
    })?;
    if !metadata.is_file() || metadata.len() < 32 {
        return Err(AppError::DecodeFailed(format!(
            "Recorded MP4 is incomplete ({} bytes)",
            metadata.len()
        )));
    }
    let ffprobe = locate_ffprobe().map_err(|error| {
        AppError::MissingDependency(format!(
            "FFprobe is required to verify the recording before publishing: {error}"
        ))
    })?;
    let task_dir = session.temp_dir.as_deref().ok_or_else(|| {
        AppError::Internal("Recording session lost its task directory".to_string())
    })?;
    let stdout_path = task_dir.join("verify.stdout.json");
    let stderr_path = task_dir.join("verify.stderr.log");
    let stdout_file = File::create(&stdout_path)
        .map_err(|error| AppError::Internal(format!("Create recording verify output: {error}")))?;
    let stderr_file = File::create(&stderr_path)
        .map_err(|error| AppError::Internal(format!("Create recording verify log: {error}")))?;
    let mut command = Command::new(ffprobe);
    command
        .arg("-v")
        .arg("error")
        .arg("-select_streams")
        .arg("v:0")
        .arg("-show_entries")
        .arg("stream=codec_name,width,height,duration,nb_frames,avg_frame_rate,pix_fmt:stream_tags=alpha_mode:format=duration")
        .arg("-of")
        .arg("json")
        .arg(&session.output_path)
        .stdin(Stdio::null())
        .stdout(Stdio::from(stdout_file))
        .stderr(Stdio::from(stderr_file));
    let status = run_recording_helper_bounded(
        session,
        command,
        Duration::from_secs(8),
        "recording FFprobe verification",
    )?;
    if !status.success() {
        return Err(AppError::DecodeFailed(format!(
            "Recording FFprobe verification exited with {status}{}",
            recording_backend_error_detail(&stderr_path)
        )));
    }
    let bytes = fs::read(&stdout_path)
        .map_err(|error| AppError::DecodeFailed(format!("Read FFprobe result: {error}")))?;
    let inspection = parse_media_inspection(&bytes)?;
    if inspection.codec != AnimationFormat::Mp4.codec_name()
        || inspection.width == 0
        || inspection.height == 0
        || inspection.frame_count == 0
    {
        return Err(AppError::DecodeFailed(format!(
            "Recorded MP4 failed verification: codec {}, dimensions {}x{}, frames {}",
            inspection.codec, inspection.width, inspection.height, inspection.frame_count
        )));
    }
    Ok(inspection)
}

fn escape_ps_path(path: &Path) -> String {
    path.to_string_lossy().replace('\'', "''")
}

fn is_video_file(path: &Path) -> bool {
    matches!(
        path.extension()
            .and_then(|value| value.to_str())
            .map(|value| value.to_ascii_lowercase())
            .as_deref(),
        Some("mp4" | "mov" | "mkv" | "webm")
    )
}

fn is_gif_file(path: &Path) -> bool {
    path.extension()
        .and_then(|value| value.to_str())
        .map(|value| value.eq_ignore_ascii_case("gif"))
        .unwrap_or(false)
}

fn is_image_file(path: &Path) -> bool {
    matches!(
        path.extension()
            .and_then(|value| value.to_str())
            .map(|value| value.to_ascii_lowercase())
            .as_deref(),
        Some("png" | "jpg" | "jpeg" | "webp")
    )
}

fn is_media_source(path: &Path) -> bool {
    is_video_file(path)
        || is_gif_file(path)
        || is_image_file(path)
        || matches!(
            path.extension()
                .and_then(|value| value.to_str())
                .map(|value| value.to_ascii_lowercase())
                .as_deref(),
            Some("apng")
        )
}

fn is_merge_source(path: &Path) -> bool {
    is_gif_file(path) || is_image_file(path)
}

fn choose_encoder(request: &GifRequest) -> &'static str {
    match request.encoder.as_str() {
        "clean_opt" => "clean_opt",
        "pngquant_opt" => "pngquant_opt",
        "hybrid" if request.fps <= 15 && request.colors >= 96 => "pngquant_opt",
        "hybrid" => "ffmpeg_fast",
        _ => "ffmpeg_fast",
    }
}

fn perceptual_filter_encoder<'a>(request: &GifRequest, legacy_encoder: &'a str) -> &'a str {
    if request
        .perceptual_selection
        .as_ref()
        .is_some_and(|selection| selection.neutral_filter_recommended)
    {
        "ffmpeg_fast"
    } else {
        legacy_encoder
    }
}

fn perceptual_filter_strategy(
    request: &GifRequest,
    selection: &PerceptualSelection,
) -> &'static str {
    let encoder = if selection.neutral_filter_recommended {
        "ffmpeg_fast"
    } else {
        choose_encoder(request)
    };
    match encoder {
        "clean_opt" => "denoise_deband+color_eq",
        "pngquant_opt" if selection.color_eq_recommended => "temporal_cleanup+color_eq",
        "pngquant_opt" => "temporal_cleanup",
        _ => "neutral",
    }
}

fn target_preference_for(request: &GifRequest) -> Result<TargetPreference, AppError> {
    let requested = request.target_preference.trim();
    if !requested.is_empty() && !requested.eq_ignore_ascii_case("auto") {
        return TargetPreference::parse(requested).ok_or_else(|| {
            AppError::InvalidInput(format!(
                "Unsupported target preference: {}",
                request.target_preference
            ))
        });
    }
    let focus = PerceptualFocus::parse(&request.perceptual_focus)
        .map_err(|error| AppError::InvalidInput(error.to_string()))?;
    Ok(match focus {
        PerceptualFocus::Auto => TargetPreference::Balanced,
        PerceptualFocus::Motion => TargetPreference::Smoothness,
        PerceptualFocus::Subject | PerceptualFocus::TextUi | PerceptualFocus::FlatArt => {
            TargetPreference::Clarity
        }
    })
}

fn target_constraint_for(request: &GifRequest) -> Result<TargetConstraint, AppError> {
    TargetConstraint::parse(&request.target_constraint).ok_or_else(|| {
        AppError::InvalidInput(format!(
            "Unsupported target constraint: {}",
            request.target_constraint
        ))
    })
}

fn target_attempt_for(
    observations: &[TargetObservation],
    candidate: TargetCandidate,
) -> Option<u8> {
    observations
        .iter()
        .position(|observation| observation.candidate == candidate)
        .map(|index| (index + 1).min(usize::from(u8::MAX)) as u8)
}

fn build_target_optimizer_report(
    search: &TargetSizeSearch,
    selected: &TargetObservation,
    routes: &[TargetRouteArtifact],
    selected_route_index: usize,
    target_bytes: u64,
    tolerance_percent: f64,
    max_attempts: u8,
) -> Result<TargetOptimizerReport, AppError> {
    let constraint = search.constraint();
    let frontier = search.pareto_frontier();
    let observations = search.observations();
    let selected_attempt =
        target_attempt_for(observations, selected.candidate).ok_or_else(|| {
            AppError::Internal("Selected target-size observation was not recorded".to_string())
        })?;
    let reports = observations
        .iter()
        .enumerate()
        .map(|(index, observation)| {
            let deviation =
                symmetric_target_deviation_percent(observation.size_bytes, target_bytes);
            TargetObservationReport {
                attempt: (index + 1).min(usize::from(u8::MAX)) as u8,
                width: observation.candidate.width,
                fps: observation.candidate.fps,
                colors: observation.candidate.colors,
                bayer_scale: observation.candidate.bayer_scale,
                size_bytes: observation.size_bytes,
                symmetric_deviation_percent: deviation,
                under_target: observation.size_bytes <= target_bytes,
                within_tolerance: constraint.within_tolerance(
                    observation.size_bytes,
                    target_bytes,
                    tolerance_percent,
                ),
                pareto_frontier: frontier
                    .iter()
                    .any(|candidate| candidate.candidate == observation.candidate),
                selected: observation.candidate == selected.candidate,
            }
        })
        .collect();
    let recommendations = [
        ("clearest", TargetPreference::Clarity),
        ("smoothest", TargetPreference::Smoothness),
        ("smallest", TargetPreference::Smallest),
    ]
    .into_iter()
    .filter_map(|(role, preference)| {
        search
            .recommendation(preference)
            .and_then(|observation| target_attempt_for(observations, observation.candidate))
            .map(|attempt| TargetRecommendationReport {
                role: role.to_string(),
                attempt,
            })
    })
    .collect();
    let route_observations = routes
        .iter()
        .enumerate()
        .map(|(index, route)| {
            let size_bytes = route.observation.size_bytes;
            let deviation =
                size_bytes.map(|size| symmetric_target_deviation_percent(size, target_bytes));
            TargetRouteObservationReport {
                route_id: route.observation.route_id.clone(),
                timeline: route.observation.timeline.as_str().to_string(),
                width: route.candidate.width,
                fps: route.candidate.fps,
                colors: route.candidate.colors,
                dither: route.observation.dither.clone(),
                palette_stats_mode: route.observation.palette_stats_mode.clone(),
                size_bytes,
                symmetric_deviation_percent: deviation,
                under_target: size_bytes.is_some_and(|size| size <= target_bytes),
                within_tolerance: size_bytes.is_some_and(|size| {
                    constraint.within_tolerance(size, target_bytes, tolerance_percent)
                }),
                selected: index == selected_route_index,
                kept_frame_count: route.kept_frame_count,
                dropped_frame_count: route.dropped_frame_count,
                timeline_verified: route.timeline_verified,
                prediction: route.prediction.as_ref().map(|prediction| {
                    TargetRoutePredictionReport {
                        model_id: prediction.model_id.clone(),
                        source_route_id: prediction.source_route_id.clone(),
                        source_size_bytes: prediction.source_size_bytes,
                        predicted_size_bytes: prediction.predicted_size_bytes,
                        actual_to_predicted_ratio: size_bytes.map(|size| {
                            size as f64 / prediction.predicted_size_bytes.max(1) as f64
                        }),
                        correction_pass: prediction.correction_pass,
                    }
                }),
                status: if size_bytes.is_some() {
                    "encoded".to_string()
                } else {
                    "failed".to_string()
                },
                failure_reason: route.failure_reason.clone(),
            }
        })
        .collect();
    let numeric_attempt_count = observations.len().min(usize::from(u8::MAX)) as u8;
    let route_attempt_count = routes.len().saturating_sub(1).min(usize::from(u8::MAX)) as u8;
    let selected_route_id = routes
        .get(selected_route_index)
        .map(|route| route.observation.route_id.clone())
        .ok_or_else(|| AppError::Internal("Selected target route was not recorded".to_string()))?;
    Ok(TargetOptimizerReport {
        optimizer_id: "gifp.target_size.pareto.v6".to_string(),
        optimizer_version: env!("CARGO_PKG_VERSION").to_string(),
        selection_policy: match constraint {
            TargetConstraint::HardCap => {
                "hard_cap_constraint_first_numeric_plus_route_probe_v3".to_string()
            }
            TargetConstraint::SymmetricMatch => {
                "symmetric_match_closest_real_bytes_plus_route_probe_v1".to_string()
            }
        },
        constraint: constraint.as_str().to_string(),
        preference: search.preference().as_str().to_string(),
        target_bytes,
        tolerance_percent,
        max_attempts,
        numeric_attempt_count,
        route_attempt_count,
        selected_attempt,
        route_probe_id: "ffmpeg_palette_dither_timeline_reinvest_correction_v2".to_string(),
        selected_route_id,
        observations: reports,
        recommendations,
        route_observations,
    })
}

fn target_fit_for_selected_size(
    size_bytes: u64,
    target_bytes: u64,
    tolerance_percent: f64,
    constraint: TargetConstraint,
) -> TargetFit {
    if constraint.within_tolerance(size_bytes, target_bytes, tolerance_percent) {
        TargetFit::Exact
    } else if size_bytes <= target_bytes {
        TargetFit::Under
    } else {
        TargetFit::Unreachable
    }
}

fn ensure_target_output_is_publishable(
    size_bytes: u64,
    target_bytes: u64,
    constraint: TargetConstraint,
    smallest_verified_size_bytes: u64,
    verified_attempt_count: usize,
) -> Result<(), AppError> {
    if constraint == TargetConstraint::HardCap && size_bytes > target_bytes {
        if smallest_verified_size_bytes <= target_bytes {
            return Err(AppError::Internal(format!(
                "Target route selection chose an oversized {size_bytes}-byte candidate even though a verified {smallest_verified_size_bytes}-byte candidate met the {target_bytes}-byte hard cap; no output was published"
            )));
        }
        return Err(AppError::EncodeFailed(format!(
            "No candidate met the {target_bytes}-byte hard cap within this search budget: the selected candidate was {size_bytes} bytes and the smallest verified candidate was {smallest_verified_size_bytes} bytes across {verified_attempt_count} encoded attempts; no output was published"
        )));
    }
    Ok(())
}

fn target_route_plan(route_id: &str, baseline: &FfmpegGifPlan) -> Option<FfmpegGifPlan> {
    let mut plan = baseline.clone();
    match route_id {
        "sierra_quality" => plan.dither = FfmpegGifDither::Sierra2_4a,
        "alternate_stats" => {
            plan.stats_mode = match baseline.stats_mode {
                PaletteStatsMode::Diff => PaletteStatsMode::Full,
                PaletteStatsMode::Full | PaletteStatsMode::Single => PaletteStatsMode::Diff,
            }
        }
        _ => return None,
    }
    Some(plan)
}

fn verify_target_perceptual_timeline(
    output: &Path,
    report: &mut PerceptualReport,
) -> Result<(), AppError> {
    let ffprobe = locate_ffprobe()?;
    let inspection = inspect_media_file(&ffprobe, output)?;
    let frame_count_matches = inspection.frame_count == u64::from(report.kept_frame_count);
    let expected_duration_cs = report.output_duration_ms / 10;
    let observed_duration_cs = (inspection.duration * 100.0).round().max(0.0) as u64;
    let duration_matches = observed_duration_cs == expected_duration_cs;
    if !frame_count_matches || !duration_matches {
        return Err(AppError::DecodeFailed(format!(
            "Target perceptual timeline verification failed: expected {} frames / {} cs, decoded {} frames / {} cs",
            report.kept_frame_count,
            expected_duration_cs,
            inspection.frame_count,
            observed_duration_cs
        )));
    }
    report.aggregate_timeline_verified = true;
    Ok(())
}

fn encode_to_target_size(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
    source_uses_transparency: bool,
) -> Result<EncodeOutcome, AppError> {
    let target = request.target_size_bytes.ok_or_else(|| {
        AppError::InvalidInput("Exact-size mode requires target_size_bytes".to_string())
    })?;
    validate_target_size_bytes(target)?;

    let temp_dir = create_unique_temp_dir("gifp-target")?;
    let result = (|| {
        let tolerance_percent = request.target_tolerance_percent.clamp(1.0, 25.0);
        let max_attempts = request.target_max_attempts.clamp(1, 12);
        let target_constraint = target_constraint_for(request)?;
        let base_candidate = TargetCandidate {
            width: request.width,
            fps: request.fps,
            colors: request.colors,
            bayer_scale: request.bayer_scale,
        };
        let mut search = TargetSizeSearch::new(
            target,
            tolerance_percent,
            usize::from(max_attempts),
            base_candidate,
        )
        .with_preference(target_preference_for(request)?)
        .with_constraint(target_constraint);
        let mut artifacts = HashMap::new();

        // Callers may provide an already measured Fast result as an optional
        // oversized search point. Direct-MB requests omit it and encode the
        // first candidate normally.
        if let Some(fast_size) = request
            .fast_baseline_size_bytes
            .filter(|size| *size > target)
        {
            search.record(base_candidate, fast_size);
        }

        while let Some(candidate) = search.next_candidate() {
            check_conversion_cancelled()?;
            let mut candidate_request = request.clone();
            candidate_request.width = candidate.width;
            candidate_request.fps = candidate.fps;
            candidate_request.colors = candidate.colors;
            candidate_request.bayer_scale = candidate.bayer_scale;
            let mut candidate_plan = plan.clone();
            candidate_plan.bayer_scale = candidate.bayer_scale;
            let candidate_path = temp_dir.join(format!(
                "candidate-{}-{}-{}-{}.gif",
                candidate.width, candidate.fps, candidate.colors, candidate.bayer_scale
            ));
            encode_with_palette(
                ffmpeg,
                input,
                &candidate_path,
                &candidate_request,
                encoder,
                &candidate_plan,
            )?;
            let size = fs::metadata(&candidate_path)
                .map_err(|error| AppError::Internal(error.to_string()))?
                .len();
            search.record(candidate, size);
            artifacts.insert(candidate, candidate_path);
        }

        let best = search.best_observation().cloned().ok_or_else(|| {
            AppError::EncodeFailed("Target-size search produced no candidates".to_string())
        })?;
        let numeric_fit = search.fit();
        let baseline_source = artifacts.get(&best.candidate).cloned().ok_or_else(|| {
            AppError::Internal("Target-size candidate artifact was lost".to_string())
        })?;
        let mut selected_request = request.clone();
        selected_request.width = best.candidate.width;
        selected_request.fps = best.candidate.fps;
        selected_request.colors = best.candidate.colors;
        selected_request.bayer_scale = best.candidate.bayer_scale;
        let mut baseline_plan = plan.clone();
        baseline_plan.bayer_scale = best.candidate.bayer_scale;
        let mut routes = vec![TargetRouteArtifact {
            observation: TargetRouteObservation::encoded(
                "baseline",
                baseline_plan.dither.as_ffmpeg_value(),
                baseline_plan.stats_mode.as_ffmpeg_value(),
                best.size_bytes,
            ),
            candidate: best.candidate,
            path: Some(baseline_source),
            failure_reason: None,
            kept_frame_count: None,
            dropped_frame_count: None,
            timeline_verified: true,
            prediction: None,
            perceptual_artifacts: None,
        }];
        for route_id in ["sierra_quality", "alternate_stats"] {
            check_conversion_cancelled()?;
            let route_plan = target_route_plan(route_id, &baseline_plan).ok_or_else(|| {
                AppError::Internal(format!("Unknown target route probe: {route_id}"))
            })?;
            let route_path = temp_dir.join(format!(
                "route-{route_id}-{}-{}-{}.gif",
                best.candidate.width, best.candidate.fps, best.candidate.colors
            ));
            let encoded = encode_with_palette(
                ffmpeg,
                input,
                &route_path,
                &selected_request,
                encoder,
                &route_plan,
            )
            .and_then(|()| {
                fs::metadata(&route_path)
                    .map(|metadata| metadata.len())
                    .map_err(|error| AppError::Internal(error.to_string()))
            });
            check_conversion_cancelled()?;
            match encoded {
                Ok(size_bytes) => routes.push(TargetRouteArtifact {
                    observation: TargetRouteObservation::encoded(
                        route_id,
                        route_plan.dither.as_ffmpeg_value(),
                        route_plan.stats_mode.as_ffmpeg_value(),
                        size_bytes,
                    ),
                    candidate: best.candidate,
                    path: Some(route_path),
                    failure_reason: None,
                    kept_frame_count: None,
                    dropped_frame_count: None,
                    timeline_verified: true,
                    prediction: None,
                    perceptual_artifacts: None,
                }),
                Err(error) => routes.push(TargetRouteArtifact {
                    observation: TargetRouteObservation {
                        route_id: route_id.to_string(),
                        dither: route_plan.dither.as_ffmpeg_value().to_string(),
                        palette_stats_mode: route_plan.stats_mode.as_ffmpeg_value().to_string(),
                        size_bytes: None,
                        timeline: TargetRouteTimeline::Cfr,
                    },
                    candidate: best.candidate,
                    path: None,
                    failure_reason: Some(error.to_string()),
                    kept_frame_count: None,
                    dropped_frame_count: None,
                    timeline_verified: false,
                    prediction: None,
                    perceptual_artifacts: None,
                }),
            }
        }
        let timeline_path = temp_dir.join(format!(
            "route-perceptual-timeline-{}-{}-{}.gif",
            best.candidate.width, best.candidate.fps, best.candidate.colors
        ));
        let timeline_attempt = if source_uses_transparency {
            Err(AppError::DecodeFailed(
                "Target perceptual timeline is disabled for sources that use transparency"
                    .to_string(),
            ))
        } else {
            build_perceptual_timeline(ffmpeg, input, &selected_request, false, false).and_then(
                |(selection, mut report, _, _, _)| {
                    let mut timeline_request = selected_request.clone();
                    timeline_request.perceptual_selection = Some(selection.clone());
                    let timeline_encoder =
                        perceptual_filter_encoder(&timeline_request, encoder).to_string();
                    encode_with_palette(
                        ffmpeg,
                        input,
                        &timeline_path,
                        &timeline_request,
                        &timeline_encoder,
                        &baseline_plan,
                    )?;
                    verify_target_perceptual_timeline(&timeline_path, &mut report)?;
                    let size_bytes = fs::metadata(&timeline_path)
                        .map_err(|error| AppError::Internal(error.to_string()))?
                        .len();
                    Ok((selection, report, size_bytes))
                },
            )
        };
        check_conversion_cancelled()?;
        match timeline_attempt {
            Ok((selection, report, size_bytes)) => routes.push(TargetRouteArtifact {
                observation: TargetRouteObservation::perceptual_encoded(
                    "perceptual_timeline",
                    baseline_plan.dither.as_ffmpeg_value(),
                    baseline_plan.stats_mode.as_ffmpeg_value(),
                    size_bytes,
                ),
                candidate: best.candidate,
                path: Some(timeline_path),
                failure_reason: None,
                kept_frame_count: Some(report.kept_frame_count),
                dropped_frame_count: Some(report.dropped_frame_count),
                timeline_verified: report.aggregate_timeline_verified,
                prediction: None,
                perceptual_artifacts: Some(TargetPerceptualArtifacts { selection, report }),
            }),
            Err(error) => routes.push(TargetRouteArtifact {
                observation: TargetRouteObservation {
                    route_id: "perceptual_timeline".to_string(),
                    dither: baseline_plan.dither.as_ffmpeg_value().to_string(),
                    palette_stats_mode: baseline_plan.stats_mode.as_ffmpeg_value().to_string(),
                    size_bytes: None,
                    timeline: TargetRouteTimeline::PerceptualDropHold,
                },
                candidate: best.candidate,
                path: None,
                failure_reason: Some(error.to_string()),
                kept_frame_count: None,
                dropped_frame_count: None,
                timeline_verified: false,
                prediction: None,
                perceptual_artifacts: None,
            }),
        }
        let timeline_seed = routes
            .iter()
            .find(|route| route.observation.route_id == "perceptual_timeline")
            .and_then(|route| {
                Some((
                    route.observation.size_bytes?,
                    route.perceptual_artifacts.clone()?,
                ))
            });
        if let Some((timeline_size, perceptual_artifacts)) = timeline_seed {
            let ceiling = TargetCandidate {
                width: request.width,
                fps: request.fps,
                colors: request.colors,
                bayer_scale: request.bayer_scale,
            };
            if let Some(reinvested) =
                reinvest_target_savings(best.candidate, ceiling, timeline_size, target)
            {
                let reinvest_prediction = TargetRoutePredictionArtifact {
                    model_id: "spatial_area_color_v1".to_string(),
                    source_route_id: "perceptual_timeline".to_string(),
                    source_size_bytes: timeline_size,
                    predicted_size_bytes: estimate_reinvestment_size(
                        best.candidate,
                        reinvested,
                        timeline_size,
                    ),
                    correction_pass: 0,
                };
                let reinvest_path = temp_dir.join(format!(
                    "route-perceptual-reinvest-{}-{}-{}.gif",
                    reinvested.width, reinvested.fps, reinvested.colors
                ));
                let mut reinvest_request = selected_request.clone();
                reinvest_request.width = reinvested.width;
                reinvest_request.fps = reinvested.fps;
                reinvest_request.colors = reinvested.colors;
                reinvest_request.bayer_scale = reinvested.bayer_scale;
                reinvest_request.perceptual_selection =
                    Some(perceptual_artifacts.selection.clone());
                let reinvest_encoder =
                    perceptual_filter_encoder(&reinvest_request, encoder).to_string();
                let mut reinvest_report = perceptual_artifacts.report.clone();
                let reinvest_attempt = encode_with_palette(
                    ffmpeg,
                    input,
                    &reinvest_path,
                    &reinvest_request,
                    &reinvest_encoder,
                    &baseline_plan,
                )
                .and_then(|()| {
                    verify_target_perceptual_timeline(&reinvest_path, &mut reinvest_report)
                })
                .and_then(|()| {
                    fs::metadata(&reinvest_path)
                        .map(|metadata| metadata.len())
                        .map_err(|error| AppError::Internal(error.to_string()))
                });
                check_conversion_cancelled()?;
                match reinvest_attempt {
                    Ok(size_bytes) => {
                        routes.push(TargetRouteArtifact {
                            observation: TargetRouteObservation::perceptual_encoded(
                                "perceptual_reinvest",
                                baseline_plan.dither.as_ffmpeg_value(),
                                baseline_plan.stats_mode.as_ffmpeg_value(),
                                size_bytes,
                            ),
                            candidate: reinvested,
                            path: Some(reinvest_path),
                            failure_reason: None,
                            kept_frame_count: Some(reinvest_report.kept_frame_count),
                            dropped_frame_count: Some(reinvest_report.dropped_frame_count),
                            timeline_verified: reinvest_report.aggregate_timeline_verified,
                            prediction: Some(reinvest_prediction.clone()),
                            perceptual_artifacts: Some(TargetPerceptualArtifacts {
                                selection: perceptual_artifacts.selection.clone(),
                                report: reinvest_report,
                            }),
                        });
                        if let Some(corrected) = correct_reinvestment_overshoot(
                            best.candidate,
                            reinvested,
                            timeline_size,
                            size_bytes,
                            target,
                        ) {
                            let corrected_path = temp_dir.join(format!(
                                "route-perceptual-reinvest-corrected-{}-{}-{}.gif",
                                corrected.width, corrected.fps, corrected.colors
                            ));
                            let mut corrected_request = selected_request.clone();
                            corrected_request.width = corrected.width;
                            corrected_request.fps = corrected.fps;
                            corrected_request.colors = corrected.colors;
                            corrected_request.bayer_scale = corrected.bayer_scale;
                            corrected_request.perceptual_selection =
                                Some(perceptual_artifacts.selection.clone());
                            let corrected_encoder =
                                perceptual_filter_encoder(&corrected_request, encoder).to_string();
                            let mut corrected_report = perceptual_artifacts.report.clone();
                            let corrected_attempt = encode_with_palette(
                                ffmpeg,
                                input,
                                &corrected_path,
                                &corrected_request,
                                &corrected_encoder,
                                &baseline_plan,
                            )
                            .and_then(|()| {
                                verify_target_perceptual_timeline(
                                    &corrected_path,
                                    &mut corrected_report,
                                )
                            })
                            .and_then(|()| {
                                fs::metadata(&corrected_path)
                                    .map(|metadata| metadata.len())
                                    .map_err(|error| AppError::Internal(error.to_string()))
                            });
                            let corrected_prediction = TargetRoutePredictionArtifact {
                                model_id: "measured_bracket_v1".to_string(),
                                source_route_id: "perceptual_reinvest".to_string(),
                                source_size_bytes: size_bytes,
                                predicted_size_bytes: target.saturating_mul(98) / 100,
                                correction_pass: 1,
                            };
                            check_conversion_cancelled()?;
                            match corrected_attempt {
                                Ok(corrected_size) => routes.push(TargetRouteArtifact {
                                    observation: TargetRouteObservation::perceptual_encoded(
                                        "perceptual_reinvest_corrected",
                                        baseline_plan.dither.as_ffmpeg_value(),
                                        baseline_plan.stats_mode.as_ffmpeg_value(),
                                        corrected_size,
                                    ),
                                    candidate: corrected,
                                    path: Some(corrected_path),
                                    failure_reason: None,
                                    kept_frame_count: Some(corrected_report.kept_frame_count),
                                    dropped_frame_count: Some(corrected_report.dropped_frame_count),
                                    timeline_verified: corrected_report.aggregate_timeline_verified,
                                    prediction: Some(corrected_prediction),
                                    perceptual_artifacts: Some(TargetPerceptualArtifacts {
                                        selection: perceptual_artifacts.selection.clone(),
                                        report: corrected_report,
                                    }),
                                }),
                                Err(error) => routes.push(TargetRouteArtifact {
                                    observation: TargetRouteObservation {
                                        route_id: "perceptual_reinvest_corrected".to_string(),
                                        dither: baseline_plan.dither.as_ffmpeg_value().to_string(),
                                        palette_stats_mode: baseline_plan
                                            .stats_mode
                                            .as_ffmpeg_value()
                                            .to_string(),
                                        size_bytes: None,
                                        timeline: TargetRouteTimeline::PerceptualDropHold,
                                    },
                                    candidate: corrected,
                                    path: None,
                                    failure_reason: Some(error.to_string()),
                                    kept_frame_count: Some(corrected_report.kept_frame_count),
                                    dropped_frame_count: Some(corrected_report.dropped_frame_count),
                                    timeline_verified: false,
                                    prediction: Some(corrected_prediction),
                                    perceptual_artifacts: None,
                                }),
                            }
                        }
                    }
                    Err(error) => routes.push(TargetRouteArtifact {
                        observation: TargetRouteObservation {
                            route_id: "perceptual_reinvest".to_string(),
                            dither: baseline_plan.dither.as_ffmpeg_value().to_string(),
                            palette_stats_mode: baseline_plan
                                .stats_mode
                                .as_ffmpeg_value()
                                .to_string(),
                            size_bytes: None,
                            timeline: TargetRouteTimeline::PerceptualDropHold,
                        },
                        candidate: reinvested,
                        path: None,
                        failure_reason: Some(error.to_string()),
                        kept_frame_count: Some(reinvest_report.kept_frame_count),
                        dropped_frame_count: Some(reinvest_report.dropped_frame_count),
                        timeline_verified: false,
                        prediction: Some(reinvest_prediction),
                        perceptual_artifacts: None,
                    }),
                }
            }
        }
        let route_observations = routes
            .iter()
            .map(|route| route.observation.clone())
            .collect::<Vec<_>>();
        let selected_route_index = select_target_route(
            &route_observations,
            search.preference(),
            baseline_plan.stats_mode.as_ffmpeg_value(),
            target,
            tolerance_percent,
            target_constraint,
        )
        .ok_or_else(|| {
            AppError::EncodeFailed("Target route probes produced no usable output".to_string())
        })?;
        let selected_route = routes.get(selected_route_index).ok_or_else(|| {
            AppError::Internal("Selected target route artifact was lost".to_string())
        })?;
        let selected_size = selected_route.observation.size_bytes.ok_or_else(|| {
            AppError::Internal("Selected target route has no encoded size".to_string())
        })?;
        let source = selected_route.path.as_ref().ok_or_else(|| {
            AppError::Internal("Selected target route has no output path".to_string())
        })?;
        let target_optimizer_report = build_target_optimizer_report(
            &search,
            &best,
            &routes,
            selected_route_index,
            target,
            tolerance_percent,
            max_attempts,
        )?;
        let numeric_attempts = search.observations().len();
        let route_attempts = routes.len().saturating_sub(1);
        let verified_attempt_count = numeric_attempts.saturating_add(
            routes
                .iter()
                .skip(1)
                .filter(|route| route.observation.size_bytes.is_some())
                .count(),
        );
        let smallest_verified_size = routes
            .iter()
            .filter_map(|route| route.observation.size_bytes)
            .chain(
                search
                    .observations()
                    .iter()
                    .map(|observation| observation.size_bytes),
            )
            .min()
            .unwrap_or(selected_size);
        ensure_target_output_is_publishable(
            selected_size,
            target,
            target_constraint,
            smallest_verified_size,
            verified_attempt_count,
        )?;
        verify_delivery_output(source, AnimationFormat::Gif)?;
        let staged_publish = stage_publish_file(source, output)?;
        Ok((
            EncodeOutcome {
                output_path: output.to_path_buf(),
                size_bytes: selected_size,
                attempts: numeric_attempts
                    .saturating_add(route_attempts)
                    .min(usize::from(u8::MAX)) as u8,
                width: selected_route.candidate.width,
                fps: selected_route.candidate.fps,
                colors: selected_route.candidate.colors,
                target_fit: Some(if selected_route_index == 0 {
                    numeric_fit
                } else {
                    target_fit_for_selected_size(
                        selected_size,
                        target,
                        tolerance_percent,
                        target_constraint,
                    )
                }),
                target_optimizer_report: Some(target_optimizer_report),
                target_perceptual_artifacts: selected_route.perceptual_artifacts.clone(),
            },
            staged_publish,
        ))
    })();
    let cleanup_result = remove_owned_temp_dir(&temp_dir, "gifp-target-");
    match (result, cleanup_result) {
        (Ok((outcome, staged)), Ok(())) => {
            finish_staged_publish(&staged, output, false)?;
            Ok(outcome)
        }
        (Ok((_, staged)), Err(cleanup_error)) => {
            let _ = fs::remove_file(staged);
            Err(AppError::Internal(format!(
                "Target candidates were not published because temporary cleanup failed for {}: {cleanup_error}",
                temp_dir.display()
            )))
        }
        (Err(error), Ok(())) => Err(error),
        (Err(error), Err(cleanup_error)) => Err(AppError::Internal(format!(
            "{error}; temporary cleanup also failed for {}: {cleanup_error}",
            temp_dir.display()
        ))),
    }
}

fn validate_target_size_bytes(target: u64) -> Result<(), AppError> {
    const MIN_TARGET_SIZE_BYTES: u64 = 1024;
    const MAX_TARGET_SIZE_BYTES: u64 = 512 * 1024 * 1024;
    if !(MIN_TARGET_SIZE_BYTES..=MAX_TARGET_SIZE_BYTES).contains(&target) {
        return Err(AppError::InvalidInput(
            "Target size must be between 1 KiB and 512 MiB".to_string(),
        ));
    }
    Ok(())
}

fn normalized_segment_cuts(request: &GifRequest, probe: &QuickContentProbe) -> Vec<f64> {
    if !request.deleted_frames.is_empty() || !request.deleted_ranges.is_empty() {
        return Vec::new();
    }
    let playback_speed = request.playback_speed.clamp(1.0, 3.0);
    let mut cuts: Vec<f64> = probe
        .scene_cut_times
        .iter()
        .map(|time| time / playback_speed)
        .filter(|time| time.is_finite() && *time >= 0.40)
        .collect();
    cuts.sort_by(f64::total_cmp);
    cuts.dedup_by(|left, right| (*left - *right).abs() < 0.50);
    cuts.truncate(3);
    cuts
}

fn encode_ffmpeg_with_strategy(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
    segment_cuts: &[f64],
) -> Result<(), AppError> {
    if segment_cuts.is_empty() {
        encode_with_palette(ffmpeg, input, output, request, encoder, plan)
    } else {
        encode_with_segment_palettes(ffmpeg, input, output, request, encoder, plan, segment_cuts)
    }
}

fn encode_with_segment_palettes(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
    segment_cuts: &[f64],
) -> Result<(), AppError> {
    let source_args = source_time_args(request);
    let graph = segmented_filter_graph(request, encoder, plan, segment_cuts);
    let loop_value = if request.loop_output { "0" } else { "-1" };
    let final_delay = request
        .perceptual_selection
        .as_ref()
        .map(|selection| selection.final_delay_cs.to_string());
    let mut output_args = vec![
        "-filter_complex",
        graph.as_str(),
        "-map",
        "[out]",
        "-loop",
        loop_value,
        "-gifflags",
        "+offsetting+transdiff",
        "-global_palette",
        "0",
    ];
    if let Some(final_delay) = final_delay.as_deref() {
        output_args.extend(["-fps_mode", "passthrough", "-final_delay", final_delay]);
    }
    run_ffmpeg(ffmpeg, input, &source_args, &output_args, output)
}

fn segmented_filter_graph(
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
    segment_cuts: &[f64],
) -> String {
    let segment_count = segment_cuts.len() + 1;
    let split_outputs = (0..segment_count)
        .map(|index| format!("[s{index}]"))
        .collect::<String>();
    let mut graph = format!(
        "[0:v]{},split={segment_count}{split_outputs};",
        video_filter(request, encoder)
    );
    let colors = palette_color_count(request.colors);
    let dither = dither_for_plan(request, encoder, plan);
    let bayer = if dither == "bayer" {
        format!(":bayer_scale={}", bayer_scale_for_plan(request, plan))
    } else {
        String::new()
    };
    let diff_mode = if plan.diff_mode_rectangle {
        ":diff_mode=rectangle"
    } else {
        ""
    };

    for index in 0..segment_count {
        let start = if index == 0 {
            0.0
        } else {
            segment_cuts[index - 1]
        };
        let trim = if let Some(end) = segment_cuts.get(index) {
            format!("trim=start={start:.3}:end={end:.3}")
        } else {
            format!("trim=start={start:.3}")
        };
        graph.push_str(&format!(
            "[s{index}]{trim},setpts=PTS-STARTPTS,split[v{index}][pg{index}];[pg{index}]palettegen=max_colors={colors}:reserve_transparent=1:stats_mode=full[p{index}];[v{index}][p{index}]paletteuse=dither={dither}{bayer}{diff_mode}:new=0:alpha_threshold={alpha}[o{index}];",
            alpha = plan.alpha_threshold,
        ));
    }
    for index in 0..segment_count {
        graph.push_str(&format!("[o{index}]"));
    }
    graph.push_str(&format!("concat=n={segment_count}:v=1:a=0[out]"));
    graph
}

fn oklab_palette_reserves_transparency(artifact: &OklabPaletteArtifact) -> bool {
    artifact.rgba.len() == 256 * 4 && artifact.rgba[usize::from(GIF_TRANSPARENT_INDEX) * 4 + 3] == 0
}

fn verify_gif_global_palette(
    output: &Path,
    artifact: &OklabPaletteArtifact,
) -> Result<bool, AppError> {
    if artifact.rgba.len() != 256 * 4 {
        return Err(AppError::Internal(format!(
            "OKLab palette artifact has {} bytes; expected 1024",
            artifact.rgba.len()
        )));
    }
    let reserves_transparency = oklab_palette_reserves_transparency(artifact);
    if artifact
        .rgba
        .chunks_exact(4)
        .enumerate()
        .any(|(index, entry)| {
            entry[3]
                != if reserves_transparency && index == usize::from(GIF_TRANSPARENT_INDEX) {
                    0
                } else {
                    u8::MAX
                }
        })
    {
        return Ok(false);
    }
    let artifact_digest = Sha256::digest(&artifact.rgba)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    if artifact_digest != artifact.sha256 {
        return Ok(false);
    }
    let bytes = fs::read(output).map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if bytes.len() < 13 || !matches!(&bytes[..6], b"GIF87a" | b"GIF89a") {
        return Err(AppError::DecodeFailed(
            "Output is not a complete GIF logical screen".to_string(),
        ));
    }
    let packed = bytes[10];
    if packed & 0x80 == 0 {
        return Ok(false);
    }
    let color_count = 1usize << (usize::from(packed & 0x07) + 1);
    let table_bytes = color_count * 3;
    if bytes.len() < 13 + table_bytes {
        return Err(AppError::DecodeFailed(
            "Output GIF global color table is truncated".to_string(),
        ));
    }
    let table = &bytes[13..13 + table_bytes];

    let mut cursor = 13 + table_bytes;
    let mut image_count = 0_u32;
    let mut transparent_output_index = None;
    loop {
        let block_type = *bytes.get(cursor).ok_or_else(|| {
            AppError::DecodeFailed("Output GIF is missing its trailer".to_string())
        })?;
        cursor += 1;
        match block_type {
            0x3b => {
                return Ok(image_count > 0
                    && cursor == bytes.len()
                    && gif_global_table_matches_artifact(
                        table,
                        artifact,
                        transparent_output_index,
                    ));
            }
            0x2c => {
                let descriptor = bytes.get(cursor..cursor + 9).ok_or_else(|| {
                    AppError::DecodeFailed("Output GIF image descriptor is truncated".to_string())
                })?;
                cursor += 9;
                if descriptor[8] & 0x80 != 0 {
                    return Ok(false);
                }
                // LZW minimum code size precedes the image-data sub-blocks.
                if bytes.get(cursor).is_none() {
                    return Err(AppError::DecodeFailed(
                        "Output GIF image data is truncated".to_string(),
                    ));
                }
                cursor += 1;
                cursor = skip_gif_sub_blocks(&bytes, cursor)?;
                image_count = image_count.saturating_add(1);
            }
            0x21 => {
                let label = *bytes.get(cursor).ok_or_else(|| {
                    AppError::DecodeFailed("Output GIF extension label is truncated".to_string())
                })?;
                cursor += 1;
                if label == 0xf9 {
                    let block_size = *bytes.get(cursor).ok_or_else(|| {
                        AppError::DecodeFailed(
                            "Output GIF graphic control extension is truncated".to_string(),
                        )
                    })?;
                    cursor += 1;
                    if block_size != 4 {
                        return Err(AppError::DecodeFailed(format!(
                            "Output GIF graphic control extension has invalid size {block_size}"
                        )));
                    }
                    let control = bytes.get(cursor..cursor + 4).ok_or_else(|| {
                        AppError::DecodeFailed(
                            "Output GIF graphic control extension is truncated".to_string(),
                        )
                    })?;
                    cursor += 4;
                    if control[0] & 0x01 != 0 {
                        match transparent_output_index {
                            Some(expected) if expected != control[3] => return Ok(false),
                            None => transparent_output_index = Some(control[3]),
                            Some(_) => {}
                        }
                    }
                    if bytes.get(cursor) != Some(&0) {
                        return Err(AppError::DecodeFailed(
                            "Output GIF graphic control extension is missing its terminator"
                                .to_string(),
                        ));
                    }
                    cursor += 1;
                } else {
                    cursor = skip_gif_sub_blocks(&bytes, cursor)?;
                }
            }
            value => {
                return Err(AppError::DecodeFailed(format!(
                    "Output GIF contains an invalid block marker 0x{value:02x}"
                )));
            }
        }
    }
}

fn gif_global_table_matches_artifact(
    table: &[u8],
    artifact: &OklabPaletteArtifact,
    transparent_output_index: Option<u8>,
) -> bool {
    let table_entries = table.len() / 3;
    if !table.len().is_multiple_of(3) || !(2..=256).contains(&table_entries) {
        return false;
    }
    let exact_full_table = table_entries == 256
        && (0..256).all(|index| gif_table_color(table, index) == artifact_color(artifact, index));
    if !oklab_palette_reserves_transparency(artifact) {
        // An opaque full palette must be lossless at the table level and must
        // not acquire a GIF Graphic Control Extension transparency index.
        return exact_full_table && transparent_output_index.is_none();
    }
    if exact_full_table {
        return transparent_output_index.is_none_or(|index| index == TRANSPARENT_PALETTE_INDEX);
    }

    match transparent_output_index {
        Some(transparent) => {
            let transparent = usize::from(transparent);
            transparent > 0
                && transparent < table_entries
                && gif_table_color(table, transparent) == artifact_color(artifact, 255)
                && (transparent + 1..table_entries).all(|index| {
                    gif_table_color(table, index) == gif_table_color(table, transparent)
                })
                && gif_table_prefix_is_artifact_subsequence(table, transparent, artifact, 255)
        }
        None => (1..=table_entries).any(|used_entries| {
            (used_entries..table_entries).all(|index| {
                gif_table_color(table, index) == gif_table_color(table, used_entries - 1)
            }) && gif_table_prefix_is_artifact_subsequence(table, used_entries, artifact, 255)
        }),
    }
}

fn gif_table_prefix_is_artifact_subsequence(
    table: &[u8],
    used_entries: usize,
    artifact: &OklabPaletteArtifact,
    artifact_limit: usize,
) -> bool {
    if used_entries == 0 || gif_table_color(table, 0) != artifact_color(artifact, 0) {
        return false;
    }
    let mut artifact_index = 1_usize;
    for table_index in 1..used_entries {
        while artifact_index < artifact_limit
            && gif_table_color(table, table_index) != artifact_color(artifact, artifact_index)
        {
            artifact_index += 1;
        }
        if artifact_index == artifact_limit {
            return false;
        }
        artifact_index += 1;
    }
    true
}

fn gif_table_color(table: &[u8], index: usize) -> &[u8] {
    &table[index * 3..index * 3 + 3]
}

fn artifact_color(artifact: &OklabPaletteArtifact, index: usize) -> &[u8] {
    &artifact.rgba[index * 4..index * 4 + 3]
}

fn verify_gif_indexed_plan_palette(output: &Path, plan: &IndexedGifPlan) -> Result<bool, AppError> {
    let bytes = fs::read(output).map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if bytes.len() < 13 || !matches!(&bytes[..6], b"GIF87a" | b"GIF89a") {
        return Err(AppError::DecodeFailed(
            "Rust writer output is not a complete GIF logical screen".to_string(),
        ));
    }
    let packed = bytes[10];
    if packed & 0x80 == 0 {
        return Ok(false);
    }
    let global_entries = 1usize << (usize::from(packed & 0x07) + 1);
    let global_bytes = global_entries
        .checked_mul(3)
        .ok_or_else(|| AppError::DecodeFailed("GIF global table overflow".to_string()))?;
    if global_entries != plan.global_palette_rgb.len() / 3
        || bytes.get(13..13 + global_bytes) != Some(plan.global_palette_rgb.as_slice())
    {
        return Ok(false);
    }

    let mut cursor = 13 + global_bytes;
    let mut frame_index = 0_usize;
    let mut pending_transparency: Option<Option<u8>> = None;
    loop {
        let block_type = *bytes.get(cursor).ok_or_else(|| {
            AppError::DecodeFailed("Rust writer GIF is missing its trailer".to_string())
        })?;
        cursor += 1;
        match block_type {
            0x3b => {
                return Ok(frame_index == plan.frames.len()
                    && pending_transparency.is_none()
                    && cursor == bytes.len());
            }
            0x2c => {
                let frame = match plan.frames.get(frame_index) {
                    Some(frame) => frame,
                    None => return Ok(false),
                };
                if pending_transparency.take().unwrap_or(None) != frame.transparent_index {
                    return Ok(false);
                }
                let descriptor = bytes.get(cursor..cursor + 9).ok_or_else(|| {
                    AppError::DecodeFailed(
                        "Rust writer GIF image descriptor is truncated".to_string(),
                    )
                })?;
                cursor += 9;
                let has_local = descriptor[8] & 0x80 != 0;
                match frame.local_palette_rgb.as_ref() {
                    None if has_local => return Ok(false),
                    Some(_) if !has_local => return Ok(false),
                    None => {}
                    Some(expected) => {
                        let local_entries = 1usize << (usize::from(descriptor[8] & 0x07) + 1);
                        if local_entries != expected.len() / 3 {
                            return Ok(false);
                        }
                        let end = cursor.checked_add(expected.len()).ok_or_else(|| {
                            AppError::DecodeFailed("GIF local table overflow".to_string())
                        })?;
                        if bytes.get(cursor..end) != Some(expected.as_slice()) {
                            return Ok(false);
                        }
                        cursor = end;
                    }
                }
                if bytes.get(cursor).is_none() {
                    return Err(AppError::DecodeFailed(
                        "Rust writer GIF image data is truncated".to_string(),
                    ));
                }
                cursor += 1;
                cursor = skip_gif_sub_blocks(&bytes, cursor)?;
                frame_index = frame_index.saturating_add(1);
            }
            0x21 => {
                let label = *bytes.get(cursor).ok_or_else(|| {
                    AppError::DecodeFailed(
                        "Rust writer GIF extension label is truncated".to_string(),
                    )
                })?;
                cursor += 1;
                if label == 0xf9 {
                    let block_size = *bytes.get(cursor).ok_or_else(|| {
                        AppError::DecodeFailed(
                            "Rust writer graphic control extension is truncated".to_string(),
                        )
                    })?;
                    cursor += 1;
                    if block_size != 4 {
                        return Ok(false);
                    }
                    let control = bytes.get(cursor..cursor + 4).ok_or_else(|| {
                        AppError::DecodeFailed(
                            "Rust writer graphic control extension is truncated".to_string(),
                        )
                    })?;
                    cursor += 4;
                    if pending_transparency.is_some() {
                        return Ok(false);
                    }
                    pending_transparency = Some((control[0] & 0x01 != 0).then_some(control[3]));
                    if bytes.get(cursor) != Some(&0) {
                        return Ok(false);
                    }
                    cursor += 1;
                } else {
                    cursor = skip_gif_sub_blocks(&bytes, cursor)?;
                }
            }
            _ => return Ok(false),
        }
    }
}

const TRANSPARENT_PALETTE_INDEX: u8 = 255;

fn skip_gif_sub_blocks(bytes: &[u8], mut cursor: usize) -> Result<usize, AppError> {
    loop {
        let block_size = usize::from(*bytes.get(cursor).ok_or_else(|| {
            AppError::DecodeFailed("Output GIF data sub-block is truncated".to_string())
        })?);
        cursor += 1;
        if block_size == 0 {
            return Ok(cursor);
        }
        cursor = cursor.checked_add(block_size).ok_or_else(|| {
            AppError::DecodeFailed("Output GIF data sub-block size overflow".to_string())
        })?;
        if cursor > bytes.len() {
            return Err(AppError::DecodeFailed(
                "Output GIF data sub-block is truncated".to_string(),
            ));
        }
    }
}

fn generate_palette_cached(
    ffmpeg: &Path,
    input: &Path,
    source_args: &[String],
    filter: &str,
    palette: &Path,
) -> Result<(), AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Palette);
    check_conversion_cancelled()?;
    if !export_pipeline::palette_cache_enabled() {
        return run_ffmpeg(
            ffmpeg,
            input,
            source_args,
            &["-vf", filter, "-frames:v", "1", "-update", "1"],
            palette,
        );
    }
    // The complete transform and source window identify the palette. Dither
    // settings that only affect paletteuse deliberately do not invalidate it.
    // A changed input file invalidates reuse even within the same export.
    let stamp = fs::metadata(input)
        .and_then(|value| value.modified().map(|modified| (value.len(), modified)));
    let Ok(stamp) = stamp else {
        // Do not reuse a source whose identity cannot be checked.
        return run_ffmpeg(
            ffmpeg,
            input,
            source_args,
            &["-vf", filter, "-frames:v", "1", "-update", "1"],
            palette,
        );
    };
    let mut key: export_pipeline::PaletteKey = vec![
        ffmpeg.as_os_str().to_owned(),
        input.as_os_str().to_owned(),
        format!("{stamp:?}").into(),
        source_args.len().to_string().into(),
    ];
    key.extend(source_args.iter().map(std::ffi::OsString::from));
    key.extend(
        animation_demux_args(input)
            .iter()
            .map(std::ffi::OsString::from),
    );
    key.push(filter.into());
    key.push("png-palette-single-frame-v1".into());
    if let Some(bytes) = export_pipeline::cached_palette(&key) {
        fs::write(palette, bytes.as_slice())
            .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
        check_conversion_cancelled()?;
        return Ok(());
    }
    run_ffmpeg(
        ffmpeg,
        input,
        source_args,
        &["-vf", filter, "-frames:v", "1", "-update", "1"],
        palette,
    )?;
    check_conversion_cancelled()?;
    if let Ok(bytes) = fs::read(palette) {
        if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
            export_pipeline::retain_palette(key, bytes);
        }
    }
    Ok(())
}

fn encode_with_palette(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
) -> Result<(), AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Encode);
    if let Some(artifact) = request
        .perceptual_selection
        .as_ref()
        .and_then(|selection| selection.palette.as_ref())
    {
        return encode_with_oklab_palette(ffmpeg, input, output, request, encoder, plan, artifact);
    }
    if plan.requires_frame_synchronized_palette() {
        return encode_with_frame_palettes(ffmpeg, input, output, request, encoder, plan);
    }
    let temp_dir = create_unique_temp_dir("gif-p-perceptual")?;
    let palette = temp_dir.join("palette.png");

    let source_args = source_time_args(request);
    let palette_filter = palette_filter(request, encoder, plan);
    let gif_filter = gif_filter(request, encoder, plan);
    let palette_arg = palette.to_string_lossy().to_string();
    let result = (|| {
        generate_palette_cached(ffmpeg, input, &source_args, &palette_filter, &palette)?;

        let loop_value = if request.loop_output { "0" } else { "-1" };
        let final_delay = request
            .perceptual_selection
            .as_ref()
            .map(|selection| selection.final_delay_cs.to_string());
        let mut output_args = vec![
            "-i",
            palette_arg.as_str(),
            "-lavfi",
            gif_filter.as_str(),
            "-loop",
            loop_value,
            "-gifflags",
            "+offsetting+transdiff",
            "-global_palette",
            "1",
        ];
        if let Some(final_delay) = final_delay.as_deref() {
            output_args.extend(["-fps_mode", "passthrough", "-final_delay", final_delay]);
        }
        run_ffmpeg(ffmpeg, input, &source_args, &output_args, output)
    })();
    let _ = fs::remove_dir_all(&temp_dir);
    result
}

fn encode_with_opaque_palette(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
    stats_mode: PaletteStatsMode,
) -> Result<(), AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Encode);
    let temp_dir = create_unique_temp_dir("gif-p-opaque-palette")?;
    let palette = temp_dir.join("palette.png");
    let source_args = source_time_args(request);
    let colors = palette_color_count(request.colors);
    let palette_filter = format!(
        "{},palettegen=max_colors={colors}:reserve_transparent=0:stats_mode={}",
        video_filter(request, encoder),
        stats_mode.as_ffmpeg_value(),
    );
    let dither = dither_for_plan(request, encoder, plan);
    let bayer = if dither == "bayer" {
        format!(":bayer_scale={}", bayer_scale_for_plan(request, plan))
    } else {
        String::new()
    };
    let gif_filter = format!(
        "[0:v]{filter}[x];[x][1:v]paletteuse=dither={dither}{bayer}:new=0:alpha_threshold={alpha}",
        filter = video_filter(request, encoder),
        alpha = plan.alpha_threshold,
    );
    let palette_arg = palette.to_string_lossy().to_string();
    let result = (|| {
        generate_palette_cached(ffmpeg, input, &source_args, &palette_filter, &palette)?;

        let loop_value = if request.loop_output { "0" } else { "-1" };
        let final_delay = request
            .perceptual_selection
            .as_ref()
            .map(|selection| selection.final_delay_cs.to_string());
        let mut output_args = vec![
            "-i",
            palette_arg.as_str(),
            "-lavfi",
            gif_filter.as_str(),
            "-loop",
            loop_value,
            "-gifflags",
            "+offsetting-transdiff",
            "-global_palette",
            "1",
        ];
        if let Some(final_delay) = final_delay.as_deref() {
            output_args.extend(["-fps_mode", "passthrough", "-final_delay", final_delay]);
        }
        run_ffmpeg(ffmpeg, input, &source_args, &output_args, output)
    })();
    let _ = fs::remove_dir_all(&temp_dir);
    result
}

fn encode_with_opaque_frame_palettes(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
) -> Result<(), AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Encode);
    let source_args = source_time_args(request);
    let colors = palette_color_count(request.colors);
    let graph = format!(
        "[0:v]{base},split[v][pg];[pg]palettegen=max_colors={colors}:reserve_transparent=0:stats_mode=single[p];[v][p]paletteuse=dither=floyd_steinberg:new=1:alpha_threshold=128[out]",
        base = video_filter(request, encoder),
    );
    let loop_value = if request.loop_output { "0" } else { "-1" };
    let final_delay = request
        .perceptual_selection
        .as_ref()
        .map(|selection| selection.final_delay_cs.to_string());
    let mut output_args = vec![
        "-filter_complex",
        graph.as_str(),
        "-map",
        "[out]",
        "-loop",
        loop_value,
        "-gifflags",
        "+offsetting-transdiff",
        "-global_palette",
        "0",
    ];
    if let Some(final_delay) = final_delay.as_deref() {
        output_args.extend(["-fps_mode", "passthrough", "-final_delay", final_delay]);
    }
    run_ffmpeg(ffmpeg, input, &source_args, &output_args, output)
}

fn encode_with_oklab_palette(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
    artifact: &OklabPaletteArtifact,
) -> Result<(), AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Encode);
    if artifact.rgba.len() != 256 * 4 {
        return Err(AppError::Internal(format!(
            "OKLab palette artifact has {} bytes; expected 1024",
            artifact.rgba.len()
        )));
    }
    let temp_dir = create_unique_temp_dir("gif-p-oklab")?;
    let palette = temp_dir.join("palette.rgba");
    let result = (|| {
        fs::write(&palette, &artifact.rgba)
            .map_err(|error| AppError::Internal(format!("Write OKLab palette: {error}")))?;
        let source_args = source_time_args(request);
        let gif_filter = gif_filter(request, encoder, plan);
        let palette_arg = palette.to_string_lossy().to_string();
        let loop_value = if request.loop_output { "0" } else { "-1" };
        let gif_flags = if oklab_palette_reserves_transparency(artifact) {
            "+offsetting+transdiff"
        } else {
            // Explicitly disable `transdiff`: a full 256-color opaque table
            // has no spare transparent index for frame deltas.
            "+offsetting-transdiff"
        };
        let final_delay = request
            .perceptual_selection
            .as_ref()
            .map(|selection| selection.final_delay_cs.to_string());
        let mut output_args = vec![
            "-f",
            "rawvideo",
            "-pixel_format",
            "rgba",
            "-video_size",
            "16x16",
            "-framerate",
            "1",
            "-i",
            palette_arg.as_str(),
            "-lavfi",
            gif_filter.as_str(),
            "-loop",
            loop_value,
            "-gifflags",
            gif_flags,
            "-global_palette",
            "1",
        ];
        if let Some(final_delay) = final_delay.as_deref() {
            output_args.extend(["-fps_mode", "passthrough", "-final_delay", final_delay]);
        }
        run_ffmpeg(ffmpeg, input, &source_args, &output_args, output)?;
        match verify_gif_global_palette(output, artifact)? {
            true => Ok(()),
            false => Err(AppError::EncodeFailed(
                "FFmpeg did not preserve the Rust OKLab global palette artifact".to_string(),
            )),
        }
    })();
    let _ = fs::remove_dir_all(&temp_dir);
    result
}

struct SerializedIndexedCandidate {
    bytes: Vec<u8>,
    optimized_plan: IndexedGifPlan,
    write_report: IndexedGifWriteReport,
    optimization_report: IndexedGifOptimizationReport,
    palette_compaction_report: IndexedPaletteCompactionExecutionReport,
}

struct TransparentGifPostprocessResult {
    report: IndexedGifWriterReport,
    published: bool,
}

type RegionalQuantizerAttempt = (
    Option<(SerializedIndexedCandidate, Vec<u8>)>,
    RegionalQuantizerExecutionReport,
);

type SegmentPaletteAttempt = (
    Option<(SerializedIndexedCandidate, Vec<u8>)>,
    SegmentPaletteExecutionReport,
);

fn full_frame_indexed_plan(
    indices: Vec<u8>,
    width: u16,
    height: u16,
    frame_delays_cs: &[u16],
    global_palette_rgb: &[u8],
    repeat: IndexedGifRepeat,
) -> Result<IndexedGifPlan, AppError> {
    let frame_pixels = usize::from(width)
        .checked_mul(usize::from(height))
        .ok_or_else(|| AppError::Internal("Rust writer frame pixel count overflow".to_string()))?;
    let expected = frame_pixels
        .checked_mul(frame_delays_cs.len())
        .ok_or_else(|| {
            AppError::Internal("Rust writer timeline pixel count overflow".to_string())
        })?;
    if indices.len() != expected {
        return Err(AppError::DecodeFailed(format!(
            "Rust writer received {} indices; expected {expected}",
            indices.len()
        )));
    }
    let frames = indices
        .chunks_exact(frame_pixels)
        .zip(frame_delays_cs.iter().copied())
        .map(|(indices, delay_cs)| IndexedGifFrame {
            left: 0,
            top: 0,
            width,
            height,
            delay_cs,
            disposal: IndexedGifDisposal::Keep,
            transparent_index: indices
                .contains(&GIF_TRANSPARENT_INDEX)
                .then_some(GIF_TRANSPARENT_INDEX),
            local_palette_rgb: None,
            indices: indices.to_vec(),
        })
        .collect();
    Ok(IndexedGifPlan {
        width,
        height,
        global_palette_rgb: global_palette_rgb.to_vec(),
        repeat,
        frames,
    })
}

fn compact_local_palette_rgb(artifact: &OklabPaletteArtifact) -> Result<Vec<u8>, AppError> {
    if artifact.rgba.len() != 256 * 4 {
        return Err(AppError::Internal(format!(
            "Segment palette artifact has {} bytes; expected 1024",
            artifact.rgba.len()
        )));
    }
    let opaque_entries = usize::from(artifact.emitted_colors.saturating_sub(1)).min(255);
    if opaque_entries == 0 {
        return Err(AppError::Internal(
            "Segment palette artifact has no opaque colors".to_string(),
        ));
    }
    let table_entries = opaque_entries.max(2).next_power_of_two().min(256);
    let mut rgb = Vec::with_capacity(table_entries * 3);
    for entry in artifact.rgba[..opaque_entries * 4].chunks_exact(4) {
        rgb.extend_from_slice(&entry[..3]);
    }
    let final_color = rgb[rgb.len() - 3..].to_vec();
    while rgb.len() < table_entries * 3 {
        rgb.extend_from_slice(&final_color);
    }
    Ok(rgb)
}

#[allow(clippy::too_many_arguments)]
fn full_frame_segmented_indexed_plan(
    indices: Vec<u8>,
    width: u16,
    height: u16,
    frame_delays_cs: &[u16],
    global_palette_rgb: &[u8],
    frame_local_palettes_rgb: Vec<Vec<u8>>,
    repeat: IndexedGifRepeat,
) -> Result<IndexedGifPlan, AppError> {
    if frame_local_palettes_rgb.len() != frame_delays_cs.len() {
        return Err(AppError::Internal(format!(
            "Segment palette timeline has {} tables for {} delays",
            frame_local_palettes_rgb.len(),
            frame_delays_cs.len()
        )));
    }
    let frame_pixels = usize::from(width)
        .checked_mul(usize::from(height))
        .ok_or_else(|| AppError::Internal("Segment writer frame size overflow".to_string()))?;
    let expected = frame_pixels
        .checked_mul(frame_delays_cs.len())
        .ok_or_else(|| AppError::Internal("Segment writer timeline overflow".to_string()))?;
    if indices.len() != expected {
        return Err(AppError::DecodeFailed(format!(
            "Segment writer received {} indices; expected {expected}",
            indices.len()
        )));
    }
    let frames = indices
        .chunks_exact(frame_pixels)
        .zip(frame_delays_cs.iter().copied())
        .zip(frame_local_palettes_rgb)
        .map(|((indices, delay_cs), local_palette_rgb)| IndexedGifFrame {
            left: 0,
            top: 0,
            width,
            height,
            delay_cs,
            disposal: IndexedGifDisposal::Keep,
            transparent_index: None,
            local_palette_rgb: Some(local_palette_rgb),
            indices: indices.to_vec(),
        })
        .collect();
    Ok(IndexedGifPlan {
        width,
        height,
        global_palette_rgb: global_palette_rgb.to_vec(),
        repeat,
        frames,
    })
}

fn serialize_optimized_indexed_candidate(
    full_frame_plan: &IndexedGifPlan,
) -> Result<SerializedIndexedCandidate, AppError> {
    let mut ignored_serialization_count = 0_u8;
    serialize_optimized_indexed_candidate_tracked(full_frame_plan, &mut ignored_serialization_count)
}

fn serialize_optimized_indexed_candidate_tracked(
    full_frame_plan: &IndexedGifPlan,
    serialization_count: &mut u8,
) -> Result<SerializedIndexedCandidate, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Encode);
    let uses_transparency = full_frame_plan.frames.iter().any(|frame| {
        frame
            .transparent_index
            .is_some_and(|transparent| frame.indices.contains(&transparent))
    });
    let (optimized, optimization_report) = if uses_transparency {
        optimize_transparent_full_frames_by_bytes(full_frame_plan)
    } else {
        optimize_full_frames_to_change_rectangles(full_frame_plan)
    }
    .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    let mut baseline_bytes = Vec::new();
    *serialization_count = serialization_count.saturating_add(1);
    let baseline_write_report = write_indexed_gif(&mut baseline_bytes, &optimized)
        .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    let (compacted, compaction) = compact_indexed_palette_tables(&optimized)
        .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    let mut compacted_bytes = Vec::new();
    *serialization_count = serialization_count.saturating_add(1);
    let compacted_write_report = write_indexed_gif(&mut compacted_bytes, &compacted)
        .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    let baseline_serialized_bytes = u64::try_from(baseline_bytes.len())
        .map_err(|_| AppError::Internal("Indexed baseline byte count overflow".to_string()))?;
    let compacted_serialized_bytes = u64::try_from(compacted_bytes.len())
        .map_err(|_| AppError::Internal("Indexed compacted byte count overflow".to_string()))?;
    let selection_gate_passed = compacted_serialized_bytes < baseline_serialized_bytes;
    let selected_serialized_bytes = if selection_gate_passed {
        compacted_serialized_bytes
    } else {
        baseline_serialized_bytes
    };
    let selected_global_palette_entries = if selection_gate_passed {
        compaction.compacted_global_palette_entries
    } else {
        compaction.original_global_palette_entries
    };
    let palette_compaction_report = IndexedPaletteCompactionExecutionReport {
        selector_id: "rust.indexed_palette_compaction.real_bytes.v1".to_string(),
        selector_version: env!("CARGO_PKG_VERSION").to_string(),
        status: if selection_gate_passed {
            "compacted_selected"
        } else {
            "baseline_retained"
        }
        .to_string(),
        real_byte_comparison_performed: true,
        selection_gate_passed,
        baseline_serialized_bytes: Some(baseline_serialized_bytes),
        compacted_serialized_bytes,
        selected_serialized_bytes,
        serialized_byte_reduction_percent: Some(serialized_reduction_percent(
            baseline_serialized_bytes,
            compacted_serialized_bytes,
        )),
        original_global_palette_entries: compaction.original_global_palette_entries,
        compacted_global_palette_entries: compaction.compacted_global_palette_entries,
        selected_global_palette_entries,
        original_local_palette_entries: compaction.original_local_palette_entries,
        compacted_local_palette_entries: compaction.compacted_local_palette_entries,
        compacted_local_palette_frame_count: compaction.compacted_local_palette_frame_count,
        remapped_frame_count: compaction.remapped_frame_count,
        display_simulation_verified: compaction.display_simulation_verified,
    };
    let (bytes, optimized_plan, write_report) = if selection_gate_passed {
        (compacted_bytes, compacted, compacted_write_report)
    } else {
        (baseline_bytes, optimized, baseline_write_report)
    };
    Ok(SerializedIndexedCandidate {
        bytes,
        optimized_plan,
        write_report,
        optimization_report,
        palette_compaction_report,
    })
}

/// Serializes one regional candidate exactly once.
///
/// Regional candidate pricing has a hard three-stream budget (ordered,
/// temporal and then either phase-locked pair or legacy diffusion). Palette
/// compaction's second real-byte probe is deliberately omitted on this path;
/// the final selected stream remains protected by the same decoded-pixel and
/// real-byte gates as every other Rust-writer candidate.
fn serialize_regional_indexed_candidate_tracked(
    full_frame_plan: &IndexedGifPlan,
    budget: &mut RegionalQuantizerBudgetTracker,
) -> Result<SerializedIndexedCandidate, AppError> {
    let uses_transparency = full_frame_plan.frames.iter().any(|frame| {
        frame
            .transparent_index
            .is_some_and(|transparent| frame.indices.contains(&transparent))
    });
    if uses_transparency {
        return Err(AppError::Internal(
            "Regional single-pass serialization does not accept transparent indexed plans"
                .to_string(),
        ));
    }
    let (optimized_plan, optimization_report) =
        optimize_full_frames_to_change_rectangles(full_frame_plan)
            .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    let (compacted_plan, compaction) = compact_indexed_palette_tables(&optimized_plan)
        .map_err(|error| AppError::EncodeFailed(error.to_string()))?;

    budget.reserve_serialization()?;
    let mut bytes = Vec::new();
    let write_report = write_indexed_gif(&mut bytes, &compacted_plan)
        .map_err(|error| AppError::EncodeFailed(error.to_string()))?;
    let serialized_bytes = u64::try_from(bytes.len())
        .map_err(|_| AppError::Internal("Regional candidate byte count overflow".to_string()))?;
    let palette_compaction_report = IndexedPaletteCompactionExecutionReport {
        selector_id: "rust.indexed_palette_compaction.regional_single_pass.v1".to_string(),
        selector_version: env!("CARGO_PKG_VERSION").to_string(),
        status: "compacted_single_pass_no_byte_comparison".to_string(),
        real_byte_comparison_performed: false,
        selection_gate_passed: false,
        baseline_serialized_bytes: None,
        compacted_serialized_bytes: serialized_bytes,
        selected_serialized_bytes: serialized_bytes,
        serialized_byte_reduction_percent: None,
        original_global_palette_entries: compaction.original_global_palette_entries,
        compacted_global_palette_entries: compaction.compacted_global_palette_entries,
        selected_global_palette_entries: compaction.compacted_global_palette_entries,
        original_local_palette_entries: compaction.original_local_palette_entries,
        compacted_local_palette_entries: compaction.compacted_local_palette_entries,
        compacted_local_palette_frame_count: compaction.compacted_local_palette_frame_count,
        remapped_frame_count: compaction.remapped_frame_count,
        display_simulation_verified: compaction.display_simulation_verified,
    };

    Ok(SerializedIndexedCandidate {
        bytes,
        optimized_plan: compacted_plan,
        write_report,
        optimization_report,
        palette_compaction_report,
    })
}

fn inspect_gif_file(input: &Path) -> Result<MediaInspection, AppError> {
    let (width, height, frame_delays_cs, has_alpha) = read_gif_timeline_contract(input, true)?;
    let frame_count = u64::try_from(frame_delays_cs.len())
        .map_err(|_| AppError::DecodeFailed("GIF frame count overflow".to_string()))?;
    let duration_cs = frame_delays_cs
        .iter()
        .fold(0_u64, |sum, delay| sum.saturating_add(u64::from(*delay)));

    Ok(MediaInspection {
        codec: "gif".to_string(),
        width: u32::from(width),
        height: u32::from(height),
        duration: duration_cs as f64 / 100.0,
        frame_count,
        animated: frame_count > 1,
        has_alpha,
    })
}

fn read_gif_timeline_contract(
    input: &Path,
    decode_frames: bool,
) -> Result<(u16, u16, Vec<u16>, bool), AppError> {
    let file = fs::File::open(input).map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    let mut options = gif::DecodeOptions::new();
    options.skip_frame_decoding(!decode_frames);
    options.check_frame_consistency(true);
    let mut decoder = options
        .read_info(file)
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    let width = decoder.width();
    let height = decoder.height();
    let mut delays = Vec::new();
    let mut has_alpha = false;
    while let Some(frame) = decoder
        .read_next_frame()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?
    {
        delays.push(frame.delay);
        has_alpha |= frame.transparent.is_some();
    }
    if width == 0 || height == 0 || delays.is_empty() {
        return Err(AppError::DecodeFailed(
            "GIF inspection received an empty timeline".to_string(),
        ));
    }
    Ok((width, height, delays, has_alpha))
}

fn opaque_palette_entries(rgba: &[u8]) -> Result<Option<Vec<[u8; 3]>>, AppError> {
    let mut entries = Vec::new();
    let mut seen = HashMap::with_capacity(255);
    for (pixel_index, pixel) in rgba.chunks_exact(4).enumerate() {
        if pixel[3] == 0 {
            continue;
        }
        if pixel[3] != u8::MAX {
            return Err(AppError::DecodeFailed(format!(
                "GIF decoded pixel {pixel_index} has unsupported partial alpha {}",
                pixel[3]
            )));
        }
        let key = rgb_key(pixel[0], pixel[1], pixel[2]);
        if let std::collections::hash_map::Entry::Vacant(entry) = seen.entry(key) {
            if entries.len() == usize::from(GIF_TRANSPARENT_INDEX) {
                return Ok(None);
            }
            entry.insert(entries.len() as u8);
            entries.push([pixel[0], pixel[1], pixel[2]]);
        }
    }
    Ok(Some(entries))
}

fn fixed_global_palette(entries: &[[u8; 3]]) -> Vec<u8> {
    let mut palette = vec![0_u8; 256 * 3];
    for (index, color) in entries.iter().enumerate() {
        palette[index * 3..index * 3 + 3].copy_from_slice(color);
    }
    palette
}

fn map_rgba_with_palette(rgba: &[u8], entries: &[[u8; 3]]) -> Result<Vec<u8>, AppError> {
    let lookup = entries
        .iter()
        .enumerate()
        .map(|(index, color)| (rgb_key(color[0], color[1], color[2]), index as u8))
        .collect::<HashMap<_, _>>();
    rgba.chunks_exact(4)
        .enumerate()
        .map(|(pixel_index, pixel)| {
            if pixel[3] == 0 {
                Ok(GIF_TRANSPARENT_INDEX)
            } else {
                lookup
                    .get(&rgb_key(pixel[0], pixel[1], pixel[2]))
                    .copied()
                    .ok_or_else(|| {
                        AppError::DecodeFailed(format!(
                            "GIF decoded pixel {pixel_index} is outside its reconstructed palette"
                        ))
                    })
            }
        })
        .collect()
}

fn transparent_full_frame_plan_from_decoded_rgba(
    rgba: &[u8],
    width: u16,
    height: u16,
    frame_delays_cs: &[u16],
    repeat: IndexedGifRepeat,
) -> Result<IndexedGifPlan, AppError> {
    let frame_bytes = usize::from(width)
        .checked_mul(usize::from(height))
        .and_then(|pixels| pixels.checked_mul(4))
        .ok_or_else(|| AppError::Internal("Transparent GIF frame size overflow".to_string()))?;
    let expected_bytes = frame_bytes
        .checked_mul(frame_delays_cs.len())
        .ok_or_else(|| AppError::Internal("Transparent GIF timeline overflow".to_string()))?;
    if rgba.len() != expected_bytes {
        return Err(AppError::DecodeFailed(format!(
            "Transparent GIF decoded {} RGBA bytes; expected {expected_bytes}",
            rgba.len()
        )));
    }

    if let Some(entries) = opaque_palette_entries(rgba)? {
        let indices = map_rgba_with_palette(rgba, &entries)?;
        return full_frame_indexed_plan(
            indices,
            width,
            height,
            frame_delays_cs,
            &fixed_global_palette(&entries),
            repeat,
        );
    }

    let mut frames = Vec::with_capacity(frame_delays_cs.len());
    for (frame_index, (frame_rgba, delay_cs)) in rgba
        .chunks_exact(frame_bytes)
        .zip(frame_delays_cs.iter().copied())
        .enumerate()
    {
        let entries = opaque_palette_entries(frame_rgba)?.ok_or_else(|| {
            AppError::UnsupportedVideo(format!(
                "Transparent GIF displayed frame {frame_index} exceeds 255 opaque colors"
            ))
        })?;
        frames.push(IndexedGifFrame {
            left: 0,
            top: 0,
            width,
            height,
            delay_cs,
            disposal: IndexedGifDisposal::Keep,
            transparent_index: Some(GIF_TRANSPARENT_INDEX),
            local_palette_rgb: Some(fixed_global_palette(&entries)),
            indices: map_rgba_with_palette(frame_rgba, &entries)?,
        });
    }
    let global_palette_rgb = frames
        .first()
        .and_then(|frame| frame.local_palette_rgb.clone())
        .unwrap_or_else(|| vec![0_u8; 256 * 3]);
    Ok(IndexedGifPlan {
        width,
        height,
        global_palette_rgb,
        repeat,
        frames,
    })
}

fn serialized_reduction_percent(baseline: u64, candidate: u64) -> f64 {
    if baseline == 0 {
        0.0
    } else {
        (1.0 - candidate as f64 / baseline as f64) * 100.0
    }
}

fn postprocess_transparent_gif_with_rust(
    ffmpeg: &Path,
    output: &Path,
    loop_output: bool,
) -> Result<TransparentGifPostprocessResult, AppError> {
    postprocess_transparent_gif_with_policy(ffmpeg, output, loop_output, true)
}

fn postprocess_transparent_gif_with_policy(
    ffmpeg: &Path,
    output: &Path,
    loop_output: bool,
    prescreen: bool,
) -> Result<TransparentGifPostprocessResult, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Validation);
    let baseline_serialized_bytes = fs::metadata(output)
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?
        .len();
    let (width, height, frame_delays_cs, _) = read_gif_timeline_contract(output, false)?;
    let expected_rgba_bytes = u64::from(width)
        .checked_mul(u64::from(height))
        .and_then(|pixels| pixels.checked_mul(4))
        .and_then(|frame_bytes| frame_bytes.checked_mul(frame_delays_cs.len() as u64))
        .ok_or_else(|| AppError::Internal("Transparent GIF parity size overflow".to_string()))?;
    if expected_rgba_bytes > MAX_EXPERIMENTAL_WRITER_RGBA_BYTES {
        return Err(AppError::UnsupportedVideo(format!(
            "Transparent GIF parity buffer needs {expected_rgba_bytes} bytes; experimental limit is {MAX_EXPERIMENTAL_WRITER_RGBA_BYTES}"
        )));
    }
    let baseline_rgba = decode_media_rgba(ffmpeg, output)?;
    if baseline_rgba.len() as u64 != expected_rgba_bytes {
        return Err(AppError::DecodeFailed(format!(
            "Transparent GIF decoded {} RGBA bytes; expected {expected_rgba_bytes}",
            baseline_rgba.len()
        )));
    }
    let canonical_baseline =
        canonical_timed_rgba_timeline(&baseline_rgba, width, height, &frame_delays_cs)?;
    let repeat = if loop_output {
        IndexedGifRepeat::Infinite
    } else {
        IndexedGifRepeat::None
    };
    let full_plan = transparent_full_frame_plan_from_decoded_rgba(
        &baseline_rgba,
        width,
        height,
        &frame_delays_cs,
        repeat,
    )?;
    let candidate = serialize_optimized_indexed_candidate(&full_plan)?;
    let candidate_serialized_bytes = candidate.bytes.len() as u64;
    let temp_dir = create_unique_temp_dir("gif-p-transparent-postprocess")?;
    let staged = temp_dir.join("candidate.gif");
    let published = candidate_serialized_bytes < baseline_serialized_bytes;
    let writer_input_rgba_sha256 =
        hash_canonical_timed_rgba_timeline(width, height, &canonical_baseline);
    let result = (|| {
        let decoded_rgba_sha256 = if published || !prescreen {
            fs::write(&staged, &candidate.bytes)
                .map_err(|error| AppError::Internal(format!("Stage transparent GIF: {error}")))?;
            if !verify_gif_indexed_plan_palette(&staged, &candidate.optimized_plan)? {
                return Err(AppError::EncodeFailed(
                    "Transparent GIF postprocessor did not preserve its indexed palette contract"
                        .to_string(),
                ));
            }
            let (candidate_width, candidate_height, candidate_delays_cs, _) =
                read_gif_timeline_contract(&staged, false)?;
            if candidate_width != width || candidate_height != height {
                return Err(AppError::EncodeFailed(format!(
                "Transparent GIF postprocessor changed the canvas from {width}x{height} to {candidate_width}x{candidate_height}"
            )));
            }
            let decoded_rgba = decode_media_rgba(ffmpeg, &staged)?;
            let canonical_decoded = canonical_timed_rgba_timeline(
                &decoded_rgba,
                candidate_width,
                candidate_height,
                &candidate_delays_cs,
            )?;
            let decoded_rgba_sha256 =
                hash_canonical_timed_rgba_timeline(width, height, &canonical_decoded);
            if canonical_decoded != canonical_baseline {
                return Err(AppError::EncodeFailed(format!(
                "Transparent GIF decoded-display parity failed (writer input {writer_input_rgba_sha256}, decoded {decoded_rgba_sha256})"
            )));
            }
            Some(decoded_rgba_sha256)
        } else {
            check_conversion_cancelled()?;
            None
        };
        let parity_verified = decoded_rgba_sha256.is_some();
        if published {
            publish_file_atomically(&staged, output, true)?;
        }
        Ok(TransparentGifPostprocessResult {
            report: IndexedGifWriterReport {
                writer_id: "rust.indexed_gif.transparent_postprocess.v7".to_string(),
                writer_version: env!("CARGO_PKG_VERSION").to_string(),
                container_backend: "image-gif 0.14.2".to_string(),
                status: if published {
                    "encoded_default"
                } else {
                    "baseline_retained"
                }
                .to_string(),
                fallback_reason: (!parity_verified).then(|| "Candidate was not smaller; skipped its decode verification and retained the original output".to_string()),
                frame_count: candidate.write_report.frame_count,
                full_frame_count: candidate.write_report.full_frame_count,
                total_indexed_pixels: candidate.write_report.total_indexed_pixels,
                original_indexed_pixels: candidate.optimization_report.original_indexed_pixels,
                optimized_indexed_pixels: candidate.optimization_report.optimized_indexed_pixels,
                rectangle_frame_count: candidate.optimization_report.rectangle_frame_count,
                transparent_hold_frame_count: candidate
                    .optimization_report
                    .transparent_hold_frame_count,
                background_disposal_frame_count: candidate
                    .optimization_report
                    .background_disposal_frame_count,
                previous_disposal_frame_count: candidate
                    .optimization_report
                    .previous_disposal_frame_count,
                disposal_candidate_count: candidate.optimization_report.disposal_candidate_count,
                selected_disposal_strategy: candidate
                    .optimization_report
                    .selected_disposal_strategy
                    .clone(),
                indexed_pixel_reduction_percent: candidate
                    .optimization_report
                    .indexed_pixel_reduction_percent,
                baseline_serialized_bytes: Some(baseline_serialized_bytes),
                candidate_serialized_bytes: Some(candidate_serialized_bytes),
                serialized_byte_reduction_percent: Some(serialized_reduction_percent(
                    baseline_serialized_bytes,
                    candidate_serialized_bytes,
                )),
                disposal_simulation_verified: candidate
                    .optimization_report
                    .disposal_simulation_verified,
                total_delay_cs: candidate.write_report.total_delay_cs,
                local_palette_frame_count: candidate.write_report.local_palette_frame_count,
                palette_boundary_full_frame_count: candidate
                    .optimization_report
                    .palette_boundary_full_frame_count,
                global_palette_rgb_sha256: Some(candidate.write_report.global_palette_sha256),
                local_palette_sequence_sha256: candidate.write_report.local_palette_sequence_sha256,
                indexed_timeline_sha256: Some(candidate.write_report.indexed_timeline_sha256),
                ffmpeg_mapped_rgba_sha256: Some(writer_input_rgba_sha256.clone()),
                writer_input_rgba_sha256: Some(writer_input_rgba_sha256),
                decoded_rgba_sha256,
                decoded_pixel_parity_verified: parity_verified,
                palette_compaction_report: Some(candidate.palette_compaction_report.clone()),
                palette_mapper_selection_report: None,
                regional_quantizer_report: None,
                segment_palette_report: None,
            },
            published,
        })
    })();
    let _ = fs::remove_dir_all(temp_dir);
    result
}

fn map_palette_rgba_to_indices(
    rgba: &[u8],
    artifact: &OklabPaletteArtifact,
) -> Result<Vec<u8>, AppError> {
    let mut palette_indices = HashMap::with_capacity(255);
    for (index, entry) in artifact.rgba[..255 * 4].chunks_exact(4).enumerate() {
        palette_indices
            .entry(rgb_key(entry[0], entry[1], entry[2]))
            .or_insert(index as u8);
    }
    let mut indices = Vec::with_capacity(rgba.len() / 4);
    for (pixel_index, pixel) in rgba.chunks_exact(4).enumerate() {
        if pixel[3] == 0 {
            indices.push(GIF_TRANSPARENT_INDEX);
            continue;
        }
        let key = rgb_key(pixel[0], pixel[1], pixel[2]);
        let index = palette_indices.get(&key).copied().ok_or_else(|| {
            AppError::DecodeFailed(format!(
                "Rust indexed writer pixel {pixel_index} has RGBA [{}, {}, {}, {}] outside the verified palette",
                pixel[0], pixel[1], pixel[2], pixel[3]
            ))
        })?;
        indices.push(index);
    }
    Ok(indices)
}

fn opaque_rgba_to_rgb24(rgba: &[u8], label: &str) -> Result<Vec<u8>, AppError> {
    if !rgba.len().is_multiple_of(4) {
        return Err(AppError::DecodeFailed(format!(
            "{label} returned an incomplete RGBA pixel"
        )));
    }
    let mut rgb = Vec::with_capacity(rgba.len() / 4 * 3);
    for (index, pixel) in rgba.chunks_exact(4).enumerate() {
        if pixel[3] != u8::MAX {
            return Err(AppError::DecodeFailed(format!(
                "{label} pixel {index} has alpha {}; regional quantization currently requires opaque frames",
                pixel[3]
            )));
        }
        rgb.extend_from_slice(&pixel[..3]);
    }
    Ok(rgb)
}

fn rgb24_to_opaque_rgba(rgb: &[u8]) -> Vec<u8> {
    let mut rgba = Vec::with_capacity(rgb.len() / 3 * 4);
    for pixel in rgb.chunks_exact(3) {
        rgba.extend_from_slice(&[pixel[0], pixel[1], pixel[2], u8::MAX]);
    }
    rgba
}

fn decode_transformed_rgba(
    ffmpeg: &Path,
    input: &Path,
    request: &GifRequest,
    encoder: &str,
) -> Result<Vec<u8>, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::DecodeTransform);
    let output = Command::new(ffmpeg)
        .arg("-hide_banner")
        .arg("-loglevel")
        .arg("error")
        .args(source_time_args(request))
        .args(animation_demux_args(input))
        .arg("-i")
        .arg(input)
        .arg("-an")
        .arg("-sn")
        .arg("-vf")
        .arg(video_filter(request, encoder))
        .arg("-fps_mode")
        .arg("passthrough")
        .arg("-pix_fmt")
        .arg("rgba")
        .arg("-f")
        .arg("rawvideo")
        .arg("pipe:1")
        .output_for_conversion_task()
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
    if !output.status.success() {
        return Err(AppError::DecodeFailed(format!(
            "Regional quantizer source decode failed: {}",
            String::from_utf8_lossy(&output.stderr)
        )));
    }
    Ok(output.stdout)
}

fn decode_quantizer_source_rgba(
    ffmpeg: &Path,
    input: &Path,
    request: &GifRequest,
    encoder: &str,
    expected_rgba_bytes: u64,
) -> Result<Vec<u8>, AppError> {
    if expected_rgba_bytes > MAX_REGIONAL_QUANTIZER_RGBA_BYTES {
        return Err(AppError::UnsupportedVideo(format!(
            "Rust quantizer needs {expected_rgba_bytes} source RGBA bytes; experimental limit is {MAX_REGIONAL_QUANTIZER_RGBA_BYTES}"
        )));
    }
    let source_rgba = decode_transformed_rgba(ffmpeg, input, request, encoder)?;
    if source_rgba.len() as u64 != expected_rgba_bytes {
        return Err(AppError::DecodeFailed(format!(
            "Rust quantizer decoded {} source RGBA bytes; expected {expected_rgba_bytes}",
            source_rgba.len()
        )));
    }
    Ok(source_rgba)
}

fn motion_reference_filter(request: &GifRequest) -> String {
    let mut filters = timeline_filters(request);
    filters.extend(style_filters(&request.filter_style));
    filters.join(",")
}

fn evaluate_motion_presentation_candidates(
    ffmpeg: &Path,
    input: &Path,
    baseline: &Path,
    candidate: &Path,
    request: &GifRequest,
    output_inspection: &MediaInspection,
) -> Result<MotionPresentationEvaluation, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Validation);
    let (sample_width, sample_height) =
        analysis_dimensions(output_inspection.width, output_inspection.height)
            .map_err(AppError::DecodeFailed)?;
    let duration_seconds = output_inspection.duration;
    let source_args = source_time_args(request);
    let source_filter = motion_reference_filter(request);
    let source = decode_rgba_frames_with_prefix(
        ffmpeg,
        input,
        &source_args,
        Some(&source_filter),
        sample_width,
        sample_height,
        duration_seconds,
    )
    .map_err(AppError::DecodeFailed)?;
    let baseline_frames = decode_rgba_frames(
        ffmpeg,
        baseline,
        sample_width,
        sample_height,
        duration_seconds,
    )
    .map_err(AppError::DecodeFailed)?;
    let candidate_frames = decode_rgba_frames(
        ffmpeg,
        candidate,
        sample_width,
        sample_height,
        duration_seconds,
    )
    .map_err(AppError::DecodeFailed)?;
    if source.len() != baseline_frames.len() || source.len() != candidate_frames.len() {
        return Err(AppError::DecodeFailed(format!(
            "Motion presentation timelines disagree after timestamp resampling: source={} bytes, baseline={} bytes, candidate={} bytes",
            source.len(),
            baseline_frames.len(),
            candidate_frames.len()
        )));
    }
    let frame_bytes = u64::from(sample_width)
        .checked_mul(u64::from(sample_height))
        .and_then(|pixels| pixels.checked_mul(4))
        .ok_or_else(|| {
            AppError::UnsupportedVideo(
                "Motion presentation proxy frame byte count overflow".to_string(),
            )
        })?;
    let compared_frames = u64::try_from(source.len()).map_err(|_| {
        AppError::UnsupportedVideo("Motion presentation proxy byte count exceeds u64".to_string())
    })? / frame_bytes;
    let baseline_metrics =
        compute_raw_metrics(&source, &baseline_frames, sample_width, sample_height)
            .map_err(AppError::DecodeFailed)?;
    let candidate_metrics =
        compute_raw_metrics(&source, &candidate_frames, sample_width, sample_height)
            .map_err(AppError::DecodeFailed)?;
    Ok(MotionPresentationEvaluation {
        baseline_metrics: MotionPresentationMetricsReport::from_raw(
            &baseline_metrics,
            sample_width,
            sample_height,
            compared_frames,
        ),
        candidate_metrics: MotionPresentationMetricsReport::from_raw(
            &candidate_metrics,
            sample_width,
            sample_height,
            compared_frames,
        ),
        baseline_decoded_sha256: format!("{:x}", Sha256::digest(&baseline_frames)),
        candidate_decoded_sha256: format!("{:x}", Sha256::digest(&candidate_frames)),
    })
}

fn attempt_best_delivery_guard(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    baseline_plan: &FfmpegGifPlan,
    gate_profile: BestDeliveryGateProfile,
) -> Result<BestDeliveryGuardOutcome, AppError> {
    let baseline_path = output.with_file_name("best-delivery-baseline.gif");
    let mut baseline_request = request.clone();
    baseline_request.encoder = "ffmpeg_fast".to_string();
    baseline_request.perceptual_selection = None;
    encode_ffmpeg_with_strategy(
        ffmpeg,
        input,
        &baseline_path,
        &baseline_request,
        "ffmpeg_fast",
        baseline_plan,
        &[],
    )?;

    let comparison = (|| -> Result<(), String> {
        let candidate_bytes = fs::metadata(output)
            .map_err(|error| format!("read Best candidate size: {error}"))?
            .len();
        let baseline_bytes = fs::metadata(&baseline_path)
            .map_err(|error| format!("read stable baseline size: {error}"))?
            .len();
        let ffprobe = locate_ffprobe().map_err(|error| error.to_string())?;
        let candidate_inspection =
            inspect_media_file(&ffprobe, output).map_err(|error| error.to_string())?;
        let baseline_inspection =
            inspect_media_file(&ffprobe, &baseline_path).map_err(|error| error.to_string())?;
        let candidate_duration_cs = (candidate_inspection.duration * 100.0).round().max(0.0) as u64;
        let baseline_duration_cs = (baseline_inspection.duration * 100.0).round().max(0.0) as u64;
        if candidate_inspection.width != baseline_inspection.width
            || candidate_inspection.height != baseline_inspection.height
            || candidate_duration_cs.abs_diff(baseline_duration_cs) > 1
        {
            return Err(format!(
                "candidate and baseline delivery contracts differ: candidate {}x{} / {} cs, baseline {}x{} / {} cs",
                candidate_inspection.width,
                candidate_inspection.height,
                candidate_duration_cs,
                baseline_inspection.width,
                baseline_inspection.height,
                baseline_duration_cs
            ));
        }
        let evaluation_inspection = if candidate_inspection.duration <= baseline_inspection.duration
        {
            &candidate_inspection
        } else {
            &baseline_inspection
        };
        let presentation = evaluate_motion_presentation_candidates(
            ffmpeg,
            input,
            &baseline_path,
            output,
            request,
            evaluation_inspection,
        )
        .map_err(|error| error.to_string())?;
        best_delivery_selection_gate(
            gate_profile,
            &presentation.candidate_metrics,
            &presentation.baseline_metrics,
            candidate_bytes,
            baseline_bytes,
        )
    })();

    match comparison {
        Ok(()) => Ok(BestDeliveryGuardOutcome {
            baseline_selected: false,
            fallback_reason: None,
        }),
        Err(reason) => {
            publish_file_atomically(&baseline_path, output, true)?;
            Ok(BestDeliveryGuardOutcome {
                baseline_selected: true,
                fallback_reason: Some(reason),
            })
        }
    }
}

/// Encodes the opaque full-palette alternative beside the already verified
/// transparent-delta GIF, then compares both against the exact transformed
/// source timeline. Failure is intentionally non-destructive: callers retain
/// the transparent baseline unless this helper completes and publishes the
/// opaque candidate atomically.
fn attempt_opaque_palette_reservation_selection(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    encoder: &str,
    plan: &FfmpegGifPlan,
    opaque_artifact: &OklabPaletteArtifact,
) -> Result<OpaquePaletteReservationSelectionOutcome, AppError> {
    let _pipeline_stage = export_pipeline::stage(Phase::Validation);
    if oklab_palette_reserves_transparency(opaque_artifact) {
        return Err(AppError::Internal(
            "Opaque palette reservation selector received a transparent palette".to_string(),
        ));
    }
    let transparent_artifact = request
        .perceptual_selection
        .as_ref()
        .and_then(|selection| selection.palette.as_ref())
        .ok_or_else(|| {
            AppError::Internal(
                "Opaque palette reservation selector requires a transparent baseline palette"
                    .to_string(),
            )
        })?;
    if !oklab_palette_reserves_transparency(transparent_artifact) {
        return Err(AppError::Internal(
            "Opaque palette reservation selector baseline did not reserve transparency".to_string(),
        ));
    }

    let (width, height, frame_delays_cs, _) = read_gif_timeline_contract(output, false)?;
    if frame_delays_cs.len() <= 1 {
        return Err(AppError::Internal(
            "Opaque palette reservation selector requires an animated GIF timeline".to_string(),
        ));
    }
    let expected_rgba_bytes = u64::from(width)
        .checked_mul(u64::from(height))
        .and_then(|pixels| pixels.checked_mul(4))
        .and_then(|frame_bytes| frame_bytes.checked_mul(frame_delays_cs.len() as u64))
        .ok_or_else(|| {
            AppError::Internal("Opaque palette reservation comparison size overflow".to_string())
        })?;
    let transparent_bytes = fs::metadata(output)
        .map_err(|error| AppError::DecodeFailed(format!("Read transparent palette size: {error}")))?
        .len();

    let temp_dir = OwnedTempDir::create("gif-p-palette-reservation")?;
    let opaque_path = temp_dir.path().join("opaque-256.gif");
    let result = (|| {
        let mut opaque_request = request.clone();
        let selection = opaque_request
            .perceptual_selection
            .as_mut()
            .ok_or_else(|| {
                AppError::Internal(
                    "Opaque palette reservation selector requires a perceptual selection"
                        .to_string(),
                )
            })?;
        selection.palette = Some(opaque_artifact.clone());
        // The alternate is deliberately a single global table. Segment and
        // regional artifacts belong to the transparent indexed-writer route
        // and must not accidentally alter this FFmpeg comparison.
        selection.structured_ui_standard_palette = None;
        selection.palette_sequence = None;
        selection.region_dither = None;
        opaque_request.perceptual_opaque_palette_candidate = None;

        encode_with_oklab_palette(
            ffmpeg,
            input,
            &opaque_path,
            &opaque_request,
            encoder,
            plan,
            opaque_artifact,
        )?;

        let (opaque_width, opaque_height, opaque_delays_cs, opaque_has_alpha) =
            read_gif_timeline_contract(&opaque_path, false)?;
        if opaque_width != width
            || opaque_height != height
            || opaque_delays_cs != frame_delays_cs
            || opaque_has_alpha
        {
            return Err(AppError::DecodeFailed(format!(
                "Opaque palette candidate changed its GIF timeline contract: baseline {}x{} / {:?}, candidate {}x{} / {:?}, candidate_has_alpha={opaque_has_alpha}",
                width, height, frame_delays_cs, opaque_width, opaque_height, opaque_delays_cs,
            )));
        }

        let source_rgba =
            decode_quantizer_source_rgba(ffmpeg, input, request, encoder, expected_rgba_bytes)?;
        let transparent_rgba = decode_media_rgba(ffmpeg, output)?;
        if transparent_rgba.len() as u64 != expected_rgba_bytes {
            return Err(AppError::DecodeFailed(format!(
                "Transparent palette GIF decoded {} RGBA bytes; expected {expected_rgba_bytes}",
                transparent_rgba.len()
            )));
        }
        let opaque_rgba = decode_media_rgba(ffmpeg, &opaque_path)?;
        if opaque_rgba.len() as u64 != expected_rgba_bytes {
            return Err(AppError::DecodeFailed(format!(
                "Opaque palette GIF decoded {} RGBA bytes; expected {expected_rgba_bytes}",
                opaque_rgba.len()
            )));
        }

        let source_rgb = opaque_rgba_to_rgb24(&source_rgba, "Opaque palette source")?;
        let transparent_rgb =
            opaque_rgba_to_rgb24(&transparent_rgba, "Transparent palette GIF baseline")?;
        let opaque_rgb = opaque_rgba_to_rgb24(&opaque_rgba, "Opaque palette GIF candidate")?;
        let transparent_metrics =
            evaluate_rgb24_candidate(&source_rgb, &transparent_rgb, width, height)
                .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
        let opaque_metrics = evaluate_rgb24_candidate(&source_rgb, &opaque_rgb, width, height)
            .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
        let transparent_timing = evaluate_timing_aware_temporal_residual(
            &source_rgb,
            &transparent_rgb,
            width,
            height,
            &frame_delays_cs,
            request.loop_output,
        )
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
        let opaque_timing = evaluate_timing_aware_temporal_residual(
            &source_rgb,
            &opaque_rgb,
            width,
            height,
            &frame_delays_cs,
            request.loop_output,
        )
        .map_err(|error| AppError::DecodeFailed(error.to_string()))?;
        let opaque_bytes = fs::metadata(&opaque_path)
            .map_err(|error| {
                AppError::DecodeFailed(format!("Read opaque palette candidate size: {error}"))
            })?
            .len();
        let gate = opaque_palette_reservation_selection_gate(
            &opaque_metrics,
            &transparent_metrics,
            &opaque_timing,
            &transparent_timing,
            opaque_bytes,
            transparent_bytes,
        );
        let quality_gate_passed = gate.is_ok();
        let fallback_reason = gate.err();
        let report = PaletteReservationSelectionReport {
            selector_id: "rust.oklab.palette_reservation_dual_candidate.v1".to_string(),
            selector_version: env!("CARGO_PKG_VERSION").to_string(),
            gate_id: "opaque_256_vfr_loop_rate_distortion_v1".to_string(),
            status: if quality_gate_passed {
                "opaque_256_selected"
            } else {
                "transparent_delta_retained"
            }
            .to_string(),
            fallback_reason,
            quality_gate_passed,
            selected_route_id: if quality_gate_passed {
                "opaque_256_no_transdiff"
            } else {
                "transparent_255_transdiff"
            }
            .to_string(),
            baseline: Some(PaletteReservationCandidateReport {
                palette_sha256: transparent_artifact.sha256.clone(),
                reserved_transparent: true,
                usable_colors: transparent_artifact.emitted_colors.saturating_sub(1),
                emitted_colors: transparent_artifact.emitted_colors,
                serialized_bytes: transparent_bytes,
                decoded_rgba_sha256: format!("{:x}", Sha256::digest(&transparent_rgba)),
                metrics: (&transparent_metrics).into(),
                timing_metrics: (&transparent_timing).into(),
            }),
            candidate: Some(PaletteReservationCandidateReport {
                palette_sha256: opaque_artifact.sha256.clone(),
                reserved_transparent: false,
                usable_colors: opaque_artifact.emitted_colors,
                emitted_colors: opaque_artifact.emitted_colors,
                serialized_bytes: opaque_bytes,
                decoded_rgba_sha256: format!("{:x}", Sha256::digest(&opaque_rgba)),
                metrics: (&opaque_metrics).into(),
                timing_metrics: (&opaque_timing).into(),
            }),
        };
        if quality_gate_passed {
            publish_file_atomically(&opaque_path, output, true)?;
            Ok(OpaquePaletteReservationSelectionOutcome {
                opaque_selected: true,
                transparent_bytes,
                opaque_bytes,
                report,
            })
        } else {
            Ok(OpaquePaletteReservationSelectionOutcome {
                opaque_selected: false,
                transparent_bytes,
                opaque_bytes,
                report,
            })
        }
    })();
    // The candidate may already have been atomically published. Never turn a
    // successful selection into an error merely because its disposable
    // workspace could not be removed immediately; `OwnedTempDir` will make a
    // second best-effort cleanup attempt on drop.
    let _ = temp_dir.cleanup();
    result
}

fn failed_palette_reservation_selection_report(
    reason: String,
) -> PaletteReservationSelectionReport {
    PaletteReservationSelectionReport {
        selector_id: "rust.oklab.palette_reservation_dual_candidate.v1".to_string(),
        selector_version: env!("CARGO_PKG_VERSION").to_string(),
        gate_id: "opaque_256_vfr_loop_rate_distortion_v1".to_string(),
        status: "candidate_failed".to_string(),
        fallback_reason: Some(reason),
        quality_gate_passed: false,
        selected_route_id: "transparent_255_transdiff".to_string(),
        baseline: None,
        candidate: None,
    }
}

fn attempt_motion_delivery_selection(
    ffmpeg: &Path,
    input: &Path,
    output: &Path,
    request: &GifRequest,
    baseline_encoder: &str,
    perceptual_report: &PerceptualReport,
    plan: &FfmpegGifPlan,
) -> Result<MotionDeliverySelectionReport, AppError> {
    let content_signal = motion_delivery_content_signal(perceptual_report);
    let temp_dir = create_unique_temp_dir("gif-p-motion-delivery")?;
    let candidate_path = temp_dir.join("neutral-bayer.gif");
    let result = (|| {
        let selection = request.perceptual_selection.as_ref().ok_or_else(|| {
            AppError::Internal(
                "Motion delivery selector requires a perceptual frame selection".to_string(),
            )
        })?;
        let mut candidate_request = request.clone();
        candidate_request.encoder = "ffmpeg_fast".to_string();
        candidate_request.dither = "bayer".to_string();
        encode_ffmpeg_with_strategy(
            ffmpeg,
            input,
            &candidate_path,
            &candidate_request,
            "ffmpeg_fast",
            plan,
            &[],
        )?;

        let ffprobe = locate_ffprobe()?;
        let baseline_inspection = inspect_media_file(&ffprobe, output)?;
        let candidate_inspection = inspect_media_file(&ffprobe, &candidate_path)?;
        let baseline_duration_cs = (baseline_inspection.duration * 100.0).round().max(0.0) as u64;
        let candidate_duration_cs = (candidate_inspection.duration * 100.0).round().max(0.0) as u64;
        if baseline_inspection.width != candidate_inspection.width
            || baseline_inspection.height != candidate_inspection.height
            || baseline_inspection.frame_count != candidate_inspection.frame_count
            || baseline_duration_cs != candidate_duration_cs
        {
            return Err(AppError::DecodeFailed(format!(
                "Motion delivery candidates disagree on layout or timeline: baseline {}x{} / {} frames / {} cs, candidate {}x{} / {} frames / {} cs",
                baseline_inspection.width,
                baseline_inspection.height,
                baseline_inspection.frame_count,
                baseline_duration_cs,
                candidate_inspection.width,
                candidate_inspection.height,
                candidate_inspection.frame_count,
                candidate_duration_cs
            )));
        }
        let presentation = evaluate_motion_presentation_candidates(
            ffmpeg,
            input,
            output,
            &candidate_path,
            request,
            &baseline_inspection,
        )?;
        let baseline_bytes = fs::metadata(output)
            .map_err(|error| AppError::Internal(error.to_string()))?
            .len();
        let candidate_bytes = fs::metadata(&candidate_path)
            .map_err(|error| AppError::Internal(error.to_string()))?
            .len();
        let gate = motion_presentation_selection_gate(
            &presentation.candidate_metrics,
            &presentation.baseline_metrics,
            candidate_bytes,
            baseline_bytes,
        );
        let quality_gate_passed = gate.is_ok();
        let fallback_reason = gate.err();
        if quality_gate_passed {
            publish_file_atomically(&candidate_path, output, true)?;
        }

        let baseline_dither = dither_for_plan(request, baseline_encoder, plan).to_string();
        let candidate_dither = dither_for_plan(&candidate_request, "ffmpeg_fast", plan).to_string();
        let baseline_filter_strategy = perceptual_filter_strategy(request, selection).to_string();
        let candidate_filter_strategy =
            perceptual_filter_strategy(&candidate_request, selection).to_string();
        Ok(MotionDeliverySelectionReport {
            selector_id: "rust.perceptual.motion_delivery_dual_candidate.v2".to_string(),
            selector_version: env!("CARGO_PKG_VERSION").to_string(),
            gate_id: "motion_delivery_presentation_proxy_v2".to_string(),
            status: if quality_gate_passed {
                "candidate_selected"
            } else {
                "baseline_retained"
            }
            .to_string(),
            fallback_reason,
            quality_gate_passed,
            selected_route_id: if quality_gate_passed {
                "neutral_bayer"
            } else {
                "current_motion"
            }
            .to_string(),
            content_signal: Some(content_signal),
            baseline: Some(MotionDeliveryCandidateReport {
                route_id: "current_motion".to_string(),
                filter_strategy: baseline_filter_strategy,
                dither: baseline_dither.clone(),
                bayer_scale: (baseline_dither == "bayer")
                    .then(|| bayer_scale_for_plan(request, plan)),
                serialized_bytes: baseline_bytes,
                decoded_rgba_sha256: presentation.baseline_decoded_sha256,
                metrics: None,
                presentation_metrics: Some(presentation.baseline_metrics),
            }),
            candidate: Some(MotionDeliveryCandidateReport {
                route_id: "neutral_bayer".to_string(),
                filter_strategy: candidate_filter_strategy,
                dither: candidate_dither.clone(),
                bayer_scale: (candidate_dither == "bayer")
                    .then(|| bayer_scale_for_plan(&candidate_request, plan)),
                serialized_bytes: candidate_bytes,
                decoded_rgba_sha256: presentation.candidate_decoded_sha256,
                metrics: None,
                presentation_metrics: Some(presentation.candidate_metrics),
            }),
        })
    })();
    let _ = fs::remove_dir_all(&temp_dir);
    result
}

fn failed_motion_delivery_selection_report(reason: String) -> MotionDeliverySelectionReport {
    MotionDeliverySelectionReport {
        selector_id: "rust.perceptual.motion_delivery_dual_candidate.v2".to_string(),
        selector_version: env!("CARGO_PKG_VERSION").to_string(),
        gate_id: "motion_delivery_presentation_proxy_v2".to_string(),
        status: "candidate_failed".to_string(),
        fallback_reason: Some(reason),
        quality_gate_passed: false,
        selected_route_id: "current_motion".to_string(),
        content_signal: None,
        baseline: None,
        candidate: None,
    }
}

fn regional_quantization_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    let mut failures = Vec::new();
    if candidate.mean_oklab_error > baseline.mean_oklab_error * 1.06 + 0.001 {
        failures.push("mean OKLab error exceeded +6%/+0.001");
    }
    if candidate.p95_oklab_error > baseline.p95_oklab_error * 1.08 + 0.002 {
        failures.push("P95 OKLab error exceeded +8%/+0.002");
    }
    if candidate.edge_weighted_mean_oklab_error
        > baseline.edge_weighted_mean_oklab_error * 1.05 + 0.001
    {
        failures.push("edge-weighted OKLab error exceeded +5%/+0.001");
    }
    if candidate.multiscale_low_frequency_oklab_error
        > baseline.multiscale_low_frequency_oklab_error * 1.04 + 0.00075
    {
        failures.push("multiscale low-frequency OKLab error exceeded +4%/+0.00075");
    }
    if candidate.multiscale_banding_score > baseline.multiscale_banding_score * 1.02 + 0.0005 {
        failures.push("multiscale banding proxy exceeded +2%/+0.0005");
    }
    if candidate.edge_gradient_error > baseline.edge_gradient_error * 1.05 + 0.002 {
        failures.push("edge-gradient error exceeded +5%/+0.002");
    }
    if candidate.static_temporal_residual > baseline.static_temporal_residual * 1.02 + 0.0005 {
        failures.push("static temporal residual exceeded +2%/+0.0005");
    }
    if candidate.multiscale_static_temporal_residual
        > baseline.multiscale_static_temporal_residual * 1.02 + 0.0004
    {
        failures.push("multiscale static temporal residual exceeded +2%/+0.0004");
    }
    let material_quality_gain = has_material_quality_gain(candidate, baseline);
    if candidate_bytes > baseline_bytes.saturating_mul(105).div_ceil(100) && !material_quality_gain
    {
        failures.push("serialized bytes exceeded +5% without a material quality gain");
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

fn structured_ui_mapper_selection_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    let mut failures = Vec::new();
    if candidate.multiscale_banding_score + 0.0001 >= baseline.multiscale_banding_score * 0.90 {
        failures.push("fine palette produced less than 10% material no-reference banding gain");
    }
    if candidate.mean_oklab_error > baseline.mean_oklab_error * 1.03 + 0.0003 {
        failures.push("mean OKLab error exceeded +3%/+0.0003");
    }
    if candidate.p95_oklab_error > baseline.p95_oklab_error * 1.04 + 0.0005 {
        failures.push("P95 OKLab error exceeded +4%/+0.0005");
    }
    if candidate.edge_weighted_mean_oklab_error
        > baseline.edge_weighted_mean_oklab_error * 1.03 + 0.0003
    {
        failures.push("edge-weighted OKLab error exceeded +3%/+0.0003");
    }
    if candidate.multiscale_low_frequency_oklab_error
        > baseline.multiscale_low_frequency_oklab_error * 1.03 + 0.0003
    {
        failures.push("multiscale low-frequency OKLab error exceeded +3%/+0.0003");
    }
    if candidate.edge_gradient_error > baseline.edge_gradient_error * 1.03 + 0.0005 {
        failures.push("edge-gradient error exceeded +3%/+0.0005");
    }
    if candidate.static_temporal_residual > baseline.static_temporal_residual * 1.02 + 0.0001 {
        failures.push("static temporal residual exceeded +2%/+0.0001");
    }
    if candidate.multiscale_static_temporal_residual
        > baseline.multiscale_static_temporal_residual * 1.02 + 0.0001
    {
        failures.push("multiscale static temporal residual exceeded +2%/+0.0001");
    }
    if candidate_bytes > baseline_bytes.saturating_mul(120).div_ceil(100) {
        failures.push("serialized bytes exceeded +20%");
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

fn motion_delivery_content_signal(report: &PerceptualReport) -> MotionDeliveryContentSignalReport {
    let matched = report.focus == "motion"
        && report.mean_motion >= 0.005
        && report.mean_motion <= 0.030
        && report.mean_changed_area <= 0.200
        && (0.120..=0.280).contains(&report.mean_edge_text)
        && (0.020..=0.080).contains(&report.mean_noise)
        && report.mean_smooth_gradient_ratio >= 0.300
        && report.mean_skin_ratio >= 0.060;
    MotionDeliveryContentSignalReport {
        signal_id: "natural_subject_gradient_motion_v1".to_string(),
        selection_role: "diagnostic_only".to_string(),
        matched,
        mean_motion: report.mean_motion,
        mean_changed_area: report.mean_changed_area,
        mean_edge_text: report.mean_edge_text,
        mean_noise: report.mean_noise,
        mean_smooth_gradient_ratio: report.mean_smooth_gradient_ratio,
        mean_skin_ratio: report.mean_skin_ratio,
    }
}

fn best_delivery_gate_profile(
    content_profile: ContentProfile,
    report: Option<&PerceptualReport>,
) -> BestDeliveryGateProfile {
    let Some(report) = report else {
        return BestDeliveryGateProfile::General;
    };
    if report.focus == "text_ui" || report.structured_ui_mapper_candidate {
        BestDeliveryGateProfile::TextUi
    } else if report.mean_smooth_gradient_ratio >= 0.18
        && report.mean_edge_text <= 0.12
        && report.mean_noise <= 0.08
    {
        BestDeliveryGateProfile::SmoothGradient
    } else if report.mean_noise >= 0.12 {
        BestDeliveryGateProfile::Noisy
    } else if report.focus == "subject" {
        BestDeliveryGateProfile::Subject
    } else if content_profile == ContentProfile::StaticOrSmallChanges
        && (report.mean_changed_area <= 0.08 || report.mean_motion <= 0.012)
    {
        BestDeliveryGateProfile::Static
    } else {
        BestDeliveryGateProfile::General
    }
}

fn prefer_smooth_gradient_quality_floor(
    content_profile: ContentProfile,
    report: &PerceptualReport,
) -> bool {
    !report.static_gradient_writer_recommended
        && best_delivery_gate_profile(content_profile, Some(report))
            == BestDeliveryGateProfile::SmoothGradient
}

fn quick_probe_prefers_smooth_gradient_quality_floor(
    content_profile: ContentProfile,
    probe: &QuickContentProbe,
) -> bool {
    content_profile == ContentProfile::StableFullFrameMotion
        && probe.sampled_frames >= 4
        && probe.scene_cut_times.is_empty()
        && probe.scene_cut_ratio <= 0.01
        && probe.mean_changed_area >= 0.45
        && probe.mean_smooth_gradient_ratio >= 0.35
        && probe.mean_spatial_edge_ratio <= 0.08
        && probe.mean_spatial_noise <= 0.06
}

fn smooth_gradient_frame_palette_is_affordable(request: &GifRequest) -> bool {
    let source_duration = request.end_seconds - request.start_seconds.max(0.0);
    if !source_duration.is_finite() || source_duration <= 0.0 {
        return false;
    }
    let playback_duration = source_duration / request.playback_speed.clamp(1.0, 3.0);
    let estimated_frames = (playback_duration * f64::from(request.fps.clamp(1, 60))).ceil();
    if !estimated_frames.is_finite() || estimated_frames <= 0.0 || estimated_frames > 120.0 {
        return false;
    }
    let width = u64::from(request.width.clamp(96, 1920));
    let work = width
        .saturating_mul(width)
        .saturating_mul(estimated_frames as u64);
    width <= 480 && work <= 12_000_000
}

fn best_delivery_gate_policy(profile: BestDeliveryGateProfile) -> BestDeliveryGatePolicy {
    match profile {
        BestDeliveryGateProfile::TextUi => BestDeliveryGatePolicy {
            mean_ratio: 1.05,
            mean_allowance: 0.0005,
            static_ratio: 1.05,
            static_allowance: 0.0005,
            edge_ratio: 1.05,
            edge_allowance: 0.0004,
            temporal_ratio: 1.12,
            temporal_allowance: 0.00008,
            max_size_percent: 110,
        },
        BestDeliveryGateProfile::SmoothGradient => BestDeliveryGatePolicy {
            mean_ratio: 1.08,
            mean_allowance: 0.0008,
            static_ratio: 1.08,
            static_allowance: 0.0008,
            edge_ratio: 1.10,
            edge_allowance: 0.001,
            temporal_ratio: 1.20,
            temporal_allowance: 0.00015,
            max_size_percent: 112,
        },
        BestDeliveryGateProfile::Noisy => BestDeliveryGatePolicy {
            mean_ratio: 1.02,
            mean_allowance: 0.0002,
            static_ratio: 1.02,
            static_allowance: 0.0002,
            edge_ratio: 1.03,
            edge_allowance: 0.0003,
            temporal_ratio: 1.08,
            temporal_allowance: 0.00005,
            max_size_percent: 105,
        },
        BestDeliveryGateProfile::Static => BestDeliveryGatePolicy {
            mean_ratio: 1.03,
            mean_allowance: 0.0003,
            static_ratio: 1.03,
            static_allowance: 0.0003,
            edge_ratio: 1.03,
            edge_allowance: 0.0003,
            temporal_ratio: 1.05,
            temporal_allowance: 0.00003,
            max_size_percent: 108,
        },
        BestDeliveryGateProfile::Subject => BestDeliveryGatePolicy {
            mean_ratio: 1.04,
            mean_allowance: 0.0004,
            static_ratio: 1.04,
            static_allowance: 0.0004,
            edge_ratio: 1.05,
            edge_allowance: 0.0005,
            temporal_ratio: 1.25,
            temporal_allowance: 0.00012,
            max_size_percent: 110,
        },
        BestDeliveryGateProfile::General => BestDeliveryGatePolicy {
            mean_ratio: 1.03,
            mean_allowance: 0.0003,
            static_ratio: 1.03,
            static_allowance: 0.0003,
            edge_ratio: 1.03,
            edge_allowance: 0.0003,
            temporal_ratio: 1.10,
            temporal_allowance: 0.00005,
            max_size_percent: 110,
        },
    }
}

fn best_delivery_baseline_mode(profile: BestDeliveryGateProfile) -> GifGenerationMode {
    if profile == BestDeliveryGateProfile::SmoothGradient {
        // Error diffusion is the stable quality floor for a Best export with
        // broad, low-noise gradients. Falling all the way back to the Fast
        // Bayer plan is exactly the failure mode this profile is meant to
        // avoid.
        GifGenerationMode::Best
    } else {
        GifGenerationMode::Fast
    }
}

fn default_indexed_writer_has_internal_pareto_evidence(report: &IndexedGifWriterReport) -> bool {
    if report.status != "encoded_default"
        || !report.decoded_pixel_parity_verified
        || !report.disposal_simulation_verified
    {
        return false;
    }
    let regional_verified = report
        .regional_quantizer_report
        .as_ref()
        .is_some_and(|candidate| candidate.status == "encoded" && candidate.quality_gate_passed);
    let mapper_verified = report
        .palette_mapper_selection_report
        .as_ref()
        .is_some_and(|candidate| candidate.quality_gate_passed);
    let segment_verified = report
        .segment_palette_report
        .as_ref()
        .is_some_and(|candidate| candidate.quality_gate_passed && candidate.selection_gate_passed);
    regional_verified || mapper_verified || segment_verified
}

fn best_delivery_selection_gate(
    profile: BestDeliveryGateProfile,
    candidate: &MotionPresentationMetricsReport,
    baseline: &MotionPresentationMetricsReport,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    let policy = best_delivery_gate_policy(profile);
    let mut failures: Vec<String> = Vec::new();
    if candidate.mean_oklab_error
        > baseline.mean_oklab_error * policy.mean_ratio + policy.mean_allowance
    {
        failures.push(format!(
            "presentation mean OKLab error {:.6} exceeded the {:.6} content-aware limit (baseline {:.6})",
            candidate.mean_oklab_error,
            baseline.mean_oklab_error * policy.mean_ratio + policy.mean_allowance,
            baseline.mean_oklab_error,
        ));
    }
    if candidate.static_region_oklab_error
        > baseline.static_region_oklab_error * policy.static_ratio + policy.static_allowance
    {
        failures.push(format!(
            "presentation static-region OKLab error {:.6} exceeded the {:.6} content-aware limit (baseline {:.6})",
            candidate.static_region_oklab_error,
            baseline.static_region_oklab_error * policy.static_ratio + policy.static_allowance,
            baseline.static_region_oklab_error,
        ));
    }
    if candidate.edge_error > baseline.edge_error * policy.edge_ratio + policy.edge_allowance {
        failures.push(format!(
            "presentation edge error {:.6} exceeded the {:.6} content-aware limit (baseline {:.6})",
            candidate.edge_error,
            baseline.edge_error * policy.edge_ratio + policy.edge_allowance,
            baseline.edge_error,
        ));
    }
    if candidate.static_region_temporal_residual
        > baseline.static_region_temporal_residual * policy.temporal_ratio
            + policy.temporal_allowance
    {
        failures.push(format!(
            "presentation static temporal residual {:.6} exceeded the {:.6} content-aware limit (baseline {:.6})",
            candidate.static_region_temporal_residual,
            baseline.static_region_temporal_residual * policy.temporal_ratio
                + policy.temporal_allowance,
            baseline.static_region_temporal_residual,
        ));
    }
    if candidate_bytes
        > baseline_bytes
            .saturating_mul(policy.max_size_percent)
            .div_ceil(100)
    {
        failures.push(format!(
            "serialized bytes {candidate_bytes} exceeded the content-aware ceiling {} (baseline {baseline_bytes})",
            baseline_bytes
                .saturating_mul(policy.max_size_percent)
                .div_ceil(100),
        ));
    }

    let material_quality_gain = candidate.mean_oklab_error + 0.0005
        < baseline.mean_oklab_error * 0.97
        || candidate.static_region_oklab_error + 0.0005 < baseline.static_region_oklab_error * 0.97
        || candidate.edge_error + 0.001 < baseline.edge_error * 0.96
        || candidate.static_region_temporal_residual + 0.00005
            < baseline.static_region_temporal_residual * 0.95;
    let material_size_gain =
        candidate_bytes.saturating_mul(100) <= baseline_bytes.saturating_mul(98);
    if !material_quality_gain && !material_size_gain {
        failures.push(
            "candidate produced no material presentation-quality or 2% byte gain".to_string(),
        );
    }

    if failures.is_empty() {
        Ok(())
    } else {
        Err(format!("{}: {}", profile.as_str(), failures.join("; ")))
    }
}

fn motion_presentation_selection_gate(
    candidate: &MotionPresentationMetricsReport,
    baseline: &MotionPresentationMetricsReport,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    let mut failures = Vec::new();
    if candidate.mean_oklab_error > baseline.mean_oklab_error * 1.01 + 0.0001 {
        failures.push("presentation mean OKLab error exceeded +1%/+0.0001");
    }
    if candidate.edge_error > baseline.edge_error * 1.02 + 0.0002 {
        failures.push("presentation edge error exceeded +2%/+0.0002");
    }
    if candidate.static_region_temporal_residual
        > baseline.static_region_temporal_residual * 1.10 + 0.00005
    {
        failures.push("presentation static temporal residual exceeded +10%/+0.00005");
    }
    if candidate_bytes > baseline_bytes.saturating_mul(110).div_ceil(100) {
        failures.push("serialized bytes exceeded +10%");
    }
    let material_gain = candidate.mean_oklab_error + 0.0005 < baseline.mean_oklab_error
        || candidate.edge_error + 0.001 < baseline.edge_error
        || candidate.static_region_temporal_residual + 0.00005
            < baseline.static_region_temporal_residual;
    if !material_gain {
        failures.push("neutral Bayer produced no material presentation-time quality gain");
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

fn has_material_quality_gain(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
) -> bool {
    candidate.mean_oklab_error + 0.0005 < baseline.mean_oklab_error * 0.97
        || candidate.multiscale_low_frequency_oklab_error + 0.0004
            < baseline.multiscale_low_frequency_oklab_error * 0.96
        || candidate.multiscale_banding_score + 0.0005 < baseline.multiscale_banding_score * 0.98
        || candidate.static_temporal_residual + 0.0002 < baseline.static_temporal_residual * 0.95
        || candidate.multiscale_static_temporal_residual + 0.00015
            < baseline.multiscale_static_temporal_residual * 0.95
}

/// Selects the full 256-color opaque palette only when the actual serialized
/// GIF is on the rate--distortion frontier against the 255-color transparent
/// delta baseline. A smaller file may be selected with equivalent quality;
/// a larger file needs a material quality gain and is capped at +3% bytes.
fn opaque_palette_reservation_selection_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_timing: &TimingAwareTemporalResidual,
    baseline_timing: &TimingAwareTemporalResidual,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    let mut failures = Vec::new();
    if let Err(reason) = timing_aware_temporal_nonregression_gate(candidate_timing, baseline_timing)
    {
        failures.push(reason);
    }
    if candidate.mean_oklab_error > baseline.mean_oklab_error * 1.01 + 0.0001 {
        failures
            .push("opaque 256-color candidate mean OKLab regressed beyond +1%/+0.0001".to_string());
    }
    if candidate.p95_oklab_error > baseline.p95_oklab_error * 1.01 + 0.0002 {
        failures
            .push("opaque 256-color candidate P95 OKLab regressed beyond +1%/+0.0002".to_string());
    }
    if candidate.edge_weighted_mean_oklab_error
        > baseline.edge_weighted_mean_oklab_error * 1.01 + 0.0001
    {
        failures.push("opaque 256-color candidate edge-weighted OKLab regressed".to_string());
    }
    if candidate.multiscale_low_frequency_oklab_error
        > baseline.multiscale_low_frequency_oklab_error * 1.01 + 0.0001
    {
        failures.push("opaque 256-color candidate low-frequency OKLab regressed".to_string());
    }
    if candidate.multiscale_banding_score > baseline.multiscale_banding_score * 1.01 + 0.0001 {
        failures.push("opaque 256-color candidate banding proxy regressed".to_string());
    }
    if candidate.edge_gradient_error > baseline.edge_gradient_error * 1.01 + 0.0002 {
        failures.push("opaque 256-color candidate edge-gradient error regressed".to_string());
    }

    let strictly_smaller = candidate_bytes < baseline_bytes;
    let material_quality_gain = has_material_quality_gain(candidate, baseline);
    if !strictly_smaller && !material_quality_gain {
        failures.push(
            "opaque 256-color candidate produced no Pareto gain (not smaller and no material quality gain)"
                .to_string(),
        );
    }
    if !strictly_smaller && candidate_bytes > baseline_bytes.saturating_mul(103).div_ceil(100) {
        failures.push("opaque 256-color candidate serialized bytes exceeded +3%".to_string());
    }

    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

#[cfg(test)]
fn segment_palette_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    regional_quantization_gate(candidate, baseline, candidate_bytes, baseline_bytes)?;
    segment_palette_pareto_gate(candidate, baseline, candidate_bytes, baseline_bytes)
}

fn segment_palette_pareto_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    if candidate_bytes >= baseline_bytes && !has_material_quality_gain(candidate, baseline) {
        return Err(
            "segment palette produced no Pareto gain (not smaller and no material quality gain)"
                .to_string(),
        );
    }
    Ok(())
}

fn temporal_quantizer_pareto_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_bytes: u64,
    baseline_bytes: u64,
    temporal_hold_count: u64,
) -> Result<(), String> {
    if temporal_hold_count == 0 {
        return Err("temporal candidate retained no previous-frame indices".to_string());
    }
    if candidate.static_temporal_residual > baseline.static_temporal_residual * 1.02 + 0.000_000_1 {
        return Err("temporal candidate regressed static residual beyond +2%".to_string());
    }
    if candidate.multiscale_static_temporal_residual
        > baseline.multiscale_static_temporal_residual * 1.02 + 0.000_000_1
    {
        return Err(
            "temporal candidate regressed multiscale static residual beyond +2%".to_string(),
        );
    }
    let temporal_gain = candidate.static_temporal_residual
        < baseline.static_temporal_residual * 0.95
        || candidate.multiscale_static_temporal_residual
            < baseline.multiscale_static_temporal_residual * 0.95;
    if candidate_bytes >= baseline_bytes && !temporal_gain {
        return Err(
            "temporal candidate produced neither smaller real bytes nor a 5% temporal gain"
                .to_string(),
        );
    }
    Ok(())
}

fn timing_aware_temporal_nonregression_gate(
    candidate: &TimingAwareTemporalResidual,
    baseline: &TimingAwareTemporalResidual,
) -> Result<(), String> {
    let mut failures = Vec::new();
    if candidate.sampled_static_transition_count != baseline.sampled_static_transition_count
        || candidate.sampled_multiscale_static_transition_count
            != baseline.sampled_multiscale_static_transition_count
    {
        failures.push("timing-aware temporal sample contracts did not match");
    }
    if candidate.weighted_static_temporal_residual
        > baseline.weighted_static_temporal_residual * 1.005 + 0.000_000_1
    {
        failures.push("VFR-weighted static residual exceeded +0.5%");
    }
    if candidate.weighted_multiscale_static_temporal_residual
        > baseline.weighted_multiscale_static_temporal_residual * 1.005 + 0.000_000_1
    {
        failures.push("VFR-weighted multiscale residual exceeded +0.5%");
    }
    match (
        candidate.loop_seam_static_temporal_residual,
        baseline.loop_seam_static_temporal_residual,
    ) {
        (Some(candidate_seam), Some(baseline_seam))
            if candidate_seam > baseline_seam * 1.005 + 0.000_000_1 =>
        {
            failures.push("infinite-loop seam static residual exceeded +0.5%");
        }
        (Some(_), None) | (None, Some(_)) => {
            failures.push("infinite-loop seam contracts did not match");
        }
        _ => {}
    }
    match (
        candidate.loop_seam_multiscale_static_temporal_residual,
        baseline.loop_seam_multiscale_static_temporal_residual,
    ) {
        (Some(candidate_seam), Some(baseline_seam))
            if candidate_seam > baseline_seam * 1.005 + 0.000_000_1 =>
        {
            failures.push("infinite-loop seam multiscale residual exceeded +0.5%");
        }
        (Some(_), None) | (None, Some(_)) => {
            failures.push("infinite-loop seam multiscale contracts did not match");
        }
        _ => {}
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

fn timing_aware_temporal_pareto_gate(
    candidate: &TimingAwareTemporalResidual,
    baseline: &TimingAwareTemporalResidual,
    candidate_bytes: u64,
    baseline_bytes: u64,
) -> Result<(), String> {
    timing_aware_temporal_nonregression_gate(candidate, baseline)?;
    let timing_gain = candidate.weighted_static_temporal_residual
        < baseline.weighted_static_temporal_residual * 0.95
        || candidate.weighted_multiscale_static_temporal_residual
            < baseline.weighted_multiscale_static_temporal_residual * 0.95;
    if candidate_bytes >= baseline_bytes && !timing_gain {
        Err(
            "temporal candidate produced neither smaller real bytes nor a 5% VFR-weighted gain"
                .to_string(),
        )
    } else {
        Ok(())
    }
}

fn temporal_final_ffmpeg_pareto_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_timing: &TimingAwareTemporalResidual,
    baseline_timing: &TimingAwareTemporalResidual,
    candidate_bytes: u64,
    baseline_bytes: u64,
    temporal_hold_count: u64,
) -> Result<(), String> {
    regional_quantization_gate(candidate, baseline, candidate_bytes, baseline_bytes)?;
    temporal_quantizer_pareto_gate(
        candidate,
        baseline,
        candidate_bytes,
        baseline_bytes,
        temporal_hold_count,
    )?;
    timing_aware_temporal_pareto_gate(
        candidate_timing,
        baseline_timing,
        candidate_bytes,
        baseline_bytes,
    )?;

    let mut failures = Vec::new();
    if candidate.mean_oklab_error > baseline.mean_oklab_error * 1.01 + 0.0001 {
        failures.push("final FFmpeg Pareto gate: mean OKLab regressed beyond +1%/+0.0001");
    }
    if candidate.p95_oklab_error > baseline.p95_oklab_error * 1.01 + 0.0002 {
        failures.push("final FFmpeg Pareto gate: P95 OKLab regressed beyond +1%/+0.0002");
    }
    if candidate.edge_weighted_mean_oklab_error
        > baseline.edge_weighted_mean_oklab_error * 1.01 + 0.0001
    {
        failures.push("final FFmpeg Pareto gate: edge-weighted OKLab regressed");
    }
    if candidate.multiscale_low_frequency_oklab_error
        > baseline.multiscale_low_frequency_oklab_error * 1.01 + 0.0001
    {
        failures.push("final FFmpeg Pareto gate: low-frequency OKLab regressed");
    }
    if candidate.multiscale_banding_score > baseline.multiscale_banding_score * 1.01 + 0.0001 {
        failures.push("final FFmpeg Pareto gate: banding proxy regressed");
    }
    if candidate.edge_gradient_error > baseline.edge_gradient_error * 1.01 + 0.0002 {
        failures.push("final FFmpeg Pareto gate: edge-gradient error regressed");
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

#[allow(clippy::too_many_arguments)]
fn error_diffusion_selection_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_timing: &TimingAwareTemporalResidual,
    baseline_timing: &TimingAwareTemporalResidual,
    candidate_bytes: u64,
    baseline_bytes: u64,
    gradient_eligible_pixel_count: u64,
    diffused_pixel_count: u64,
) -> Result<(), String> {
    let timing_failure =
        timing_aware_temporal_nonregression_gate(candidate_timing, baseline_timing).err();
    let mut failures: Vec<String> = Vec::new();
    if let Err(reason) =
        regional_quantization_gate(candidate, baseline, candidate_bytes, baseline_bytes)
    {
        failures.push(format!(
            "regional quality gate rejected error diffusion: {reason}"
        ));
    }
    if gradient_eligible_pixel_count == 0 || diffused_pixel_count == 0 {
        failures.push(
            "error-diffusion candidate had no eligible gradient pixels or index changes"
                .to_string(),
        );
    }
    if candidate.mean_oklab_error > baseline.mean_oklab_error * 1.01 + 0.0001 {
        failures.push("error-diffusion mean OKLab regressed beyond +1%/+0.0001".to_string());
    }
    if candidate.p95_oklab_error > baseline.p95_oklab_error * 1.01 + 0.0002 {
        failures.push("error-diffusion P95 OKLab regressed beyond +1%/+0.0002".to_string());
    }
    if candidate.edge_weighted_mean_oklab_error
        > baseline.edge_weighted_mean_oklab_error * 1.01 + 0.0001
    {
        failures
            .push("error-diffusion edge-weighted OKLab regressed beyond +1%/+0.0001".to_string());
    }
    if candidate.multiscale_low_frequency_oklab_error
        > baseline.multiscale_low_frequency_oklab_error * 1.01 + 0.0001
    {
        failures
            .push("error-diffusion low-frequency OKLab regressed beyond +1%/+0.0001".to_string());
    }
    if candidate.multiscale_banding_score > baseline.multiscale_banding_score * 1.01 + 0.0001 {
        failures.push("error-diffusion banding proxy regressed".to_string());
    }
    if candidate.edge_gradient_error > baseline.edge_gradient_error * 1.01 + 0.0002 {
        failures
            .push("error-diffusion edge-gradient error regressed beyond +1%/+0.0002".to_string());
    }
    if candidate.static_temporal_residual > baseline.static_temporal_residual * 1.005 + 0.000_005 {
        failures
            .push("error-diffusion static temporal residual exceeded +0.5%/+0.000005".to_string());
    }
    if candidate.multiscale_static_temporal_residual
        > baseline.multiscale_static_temporal_residual * 1.005 + 0.000_005
    {
        failures.push(
            "error-diffusion multiscale temporal residual exceeded +0.5%/+0.000005".to_string(),
        );
    }
    if candidate_bytes > baseline_bytes.saturating_mul(105).div_ceil(100) {
        failures.push("error-diffusion serialized bytes exceeded +5%".to_string());
    }
    if let Some(reason) = timing_failure.as_deref() {
        failures.push(reason.to_string());
    }
    let banding_gain = baseline.multiscale_banding_score > 0.0001
        && candidate.multiscale_banding_score + 0.0001 < baseline.multiscale_banding_score * 0.92;
    if !banding_gain {
        failures.push("error-diffusion produced less than an 8% material banding gain".to_string());
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

#[allow(clippy::too_many_arguments)]
fn phase_locked_pair_selection_gate(
    candidate: &QuantizationMetrics,
    baseline: &QuantizationMetrics,
    candidate_timing: &TimingAwareTemporalResidual,
    baseline_timing: &TimingAwareTemporalResidual,
    candidate_bytes: u64,
    baseline_bytes: u64,
    diagnostics: &PhaseLockedPairDiagnostics,
) -> Result<(), String> {
    let mut failures = Vec::new();
    if diagnostics.protected_edge_index_change_count != 0 {
        failures.push("phase-locked pair changed protected edge pixels".to_string());
    }
    if diagnostics.ineligible_index_change_count != 0 {
        failures.push("phase-locked pair changed ineligible pixels".to_string());
    }
    if diagnostics.stored_frame_early_reject_count != 0 {
        failures.push("phase-locked pair stored-frame guard rejected the candidate".to_string());
    }
    if diagnostics.eligible_pixel_count == 0
        || diagnostics.changed_pixel_count == 0
        || diagnostics.pre_reject_changed_pixel_count == 0
    {
        failures.push("phase-locked pair produced no eligible stored index changes".to_string());
    }
    if let Err(reason) =
        regional_quantization_gate(candidate, baseline, candidate_bytes, baseline_bytes)
    {
        failures.push(format!(
            "regional quality gate rejected phase-locked pair: {reason}"
        ));
    }
    if candidate.mean_oklab_error > baseline.mean_oklab_error * 1.01 + 0.0001 {
        failures.push("phase-locked pair mean OKLab regressed beyond +1%/+0.0001".to_string());
    }
    if candidate.p95_oklab_error > baseline.p95_oklab_error * 1.01 + 0.0002 {
        failures.push("phase-locked pair P95 OKLab regressed beyond +1%/+0.0002".to_string());
    }
    if candidate.edge_weighted_mean_oklab_error
        > baseline.edge_weighted_mean_oklab_error * 1.01 + 0.0001
    {
        failures
            .push("phase-locked pair edge-weighted OKLab regressed beyond +1%/+0.0001".to_string());
    }
    if candidate.multiscale_low_frequency_oklab_error
        > baseline.multiscale_low_frequency_oklab_error * 1.01 + 0.0001
    {
        failures
            .push("phase-locked pair low-frequency OKLab regressed beyond +1%/+0.0001".to_string());
    }
    if candidate.multiscale_banding_score > baseline.multiscale_banding_score * 1.01 + 0.0001 {
        failures.push("phase-locked pair banding proxy regressed".to_string());
    }
    if candidate.edge_gradient_error > baseline.edge_gradient_error * 1.01 + 0.0002 {
        failures
            .push("phase-locked pair edge-gradient error regressed beyond +1%/+0.0002".to_string());
    }
    if candidate_bytes > baseline_bytes.saturating_mul(105).div_ceil(100) {
        failures.push("phase-locked pair serialized bytes exceeded +5%".to_string());
    }
    if let Err(reason) = timing_aware_temporal_nonregression_gate(candidate_timing, baseline_timing)
    {
        failures.push(reason);
    }

    let banding_gain = baseline.multiscale_banding_score > 0.0001
        && candidate.multiscale_banding_score + 0.0001 < baseline.multiscale_banding_score * 0.92;
    let vfr_gain = (baseline_timing.weighted_static_temporal_residual > 0.000_000_1
        && candidate_timing.weighted_static_temporal_residual + 0.000_000_1
            < baseline_timing.weighted_static_temporal_residual * 0.95)
        || (baseline_timing.weighted_multiscale_static_temporal_residual > 0.000_000_1
            && candidate_timing.weighted_multiscale_static_temporal_residual + 0.000_000_1
                < baseline_timing.weighted_multiscale_static_temporal_residual * 0.95);
    let loop_gain = match (
        candidate_timing.loop_seam_static_temporal_residual,
        baseline_timing.loop_seam_static_temporal_residual,
    ) {
        (Some(candidate), Some(baseline)) if baseline > 0.000_000_1 => {
            candidate + 0.000_000_1 < baseline * 0.95
        }
        _ => false,
    } || match (
        candidate_timing.loop_seam_multiscale_static_temporal_residual,
        baseline_timing.loop_seam_multiscale_static_temporal_residual,
    ) {
        (Some(candidate), Some(baseline)) if baseline > 0.000_000_1 => {
            candidate + 0.000_000_1 < baseline * 0.95
        }
        _ => false,
    };
    let byte_gain = candidate_bytes <= baseline_bytes.saturating_mul(95) / 100;
    if !banding_gain && !vfr_gain && !loop_gain && !byte_gain {
        failures.push(
            "phase-locked pair produced no material gain (8% banding, 5% temporal/loop, or 5% real bytes)"
                .to_string(),
        );
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

const ERROR_DIFFUSION_SPATIAL_KERNEL_ID: &str =
    "oklab_hybrid_coherent_edge_protected_serpentine_fs_temporal_v5";
const PHASE_LOCKED_PAIR_SPATIAL_KERNEL_ID: &str = "oklab_phase_locked_bracketing_pair_temporal_v1";

#[derive(Clone, Debug)]
struct RegionalQuantizerInputContractHashes {
    source_rgb24_sha256: String,
    palette_sha256: String,
    region_dither_sha256: String,
    frame_delays_sha256: String,
    fallback_route_id: String,
    fallback_indices_sha256: String,
    kernel_config_sha256: String,
    input_contract_sha256: String,
}

fn update_sha256_length_prefixed(hasher: &mut Sha256, value: &[u8]) {
    hasher.update(u64::try_from(value.len()).unwrap_or(u64::MAX).to_le_bytes());
    hasher.update(value);
}

#[allow(clippy::too_many_arguments)]
fn regional_quantizer_input_contract_hashes(
    source_rgb24: &[u8],
    width: u16,
    height: u16,
    palette_sha256: &str,
    region_dither_sha256: &str,
    frame_delays_cs: &[u16],
    repeat: IndexedGifRepeat,
    spatial_kernel_id: &str,
    kernel_config_sha256: &str,
    temporal_policy: TemporalHysteresisPolicy,
    fallback_indices: &[u8],
    fallback_route_id: &str,
) -> RegionalQuantizerInputContractHashes {
    let source_rgb24_sha256 = format!("{:x}", Sha256::digest(source_rgb24));
    let mut delays_hasher = Sha256::new();
    delays_hasher.update(b"gifp.regional-quantizer.frame-delays.v1\0");
    delays_hasher.update((frame_delays_cs.len() as u64).to_le_bytes());
    for delay_cs in frame_delays_cs {
        delays_hasher.update(delay_cs.to_le_bytes());
    }
    let frame_delays_sha256 = format!("{:x}", delays_hasher.finalize());

    let fallback_indices_sha256 = format!("{:x}", Sha256::digest(fallback_indices));
    let mut contract_hasher = Sha256::new();
    contract_hasher.update(b"gifp.regional-quantizer.input-contract.v4\0");
    contract_hasher.update(width.to_le_bytes());
    contract_hasher.update(height.to_le_bytes());
    contract_hasher.update([match repeat {
        IndexedGifRepeat::None => 0,
        IndexedGifRepeat::Infinite => 1,
    }]);
    contract_hasher.update([temporal_policy.max_hold_frames]);
    contract_hasher.update(temporal_policy.max_hold_duration_cs.to_le_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, spatial_kernel_id.as_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, kernel_config_sha256.as_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, source_rgb24_sha256.as_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, palette_sha256.as_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, region_dither_sha256.as_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, frame_delays_sha256.as_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, fallback_route_id.as_bytes());
    update_sha256_length_prefixed(&mut contract_hasher, fallback_indices_sha256.as_bytes());
    let input_contract_sha256 = format!("{:x}", contract_hasher.finalize());

    RegionalQuantizerInputContractHashes {
        source_rgb24_sha256,
        palette_sha256: palette_sha256.to_string(),
        region_dither_sha256: region_dither_sha256.to_string(),
        frame_delays_sha256,
        fallback_route_id: fallback_route_id.to_string(),
        fallback_indices_sha256,
        kernel_config_sha256: kernel_config_sha256.to_string(),
        input_contract_sha256,
    }
}

fn error_diffusion_candidate_report(
    report: &RegionalQuantizationReport,
    timing: &TimingAwareTemporalResidual,
    candidate: &SerializedIndexedCandidate,
) -> Result<ErrorDiffusionCandidateReport, AppError> {
    let diagnostics = report.error_diffusion.as_ref().ok_or_else(|| {
        AppError::Internal("Error-diffusion artifact omitted kernel diagnostics".to_string())
    })?;
    Ok(ErrorDiffusionCandidateReport {
        spatial_kernel_id: report.spatial_kernel_id.clone(),
        kernel_config_sha256: diagnostics.kernel_config_sha256.clone(),
        fallback_route_id: diagnostics.fallback_route_id.clone(),
        fallback_indices_sha256: diagnostics.fallback_indices_sha256.clone(),
        gradient_eligibility_mask_sha256: diagnostics.gradient_eligibility_mask_sha256.clone(),
        edge_protection_mask_sha256: diagnostics.edge_protection_mask_sha256.clone(),
        max_hold_frames: report.temporal_policy_max_hold_frames,
        max_hold_duration_cs: report.temporal_policy_max_hold_duration_cs,
        metrics: (&report.metrics).into(),
        timing_metrics: timing.into(),
        serialized_bytes: u64::try_from(candidate.bytes.len()).map_err(|_| {
            AppError::Internal("Error-diffusion candidate byte count overflow".to_string())
        })?,
        indices_sha256: report.indices_sha256.clone(),
        reconstructed_rgb24_sha256: report.reconstructed_rgb24_sha256.clone(),
        artifact_sha256: report.artifact_sha256.clone(),
        indexed_timeline_sha256: candidate.write_report.indexed_timeline_sha256.clone(),
        serialized_gif_sha256: format!("{:x}", Sha256::digest(&candidate.bytes)),
        direct_gradient_eligible_cell_count: diagnostics.direct_gradient_eligible_cell_count,
        coherence_rescued_cell_count: diagnostics.coherence_rescued_cell_count,
        coherence_rescued_pixel_count: diagnostics.coherence_rescued_pixel_count,
        pre_protection_gradient_pixel_count: diagnostics.pre_protection_gradient_pixel_count,
        gradient_eligible_pixel_count: diagnostics.gradient_eligible_pixel_count,
        protected_edge_seed_pixel_count: diagnostics.protected_edge_seed_pixel_count,
        protected_edge_halo_pixel_count: diagnostics.protected_edge_halo_pixel_count,
        protected_edge_fallback_pixel_count: diagnostics.protected_edge_fallback_pixel_count,
        protected_edge_index_change_count: diagnostics.protected_edge_index_change_count,
        diffused_pixel_count: diagnostics.diffused_pixel_count,
        diffused_pixel_by_class: diagnostics.diffused_pixel_by_class,
        residual_clamp_count: diagnostics.residual_clamp_count,
        cell_reset_count: diagnostics.cell_reset_count,
        fallback_preserved_pixel_count: diagnostics.fallback_preserved_pixel_count,
        eligible_index_change_count: diagnostics.eligible_index_change_count,
        ineligible_index_change_count: diagnostics.ineligible_index_change_count,
        eligible_index_change_rate: diagnostics.eligible_index_change_rate,
        frame_error_buffer_reset_count: diagnostics.frame_error_buffer_reset_count,
        residual_link_candidate_count: diagnostics.residual_link_candidate_count,
        full_conductance_residual_link_count: diagnostics.full_conductance_residual_link_count,
        cross_cell_candidate_link_count: diagnostics.cross_cell_candidate_link_count,
        cross_cell_propagated_link_count: diagnostics.cross_cell_propagated_link_count,
        cross_cell_rejected_class_count: diagnostics.cross_cell_rejected_class_count,
        cross_cell_rejected_eligibility_count: diagnostics.cross_cell_rejected_eligibility_count,
        cross_cell_rejected_protection_count: diagnostics.cross_cell_rejected_protection_count,
        cross_cell_blocked_hard_edge_count: diagnostics.cross_cell_blocked_hard_edge_count,
        protected_target_link_count: diagnostics.protected_target_link_count,
        edge_guarded_pixel_count: diagnostics.edge_guarded_pixel_count,
        attenuated_residual_link_count: diagnostics.attenuated_residual_link_count,
        blocked_residual_link_count: diagnostics.blocked_residual_link_count,
        temporal_regularized_hold_count: diagnostics.temporal_regularized_hold_count,
        temporal_prev_candidate_count: diagnostics.temporal_prev_candidate_count,
        temporal_prev_rejected_by_color_count: diagnostics.temporal_prev_rejected_by_color_count,
        temporal_prev_rejected_by_budget_count: diagnostics.temporal_prev_rejected_by_budget_count,
        temporal_prev_rejected_by_regularizer_count: diagnostics
            .temporal_prev_rejected_by_regularizer_count,
        temporal_vfr_single_frame_extension_count: diagnostics
            .temporal_vfr_single_frame_extension_count,
        loop_seeded_pixel_count: diagnostics.loop_seeded_pixel_count,
        static_index_flip_count: diagnostics.static_index_flip_count,
        vfr_weighted_static_index_flip_rate: diagnostics.vfr_weighted_static_index_flip_rate,
        temporal_hold_count: report.temporal_hold_count,
        temporal_hold_by_class: report.temporal_hold_by_class,
        temporal_hold_duration_cs: report.temporal_hold_duration_cs,
        temporal_max_observed_hold_duration_cs: report.temporal_max_observed_hold_duration_cs,
    })
}

fn validate_phase_locked_pair_pre_serialization(
    report: &RegionalQuantizationReport,
    diagnostics: &PhaseLockedPairDiagnostics,
    input_contract: &RegionalQuantizerInputContractHashes,
    ffmpeg_baseline_metrics: &QuantizationMetrics,
) -> Result<(), String> {
    let mut failures = Vec::new();
    if report.spatial_kernel_id != PHASE_LOCKED_PAIR_SPATIAL_KERNEL_ID
        || diagnostics.kernel_config_sha256 != input_contract.kernel_config_sha256
        || diagnostics.fallback_route_id != input_contract.fallback_route_id
        || diagnostics.fallback_indices_sha256 != input_contract.fallback_indices_sha256
    {
        failures.push("phase-locked pair kernel or fallback identity drifted".to_string());
    }
    if diagnostics.protected_edge_index_change_count != 0 {
        failures.push("phase-locked pair changed protected edge pixels".to_string());
    }
    if diagnostics.ineligible_index_change_count != 0 {
        failures.push("phase-locked pair changed ineligible pixels".to_string());
    }
    if diagnostics.stored_frame_early_reject_count != 0 {
        failures.push("phase-locked pair stored-frame guard rejected the candidate".to_string());
    }
    if diagnostics.pre_reject_changed_pixel_count == 0
        || diagnostics.changed_pixel_count == 0
        || diagnostics.eligible_pixel_count == 0
    {
        failures.push("phase-locked pair produced no serializable index changes".to_string());
    }
    let same_metric = |left: f64, right: f64| (left - right).abs() <= 1.0e-12;
    if !same_metric(
        diagnostics.fallback_mean_oklab_error,
        ffmpeg_baseline_metrics.mean_oklab_error,
    ) || !same_metric(
        diagnostics.fallback_multiscale_banding_score,
        ffmpeg_baseline_metrics.multiscale_banding_score,
    ) {
        failures.push("phase-locked pair FFmpeg stored metrics drifted".to_string());
    }
    if !same_metric(
        diagnostics.candidate_mean_oklab_error,
        report.metrics.mean_oklab_error,
    ) || !same_metric(
        diagnostics.candidate_multiscale_banding_score,
        report.metrics.multiscale_banding_score,
    ) {
        failures.push("phase-locked pair candidate stored metrics drifted".to_string());
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

fn phase_locked_pair_candidate_report(
    report: &RegionalQuantizationReport,
    timing: &TimingAwareTemporalResidual,
    candidate: Option<&SerializedIndexedCandidate>,
) -> Result<PhaseLockedPairCandidateReport, AppError> {
    let diagnostics = report.phase_locked_pair.as_ref().ok_or_else(|| {
        AppError::Internal("Phase-locked pair artifact omitted kernel diagnostics".to_string())
    })?;
    let serialized_bytes = candidate
        .map(|candidate| u64::try_from(candidate.bytes.len()))
        .transpose()
        .map_err(|_| {
            AppError::Internal("Phase-locked pair candidate byte count overflow".to_string())
        })?;
    Ok(PhaseLockedPairCandidateReport {
        spatial_kernel_id: report.spatial_kernel_id.clone(),
        kernel_config_sha256: diagnostics.kernel_config_sha256.clone(),
        fallback_route_id: diagnostics.fallback_route_id.clone(),
        fallback_indices_sha256: diagnostics.fallback_indices_sha256.clone(),
        pair_lookup_sha256: diagnostics.pair_lookup_sha256.clone(),
        eligibility_mask_sha256: diagnostics.eligibility_mask_sha256.clone(),
        edge_protection_mask_sha256: diagnostics.edge_protection_mask_sha256.clone(),
        max_hold_frames: report.temporal_policy_max_hold_frames,
        max_hold_duration_cs: report.temporal_policy_max_hold_duration_cs,
        metrics: (&report.metrics).into(),
        timing_metrics: timing.into(),
        serialized_bytes,
        indices_sha256: report.indices_sha256.clone(),
        reconstructed_rgb24_sha256: report.reconstructed_rgb24_sha256.clone(),
        artifact_sha256: report.artifact_sha256.clone(),
        indexed_timeline_sha256: candidate
            .map(|candidate| candidate.write_report.indexed_timeline_sha256.clone()),
        serialized_gif_sha256: candidate
            .map(|candidate| format!("{:x}", Sha256::digest(&candidate.bytes))),
        opaque_fallback_pixel_count: diagnostics.opaque_fallback_pixel_count,
        transparent_fallback_pixel_count: diagnostics.transparent_fallback_pixel_count,
        smooth_region_pixel_count: diagnostics.smooth_region_pixel_count,
        protected_edge_pixel_count: diagnostics.protected_edge_pixel_count,
        non_micro_change_fallback_pixel_count: diagnostics.non_micro_change_fallback_pixel_count,
        scene_cut_fallback_pixel_count: diagnostics.scene_cut_fallback_pixel_count,
        no_bracketing_pair_fallback_pixel_count: diagnostics
            .no_bracketing_pair_fallback_pixel_count,
        eligible_pixel_count: diagnostics.eligible_pixel_count,
        paired_pixel_count: diagnostics.paired_pixel_count,
        pair_candidate_count: diagnostics.pair_candidate_count,
        changed_pixel_count: diagnostics.changed_pixel_count,
        changed_pixel_by_class: diagnostics.changed_pixel_by_class,
        fallback_preserved_pixel_count: diagnostics.fallback_preserved_pixel_count,
        protected_edge_index_change_count: diagnostics.protected_edge_index_change_count,
        ineligible_index_change_count: diagnostics.ineligible_index_change_count,
        skin_pair_hue_rejection_count: diagnostics.skin_pair_hue_rejection_count,
        skin_pair_chroma_rejection_count: diagnostics.skin_pair_chroma_rejection_count,
        temporal_candidate_count: diagnostics.temporal_candidate_count,
        temporal_hold_count: diagnostics.temporal_hold_count,
        temporal_hold_by_class: diagnostics.temporal_hold_by_class,
        temporal_hold_duration_cs: diagnostics.temporal_hold_duration_cs,
        temporal_max_observed_hold_duration_cs: diagnostics.temporal_max_observed_hold_duration_cs,
        temporal_rejected_by_pair_count: diagnostics.temporal_rejected_by_pair_count,
        temporal_rejected_by_color_count: diagnostics.temporal_rejected_by_color_count,
        temporal_rejected_by_budget_count: diagnostics.temporal_rejected_by_budget_count,
        cut_reset_pixel_count: diagnostics.cut_reset_pixel_count,
        loop_seeded_pixel_count: diagnostics.loop_seeded_pixel_count,
        fallback_static_index_flip_count: diagnostics.fallback_static_index_flip_count,
        static_index_flip_count: diagnostics.static_index_flip_count,
        fallback_vfr_weighted_static_index_flip_rate: diagnostics
            .fallback_vfr_weighted_static_index_flip_rate,
        vfr_weighted_static_index_flip_rate: diagnostics.vfr_weighted_static_index_flip_rate,
        fallback_loop_seam_static_index_flip_count: diagnostics
            .fallback_loop_seam_static_index_flip_count,
        loop_seam_static_index_flip_count: diagnostics.loop_seam_static_index_flip_count,
        stored_frame_early_reject_count: diagnostics.stored_frame_early_reject_count,
        pre_reject_changed_pixel_count: diagnostics.pre_reject_changed_pixel_count,
        pre_reject_temporal_hold_count: diagnostics.pre_reject_temporal_hold_count,
        fallback_mean_oklab_error: diagnostics.fallback_mean_oklab_error,
        candidate_mean_oklab_error: diagnostics.candidate_mean_oklab_error,
        fallback_multiscale_banding_score: diagnostics.fallback_multiscale_banding_score,
        candidate_multiscale_banding_score: diagnostics.candidate_multiscale_banding_score,
    })
}

const fn segment_palette_status(
    quality_gate_passed: bool,
    selection_gate_passed: bool,
) -> &'static str {
    if selection_gate_passed {
        "encoded"
    } else if quality_gate_passed {
        "selection_gate_rejected"
    } else {
        "quality_gate_rejected"
    }
}

