#[cfg(not(any(unix, windows)))]
fn install_new_file_without_overwrite(staged: &Path, output: &Path) -> io::Result<()> {
    fs::rename(staged, output)
}

#[cfg(windows)]
fn install_new_directory_without_overwrite(staged: &Path, output: &Path) -> io::Result<()> {
    use std::os::windows::ffi::OsStrExt;
    use windows_sys::Win32::Storage::FileSystem::{MoveFileExW, MOVEFILE_WRITE_THROUGH};

    let staged = fs::canonicalize(staged)?;
    let output_parent = output
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let output_name = output.file_name().ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "output path has no file name")
    })?;
    let output = fs::canonicalize(output_parent)?.join(output_name);
    let staged_wide = staged
        .as_os_str()
        .encode_wide()
        .chain(std::iter::once(0))
        .collect::<Vec<_>>();
    let output_wide = output
        .as_os_str()
        .encode_wide()
        .chain(std::iter::once(0))
        .collect::<Vec<_>>();
    let moved = unsafe {
        MoveFileExW(
            staged_wide.as_ptr(),
            output_wide.as_ptr(),
            MOVEFILE_WRITE_THROUGH,
        )
    };
    if moved == 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(())
    }
}

#[cfg(any(target_os = "linux", target_os = "android"))]
fn install_new_directory_without_overwrite(staged: &Path, output: &Path) -> io::Result<()> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;

    let staged_c = CString::new(staged.as_os_str().as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "staged path contains NUL"))?;
    let output_c = CString::new(output.as_os_str().as_bytes())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "output path contains NUL"))?;
    let renamed = unsafe {
        libc::renameat2(
            libc::AT_FDCWD,
            staged_c.as_ptr(),
            libc::AT_FDCWD,
            output_c.as_ptr(),
            libc::RENAME_NOREPLACE,
        )
    };
    if renamed == 0 {
        return Ok(());
    }
    let error = io::Error::last_os_error();
    let unsupported = error
        .raw_os_error()
        .is_some_and(|code| [libc::ENOSYS, libc::EINVAL, libc::EOPNOTSUPP].contains(&code));
    if unsupported {
        Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "the output filesystem does not support atomic no-replace directory publication",
        ))
    } else {
        Err(error)
    }
}

