    #[test]
    fn adaptive_scheduler_preserves_temporal_fidelity_by_content_class() {
        let motion = PerceptualSummary {
            mean_motion: 0.011,
            mean_changed_area: 0.078,
            mean_subject_saliency: 0.90,
            ..PerceptualSummary::default()
        };
        let motion_config = perceptual_scheduler_config(PerceptualFocus::Auto, motion, 0.61, 20);
        assert_eq!(
            motion.resolve_focus(PerceptualFocus::Auto),
            PerceptualFocus::Motion
        );
        assert_eq!(motion_config.retention_ratio, 1.0);
        assert_eq!(motion_config.duplicate_motion_threshold, 0.003);
        assert_eq!(motion_config.low_value_threshold, 0.035);
        assert!(motion_config.fill_target_with_subtle_changes);

        let low_activity_motion = PerceptualSummary {
            mean_motion: 0.0065,
            mean_changed_area: 0.0496,
            mean_edge_text: 0.326,
            mean_noise: 0.055,
            ..PerceptualSummary::default()
        };
        let low_activity_config =
            perceptual_scheduler_config(PerceptualFocus::Auto, low_activity_motion, 0.61, 20);
        assert_eq!(low_activity_config.retention_ratio, 0.82);
        assert!(!low_activity_config.fill_target_with_subtle_changes);

        let noisy_motion = PerceptualSummary {
            mean_changed_area: 0.069,
            mean_noise: 0.055,
            ..motion
        };
        assert!(neutral_motion_filter_recommended(
            PerceptualFocus::Motion,
            noisy_motion
        ));
        assert!(!neutral_motion_filter_recommended(
            PerceptualFocus::Motion,
            motion
        ));

        let scrolling_ui = PerceptualSummary {
            mean_motion: 0.0025,
            mean_changed_area: 0.014,
            mean_edge_text: 0.31,
            mean_noise: 0.04,
            mean_subject_saliency: 1.0,
            ..PerceptualSummary::default()
        };
        let ui_config = perceptual_scheduler_config(PerceptualFocus::Auto, scrolling_ui, 0.61, 20);
        assert_eq!(
            scrolling_ui.resolve_focus(PerceptualFocus::Auto),
            PerceptualFocus::TextUi
        );
        assert_eq!(ui_config.retention_ratio, 1.0);
        assert!(ffmpeg_palette_recommended(
            PerceptualFocus::TextUi,
            scrolling_ui
        ));
        assert!(!ffmpeg_palette_recommended(
            PerceptualFocus::Subject,
            scrolling_ui
        ));

        let static_subject = PerceptualSummary {
            mean_changed_area: 0.002,
            mean_subject_saliency: 0.90,
            mean_skin_ratio: 0.12,
            ..PerceptualSummary::default()
        };
        let subject_config =
            perceptual_scheduler_config(PerceptualFocus::Auto, static_subject, 0.61, 20);
        assert!((subject_config.retention_ratio - 0.59).abs() < f32::EPSILON);
        assert_eq!(subject_config.duplicate_motion_threshold, 0.012);
        assert!(!ffmpeg_palette_recommended(
            PerceptualFocus::Subject,
            static_subject
        ));
        assert!(perceptual_color_eq_recommended(PerceptualFocus::Motion));
        assert!(!perceptual_color_eq_recommended(PerceptualFocus::Subject));
        assert!(!perceptual_color_eq_recommended(PerceptualFocus::TextUi));
        assert!(!perceptual_color_eq_recommended(PerceptualFocus::FlatArt));

        let banded_gradient = PerceptualSummary {
            mean_motion: 0.00014,
            mean_changed_area: 0.0,
            mean_edge_text: 0.0025,
            mean_noise: 0.0066,
            ..PerceptualSummary::default()
        };
        assert_eq!(
            perceptual_bayer_dither_scale(PerceptualFocus::FlatArt, banded_gradient),
            Some(3)
        );
        assert_eq!(
            perceptual_bayer_dither_scale(
                PerceptualFocus::FlatArt,
                PerceptualSummary {
                    mean_motion: 0.00091,
                    ..banded_gradient
                }
            ),
            None
        );

        let slow_moving_gradient = PerceptualSummary {
            mean_motion: 0.0025,
            mean_changed_area: 0.007,
            mean_edge_text: 0.098,
            mean_noise: 0.022,
            mean_smooth_gradient_ratio: 0.47,
            ..PerceptualSummary::default()
        };
        assert!(perceptual_floyd_dither_recommended(
            PerceptualFocus::Auto,
            slow_moving_gradient
        ));
        assert!(!perceptual_floyd_dither_recommended(
            PerceptualFocus::Subject,
            slow_moving_gradient
        ));
        assert!(!perceptual_floyd_dither_recommended(
            PerceptualFocus::Auto,
            PerceptualSummary {
                mean_changed_area: 0.0,
                ..slow_moving_gradient
            }
        ));

        let mut request = request_with_speed(1.0);
        let smooth_gradient = PerceptualSummary {
            mean_smooth_gradient_ratio: 0.31,
            mean_noise: 0.02,
            ..PerceptualSummary::default()
        };
        assert!(static_gradient_writer_recommended(smooth_gradient));
        assert!(!static_gradient_writer_recommended(PerceptualSummary {
            mean_motion: 0.0002,
            ..smooth_gradient
        }));
        assert!(!static_gradient_writer_recommended(PerceptualSummary {
            mean_edge_text: 0.10,
            ..smooth_gradient
        }));
        let structured_ui = PerceptualSummary {
            mean_motion: 0.00068,
            mean_changed_area: 0.00199,
            mean_edge_text: 0.153,
            mean_noise: 0.033,
            mean_smooth_gradient_ratio: 0.46,
            mean_skin_ratio: 0.004,
            ..PerceptualSummary::default()
        };
        assert!(structured_ui_mapper_candidate(structured_ui));
        assert!(!structured_ui_mapper_candidate(PerceptualSummary {
            mean_skin_ratio: 0.08,
            ..structured_ui
        }));
        assert!(!structured_ui_mapper_candidate(PerceptualSummary {
            mean_smooth_gradient_ratio: 0.10,
            ..structured_ui
        }));
        assert!(!structured_ui_mapper_candidate(PerceptualSummary {
            mean_motion: 0.002,
            ..structured_ui
        }));
        assert_eq!(
            perceptual_palette_histogram_precision(&request, smooth_gradient, false, false),
            PaletteHistogramPrecision::Standard5Bit
        );
        assert_eq!(
            perceptual_palette_histogram_precision(&request, smooth_gradient, false, true),
            PaletteHistogramPrecision::Fine6Bit
        );
        request.allow_experimental = true;
        assert_eq!(
            perceptual_palette_histogram_precision(&request, smooth_gradient, false, false),
            PaletteHistogramPrecision::Fine6Bit
        );
        assert_eq!(
            perceptual_palette_histogram_precision(
                &request,
                PerceptualSummary {
                    mean_noise: 0.04,
                    ..smooth_gradient
                },
                false,
                false,
            ),
            PaletteHistogramPrecision::Standard5Bit
        );
        assert_eq!(
            perceptual_palette_histogram_precision(&request, smooth_gradient, true, true),
            PaletteHistogramPrecision::Standard5Bit
        );
    }

