    #[test]
    fn real_frame_page_matches_the_requested_output_frame_index() {
        let output_dir = isolated_smoke_dir("gifp-frame-page-smoke");
        fs::create_dir_all(&output_dir).expect("create frame-page smoke directory");
        let input = output_dir.join("source.mkv");
        let reference = output_dir.join("reference.jpg");
        let ffmpeg = locate_ffmpeg().expect("locate FFmpeg");
        let generated = Command::new(&ffmpeg)
            .arg("-y")
            .arg("-hide_banner")
            .arg("-loglevel")
            .arg("error")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("testsrc2=s=96x64:r=6:d=1")
            .arg("-c:v")
            .arg("ffv1")
            .arg(&input)
            .output_for_conversion_task()
            .expect("generate frame-page fixture");
        assert!(
            generated.status.success(),
            "{}",
            String::from_utf8_lossy(&generated.stderr)
        );

        let page = generate_frame_page_inner(FramePageRequest {
            input_path: input.to_string_lossy().to_string(),
            start_seconds: 0.0,
            end_seconds: 1.0,
            playback_speed: 2.0,
            fps: 3,
            page_start: 1,
            page_size: 1,
            max_width: 96,
        })
        .expect("extract the second real output frame");
        assert_eq!(page.total_frames, 2);
        assert_eq!(page.page_start, 1);
        assert_eq!(page.page_size, 1);
        assert_eq!(page.frames.len(), 1);
        assert_eq!(page.frames[0].index, 1);
        assert!((page.frames[0].time - (2.0 / 3.0)).abs() < 0.000_001);

        let reference_output = Command::new(&ffmpeg)
            .arg("-hide_banner")
            .arg("-loglevel")
            .arg("error")
            .arg("-i")
            .arg(&input)
            .arg("-t")
            .arg("1.000000")
            .arg("-an")
            .arg("-vf")
            .arg("setpts=PTS/2.000000,fps=fps=3:start_time=0:eof_action=pass,select='eq(n\\,1)',scale=96:-2:flags=lanczos,format=yuvj420p")
            .arg("-fps_mode")
            .arg("vfr")
            .arg("-frames:v")
            .arg("1")
            .arg("-q:v")
            .arg("4")
            .arg("-y")
            .arg(&reference)
            .output_for_conversion_task()
            .expect("extract direct reference frame");
        assert!(
            reference_output.status.success(),
            "{}",
            String::from_utf8_lossy(&reference_output.stderr)
        );
        assert_eq!(
            Sha256::digest(fs::read(&page.frames[0].path).expect("read frame-page image")),
            Sha256::digest(fs::read(&reference).expect("read direct reference image")),
            "frame editor page index must resolve to the same FFmpeg output frame used by deletion"
        );

        let frame_page_dir = Path::new(&page.frames[0].path)
            .parent()
            .expect("frame-page parent")
            .to_path_buf();
        let _ = fs::remove_dir_all(frame_page_dir);
        let _ = fs::remove_dir_all(output_dir);
    }

