    fn assert_real_output_quality_stamp(width: u32, height: u32) {
        let temp_scope = TestTempDirScope::begin();
        let output_dir = isolated_smoke_dir("gifp-quality-stamp-smoke");
        fs::create_dir_all(&output_dir).expect("create quality-stamp smoke directory");
        let input = output_dir.join("source.mkv");
        let ffmpeg = locate_ffmpeg().expect("locate FFmpeg");
        let generated = Command::new(&ffmpeg)
            .arg("-y")
            .arg("-hide_banner")
            .arg("-loglevel")
            .arg("error")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg(format!("testsrc2=s={width}x{height}:r=6:d=1"))
            .arg("-c:v")
            .arg("ffv1")
            .arg(&input)
            .output_for_conversion_task()
            .expect("generate quality-stamp fixture");
        assert!(
            generated.status.success(),
            "{}",
            String::from_utf8_lossy(&generated.stderr)
        );

        let mut encode_request = request_with_speed(1.0);
        encode_request.input_path = input.to_string_lossy().to_string();
        encode_request.output_dir = output_dir.to_string_lossy().to_string();
        encode_request.width = width;
        encode_request.fps = 6;
        encode_request.colors = 256;
        encode_request.end_seconds = 1.0;
        encode_request.generation_mode = "fast_gif".to_string();
        let result = convert_animation_inner(encode_request.clone()).expect("encode fixture GIF");
        let output_sha256_before = Sha256::digest(
            fs::read(&result.output_path).expect("read encoded output before quality scoring"),
        );
        let report = evaluate_output_quality_inner(OutputQualityRequest {
            encode_request,
            output_path: result.output_path.clone(),
        })
        .expect("score fixture GIF");

        assert_eq!(report.status, "measured", "{report:?}");
        assert!(report.vmaf_mean.is_some_and(|value| value > 0.0));
        assert!(report.ssim_mean.is_some_and(|value| value > 0.0));
        assert!(report.compared_frames > 0);
        let output_sha256_after = Sha256::digest(
            fs::read(&result.output_path).expect("read encoded output after quality scoring"),
        );
        assert_eq!(
            output_sha256_before, output_sha256_after,
            "quality scoring must never modify or stamp the exported media"
        );

        let _ = fs::remove_file(result.output_path);
        let _ = fs::remove_file(input);
        let _ = fs::remove_dir_all(output_dir);
        drop(temp_scope);
    }

