    #[test]
    fn perceptual_palette_sampling_reuses_the_final_color_transform_chain() {
        let mut request = request_with_speed(1.0);
        request.width = 512;
        request.filter_style = "vivid".to_string();
        request.perceptual_selection = Some(PerceptualSelection {
            keep_indices: vec![0, 2, 4],
            source_frame_count: 5,
            final_delay_cs: 7,
            frame_delays_cs: vec![7; 3],
            palette: None,
            structured_ui_standard_palette: None,
            palette_sequence: None,
            region_dither: None,
            color_eq_recommended: false,
            bayer_dither_scale: None,
            floyd_dither_recommended: false,
            structured_ui_mapper_candidate: false,
            neutral_filter_recommended: false,
        });

        let encoding = video_filter(&request, "pngquant_opt");
        let sampling = perceptual_palette_sample_filter(&request, "pngquant_opt");
        assert!(sampling.starts_with(&encoding), "{sampling}");
        assert!(
            encoding.contains("1.180*(val-(maxval+minval)/2)"),
            "{encoding}"
        );
        assert!(
            !encoding.contains("1.035*(val-(maxval+minval)/2)"),
            "{encoding}"
        );
        assert!(encoding.contains("bilateral=sigmaS=0.5"), "{encoding}");
        assert!(encoding.contains("atadenoise=0a=0.006"), "{encoding}");
        assert!(!encoding.contains("eq="), "{encoding}");
        assert!(!encoding.contains("hqdn3d="), "{encoding}");
        assert!(encoding.contains("select='not(eq(n\\,1)+eq(n\\,3))'"));
        assert!(sampling.ends_with("scale=128:128:flags=area,format=rgb24"));

        request
            .perceptual_selection
            .as_mut()
            .expect("perceptual selection")
            .color_eq_recommended = true;
        let motion_encoding = video_filter(&request, "pngquant_opt");
        assert!(
            motion_encoding.contains("1.035*(val-(maxval+minval)/2)"),
            "{motion_encoding}"
        );
    }

