    #[test]
    fn h264_arguments_are_encoder_specific() {
        let x264 = h264_encoder_args(
            FfmpegH264Encoder::Libx264,
            H264Usage::Delivery { lossy: 60 },
        );
        assert!(x264.windows(2).any(|pair| pair == ["-c:v", "libx264"]));
        assert!(x264.windows(2).any(|pair| pair == ["-preset", "medium"]));
        assert!(x264.windows(2).any(|pair| pair == ["-crf", "28"]));
        assert!(!x264.iter().any(|value| value == "-quality"));

        let media_foundation = h264_encoder_args(
            FfmpegH264Encoder::MediaFoundation,
            H264Usage::Delivery { lossy: 60 },
        );
        assert!(media_foundation
            .windows(2)
            .any(|pair| pair == ["-c:v", "h264_mf"]));
        assert!(media_foundation
            .windows(2)
            .any(|pair| pair == ["-rate_control", "quality"]));
        assert!(media_foundation
            .windows(2)
            .any(|pair| pair == ["-quality", "65"]));
        assert!(!media_foundation.iter().any(|value| value == "-crf"));

        let x264_recording = h264_encoder_args(
            FfmpegH264Encoder::Libx264,
            H264Usage::Recording {
                media_foundation_hardware: false,
            },
        );
        assert!(x264_recording
            .windows(2)
            .any(|pair| pair == ["-preset", "ultrafast"]));
        assert!(x264_recording.windows(2).any(|pair| pair == ["-crf", "18"]));

        let media_foundation_recording = h264_encoder_args(
            FfmpegH264Encoder::MediaFoundation,
            H264Usage::Recording {
                media_foundation_hardware: false,
            },
        );
        assert!(media_foundation_recording
            .windows(2)
            .any(|pair| pair == ["-quality", "88"]));
        assert!(media_foundation_recording
            .windows(2)
            .any(|pair| pair == ["-hw_encoding", "0"]));

        let media_foundation_hardware_recording = h264_encoder_args(
            FfmpegH264Encoder::MediaFoundation,
            H264Usage::Recording {
                media_foundation_hardware: true,
            },
        );
        assert!(media_foundation_hardware_recording
            .windows(2)
            .any(|pair| pair == ["-hw_encoding", "1"]));
    }

