    #[test]
    fn meme_overlay_builds_unicode_ass_and_runs_after_final_scale() {
        let mut request = request_with_speed(1.0);
        request.meme_overlay = Some(MemeOverlayRequest {
            top_text: "上方：先别急".to_string(),
            bottom_text: "下方\\路径 {安全}".to_string(),
            style: "classic".to_string(),
            font_size: 44,
            text_align: "center".to_string(),
            position: "split".to_string(),
            top_x: Some(18.0),
            top_y: Some(34.0),
            bottom_x: Some(75.0),
            bottom_y: Some(82.0),
            start_seconds: Some(1.25),
            end_seconds: Some(2.75),
            ass_path: None,
        });
        let output_dir = std::env::temp_dir();
        let prepared = prepare_meme_overlay(&output_dir, &mut request, (420, 236))
            .expect("prepare meme overlay")
            .expect("overlay file");
        assert!(prepared.path.is_file());
        let script = fs::read_to_string(&prepared.path).expect("read ASS overlay");
        assert!(script.contains("上方：先别急"), "{script}");
        assert!(script.contains(r"下方\\路径 \{安全\}"), "{script}");
        assert!(script.contains("PlayResX: 420"), "{script}");
        assert!(script.contains("PlayResY: 236"), "{script}");
        assert!(script.contains("0:00:01.25,0:00:02.75"), "{script}");
        assert!(script.contains("Style: Top,Microsoft YaHei,44"));
        assert!(script.contains(r"\pos(76,80)"), "{script}");
        assert!(script.contains(r"\pos(315,194)"), "{script}");

        let filter = video_filter(&request, "ffmpeg_fast");
        let scale = filter.find("scale=420").expect("scale filter");
        let ass = filter.find("ass=filename=").expect("ASS filter");
        let rgba = filter.rfind("format=rgba").expect("RGBA filter");
        assert!(scale < ass && ass < rgba, "{filter}");
        assert!(filter.contains(":alpha=1"), "{filter}");
        assert!(filter.contains(r"\:"), "{filter}");

        let path = prepared.path.clone();
        drop(prepared);
        assert!(!path.exists());
    }

