    #[test]
    #[ignore = "requires reviewed FFmpeg; writes a real three-caption set to GIFP_R1_OUTPUT"]
    fn meme_set_real_output_smoke() {
        let ffmpeg = locate_ffmpeg().expect("locate FFmpeg");
        let work = PathBuf::from(std::env::var_os("GIFP_R1_OUTPUT").expect("set GIFP_R1_OUTPUT"));
        fs::create_dir_all(&work).unwrap();
        let input = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../public/preset-previews/meme.gif")
            .canonicalize()
            .unwrap();
        let mut images = Vec::new();
        let mut results = Vec::new();
        for caption in ["收到！", "好耶", "让我想想"] {
            let mut request = request_with_speed(1.0);
            request.input_path = input.to_string_lossy().to_string();
            request.output_dir = work.to_string_lossy().to_string();
            request.width = 240;
            request.fps = 8;
            request.end_seconds = 1.0;
            request.colors = 128;
            request.encoder = "ffmpeg_fast".into();
            request.generation_mode = "fast_gif".into();
            request.filter_style = "none".into();
            request.meme_overlay = Some(MemeOverlayRequest {
                top_text: String::new(),
                bottom_text: caption.into(),
                style: "classic".into(),
                font_size: 48,
                text_align: "center".into(),
                position: "lower".into(),
                top_x: Some(50.0),
                top_y: Some(78.0),
                bottom_x: Some(50.0),
                bottom_y: Some(90.0),
                start_seconds: None,
                end_seconds: None,
                ass_path: None,
            });
            let result = convert_animation_inner(request).expect("export meme variant");
            assert_eq!(result.output_width, 240);
            assert!(result.output_frame_count >= 2);
            assert!(Path::new(&result.output_path).is_file());
            let decoded = Command::new(&ffmpeg)
                .args(["-v", "error", "-i"])
                .arg(&result.output_path)
                .args(["-frames:v", "1", "-f", "rawvideo", "-pix_fmt", "rgba", "-"])
                .output()
                .unwrap();
            assert!(decoded.status.success());
            assert!(!decoded.stdout.is_empty());
            for previous in &images {
                assert_ne!(
                    previous, &decoded.stdout,
                    "captions must produce distinct pixels"
                );
            }
            images.push(decoded.stdout);
            results.push(serde_json::json!({ "caption": caption, "result": result }));
        }
        let paths = results
            .iter()
            .map(|item| item["result"]["output_path"].as_str().unwrap())
            .collect::<HashSet<_>>();
        assert_eq!(paths.len(), 3, "exports must never overwrite one another");
        fs::write(
            work.join("meme-set-results.json"),
            serde_json::to_vec_pretty(&results).unwrap(),
        )
        .unwrap();
    }

    #[test]
    #[ignore = "set GIFP_REAL_MEDIA_INPUTS to a platform-separated list of local videos"]
    fn meme_overlay_user_media_delivery_smoke() {
        let inputs = std::env::var_os("GIFP_REAL_MEDIA_INPUTS")
            .expect("set GIFP_REAL_MEDIA_INPUTS to one or more local media paths");
        let input_paths = std::env::split_paths(&inputs).collect::<Vec<_>>();
        assert!(
            !input_paths.is_empty(),
            "no real media inputs were provided"
        );

        let sequence = OUTPUT_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        let work = std::env::temp_dir().join(format!(
            "gifp-user-media-smoke-{}-{sequence}",
            std::process::id()
        ));
        fs::create_dir_all(&work).expect("create real-media smoke directory");
        let formats = ["gif", "webp", "apng"];
        let filters = ["warm_skin", "comic_ink", "soft_matte"];

        for (index, input) in input_paths.iter().enumerate() {
            assert!(
                input.is_file(),
                "real media input does not exist: {input:?}"
            );
            let format = formats[index % formats.len()];
            let filter = filters[index % filters.len()];
            let mut request = request_with_speed(1.0);
            request.input_path = input.to_string_lossy().to_string();
            request.output_dir = work.to_string_lossy().to_string();
            request.width = 240;
            request.fps = 8;
            request.colors = 64;
            request.start_seconds = 0.0;
            request.end_seconds = 1.5;
            request.encoder = "ffmpeg_fast".to_string();
            request.generation_mode = "fast_gif".to_string();
            request.output_format = format.to_string();
            request.filter_style = filter.to_string();
            request.meme_overlay = Some(MemeOverlayRequest {
                top_text: "GIFP 真实素材".to_string(),
                bottom_text: format!("{format} · 字幕与滤镜通过"),
                style: "highlight".to_string(),
                font_size: 40,
                text_align: "center".to_string(),
                position: "split".to_string(),
                top_x: None,
                top_y: None,
                bottom_x: None,
                bottom_y: None,
                start_seconds: None,
                end_seconds: None,
                ass_path: None,
            });

            let result = convert_animation_inner(request)
                .unwrap_or_else(|error| panic!("encode {format} from {input:?}: {error}"));
            assert_eq!(result.output_format, format, "{result:?}");
            assert!(Path::new(&result.output_path).is_file(), "{result:?}");
            assert!(result.size_bytes > 500, "{result:?}");
            assert!(result.output_frame_count >= 2, "{result:?}");
        }

        assert!(
            fs::read_dir(&work)
                .expect("read real-media smoke directory")
                .all(|entry| !entry
                    .expect("directory entry")
                    .file_name()
                    .to_string_lossy()
                    .ends_with(".ass")),
            "temporary ASS overlays should be removed"
        );
        if std::env::var_os("GIFP_KEEP_SMOKE_OUTPUTS").is_some() {
            eprintln!("kept real-media smoke outputs at {}", work.display());
        } else {
            let _ = fs::remove_dir_all(&work);
        }
    }

