    #[test]
    fn best_mode_respects_explicit_dither_and_only_adapts_default_sierra() {
        let mut request = request_with_speed(1.0);
        request.dither = "none".to_string();
        let best = plan_ffmpeg_gif(&StrategyInput {
            mode: GifGenerationMode::Best,
            ..StrategyInput::default()
        });
        let fast = plan_ffmpeg_gif(&StrategyInput {
            mode: GifGenerationMode::Fast,
            ..StrategyInput::default()
        });
        assert_eq!(dither_for_plan(&request, "pngquant_opt", &best), "none");
        assert_eq!(dither_for_plan(&request, "hybrid", &fast), "bayer");

        request.perceptual_selection = Some(PerceptualSelection {
            keep_indices: vec![0],
            source_frame_count: 1,
            final_delay_cs: 10,
            frame_delays_cs: vec![10],
            palette: None,
            structured_ui_standard_palette: None,
            palette_sequence: None,
            region_dither: None,
            color_eq_recommended: false,
            bayer_dither_scale: Some(3),
            floyd_dither_recommended: false,
            structured_ui_mapper_candidate: false,
            neutral_filter_recommended: false,
        });
        assert_eq!(dither_for_plan(&request, "pngquant_opt", &best), "none");

        request.dither = "floyd_steinberg".to_string();
        assert_eq!(
            dither_for_plan(&request, "pngquant_opt", &best),
            "floyd_steinberg"
        );

        request.dither = "bayer".to_string();
        request.bayer_scale = 1;
        let explicit_bayer = plan_ffmpeg_gif(&StrategyInput {
            mode: GifGenerationMode::Best,
            bayer_scale: 1,
            ..StrategyInput::default()
        });
        assert_eq!(
            dither_for_plan(&request, "pngquant_opt", &explicit_bayer),
            "bayer"
        );
        assert_eq!(bayer_scale_for_plan(&request, &explicit_bayer), 1);

        request.dither = "sierra2_4a".to_string();
        assert_eq!(dither_for_plan(&request, "pngquant_opt", &best), "bayer");
        assert_eq!(bayer_scale_for_plan(&request, &best), 3);

        let selection = request
            .perceptual_selection
            .as_mut()
            .expect("perceptual selection");
        selection.bayer_dither_scale = None;
        selection.floyd_dither_recommended = true;
        assert_eq!(
            dither_for_plan(&request, "pngquant_opt", &best),
            "floyd_steinberg"
        );
        request.allow_experimental = true;
        assert_eq!(
            dither_for_plan(&request, "pngquant_opt", &best),
            "floyd_steinberg"
        );
        request.dither = "none".to_string();
        assert_eq!(dither_for_plan(&request, "pngquant_opt", &best), "none");
    }

    #[test]
