    #[test]
    fn practical_filter_styles_map_to_explicit_ffmpeg_chains() {
        let cases = [
            ("warm_skin", 2, "colorbalance=rs=0.06"),
            ("cool_tone", 2, "colorbalance=rs=-0.035"),
            ("mono_contrast", 1, "lutyuv="),
            ("vintage_film", 3, "curves=preset=vintage"),
            ("soft_matte", 2, "curves=all="),
            ("comic_ink", 2, "unsharp=5:5:1.25"),
        ];

        for (style, expected_filter_count, expected_fragment) in cases {
            let filters = style_filters(style);
            assert_eq!(filters.len(), expected_filter_count, "{style}: {filters:?}");
            assert!(
                filters
                    .iter()
                    .any(|filter| filter.contains(expected_fragment)),
                "{style}: {filters:?}"
            );
        }
        assert!(style_filters("none").is_empty());
        assert!(style_filters("unknown-style").is_empty());
        for legacy_style in ["vivid", "gb", "gba_lcd", "crt", "pixel"] {
            assert!(
                !style_filters(legacy_style).is_empty(),
                "legacy style {legacy_style} must remain mapped"
            );
        }
    }

