    #[test]
    fn segmented_palette_graph_covers_every_scene_once() {
        let request = request_with_speed(1.0);
        let plan = plan_ffmpeg_gif(&StrategyInput {
            mode: GifGenerationMode::Best,
            content_profile: ContentProfile::FrequentSceneChanges,
            ..StrategyInput::default()
        });
        let graph = segmented_filter_graph(&request, "hybrid", &plan, &[1.0, 2.5]);
        assert!(graph.contains("split=3[s0][s1][s2]"), "{graph}");
        assert!(graph.contains("trim=start=0.000:end=1.000"), "{graph}");
        assert!(graph.contains("trim=start=1.000:end=2.500"), "{graph}");
        assert!(graph.contains("trim=start=2.500"), "{graph}");
        assert_eq!(graph.matches("stats_mode=full").count(), 3, "{graph}");
        assert!(graph.ends_with("concat=n=3:v=1:a=0[out]"), "{graph}");
    }

