    #[test]
    fn psgrab_forced_termination_is_bounded_and_reaped() {
        let test_binary = std::env::current_exe().expect("locate current Rust test binary");
        let mut child = Command::new(test_binary)
            .arg("--ignored")
            .arg("--exact")
            .arg("commands::tests::psgrab_termination_child")
            .arg("--test-threads=1")
            .env("GIFP_PSGRAB_TERMINATION_CHILD", "1")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .expect("spawn psgrab termination helper");
        std::thread::sleep(Duration::from_millis(100));
        let started = Instant::now();
        terminate_and_reap_child(&mut child).expect("terminate and reap psgrab helper");
        assert!(started.elapsed() < Duration::from_secs(2));
        assert!(child
            .try_wait()
            .expect("poll terminated psgrab helper")
            .is_some());
    }

