    #[test]
    #[ignore = "helper invoked by the multi-process paired-output publish test"]
    fn multiprocess_paired_output_publish_child() {
        const PREFIX: &str = ".gifp-live-stage-";
        let Some(output_dir) = std::env::var_os("GIFP_MULTIPROCESS_LIVE_DIR").map(PathBuf::from)
        else {
            return;
        };
        let payload = std::env::var("GIFP_MULTIPROCESS_LIVE_PAYLOAD")
            .expect("multi-process paired-output payload");
        let staged = OwnedPublishDir::create(&output_dir, PREFIX)
            .expect("create child paired-output transaction");
        fs::write(staged.path().join("payload.txt"), payload.as_bytes())
            .expect("write child paired-output payload");
        let ready = output_dir.join(format!(".live-publish-ready-{}", std::process::id()));
        fs::write(&ready, b"ready").expect("write paired-output barrier marker");
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let ready_count = fs::read_dir(&output_dir)
                .expect("read paired-output barrier directory")
                .filter_map(Result::ok)
                .filter(|entry| {
                    entry
                        .file_name()
                        .to_string_lossy()
                        .starts_with(".live-publish-ready-")
                })
                .count();
            if ready_count >= 2 {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "timed out waiting for the second paired-output publisher"
            );
            std::thread::sleep(Duration::from_millis(10));
        }

        match staged.publish(&output_dir.join("shared-live.pvt")) {
            Ok(()) => println!("GIFP_SHARED_LIVE_PUBLISH=published"),
            Err(error) => {
                assert!(
                    error.to_string().contains("refusing to overwrite"),
                    "unexpected paired-output collision failure: {error}"
                );
                println!("GIFP_SHARED_LIVE_PUBLISH=collision");
            }
        }
    }

    #[test]
    fn two_os_processes_publish_one_paired_output_without_overwriting_the_winner() {
        let output_dir = isolated_smoke_dir("gifp-multiprocess-live-publish-race");
        fs::create_dir_all(&output_dir).expect("create paired-output race directory");
        let test_binary = std::env::current_exe().expect("locate current Rust test binary");
        let spawn_child = |payload: &str| {
            Command::new(&test_binary)
                .arg("--ignored")
                .arg("--exact")
                .arg("commands::tests::multiprocess_paired_output_publish_child")
                .arg("--nocapture")
                .arg("--test-threads=1")
                .env("GIFP_MULTIPROCESS_LIVE_DIR", &output_dir)
                .env("GIFP_MULTIPROCESS_LIVE_PAYLOAD", payload)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .expect("spawn paired-output contender")
        };
        let first = spawn_child("first contender");
        let second = spawn_child("second contender");
        let first = first.wait_with_output().expect("wait for first contender");
        let second = second
            .wait_with_output()
            .expect("wait for second contender");
        for (label, child) in [("first", &first), ("second", &second)] {
            assert!(
                child.status.success(),
                "{label} paired-output contender failed: {}{}",
                String::from_utf8_lossy(&child.stdout),
                String::from_utf8_lossy(&child.stderr)
            );
        }

        let combined_stdout = format!(
            "{}{}",
            String::from_utf8_lossy(&first.stdout),
            String::from_utf8_lossy(&second.stdout)
        );
        assert_eq!(
            combined_stdout
                .matches("GIFP_SHARED_LIVE_PUBLISH=published")
                .count(),
            1
        );
        assert_eq!(
            combined_stdout
                .matches("GIFP_SHARED_LIVE_PUBLISH=collision")
                .count(),
            1
        );
        let payload = fs::read_to_string(output_dir.join("shared-live.pvt/payload.txt"))
            .expect("read winning paired-output payload");
        assert!(
            payload == "first contender" || payload == "second contender",
            "{payload}"
        );
        assert!(
            fs::read_dir(&output_dir)
                .expect("read paired-output race directory")
                .filter_map(Result::ok)
                .all(|entry| !entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with(".gifp-live-stage-")),
            "paired-output race left a staging directory"
        );
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    #[ignore = "helper invoked by the multi-process publish contract test"]
    fn multiprocess_publish_child() {
        let Some(output_dir) = std::env::var_os("GIFP_MULTIPROCESS_CHILD_DIR").map(PathBuf::from)
        else {
            return;
        };
        let payload =
            std::env::var("GIFP_MULTIPROCESS_CHILD_PAYLOAD").expect("multi-process child payload");
        let source = output_dir.join(format!(".child-source-{}.gif", unique_output_token()));
        fs::write(&source, payload.as_bytes()).expect("write child publish source");
        let shared_output_name = std::env::var_os("GIFP_MULTIPROCESS_SHARED_OUTPUT");
        let output = shared_output_name
            .as_ref()
            .map(|name| output_dir.join(name))
            .unwrap_or_else(|| next_output_path(Path::new("shared-input.mp4"), &output_dir));
        if shared_output_name.is_some() {
            let staged = stage_publish_file(&source, &output).expect("stage shared child output");
            let ready = output_dir.join(format!(".publish-ready-{}", std::process::id()));
            fs::write(&ready, b"ready").expect("write shared-publish barrier marker");
            let deadline = Instant::now() + Duration::from_secs(5);
            loop {
                let ready_count = fs::read_dir(&output_dir)
                    .expect("read shared-publish barrier directory")
                    .filter_map(Result::ok)
                    .filter(|entry| {
                        entry
                            .file_name()
                            .to_string_lossy()
                            .starts_with(".publish-ready-")
                    })
                    .count();
                if ready_count >= 2 {
                    break;
                }
                assert!(
                    Instant::now() < deadline,
                    "timed out waiting for the second publish process"
                );
                std::thread::sleep(Duration::from_millis(10));
            }
            match finish_staged_publish(&staged, &output, false) {
                Ok(()) => println!("GIFP_SHARED_PUBLISH=published"),
                Err(error) => {
                    assert!(
                        error.to_string().contains("refusing to overwrite"),
                        "unexpected shared-publish failure: {error}"
                    );
                    println!("GIFP_SHARED_PUBLISH=collision");
                }
            }
        } else {
            publish_file_atomically(&source, &output, false).expect("publish from child process");
        }
        fs::remove_file(source).expect("remove child publish source");
    }

