            std::env::var("GIFP_MULTIPROCESS_DELIVERY_FORMAT").expect("delivery format");
        let format = AnimationFormat::parse(&format_name).expect("supported delivery format");
        let owned_prefix = if format == AnimationFormat::Gif {
            "gif-p-export-"
        } else {
            "gif-p-modern-"
        };
