    #[test]
    #[ignore = "runs four real FFmpeg delivery processes against private MP4 fixtures"]
    fn four_os_processes_export_real_media_to_one_directory() {
        let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("workspace root")
            .to_path_buf();
        let fixture_root = root.join("test");
        let fixtures = [
            fixture_root
                .join("jimeng-2026-07-15-3551-角色，玩扭蛋机，背景纯色背景，扭蛋机更写实一些.mp4"),
            fixture_root.join("s_EuSr2hOyee5Jzw (1).mp4"),
            fixture_root.join("【鱼肉肉】最伟大的发明ᗜωᗜ.mp4"),
        ];
        for fixture in &fixtures {
            assert!(
                fixture.is_file(),
                "missing real fixture {}",
                fixture.display()
            );
        }
        let output_dir = isolated_smoke_dir("gifp-real-multiprocess-delivery");
        fs::create_dir_all(&output_dir).expect("create real multi-process output directory");
        let test_binary = std::env::current_exe().expect("locate current Rust test binary");
        let routes = [
            ("gif", &fixtures[0]),
            ("webp", &fixtures[1]),
            ("apng", &fixtures[2]),
            ("mp4", &fixtures[0]),
        ];
        let mut children = Vec::with_capacity(routes.len());
        for (format, input) in routes {
            let child = Command::new(&test_binary)
                .arg("--ignored")
                .arg("--exact")
                .arg("commands::tests::multiprocess_real_delivery_child")
                .arg("--nocapture")
                .arg("--test-threads=1")
                .env("GIFP_MULTIPROCESS_DELIVERY_DIR", &output_dir)
                .env("GIFP_MULTIPROCESS_DELIVERY_INPUT", input)
                .env("GIFP_MULTIPROCESS_DELIVERY_FORMAT", format)
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .unwrap_or_else(|error| panic!("spawn {format} delivery child: {error}"));
            children.push((format, child));
        }

        let mut reported_outputs = Vec::with_capacity(children.len());
        for (format, child) in children {
            let output = child
                .wait_with_output()
                .unwrap_or_else(|error| panic!("wait for {format} child: {error}"));
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            assert!(
                output.status.success(),
                "{format} child failed:\n{stdout}\n{stderr}"
            );
            let published = stdout
                .lines()
                .find_map(|line| {
                    line.split_once("GIFP_REAL_DELIVERY_OUTPUT=")
                        .map(|(_, path)| path.trim())
                })
                .map(PathBuf::from)
                .unwrap_or_else(|| panic!("{format} child did not report an output:\n{stdout}"));
            assert!(published.is_file(), "{}", published.display());
            reported_outputs.push(published);
        }
        reported_outputs.sort();
        reported_outputs.dedup();
        assert_eq!(reported_outputs.len(), 4, "{reported_outputs:?}");
        assert!(
            fs::read_dir(&output_dir)
                .expect("read real multi-process output directory")
                .filter_map(Result::ok)
                .all(|entry| !entry.file_name().to_string_lossy().ends_with(".part")),
            "real multi-process delivery left a publish staging file"
        );
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    fn gif_palette_verifier_checks_transparency_local_tables_and_trailer() {
        let mut rgba = Vec::with_capacity(256 * 4);
        for index in 0_u8..=u8::MAX {
            rgba.extend([index, index, index, if index == u8::MAX { 0 } else { 255 }]);
        }
        let sha256 = Sha256::digest(&rgba)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        let artifact = OklabPaletteArtifact {
            rgba,
            emitted_colors: 256,
            sampled_frame_count: 1,
            sampled_pixel_count: 1,
            weighted_sample_mass: 1.0,
            weighted_histogram_mean_oklab_error: 0.0,
            weighted_histogram_p95_oklab_error: 0.0,
            sha256,
        };

        let mut gif = b"GIF89a".to_vec();
        gif.extend([1, 0, 1, 0, 0xf7, 0, 0]);
        for index in 0_u8..=u8::MAX {
            gif.extend([index, index, index]);
        }
        let graphic_control_offset = gif.len();
        gif.extend([0x21, 0xf9, 4, 1, 0, 0, 255, 0]);
        let image_descriptor_offset = gif.len();
        gif.extend([0x2c, 0, 0, 0, 0, 1, 0, 1, 0, 0]);
        gif.extend([2, 2, 0x44, 0x01, 0, 0x3b]);

        let output_dir = isolated_smoke_dir("gifp-palette-verifier");
        fs::create_dir_all(&output_dir).expect("create palette verifier directory");
        let output = output_dir.join("fixture.gif");
        fs::write(&output, &gif).expect("write valid verifier fixture");
        assert!(verify_gif_global_palette(&output, &artifact).unwrap());

        let mut compacted_gif = b"GIF89a".to_vec();
        compacted_gif.extend([1, 0, 1, 0, 0xf1, 0, 0]);
        for index in [0_u8, 7, 200, 255] {
            compacted_gif.extend([index, index, index]);
        }
        compacted_gif.extend([0x21, 0xf9, 4, 1, 0, 0, 3, 0]);
        compacted_gif.extend([0x2c, 0, 0, 0, 0, 1, 0, 1, 0, 0]);
        compacted_gif.extend([2, 2, 0x44, 0x01, 0, 0x3b]);
        fs::write(&output, &compacted_gif).expect("write compacted verifier fixture");
        assert!(verify_gif_global_palette(&output, &artifact).unwrap());

        let mut wrong_compacted_color = compacted_gif;
        wrong_compacted_color[13 + 3] = 6;
        fs::write(&output, wrong_compacted_color).expect("write wrong compacted table fixture");
        assert!(!verify_gif_global_palette(&output, &artifact).unwrap());

        let mut wrong_transparency = gif.clone();
        wrong_transparency[graphic_control_offset + 6] = 254;
        fs::write(&output, wrong_transparency).expect("write wrong transparency fixture");
        assert!(!verify_gif_global_palette(&output, &artifact).unwrap());

        let mut local_table = gif.clone();
        local_table[image_descriptor_offset + 9] = 0x80;
        fs::write(&output, local_table).expect("write local table fixture");
        assert!(!verify_gif_global_palette(&output, &artifact).unwrap());

        let mut truncated = gif.clone();
        truncated.pop();
        fs::write(&output, truncated).expect("write truncated fixture");
        assert!(verify_gif_global_palette(&output, &artifact).is_err());

        let mut bad_hash = artifact;
        let replacement = if bad_hash.sha256.starts_with('0') {
            "1"
        } else {
            "0"
        };
        bad_hash.sha256.replace_range(..1, replacement);
        fs::write(&output, gif).expect("restore verifier fixture");
        assert!(!verify_gif_global_palette(&output, &bad_hash).unwrap());
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    fn opaque_palette_verifier_requires_a_full_table_without_transparency() {
        let mut rgba = Vec::with_capacity(256 * 4);
        for index in 0_u8..=u8::MAX {
            rgba.extend([index, index, index, u8::MAX]);
        }
        let artifact = OklabPaletteArtifact {
            sha256: format!("{:x}", Sha256::digest(&rgba)),
            rgba,
            emitted_colors: 256,
            sampled_frame_count: 1,
            sampled_pixel_count: 1,
            weighted_sample_mass: 1.0,
            weighted_histogram_mean_oklab_error: 0.0,
            weighted_histogram_p95_oklab_error: 0.0,
        };
        assert!(!oklab_palette_reserves_transparency(&artifact));

        let mut gif = b"GIF89a".to_vec();
        gif.extend([1, 0, 1, 0, 0xf7, 0, 0]);
        for index in 0_u8..=u8::MAX {
            gif.extend([index, index, index]);
        }
        let image_descriptor_offset = gif.len();
        gif.extend([0x2c, 0, 0, 0, 0, 1, 0, 1, 0, 0]);
        gif.extend([2, 2, 0x44, 0x01, 0, 0x3b]);

        let output_dir = isolated_smoke_dir("gifp-opaque-palette-verifier");
        fs::create_dir_all(&output_dir).expect("create opaque verifier directory");
        let output = output_dir.join("fixture.gif");
        fs::write(&output, &gif).expect("write opaque verifier fixture");
        assert!(verify_gif_global_palette(&output, &artifact).unwrap());

        let mut compacted = b"GIF89a".to_vec();
        compacted.extend([1, 0, 1, 0, 0xf1, 0, 0]);
        for index in [0_u8, 7, 200, 255] {
            compacted.extend([index, index, index]);
        }
        compacted.extend([0x2c, 0, 0, 0, 0, 1, 0, 1, 0, 0]);
        compacted.extend([2, 2, 0x44, 0x01, 0, 0x3b]);
        fs::write(&output, compacted).expect("write compacted opaque fixture");
        assert!(!verify_gif_global_palette(&output, &artifact).unwrap());

        let mut transparency = gif.clone();
        transparency.splice(
            image_descriptor_offset..image_descriptor_offset,
            [0x21, 0xf9, 4, 1, 0, 0, 255, 0],
        );
        fs::write(&output, transparency).expect("write transparent opaque fixture");
        assert!(!verify_gif_global_palette(&output, &artifact).unwrap());

        let mut local_table = gif;
        local_table[image_descriptor_offset + 9] = 0x80;
        fs::write(&output, local_table).expect("write local-table opaque fixture");
        assert!(!verify_gif_global_palette(&output, &artifact).unwrap());
        let _ = fs::remove_dir_all(output_dir);
    }

