    #[test]
    fn real_perceptual_alpha_source_uses_safe_verified_transparent_route() {
        let output_dir = isolated_smoke_dir("gifp-perceptual-alpha-smoke");
        fs::create_dir_all(&output_dir).expect("create perceptual alpha smoke directory");
        let input = output_dir.join("alpha-fade.apng");
        let ffmpeg = locate_ffmpeg().expect("locate FFmpeg");
        let generated = Command::new(&ffmpeg)
            .arg("-y")
            .arg("-hide_banner")
            .arg("-loglevel")
            .arg("error")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("color=c=black@0.0:s=32x32:r=5:d=0.6,format=rgba,drawbox=x=8:y=8:w=16:h=16:color=red@1.0:t=fill:replace=1")
            .arg("-f")
            .arg("apng")
            .arg("-plays")
            .arg("0")
            .arg(&input)
            .output_for_conversion_task()
            .expect("generate alpha-fade APNG");
        assert!(
            generated.status.success(),
            "{}",
            String::from_utf8_lossy(&generated.stderr)
        );

        let mut request = request_with_speed(1.0);
        request.input_path = input.to_string_lossy().to_string();
        request.output_dir = output_dir.to_string_lossy().to_string();
        request.width = 96;
        request.fps = 12;
        request.colors = 96;
        request.filter_style = "vivid".to_string();
        request.generation_mode = "best_gif".to_string();

        let result = convert_animation_inner(request).expect("encode alpha source safely");
        assert_eq!(
            result.backend_id, "rust.indexed_gif.transparent",
            "{result:?}"
        );
        assert_eq!(
            result.encoder_used, "rust_transparent_disposal_postprocess",
            "{result:?}"
        );
        assert!(
            result
                .backend_version
                .as_deref()
                .is_some_and(|version| version == env!("CARGO_PKG_VERSION")),
            "{result:?}"
        );
        assert!(
            result
                .palette_strategy
                .contains("rust_timed_coalesce+disposal_byte_search"),
            "{result:?}"
        );
        assert!(result.perceptual_report.is_none(), "{result:?}");
        assert!(result.palette_report.is_none(), "{result:?}");
        assert!(
            result.fallback_reason.is_none(),
            "an intentional alpha-safe route must not be reported as a failed perceptual attempt: {result:?}"
        );
        let writer = result
            .indexed_gif_writer_report
            .as_ref()
            .unwrap_or_else(|| panic!("missing transparent writer report: {result:?}"));
        assert_eq!(writer.status, "encoded_default", "{writer:?}");
        assert!(writer.decoded_pixel_parity_verified, "{writer:?}");
        assert!(writer.disposal_simulation_verified, "{writer:?}");
        assert_eq!(result.output_frame_count, 1, "{result:?}");
        assert!(
            result
                .warnings
                .iter()
                .any(|warning| warning.contains("RGB cleanup filters")),
            "{result:?}"
        );
        assert!(
            result
                .warnings
                .iter()
                .any(|warning| warning.contains("visual style")),
            "{result:?}"
        );
        let source_alpha = decoded_mean_alpha(&ffmpeg, &input);
        let output_alpha = decoded_mean_alpha(&ffmpeg, Path::new(&result.output_path));
        assert!(
            (source_alpha - output_alpha).abs() <= 2.0,
            "source alpha {source_alpha:.3}, output alpha {output_alpha:.3}: {result:?}"
        );
        let _ = fs::remove_file(result.output_path);

        let mut target_request = request_with_speed(1.0);
        target_request.input_path = input.to_string_lossy().to_string();
        target_request.output_dir = output_dir.to_string_lossy().to_string();
        target_request.width = 96;
        target_request.fps = 5;
        target_request.colors = 64;
        target_request.generation_mode = "target_size".to_string();
        target_request.target_size_bytes = Some(128 * 1024);
        target_request.target_max_attempts = 4;
        target_request.encoder = "ffmpeg_fast".to_string();
        let target_result =
            convert_animation_inner(target_request).expect("encode alpha target safely");
        let optimizer = target_result
            .target_optimizer_report
            .as_ref()
            .unwrap_or_else(|| panic!("missing alpha target report: {target_result:?}"));
        let timeline_route = optimizer
            .route_observations
            .iter()
            .find(|route| route.route_id == "perceptual_timeline")
            .unwrap_or_else(|| panic!("missing alpha target timeline: {optimizer:?}"));
        assert_eq!(timeline_route.status, "failed", "{optimizer:?}");
        assert!(
            timeline_route
                .failure_reason
                .as_deref()
                .is_some_and(|reason| reason.contains("transparency")),
            "{optimizer:?}"
        );
        assert!(
            target_result.perceptual_report.is_none(),
            "{target_result:?}"
        );
        let target_alpha = decoded_mean_alpha(&ffmpeg, Path::new(&target_result.output_path));
        assert!(
            (source_alpha - target_alpha).abs() <= 2.0,
            "source alpha {source_alpha:.3}, target alpha {target_alpha:.3}: {target_result:?}"
        );
        let _ = fs::remove_file(target_result.output_path);
        let _ = fs::remove_file(input);
    }

