    #[test]
    fn regional_quantizer_gate_accepts_a_real_pareto_improvement() {
        let baseline = QuantizationMetrics {
            sampled_pixel_count: 10_000,
            sampled_static_pixel_count: 4_000,
            mean_oklab_error: 0.020,
            p95_oklab_error: 0.060,
            edge_weighted_mean_oklab_error: 0.024,
            multiscale_low_frequency_oklab_error: 0.018,
            multiscale_banding_score: 0.010,
            edge_gradient_error: 0.020,
            static_temporal_residual: 0.008,
            multiscale_static_temporal_residual: 0.006,
        };
        let candidate = QuantizationMetrics {
            mean_oklab_error: 0.018,
            p95_oklab_error: 0.052,
            edge_weighted_mean_oklab_error: 0.021,
            multiscale_low_frequency_oklab_error: 0.016,
            multiscale_banding_score: 0.008,
            edge_gradient_error: 0.018,
            static_temporal_residual: 0.006,
            multiscale_static_temporal_residual: 0.005,
            ..baseline.clone()
        };
        assert_eq!(
            regional_quantization_gate(&candidate, &baseline, 102_000, 100_000),
            Ok(())
        );
    }

    #[test]
    fn temporal_quantizer_gate_requires_real_pareto_gain_without_flicker_regression() {
        let baseline = QuantizationMetrics {
            sampled_pixel_count: 10_000,
            sampled_static_pixel_count: 8_000,
            mean_oklab_error: 0.012,
            p95_oklab_error: 0.030,
            edge_weighted_mean_oklab_error: 0.014,
            multiscale_low_frequency_oklab_error: 0.010,
            multiscale_banding_score: 0.006,
            edge_gradient_error: 0.011,
            static_temporal_residual: 0.008,
            multiscale_static_temporal_residual: 0.006,
        };
        let temporally_improved = QuantizationMetrics {
            static_temporal_residual: 0.006,
            multiscale_static_temporal_residual: 0.005,
            ..baseline.clone()
        };
        assert_eq!(
            temporal_quantizer_pareto_gate(&temporally_improved, &baseline, 102_000, 100_000, 400,),
            Ok(())
        );
        assert_eq!(
            temporal_quantizer_pareto_gate(&baseline, &baseline, 99_000, 100_000, 400),
            Ok(())
        );

        let no_gain = temporal_quantizer_pareto_gate(&baseline, &baseline, 100_000, 100_000, 400)
            .expect_err("equal bytes and quality are not a Pareto gain");
        assert!(no_gain.contains("neither smaller real bytes nor a 5% temporal gain"));

        let regressed = QuantizationMetrics {
            static_temporal_residual: 0.009,
            ..baseline.clone()
        };
        let reason = temporal_quantizer_pareto_gate(&regressed, &baseline, 99_000, 100_000, 400)
            .expect_err("smaller bytes must not pay for visible temporal regression");
        assert!(reason.contains("regressed static residual"));
        assert!(temporal_quantizer_pareto_gate(&baseline, &baseline, 99_000, 100_000, 0).is_err());
    }

    #[test]
    fn temporal_final_gate_protects_vfr_loop_seams_and_ffmpeg_pareto_status() {
        let baseline = QuantizationMetrics {
            sampled_pixel_count: 10_000,
            sampled_static_pixel_count: 8_000,
            mean_oklab_error: 0.012,
            p95_oklab_error: 0.030,
            edge_weighted_mean_oklab_error: 0.014,
            multiscale_low_frequency_oklab_error: 0.010,
            multiscale_banding_score: 0.006,
            edge_gradient_error: 0.011,
            static_temporal_residual: 0.008,
            multiscale_static_temporal_residual: 0.006,
        };
        let timing = TimingAwareTemporalResidual {
            sampled_static_transition_count: 8_000,
            weighted_static_sample_duration_cs: 80_000,
            weighted_static_temporal_residual: 0.008,
            sampled_multiscale_static_transition_count: 16_000,
            weighted_multiscale_static_sample_duration_cs: 160_000,
            weighted_multiscale_static_temporal_residual: 0.006,
            loop_seam_sampled_static_pixel_count: 2_000,
            loop_seam_static_temporal_residual: Some(0.004),
            loop_seam_sampled_multiscale_count: 4_000,
            loop_seam_multiscale_static_temporal_residual: Some(0.003),
        };
        assert!(temporal_final_ffmpeg_pareto_gate(
            &baseline, &baseline, &timing, &timing, 99_000, 100_000, 100,
        )
        .is_ok());

        let mut seam_regression = timing.clone();
        seam_regression.loop_seam_static_temporal_residual = Some(0.0041);
        let reason = temporal_final_ffmpeg_pareto_gate(
            &baseline,
            &baseline,
            &seam_regression,
            &timing,
            99_000,
            100_000,
            100,
        )
        .expect_err("smaller bytes must not hide a loop-seam regression");
        assert!(reason.contains("loop seam"), "{reason}");

        let spatially_dominated = QuantizationMetrics {
            mean_oklab_error: 0.0123,
            ..baseline.clone()
        };
        let reason = temporal_final_ffmpeg_pareto_gate(
            &spatially_dominated,
            &baseline,
            &timing,
            &timing,
            99_000,
            100_000,
            100,
        )
        .expect_err("a smaller candidate with a key quality regression is not Pareto-safe");
        assert!(reason.contains("mean OKLab"), "{reason}");
    }

    #[test]
    fn opaque_palette_reservation_gate_requires_a_real_safe_pareto_win() {
        let baseline = QuantizationMetrics {
            sampled_pixel_count: 10_000,
            sampled_static_pixel_count: 8_000,
            mean_oklab_error: 0.020,
            p95_oklab_error: 0.050,
            edge_weighted_mean_oklab_error: 0.024,
            multiscale_low_frequency_oklab_error: 0.018,
            multiscale_banding_score: 0.010,
            edge_gradient_error: 0.020,
            static_temporal_residual: 0.008,
            multiscale_static_temporal_residual: 0.006,
        };
        let timing = TimingAwareTemporalResidual {
            sampled_static_transition_count: 8_000,
            weighted_static_sample_duration_cs: 80_000,
            weighted_static_temporal_residual: 0.008,
            sampled_multiscale_static_transition_count: 16_000,
            weighted_multiscale_static_sample_duration_cs: 160_000,
            weighted_multiscale_static_temporal_residual: 0.006,
            loop_seam_sampled_static_pixel_count: 2_000,
            loop_seam_static_temporal_residual: Some(0.004),
            loop_seam_sampled_multiscale_count: 4_000,
            loop_seam_multiscale_static_temporal_residual: Some(0.003),
        };

        assert!(opaque_palette_reservation_selection_gate(
            &baseline, &baseline, &timing, &timing, 99_999, 100_000,
        )
        .is_ok());

        let tie = opaque_palette_reservation_selection_gate(
            &baseline, &baseline, &timing, &timing, 100_000, 100_000,
        )
        .expect_err("a byte-and-quality tie must retain transparent deltas");
        assert!(tie.contains("no Pareto gain"), "{tie}");

        let improved = QuantizationMetrics {
            mean_oklab_error: 0.018,
            p95_oklab_error: 0.045,
            edge_weighted_mean_oklab_error: 0.021,
            multiscale_low_frequency_oklab_error: 0.016,
            multiscale_banding_score: 0.008,
            edge_gradient_error: 0.018,
            static_temporal_residual: 0.006,
            multiscale_static_temporal_residual: 0.005,
            ..baseline.clone()
        };
        assert!(opaque_palette_reservation_selection_gate(
            &improved, &baseline, &timing, &timing, 102_000, 100_000,
        )
        .is_ok());
        let above_ceiling = opaque_palette_reservation_selection_gate(
            &improved, &baseline, &timing, &timing, 103_001, 100_000,
        )
        .expect_err("a quality gain must not buy more than three percent bytes");
        assert!(above_ceiling.contains("exceeded +3%"), "{above_ceiling}");

        let edge_regression = QuantizationMetrics {
            edge_gradient_error: 0.021,
            ..baseline.clone()
        };
        let edge_reason = opaque_palette_reservation_selection_gate(
            &edge_regression,
            &baseline,
            &timing,
            &timing,
            99_999,
            100_000,
        )
        .expect_err("a one-byte win must not buy an edge regression");
        assert!(edge_reason.contains("edge-gradient"), "{edge_reason}");

        let mut seam_regression = timing.clone();
        seam_regression.loop_seam_static_temporal_residual = Some(0.0041);
        let seam_reason = opaque_palette_reservation_selection_gate(
            &baseline,
            &baseline,
            &seam_regression,
            &timing,
            99_999,
            100_000,
        )
        .expect_err("a byte win must not hide a loop-seam regression");
        assert!(seam_reason.contains("loop seam"), "{seam_reason}");
    }

    #[test]
    fn error_diffusion_gate_requires_gradient_gain_and_protects_vfr_loop_seams() {
        let baseline = QuantizationMetrics {
            sampled_pixel_count: 10_000,
            sampled_static_pixel_count: 8_000,
            mean_oklab_error: 0.020,
            p95_oklab_error: 0.050,
            edge_weighted_mean_oklab_error: 0.023,
            multiscale_low_frequency_oklab_error: 0.020,
            multiscale_banding_score: 0.010,
            edge_gradient_error: 0.018,
            static_temporal_residual: 0.004,
            multiscale_static_temporal_residual: 0.003,
        };
        let candidate = QuantizationMetrics {
            multiscale_low_frequency_oklab_error: 0.017,
            multiscale_banding_score: 0.008,
            ..baseline.clone()
        };
        let timing = TimingAwareTemporalResidual {
            sampled_static_transition_count: 8_000,
            weighted_static_sample_duration_cs: 80_000,
            weighted_static_temporal_residual: 0.004,
            sampled_multiscale_static_transition_count: 16_000,
            weighted_multiscale_static_sample_duration_cs: 160_000,
            weighted_multiscale_static_temporal_residual: 0.003,
            loop_seam_sampled_static_pixel_count: 2_000,
            loop_seam_static_temporal_residual: Some(0.002),
            loop_seam_sampled_multiscale_count: 4_000,
            loop_seam_multiscale_static_temporal_residual: Some(0.0015),
        };
        assert!(error_diffusion_selection_gate(
            &candidate, &baseline, &timing, &timing, 104_000, 100_000, 4_000, 1_000,
        )
        .is_ok());

        let no_gain = error_diffusion_selection_gate(
            &baseline, &baseline, &timing, &timing, 99_000, 100_000, 4_000, 1_000,
        )
        .expect_err("smaller bytes alone must not promote spatial noise");
        assert!(
            no_gain.contains("less than an 8% material banding gain"),
            "{no_gain}"
        );

        let low_frequency_only = QuantizationMetrics {
            multiscale_low_frequency_oklab_error: 0.016,
            ..baseline.clone()
        };
        let reason = error_diffusion_selection_gate(
            &low_frequency_only,
            &baseline,
            &timing,
            &timing,
            99_000,
            100_000,
            4_000,
            1_000,
        )
        .expect_err("low-frequency gain without a banding gain must remain experimental");
        assert!(
            reason.contains("less than an 8% material banding gain"),
            "{reason}"
        );

        let edge_regression = QuantizationMetrics {
            multiscale_low_frequency_oklab_error: 0.017,
            multiscale_banding_score: 0.008,
            edge_gradient_error: 0.0185,
            ..baseline.clone()
        };
        let reason = error_diffusion_selection_gate(
            &edge_regression,
            &baseline,
            &timing,
            &timing,
            99_000,
            100_000,
            4_000,
            1_000,
        )
        .expect_err("banding gain must not buy an edge-gradient regression");
        assert!(reason.contains("edge-gradient error regressed"), "{reason}");

        let reason = error_diffusion_selection_gate(
            &candidate, &baseline, &timing, &timing, 106_000, 100_000, 4_000, 1_000,
        )
        .expect_err("banding gain must not buy more than five percent real bytes");
        assert!(reason.contains("serialized bytes exceeded +5%"), "{reason}");

        let mut seam_regression = timing.clone();
        seam_regression.loop_seam_static_temporal_residual = Some(0.0021);
        let reason = error_diffusion_selection_gate(
            &candidate,
            &baseline,
            &seam_regression,
            &timing,
            99_000,
            100_000,
            4_000,
            1_000,
        )
        .expect_err("a loop-seam regression must reject the diffusion candidate");
        assert!(reason.contains("loop seam"), "{reason}");
    }

    #[test]
    fn ordered_rejection_routes_diffusion_against_ffmpeg_and_falls_back_without_payload_leak() {
        let width = 16_u16;
        let height = 16_u16;
        let pixels_per_frame = usize::from(width) * usize::from(height);
        let source_rgb = [99_u8, 101, 99]
            .into_iter()
            .flat_map(|value| (0..pixels_per_frame).flat_map(move |_| [value, value, value]))
            .collect::<Vec<_>>();
        let source_rgba = rgb24_to_opaque_rgba(&source_rgb);

        let mut rgba = Vec::with_capacity(256 * 4);
        rgba.extend_from_slice(&[96, 96, 96, 255]);
        rgba.extend_from_slice(&[104, 104, 104, 255]);
        for _ in 2..255 {
            rgba.extend_from_slice(&[104, 104, 104, 255]);
        }
        rgba.extend_from_slice(&[0, 0, 0, 0]);
        let palette = OklabPaletteArtifact {
            sha256: format!("{:x}", Sha256::digest(&rgba)),
            rgba,
            emitted_colors: 3,
            sampled_frame_count: 3,
            sampled_pixel_count: u64::try_from(pixels_per_frame * 3).unwrap(),
            weighted_sample_mass: (pixels_per_frame * 3) as f64,
            weighted_histogram_mean_oklab_error: 0.0,
            weighted_histogram_p95_oklab_error: 0.0,
        };
        let global_palette_rgb = palette
            .rgba
            .chunks_exact(4)
            .flat_map(|entry| [entry[0], entry[1], entry[2]])
            .collect::<Vec<_>>();
        let regions = RegionDitherArtifact {
            grid_width: 2,
            grid_height: 1,
            class_map: vec![0, 0],
            strength_map: vec![0, 0],
            class_counts: [2, 0, 0, 0],
            sampled_frame_count: 3,
            sampled_pixel_count: u64::try_from(pixels_per_frame * 3).unwrap(),
            weighted_sample_mass: (pixels_per_frame * 3) as f64,
            mean_dither_strength: 0.0,
            mean_spatial_std: 0.0,
            mean_edge: 0.0,
            mean_skin_ratio: 0.0,
            mean_temporal_delta: 2.0 / 255.0,
            mean_high_frequency_noise: 0.0,
            class_map_sha256: "forced-route-classes".to_string(),
            strength_map_sha256: "forced-route-strengths".to_string(),
            sha256: "forced-route-regions".to_string(),
        };
        let ordered = quantize_rgb24_with_region(&source_rgb, width, height, &palette, &regions)
            .expect("quantize ordered fixture");
        let mapped_rgba = rgb24_to_opaque_rgba(&ordered.reconstructed_rgb24);
        let baseline_indices = ordered.indices;
        let delays = vec![4_u16; 3];
        let baseline_plan = full_frame_indexed_plan(
            baseline_indices.clone(),
            width,
            height,
            &delays,
            &global_palette_rgb,
            IndexedGifRepeat::Infinite,
        )
        .expect("build forced-route baseline");
        let baseline = serialize_optimized_indexed_candidate(&baseline_plan)
            .expect("serialize forced-route baseline");
        let mut request = request_with_speed(1.0);
        request.allow_experimental = true;
        request.perceptual_selection = Some(PerceptualSelection {
            keep_indices: (0_u32..3).collect(),
            source_frame_count: 3,
            final_delay_cs: 4,
            frame_delays_cs: delays,
            palette: Some(palette.clone()),
            structured_ui_standard_palette: None,
            palette_sequence: None,
            region_dither: Some(regions.clone()),
            color_eq_recommended: false,
            bayer_dither_scale: None,
            floyd_dither_recommended: false,
            structured_ui_mapper_candidate: false,
            neutral_filter_recommended: false,
        });

        let phase_selected_gates = RegionalQuantizerGateOverrides {
            ordered: Some(Err("forced ordered rejection".to_string())),
            phase_pre_serialization: Some(Ok(())),
            phase_vs_ffmpeg: Some(Ok(())),
            phase_vs_comparison: Some(Ok(())),
            ..RegionalQuantizerGateOverrides::default()
        };
        let (phase_selected, phase_report) = attempt_regional_quantizer_with_gate_overrides(
            &source_rgba,
            &request,
            width,
            height,
            &palette,
            &regions,
            &global_palette_rgb,
            IndexedGifRepeat::Infinite,
            &mapped_rgba,
            &baseline_indices,
            &baseline,
            &phase_selected_gates,
        )
        .expect("run forced Phase rescue");
        assert_eq!(phase_report.selected_route_id, "phase_locked_pair_temporal");
        assert_eq!(phase_report.status, "encoded");
        assert!(phase_report.quality_gate_passed);
        assert_eq!(phase_report.logical_candidate_count, 2);
        assert_eq!(phase_report.serialization_count, 2);
        assert!(phase_report.temporal_selection.is_none());
        assert!(phase_report.error_diffusion_selection.is_none());
        let phase_selection = phase_report
            .phase_locked_pair_selection
            .as_ref()
            .expect("selected Phase report");
        assert_eq!(phase_selection.status, "candidate_selected");
        assert_eq!(phase_selection.comparison_route_id, "ffmpeg_mapper");
        assert_eq!(phase_selection.fallback_route_id, "ffmpeg_mapper");
        assert_eq!(phase_selection.fallback_indices_sha256.len(), 64);
        assert_eq!(phase_selection.input_contract_sha256.len(), 64);
        let phase_candidate = phase_selection
            .candidate
            .as_ref()
            .expect("selected Phase candidate");
        let (phase_serialized, _) = phase_selected.expect("selected Phase payload");
        assert_eq!(
            phase_candidate.serialized_bytes,
            Some(u64::try_from(phase_serialized.bytes.len()).unwrap())
        );
        assert_eq!(
            phase_serialized.palette_compaction_report.status,
            "compacted_single_pass_no_byte_comparison"
        );
        assert!(
            !phase_serialized
                .palette_compaction_report
                .real_byte_comparison_performed
        );
        assert!(
            !phase_serialized
                .palette_compaction_report
                .selection_gate_passed
        );
        assert!(phase_serialized
            .palette_compaction_report
            .baseline_serialized_bytes
            .is_none());
        assert!(phase_serialized
            .palette_compaction_report
            .serialized_byte_reduction_percent
            .is_none());

        let gate_artifact =
            quantize_rgb24_with_region_phase_locked_pair_temporal_with_delays_and_fallback(
                &source_rgb,
                width,
                height,
                &palette,
                &regions,
                &[4_u16; 3],
                TemporalHysteresisPolicy::CONSERVATIVE_V1,
                true,
                &baseline_indices,
                "ffmpeg_mapper",
            )
            .expect("build direct Phase gate fixture");
        let mut diagnostics = gate_artifact
            .report
            .phase_locked_pair
            .as_ref()
            .expect("direct Phase diagnostics")
            .clone();
        diagnostics.eligible_pixel_count = 1;
        diagnostics.changed_pixel_count = 1;
        diagnostics.pre_reject_changed_pixel_count = 1;
        diagnostics.stored_frame_early_reject_count = 0;
        diagnostics.protected_edge_index_change_count = 0;
        diagnostics.ineligible_index_change_count = 0;
        let baseline_reconstructed =
            opaque_rgba_to_rgb24(&mapped_rgba, "Phase gate baseline").unwrap();
        let gate_metrics =
            evaluate_rgb24_candidate(&source_rgb, &baseline_reconstructed, width, height)
                .expect("measure Phase gate baseline");
        let gate_timing = evaluate_timing_aware_temporal_residual(
            &source_rgb,
            &baseline_reconstructed,
            width,
            height,
            &[4_u16; 3],
            true,
        )
        .expect("measure Phase gate timing");
        let baseline_bytes = u64::try_from(baseline.bytes.len()).unwrap();
        let materially_smaller_bytes = baseline_bytes.saturating_mul(94) / 100;
        phase_locked_pair_selection_gate(
            &gate_metrics,
            &gate_metrics,
            &gate_timing,
            &gate_timing,
            materially_smaller_bytes,
            baseline_bytes,
            &diagnostics,
        )
        .expect("five-percent real-byte gain should pass unchanged quality");
        let no_gain = phase_locked_pair_selection_gate(
            &gate_metrics,
            &gate_metrics,
            &gate_timing,
            &gate_timing,
            baseline_bytes,
            baseline_bytes,
            &diagnostics,
        )
        .expect_err("Phase gate must require a material gain");
        assert!(no_gain.contains("no material gain"), "{no_gain}");
        let oversized = phase_locked_pair_selection_gate(
            &gate_metrics,
            &gate_metrics,
            &gate_timing,
            &gate_timing,
            baseline_bytes.saturating_mul(106).div_ceil(100),
            baseline_bytes,
            &diagnostics,
        )
        .expect_err("Phase gate must enforce the +5% byte ceiling");
        assert!(oversized.contains("serialized bytes exceeded +5%"));
        let mut protected_change = diagnostics.clone();
        protected_change.protected_edge_index_change_count = 1;
        let protected = phase_locked_pair_selection_gate(
            &gate_metrics,
            &gate_metrics,
            &gate_timing,
            &gate_timing,
            materially_smaller_bytes,
            baseline_bytes,
            &protected_change,
        )
        .expect_err("Phase gate must reject protected-edge changes");
        assert!(protected.contains("changed protected edge pixels"));

        for (ffmpeg_gate, comparison_gate, expected_status) in [
            (
                Err("forced Phase FFmpeg rejection".to_string()),
                Ok(()),
                "quality_gate_rejected",
            ),
            (
                Ok(()),
                Err("forced Phase comparison rejection".to_string()),
                "selection_gate_rejected",
            ),
        ] {
            let rejected_phase_gates = RegionalQuantizerGateOverrides {
                ordered: Some(Err("forced ordered rejection".to_string())),
                phase_pre_serialization: Some(Ok(())),
                phase_vs_ffmpeg: Some(ffmpeg_gate),
                phase_vs_comparison: Some(comparison_gate),
                ..RegionalQuantizerGateOverrides::default()
            };
            let (selected, rejected_phase_report) = attempt_regional_quantizer_with_gate_overrides(
                &source_rgba,
                &request,
                width,
                height,
                &palette,
                &regions,
                &global_palette_rgb,
                IndexedGifRepeat::Infinite,
                &mapped_rgba,
                &baseline_indices,
                &baseline,
                &rejected_phase_gates,
            )
            .expect("run forced Phase gate rejection");
            assert!(selected.is_none());
            assert_eq!(rejected_phase_report.selected_route_id, "ffmpeg_mapper");
            assert_eq!(rejected_phase_report.status, "quality_gate_rejected");
            assert_eq!(rejected_phase_report.serialization_count, 2);
            assert!(rejected_phase_report.error_diffusion_selection.is_none());
            let rejected_phase = rejected_phase_report
                .phase_locked_pair_selection
                .as_ref()
                .expect("rejected Phase report");
            assert_eq!(rejected_phase.status, expected_status);
            assert!(rejected_phase.candidate.is_some());
        }

        let selected_gates = RegionalQuantizerGateOverrides {
            ordered: Some(Err("forced ordered rejection".to_string())),
            phase_pre_serialization: Some(Err("forced phase pre-serialization skip".to_string())),
            error_diffusion_vs_ffmpeg: Some(Ok(())),
            error_diffusion_vs_comparison: Some(Ok(())),
            ..RegionalQuantizerGateOverrides::default()
        };
        let (selected, report) = attempt_regional_quantizer_with_gate_overrides(
            &source_rgba,
            &request,
            width,
            height,
            &palette,
            &regions,
            &global_palette_rgb,
            IndexedGifRepeat::Infinite,
            &mapped_rgba,
            &baseline_indices,
            &baseline,
            &selected_gates,
        )
        .expect("run forced independent diffusion challenge");
        assert_eq!(report.selected_route_id, "error_diffusion_temporal");
        assert_eq!(report.status, "encoded");
        assert!(report.quality_gate_passed);
        assert_eq!(report.logical_candidate_count, 3);
        assert_eq!(report.serialization_count, 2);
        assert!(report.temporal_selection.is_none());
        let skipped_phase = report
            .phase_locked_pair_selection
            .as_ref()
            .expect("pre-serialization Phase skip report");
        assert_eq!(skipped_phase.status, "candidate_skipped");
        let skipped_candidate = skipped_phase
            .candidate
            .as_ref()
            .expect("unmaterialized Phase diagnostics");
        assert!(skipped_candidate.serialized_bytes.is_none());
        assert!(skipped_candidate.indexed_timeline_sha256.is_none());
        assert!(skipped_candidate.serialized_gif_sha256.is_none());
        assert_eq!(skipped_phase.fallback_route_id, "ffmpeg_mapper");
        assert_eq!(skipped_phase.fallback_indices_sha256.len(), 64);
        assert_eq!(skipped_phase.source_rgb24_sha256.len(), 64);
        assert_eq!(skipped_phase.palette_sha256, palette.sha256);
        assert_eq!(skipped_phase.region_dither_sha256, regions.sha256);
        assert_eq!(skipped_phase.frame_delays_sha256.len(), 64);
        let diffusion = report
            .error_diffusion_selection
            .as_ref()
            .expect("independent diffusion report");
        assert_eq!(diffusion.comparison_route_id, "ffmpeg_mapper");
        assert_eq!(diffusion.status, "candidate_selected");
        let candidate = diffusion.candidate.as_ref().expect("diffusion candidate");
        let (serialized, reconstructed_rgba) = selected.expect("selected diffusion payload");
        assert_eq!(
            u64::try_from(serialized.bytes.len()).unwrap(),
            candidate.serialized_bytes
        );
        assert_eq!(
            format!("{:x}", Sha256::digest(&serialized.bytes)),
            candidate.serialized_gif_sha256
        );
        let reconstructed_rgb =
            opaque_rgba_to_rgb24(&reconstructed_rgba, "forced selected payload").unwrap();
        assert_eq!(
            format!("{:x}", Sha256::digest(&reconstructed_rgb)),
            candidate.reconstructed_rgb24_sha256
        );
        assert_eq!(
            report.candidate_serialized_bytes,
            Some(candidate.serialized_bytes)
        );
        assert_eq!(
            report.indices_sha256.as_deref(),
            Some(candidate.indices_sha256.as_str())
        );
        assert_eq!(
            report.artifact_sha256.as_deref(),
            Some(candidate.artifact_sha256.as_str())
        );
        let selected_metrics = serde_json::to_value(
            report
                .candidate_metrics
                .as_ref()
                .expect("selected diffusion metrics"),
        )
        .unwrap();
        assert_eq!(
            selected_metrics,
            serde_json::to_value(&candidate.metrics).unwrap()
        );

        let rejected_gates = RegionalQuantizerGateOverrides {
            ordered: Some(Err("forced ordered rejection".to_string())),
            phase_pre_serialization: Some(Err("forced phase pre-serialization skip".to_string())),
            error_diffusion_vs_ffmpeg: Some(Err("forced diffusion rejection".to_string())),
            error_diffusion_vs_comparison: Some(Ok(())),
            ..RegionalQuantizerGateOverrides::default()
        };
        let (selected, report) = attempt_regional_quantizer_with_gate_overrides(
            &source_rgba,
            &request,
            width,
            height,
            &palette,
            &regions,
            &global_palette_rgb,
            IndexedGifRepeat::Infinite,
            &mapped_rgba,
            &baseline_indices,
            &baseline,
            &rejected_gates,
        )
        .expect("run forced dual rejection");
        assert!(
            selected.is_none(),
            "rejected ordered payload escaped fallback"
        );
        assert_eq!(report.selected_route_id, "ffmpeg_mapper");
        assert_eq!(report.status, "quality_gate_rejected");
        assert!(!report.quality_gate_passed);
        assert!(report.candidate_metrics.is_none());
        assert!(report.candidate_serialized_bytes.is_none());
        assert!(report.indices_sha256.is_none());
        assert!(report.artifact_sha256.is_none());
        assert_eq!(report.secondary_choice_count, 0);
        assert_eq!(report.secondary_choice_by_class, [0; 4]);
        let diffusion = report
            .error_diffusion_selection
            .as_ref()
            .expect("rejected diffusion report");
        assert_eq!(diffusion.comparison_route_id, "ffmpeg_mapper");
        assert_eq!(diffusion.status, "quality_gate_rejected");

        let mut invalid_regions = regions.clone();
        invalid_regions.class_map.clear();
        let (selected, report) = attempt_regional_quantizer(
            &source_rgba,
            &request,
            width,
            height,
            &palette,
            &invalid_regions,
            &global_palette_rgb,
            IndexedGifRepeat::Infinite,
            &mapped_rgba,
            &baseline_indices,
            &baseline,
        )
        .expect("invalid regional plan must produce a measured fallback report");
        assert!(selected.is_none());
        assert_eq!(report.selected_route_id, "ffmpeg_mapper");
        assert_eq!(report.status, "candidate_failed");
        assert!(!report.quality_gate_passed);
        assert_eq!(report.logical_candidate_count, 1);
        assert_eq!(report.serialization_count, 0);
        assert!(report.ordered_candidate_elapsed_ms.is_some());
        assert!(report.temporal_candidate_elapsed_ms.is_none());
        assert!(report.error_diffusion_candidate_elapsed_ms.is_none());
        assert!(report.candidate_metrics.is_none());
        assert!(report.candidate_serialized_bytes.is_none());
        assert!(report.indices_sha256.is_none());
        assert!(report.artifact_sha256.is_none());
    }

    #[test]
    fn regional_quantizer_input_contract_hashes_bind_source_palette_regions_delays_and_fallback() {
        let kernel_config_sha256 = error_diffusion_v5_kernel_config_sha256();
        let baseline = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            &kernel_config_sha256,
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        let repeated = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            &kernel_config_sha256,
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        assert_eq!(
            baseline.input_contract_sha256,
            repeated.input_contract_sha256
        );
        assert_eq!(baseline.source_rgb24_sha256.len(), 64);
        assert_eq!(baseline.frame_delays_sha256.len(), 64);
        assert_eq!(baseline.fallback_route_id, "regional_ordered");
        assert_eq!(baseline.fallback_indices_sha256.len(), 64);

        let changed_delays = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[5, 6],
            IndexedGifRepeat::Infinite,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            &kernel_config_sha256,
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        let changed_repeat = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::None,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            &kernel_config_sha256,
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        let changed_source = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 7],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            &kernel_config_sha256,
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        let changed_kernel_config = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            "different-kernel-config",
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        let changed_fallback_indices = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            &kernel_config_sha256,
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 11],
            "regional_ordered",
        );
        let changed_fallback_route = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            ERROR_DIFFUSION_SPATIAL_KERNEL_ID,
            &kernel_config_sha256,
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "temporal_hysteresis",
        );
        let framed_left = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            "ab",
            "c",
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        let framed_right = regional_quantizer_input_contract_hashes(
            &[1, 2, 3, 4, 5, 6],
            2,
            1,
            "palette-a",
            "regions-a",
            &[4, 7],
            IndexedGifRepeat::Infinite,
            "a",
            "bc",
            TemporalHysteresisPolicy::CONSERVATIVE_V1,
            &[9, 10],
            "regional_ordered",
        );
        assert_ne!(
            baseline.input_contract_sha256,
            changed_delays.input_contract_sha256
        );
        assert_ne!(
            baseline.input_contract_sha256,
            changed_repeat.input_contract_sha256
        );
        assert_ne!(
            baseline.input_contract_sha256,
            changed_source.input_contract_sha256
        );
        assert_ne!(
            baseline.input_contract_sha256,
            changed_kernel_config.input_contract_sha256
        );
        assert_ne!(
            baseline.input_contract_sha256,
            changed_fallback_indices.input_contract_sha256
        );
        assert_ne!(
            baseline.input_contract_sha256,
            changed_fallback_route.input_contract_sha256
        );
        assert_ne!(
            framed_left.input_contract_sha256, framed_right.input_contract_sha256,
            "length framing must prevent adjacent variable fields from aliasing"
        );
    }

    #[test]
    fn phase_locked_pair_contract_binds_loop_delays_and_ffmpeg_fallback() {
        let kernel_config = phase_locked_pair_kernel_config_sha256();
        let contract = |delays: &[u16], repeat| {
            regional_quantizer_input_contract_hashes(
                &[1, 2, 3, 4, 5, 6],
                2,
                1,
                "phase-palette",
                "phase-regions",
                delays,
                repeat,
                PHASE_LOCKED_PAIR_SPATIAL_KERNEL_ID,
                &kernel_config,
                TemporalHysteresisPolicy::CONSERVATIVE_V1,
                &[9, 10],
                "ffmpeg_mapper",
            )
        };
        let infinite = contract(&[4, 7], IndexedGifRepeat::Infinite);
        let different_delays = contract(&[5, 6], IndexedGifRepeat::Infinite);
        let no_loop = contract(&[4, 7], IndexedGifRepeat::None);
        assert_eq!(infinite.fallback_route_id, "ffmpeg_mapper");
        assert_eq!(infinite.fallback_indices_sha256.len(), 64);
        assert_eq!(infinite.kernel_config_sha256, kernel_config);
        assert_ne!(
            infinite.input_contract_sha256,
            different_delays.input_contract_sha256
        );
        assert_ne!(
            infinite.input_contract_sha256,
            no_loop.input_contract_sha256
        );
    }

    #[test]
    fn regional_serialization_budget_rejects_a_fourth_real_write_without_incrementing() {
        let mut budget = RegionalQuantizerBudgetTracker {
            serialization_count: MAX_REGIONAL_CANDIDATE_SERIALIZATIONS,
            ..RegionalQuantizerBudgetTracker::default()
        };
        let error = budget
            .reserve_serialization()
            .expect_err("a fourth regional stream must be rejected");
        assert!(error.to_string().contains("budget exceeded"), "{error}");
        assert_eq!(
            budget.serialization_count,
            MAX_REGIONAL_CANDIDATE_SERIALIZATIONS
        );
    }

    #[test]
    fn regional_single_pass_rejects_transparency_before_any_hidden_byte_search() {
        let plan = IndexedGifPlan {
            width: 1,
            height: 1,
            global_palette_rgb: vec![0, 0, 0, 255, 255, 255],
            repeat: IndexedGifRepeat::None,
            frames: vec![IndexedGifFrame {
                left: 0,
                top: 0,
                width: 1,
                height: 1,
                delay_cs: 4,
                disposal: IndexedGifDisposal::Keep,
                transparent_index: Some(1),
                local_palette_rgb: None,
                indices: vec![1],
            }],
        };
        let mut budget = RegionalQuantizerBudgetTracker::default();
        let error = match serialize_regional_indexed_candidate_tracked(&plan, &mut budget) {
            Ok(_) => panic!("transparent regional plan reached serialization"),
            Err(error) => error,
        };
        assert!(error.to_string().contains("does not accept transparent"));
        assert_eq!(budget.serialization_count, 0);
    }

    #[test]
    fn temporal_quantizer_real_bytes_and_decoded_pixels_select_a_micro_noise_gain() {
        let width = 16_u16;
        let height = 16_u16;
        let pixels_per_frame = usize::from(width) * usize::from(height);
        let source_rgb = [99_u8, 101, 99, 101, 99]
            .into_iter()
            .flat_map(|value| {
                (0..pixels_per_frame).flat_map(move |pixel_index| {
                    let value = if pixel_index < 8 { value } else { 96 };
                    [value, value, value]
                })
            })
            .collect::<Vec<_>>();
        let source_rgba = rgb24_to_opaque_rgba(&source_rgb);

        let mut rgba = Vec::with_capacity(256 * 4);
        rgba.extend_from_slice(&[96, 96, 96, 255]);
        rgba.extend_from_slice(&[104, 104, 104, 255]);
        for _ in 2..255 {
            rgba.extend_from_slice(&[104, 104, 104, 255]);
        }
        rgba.extend_from_slice(&[0, 0, 0, 0]);
        let palette = OklabPaletteArtifact {
            sha256: format!("{:x}", Sha256::digest(&rgba)),
            rgba,
            emitted_colors: 3,
            sampled_frame_count: 5,
            sampled_pixel_count: u64::try_from(pixels_per_frame * 5).unwrap(),
            weighted_sample_mass: (pixels_per_frame * 5) as f64,
            weighted_histogram_mean_oklab_error: 0.0,
            weighted_histogram_p95_oklab_error: 0.0,
        };
        let global_palette_rgb = palette
            .rgba
            .chunks_exact(4)
            .flat_map(|entry| [entry[0], entry[1], entry[2]])
            .collect::<Vec<_>>();
        let regions = RegionDitherArtifact {
            grid_width: 2,
            grid_height: 1,
            class_map: vec![0, 0],
            strength_map: vec![0, 0],
            class_counts: [2, 0, 0, 0],
            sampled_frame_count: 5,
            sampled_pixel_count: u64::try_from(pixels_per_frame * 5).unwrap(),
            weighted_sample_mass: (pixels_per_frame * 5) as f64,
            mean_dither_strength: 0.0,
            mean_spatial_std: 0.0,
            mean_edge: 0.0,
            mean_skin_ratio: 0.0,
            mean_temporal_delta: 2.0 / 255.0,
            mean_high_frequency_noise: 0.0,
            class_map_sha256: "flat-classes".to_string(),
            strength_map_sha256: "zero-strength".to_string(),
            sha256: "micro-noise-regions".to_string(),
        };
        let ordered = quantize_rgb24_with_region(&source_rgb, width, height, &palette, &regions)
            .expect("quantize ordered baseline");
        let mapped_rgba = rgb24_to_opaque_rgba(&ordered.reconstructed_rgb24);
        let baseline_indices = ordered.indices;
        let delays = vec![10_u16; 5];
        let baseline_plan = full_frame_indexed_plan(
            baseline_indices.clone(),
            width,
            height,
            &delays,
            &global_palette_rgb,
            IndexedGifRepeat::None,
        )
        .expect("build ordered baseline plan");
        let baseline = serialize_optimized_indexed_candidate(&baseline_plan)
            .expect("serialize ordered baseline");
        let mut request = request_with_speed(1.0);
        request.allow_experimental = true;
        request.perceptual_selection = Some(PerceptualSelection {
            keep_indices: (0_u32..5).collect(),
            source_frame_count: 5,
            final_delay_cs: 10,
            frame_delays_cs: delays,
            palette: Some(palette.clone()),
            structured_ui_standard_palette: None,
            palette_sequence: None,
            region_dither: Some(regions.clone()),
            color_eq_recommended: false,
            bayer_dither_scale: None,
            floyd_dither_recommended: false,
            structured_ui_mapper_candidate: false,
            neutral_filter_recommended: false,
        });

        let (selected, report) = attempt_regional_quantizer(
            &source_rgba,
            &request,
            width,
            height,
            &palette,
            &regions,
            &global_palette_rgb,
            IndexedGifRepeat::None,
            &mapped_rgba,
            &baseline_indices,
            &baseline,
        )
        .expect("run temporal dual candidate");
        assert_eq!(
            report.selected_route_id, "temporal_hysteresis",
            "{report:?}"
        );
        let temporal = report
            .temporal_selection
            .as_ref()
            .unwrap_or_else(|| panic!("missing temporal report: {report:?}"));
        assert_eq!(temporal.status, "candidate_selected", "{temporal:?}");
        let candidate = temporal
            .candidate
            .as_ref()
            .unwrap_or_else(|| panic!("missing temporal candidate: {temporal:?}"));
        assert!(candidate.temporal_hold_count > 0, "{candidate:?}");
        assert!(
            candidate.serialized_bytes < temporal.baseline.serialized_bytes,
            "{temporal:?}"
        );
        assert!(
            candidate.metrics.static_temporal_residual
                < temporal.baseline.metrics.static_temporal_residual,
            "{temporal:?}"
        );
        assert_eq!(report.logical_candidate_count, 3, "{report:?}");
        assert_eq!(report.serialization_count, 3, "{report:?}");
        assert!(report.ordered_candidate_elapsed_ms.is_some(), "{report:?}");
        assert!(report.temporal_candidate_elapsed_ms.is_some(), "{report:?}");
        assert!(
            report.phase_locked_pair_candidate_elapsed_ms.is_some(),
            "{report:?}"
        );
        assert!(
            report.error_diffusion_candidate_elapsed_ms.is_none(),
            "{report:?}"
        );
        assert!(report.error_diffusion_selection.is_none(), "{report:?}");
        let phase = report
            .phase_locked_pair_selection
            .as_ref()
            .unwrap_or_else(|| panic!("missing phase-locked pair report: {report:?}"));
        assert_eq!(
            phase.selector_id,
            "rust.oklab.phase_locked_pair_triple_candidate.v1"
        );
        assert_eq!(
            phase.max_hold_frames,
            TemporalHysteresisPolicy::CONSERVATIVE_V1.max_hold_frames
        );
        assert_eq!(
            phase.max_hold_duration_cs,
            TemporalHysteresisPolicy::CONSERVATIVE_V1.max_hold_duration_cs
        );
        assert_eq!(phase.spatial_kernel_id, PHASE_LOCKED_PAIR_SPATIAL_KERNEL_ID);
        assert_eq!(phase.source_rgb24_sha256.len(), 64);
        assert_eq!(phase.palette_sha256, palette.sha256);
        assert_eq!(phase.region_dither_sha256, regions.sha256);
        assert_eq!(phase.frame_delays_sha256.len(), 64);
        assert_eq!(phase.fallback_route_id, "ffmpeg_mapper");
        assert_eq!(phase.fallback_indices_sha256.len(), 64);
        assert_eq!(phase.kernel_config_sha256.len(), 64);
        assert_eq!(phase.input_contract_sha256.len(), 64);
        assert_eq!(
            phase.ffmpeg_baseline_serialized_bytes,
            u64::try_from(baseline.bytes.len()).unwrap()
        );
        assert_eq!(phase.ffmpeg_baseline_indexed_timeline_sha256.len(), 64);
        assert_eq!(phase.ffmpeg_baseline_serialized_gif_sha256.len(), 64);
        let phase_candidate = phase
            .candidate
            .as_ref()
            .unwrap_or_else(|| panic!("missing phase-locked pair candidate: {phase:?}"));
        assert_eq!(phase_candidate.indices_sha256.len(), 64);
        assert_eq!(phase_candidate.reconstructed_rgb24_sha256.len(), 64);
        assert_eq!(phase_candidate.artifact_sha256.len(), 64);
        assert_eq!(
            phase_candidate
                .indexed_timeline_sha256
                .as_deref()
                .map(str::len),
            Some(64)
        );
        assert_eq!(
            phase_candidate
                .serialized_gif_sha256
                .as_deref()
                .map(str::len),
            Some(64)
        );
        assert_eq!(phase_candidate.eligibility_mask_sha256.len(), 64);
        assert_eq!(phase_candidate.edge_protection_mask_sha256.len(), 64);
        assert_eq!(phase_candidate.fallback_route_id, phase.fallback_route_id);
        assert_eq!(
            phase_candidate.fallback_indices_sha256,
            phase.fallback_indices_sha256
        );
        assert_eq!(
            phase_candidate.kernel_config_sha256, phase.kernel_config_sha256,
            "the measured candidate and its input contract must identify one kernel config"
        );
        let serialized_report = serde_json::to_value(&report).expect("serialize regional report");
        assert_eq!(serialized_report["logical_candidate_count"], 3);
        assert_eq!(serialized_report["serialization_count"], 3);
        assert_eq!(
            serialized_report["phase_locked_pair_selection"]["source_rgb24_sha256"]
                .as_str()
                .map(str::len),
            Some(64)
        );
        assert_eq!(
            serialized_report["phase_locked_pair_selection"]["candidate"]["serialized_gif_sha256"]
                .as_str()
                .map(str::len),
            Some(64)
        );
        for field in [
            "eligible_pixel_count",
            "paired_pixel_count",
            "pair_candidate_count",
            "changed_pixel_count",
            "protected_edge_index_change_count",
            "fallback_preserved_pixel_count",
            "ineligible_index_change_count",
            "temporal_candidate_count",
            "temporal_hold_count",
            "stored_frame_early_reject_count",
            "loop_seeded_pixel_count",
        ] {
            assert!(
                serialized_report["phase_locked_pair_selection"]["candidate"][field].is_u64(),
                "missing serialized phase-locked pair diagnostic {field}"
            );
        }
        let (selected, reconstructed_rgba) =
            selected.unwrap_or_else(|| panic!("temporal candidate was not published: {report:?}"));
        assert_eq!(
            u64::try_from(selected.bytes.len()).unwrap(),
            candidate.serialized_bytes
        );
        let output_dir = isolated_smoke_dir("gifp-temporal-micro-noise");
        fs::create_dir_all(&output_dir).expect("create temporal smoke directory");
        let output = output_dir.join("temporal-micro-noise.gif");
        fs::write(&output, &selected.bytes).expect("write temporal GIF");
        let decoded = decode_media_rgba(
            &locate_ffmpeg().expect("locate FFmpeg for temporal decode"),
            &output,
        )
        .expect("decode temporal GIF");
        assert_eq!(decoded, reconstructed_rgba);
        let _ = fs::remove_dir_all(output_dir);
    }

