    #[test]
    fn transparent_disposal_byte_search_matches_independent_ffmpeg_decode() {
        let width = 8_u16;
        let height = 4_u16;
        let mut palette = vec![0_u8; 256 * 3];
        palette[0..3].copy_from_slice(&[245, 88, 92]);
        palette[3..6].copy_from_slice(&[45, 204, 128]);
        let frame_pixels = usize::from(width) * usize::from(height);
        let sprite_frames = [(0_usize, 0_u8), (2, 0), (2, 1), (5, 0)];
        let mut expected_rgba = Vec::with_capacity(sprite_frames.len() * frame_pixels * 4);
        let frames = sprite_frames
            .iter()
            .map(|(left, color_index)| {
                let mut indices = vec![GIF_TRANSPARENT_INDEX; frame_pixels];
                for y in 1..=2 {
                    for x in *left..*left + 2 {
                        indices[y * usize::from(width) + x] = *color_index;
                    }
                }
                for value in &indices {
                    if *value == GIF_TRANSPARENT_INDEX {
                        expected_rgba.extend_from_slice(&[0, 0, 0, 0]);
                    } else {
                        let offset = usize::from(*value) * 3;
                        expected_rgba.extend_from_slice(&[
                            palette[offset],
                            palette[offset + 1],
                            palette[offset + 2],
                            u8::MAX,
                        ]);
                    }
                }
                IndexedGifFrame {
                    left: 0,
                    top: 0,
                    width,
                    height,
                    delay_cs: 8,
                    disposal: IndexedGifDisposal::Keep,
                    transparent_index: Some(GIF_TRANSPARENT_INDEX),
                    local_palette_rgb: None,
                    indices,
                }
            })
            .collect();
        let source = IndexedGifPlan {
            width,
            height,
            global_palette_rgb: palette,
            repeat: IndexedGifRepeat::None,
            frames,
        };

        let candidate =
            serialize_optimized_indexed_candidate(&source).expect("optimize transparent timeline");
        assert_eq!(candidate.optimization_report.disposal_candidate_count, 3);
        assert!(candidate.optimization_report.disposal_simulation_verified);
        assert!(candidate.palette_compaction_report.selection_gate_passed);
        assert_eq!(
            candidate
                .palette_compaction_report
                .original_global_palette_entries,
            256
        );
        assert_eq!(
            candidate
                .palette_compaction_report
                .selected_global_palette_entries,
            4
        );
        assert!(
            candidate
                .palette_compaction_report
                .compacted_serialized_bytes
                < candidate
                    .palette_compaction_report
                    .baseline_serialized_bytes
                    .expect("two-pass compaction observed baseline bytes")
        );
        assert!(
            candidate
                .optimization_report
                .background_disposal_frame_count
                + candidate.optimization_report.previous_disposal_frame_count
                > 0,
            "{:?}",
            candidate.optimization_report
        );

        let output_dir = isolated_smoke_dir("gifp-transparent-disposal-decode");
        fs::create_dir_all(&output_dir).expect("create transparent disposal test directory");
        let output = output_dir.join("transparent-disposal.gif");
        fs::write(&output, &candidate.bytes).expect("write transparent disposal candidate");
        assert!(
            verify_gif_indexed_plan_palette(&output, &candidate.optimized_plan)
                .expect("verify compacted palette contract")
        );
        let decoded = decode_media_rgba(
            &locate_ffmpeg().expect("locate FFmpeg for transparent disposal decode"),
            &output,
        )
        .expect("decode transparent disposal candidate");
        assert_eq!(
            canonicalize_transparent_rgb(decoded),
            canonicalize_transparent_rgb(expected_rgba)
        );

        let _ = fs::remove_file(output);
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    fn transparent_reconstruction_uses_rgba_safe_local_tables_when_color_union_exceeds_255() {
        let width = 20_u16;
        let height = 10_u16;
        let frame_pixels = usize::from(width) * usize::from(height);
        let mut rgba = Vec::with_capacity(frame_pixels * 4 * 2);
        for frame in 0..2_u8 {
            rgba.extend_from_slice(&[0, 0, 0, 0]);
            for pixel in 1..frame_pixels {
                rgba.extend_from_slice(&[
                    pixel as u8,
                    frame.saturating_add(1),
                    (pixel / 128) as u8,
                    u8::MAX,
                ]);
            }
        }
        let plan = transparent_full_frame_plan_from_decoded_rgba(
            &rgba,
            width,
            height,
            &[7, 9],
            IndexedGifRepeat::None,
        )
        .expect("reconstruct local-table transparent timeline");
        assert!(plan.frames.iter().all(|frame| frame
            .local_palette_rgb
            .as_ref()
            .is_some_and(|table| table.len() == 768)));
        let candidate =
            serialize_optimized_indexed_candidate(&plan).expect("serialize local-table timeline");
        assert_eq!(candidate.write_report.local_palette_frame_count, 2);
        assert!(candidate.optimization_report.disposal_simulation_verified);

        let output_dir = isolated_smoke_dir("gifp-transparent-local-table");
        fs::create_dir_all(&output_dir).expect("create transparent local-table directory");
        let output = output_dir.join("local-table.gif");
        fs::write(&output, candidate.bytes).expect("write transparent local-table GIF");
        assert_eq!(
            canonicalize_transparent_rgb(
                decode_media_rgba(
                    &locate_ffmpeg().expect("locate FFmpeg for local-table decode"),
                    &output,
                )
                .expect("decode transparent local-table GIF")
            ),
            canonicalize_transparent_rgb(rgba)
        );

        let _ = fs::remove_file(output);
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    fn transparent_postprocessor_publishes_only_a_smaller_verified_candidate() {
        let ffmpeg = locate_ffmpeg().expect("locate FFmpeg for transparent postprocessor");
        let width = 64_u16;
        let height = 32_u16;
        let frame_pixels = usize::from(width) * usize::from(height);
        let mut palette = vec![0_u8; 256 * 3];
        palette[0..3].copy_from_slice(&[83, 214, 138]);
        let frames = (0..18_usize)
            .map(|frame_index| {
                let mut indices = vec![GIF_TRANSPARENT_INDEX; frame_pixels];
                let left = (frame_index * 3) % (usize::from(width) - 3);
                let top = 12_usize;
                for y in top..top + 3 {
                    for x in left..left + 3 {
                        indices[y * usize::from(width) + x] = 0;
                    }
                }
                IndexedGifFrame {
                    left: 0,
                    top: 0,
                    width,
                    height,
                    delay_cs: 6,
                    disposal: IndexedGifDisposal::Background,
                    transparent_index: Some(GIF_TRANSPARENT_INDEX),
                    local_palette_rgb: None,
                    indices,
                }
            })
            .collect();
        let plan = IndexedGifPlan {
            width,
            height,
            global_palette_rgb: palette,
            repeat: IndexedGifRepeat::Infinite,
            frames,
        };
        let output_dir = isolated_smoke_dir("gifp-transparent-postprocessor");
        fs::create_dir_all(&output_dir).expect("create transparent postprocessor directory");
        let output = output_dir.join("baseline.gif");
        let mut baseline_bytes = Vec::new();
        write_indexed_gif(&mut baseline_bytes, &plan).expect("write transparent baseline");
        fs::write(&output, &baseline_bytes).expect("persist transparent baseline");
        let baseline_rgba = canonicalize_transparent_rgb(
            decode_media_rgba(&ffmpeg, &output).expect("decode transparent baseline"),
        );

        let result = postprocess_transparent_gif_with_rust(&ffmpeg, &output, true)
            .expect("postprocess transparent baseline");
        assert!(result.published, "{:?}", result.report);
        assert_eq!(result.report.status, "encoded_default");
        assert!(result.report.disposal_candidate_count >= 2);
        assert!(result.report.decoded_pixel_parity_verified);
        assert!(
            result.report.candidate_serialized_bytes < result.report.baseline_serialized_bytes,
            "{:?}",
            result.report
        );
        assert_eq!(
            canonicalize_transparent_rgb(
                decode_media_rgba(&ffmpeg, &output).expect("decode published transparent GIF")
            ),
            baseline_rgba
        );

        let _ = fs::remove_file(output);
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    fn best_gif_transparent_source_reaches_disposal_search_without_opaque_perceptual_failure() {
        let width = 48_u16;
        let height = 32_u16;
        let frame_pixels = usize::from(width) * usize::from(height);
        let mut palette = vec![0_u8; 256 * 3];
        palette[0..3].copy_from_slice(&[73, 211, 132]);
        palette[3..6].copy_from_slice(&[255, 220, 96]);
        let frames = (0..12_usize)
            .map(|frame_index| {
                let mut indices = vec![GIF_TRANSPARENT_INDEX; frame_pixels];
                let left = (frame_index * 3) % (usize::from(width) - 4);
                for y in 13..17 {
                    for x in left..left + 4 {
                        indices[y * usize::from(width) + x] = (frame_index % 2) as u8;
                    }
                }
                IndexedGifFrame {
                    left: 0,
                    top: 0,
                    width,
                    height,
                    delay_cs: 8,
                    disposal: IndexedGifDisposal::Background,
                    transparent_index: Some(GIF_TRANSPARENT_INDEX),
                    local_palette_rgb: None,
                    indices,
                }
            })
            .collect();
        let plan = IndexedGifPlan {
            width,
            height,
            global_palette_rgb: palette,
            repeat: IndexedGifRepeat::Infinite,
            frames,
        };
        let output_dir = isolated_smoke_dir("gifp-transparent-best-route");
        fs::create_dir_all(&output_dir).expect("create transparent best-route directory");
        let input = output_dir.join("transparent-source.gif");
        let mut input_bytes = Vec::new();
        write_indexed_gif(&mut input_bytes, &plan).expect("write transparent source fixture");
        fs::write(&input, input_bytes).expect("persist transparent source fixture");

        let mut request = request_with_speed(1.0);
        request.input_path = input.to_string_lossy().to_string();
        request.output_dir = output_dir.to_string_lossy().to_string();
        request.width = 96;
        request.fps = 12;
        request.colors = 32;
        request.encoder = "ffmpeg_fast".to_string();
        request.filter_style = "original".to_string();
        request.generation_mode = "best_gif".to_string();
        request.allow_experimental = false;

        let result = convert_animation_inner(request).expect("encode transparent best GIF");
        let writer = result
            .indexed_gif_writer_report
            .as_ref()
            .unwrap_or_else(|| panic!("missing transparent writer report: {result:?}"));
        assert_ne!(writer.status, "fallback_ffmpeg", "{writer:?}");
        assert!(writer.disposal_candidate_count >= 2, "{writer:?}");
        assert!(writer.disposal_simulation_verified, "{writer:?}");
        assert!(writer.decoded_pixel_parity_verified, "{writer:?}");
        assert!(writer.baseline_serialized_bytes.is_some(), "{writer:?}");
        assert!(writer.candidate_serialized_bytes.is_some(), "{writer:?}");
        assert!(result.perceptual_report.is_none(), "{result:?}");
        assert!(
            result
                .fallback_reason
                .as_deref()
                .is_none_or(|reason| !reason.contains("perceptual analysis failed")),
            "{result:?}"
        );
        assert!(result.output_has_alpha, "{result:?}");
        if writer.status == "encoded_default" {
            assert_eq!(result.backend_id, "rust.indexed_gif.transparent");
            assert!(
                writer.candidate_serialized_bytes < writer.baseline_serialized_bytes,
                "{writer:?}"
            );
        } else {
            assert_eq!(writer.status, "baseline_retained", "{writer:?}");
            assert_eq!(result.backend_id, "ffmpeg.animation", "{result:?}");
        }

        let _ = fs::remove_file(result.output_path);
        let _ = fs::remove_file(input);
        let _ = fs::remove_dir_all(output_dir);
    }

    #[test]
    fn real_static_gradient_promotes_the_verified_indexed_writer_by_default() {
        let output_dir = isolated_smoke_dir("gifp-indexed-writer-smoke");
        fs::create_dir_all(&output_dir).expect("create indexed writer smoke directory");
        let input = output_dir.join("static-gradient.mkv");
        let ffmpeg = locate_ffmpeg().expect("locate FFmpeg");
        let generated = Command::new(&ffmpeg)
            .arg("-y")
            .arg("-hide_banner")
            .arg("-loglevel")
            .arg("error")
            .arg("-f")
            .arg("lavfi")
            .arg("-i")
            .arg("gradients=s=320x180:r=12:d=1:c0=0xECE5D6:c1=0x8DC7B1:c2=0x527B73:n=3:x0=0:y0=0:x1=320:y1=180:speed=0:seed=109")
            .arg("-pix_fmt")
            .arg("yuv444p")
            .arg("-c:v")
            .arg("ffv1")
            .arg(&input)
            .output_for_conversion_task()
            .expect("generate accepted regional-gradient fixture");
        assert!(
            generated.status.success(),
            "{}",
            String::from_utf8_lossy(&generated.stderr)
        );

        let mut request = request_with_speed(1.0);
        request.input_path = input.to_string_lossy().to_string();
        request.output_dir = output_dir.to_string_lossy().to_string();
        request.width = 320;
        request.fps = 12;
        request.colors = 96;
        request.filter_style = "original".to_string();
        request.generation_mode = "best_gif".to_string();
        request.perceptual_focus = "auto".to_string();
        request.allow_experimental = true;

        let mut default_request = request.clone();
        default_request.allow_experimental = false;
        let default_result = convert_animation_inner(default_request)
            .expect("encode default static-gradient writer");
        let result = convert_animation_inner(request).expect("encode with Rust indexed writer");
        let writer = result
            .indexed_gif_writer_report
            .as_ref()
            .unwrap_or_else(|| panic!("indexed writer report: {result:?}"));
        let perceptual = result
            .perceptual_report
            .as_ref()
            .unwrap_or_else(|| panic!("perceptual report: {result:?}"));
        let palette = result
            .palette_report
            .as_ref()
            .unwrap_or_else(|| panic!("palette report: {result:?}"));
        assert_eq!(
            result.backend_id, "rust.indexed_gif.experimental",
            "{result:?}"
        );
        assert_eq!(writer.status, "encoded_experimental", "{writer:?}");
        assert_eq!(writer.container_backend, "image-gif 0.14.2");
        assert!(writer.decoded_pixel_parity_verified, "{writer:?}");
        assert!(writer.disposal_simulation_verified, "{writer:?}");
        assert_eq!(writer.writer_input_rgba_sha256, writer.decoded_rgba_sha256);
        assert_ne!(
            writer.ffmpeg_mapped_rgba_sha256,
            writer.writer_input_rgba_sha256,
            "an accepted regional candidate must remain distinguishable from its FFmpeg mapping baseline"
        );
        let quantizer = writer
            .regional_quantizer_report
            .as_ref()
            .unwrap_or_else(|| panic!("regional quantizer report: {writer:?}"));
        assert_eq!(
            quantizer.quantizer_id,
            "rust.oklab.regional_phase_temporal_budgeted.v4"
        );
        assert_eq!(quantizer.gate_id, "multiscale_banding_proxy_v5");
        assert_eq!(quantizer.status, "encoded", "{quantizer:?}");
        assert!(quantizer.quality_gate_passed, "{quantizer:?}");
        assert!(
            matches!(
                quantizer.selected_route_id.as_str(),
                "regional_ordered"
                    | "temporal_hysteresis"
                    | "phase_locked_pair_temporal"
                    | "error_diffusion_temporal"
            ),
            "{quantizer:?}"
        );
        match quantizer.selected_route_id.as_str() {
            "temporal_hysteresis" => {
                assert_eq!(result.encoder_used, "rust_indexed_gif_temporal_quantizer");
                assert_eq!(
                    result.palette_strategy,
                    "perceptual_vfr+oklab_global+rust_temporal+rust_writer"
                );
            }
            "regional_ordered" => {
                assert_eq!(result.encoder_used, "rust_indexed_gif_regional_quantizer");
                assert_eq!(
                    result.palette_strategy,
                    "perceptual_vfr+oklab_global+rust_regional+rust_writer"
                );
            }
            "error_diffusion_temporal" => {
                assert_eq!(result.encoder_used, "rust_indexed_gif_error_diffusion");
                assert_eq!(
                    result.palette_strategy,
                    "perceptual_vfr+oklab_global+rust_error_diffusion_temporal+rust_writer"
                );
            }
            "phase_locked_pair_temporal" => {
                assert_eq!(result.encoder_used, "rust_indexed_gif_phase_locked_pair");
                assert_eq!(
                    result.palette_strategy,
                    "perceptual_vfr+oklab_global+rust_phase_locked_pair_temporal+rust_writer"
                );
            }
            route => panic!("unexpected regional route {route}: {result:?}"),
        }
        let temporal = quantizer
            .temporal_selection
            .as_ref()
            .unwrap_or_else(|| panic!("temporal selection report: {quantizer:?}"));
        assert!(temporal.candidate.is_some(), "{temporal:?}");
        assert!(temporal.baseline.serialized_bytes > 0, "{temporal:?}");
        let phase = quantizer
            .phase_locked_pair_selection
            .as_ref()
            .unwrap_or_else(|| panic!("phase-locked pair selection report: {quantizer:?}"));
        assert!(phase.candidate.is_some(), "{phase:?}");
        assert!(
            quantizer.error_diffusion_selection.is_none(),
            "{quantizer:?}"
        );
        assert!(quantizer.candidate_metrics.is_some(), "{quantizer:?}");
        assert!(quantizer.baseline_metrics.is_some(), "{quantizer:?}");
        assert!(quantizer.secondary_choice_count > 0, "{quantizer:?}");
        assert!(quantizer.indices_sha256.is_some(), "{quantizer:?}");
        assert!(quantizer.artifact_sha256.is_some(), "{quantizer:?}");
        assert_eq!(quantizer.logical_candidate_count, 3, "{quantizer:?}");
        assert_eq!(quantizer.serialization_count, 3, "{quantizer:?}");
        // One indexed candidate plus the final stable FFmpeg comparison.
        assert_eq!(result.attempts, 2, "{result:?}");
        let metrics = quantizer
            .candidate_metrics
            .as_ref()
            .unwrap_or_else(|| panic!("missing multiscale metrics: {quantizer:?}"));
        assert!(
            metrics.multiscale_low_frequency_oklab_error.is_finite(),
            "{metrics:?}"
        );
        assert!(metrics.edge_gradient_error.is_finite(), "{metrics:?}");
        assert!(
            metrics.multiscale_static_temporal_residual.is_finite(),
            "{metrics:?}"
        );
        assert_eq!(writer.frame_count, perceptual.kept_frame_count);
        assert_eq!(writer.total_indexed_pixels, writer.optimized_indexed_pixels);
        assert!(
            writer.optimized_indexed_pixels <= writer.original_indexed_pixels,
            "{writer:?}"
        );
        assert!(writer.full_frame_count >= 1, "{writer:?}");
        assert!(
            writer.rectangle_frame_count < writer.frame_count,
            "{writer:?}"
        );
        assert_eq!(writer.total_delay_cs * 10, perceptual.output_duration_ms);
        assert_eq!(u64::from(writer.frame_count), result.output_frame_count);
        assert!(perceptual.aggregate_timeline_verified, "{perceptual:?}");
        assert!(palette.global_color_table_verified, "{palette:?}");
        assert_eq!(palette.histogram_precision_bits, 6, "{palette:?}");
        assert!(result.fallback_reason.is_none(), "{result:?}");
        assert!(result.warnings.is_empty(), "{result:?}");
        assert_eq!(
            default_result.backend_id, "rust.indexed_gif",
            "{default_result:?}"
        );
        let default_writer = default_result
            .indexed_gif_writer_report
            .as_ref()
            .unwrap_or_else(|| panic!("default indexed writer report: {default_result:?}"));
        assert_eq!(
            default_writer.status, "encoded_default",
            "{default_writer:?}"
        );
        let default_quantizer = default_writer
            .regional_quantizer_report
            .as_ref()
            .unwrap_or_else(|| panic!("default quantizer report: {default_writer:?}"));
        assert_eq!(default_quantizer.logical_candidate_count, 1);
        assert_eq!(default_quantizer.serialization_count, 1);
        assert!(default_quantizer.ordered_candidate_elapsed_ms.is_some());
        assert!(default_quantizer.temporal_candidate_elapsed_ms.is_none());
        assert!(default_quantizer
            .phase_locked_pair_candidate_elapsed_ms
            .is_none());
        assert!(default_quantizer
            .error_diffusion_candidate_elapsed_ms
            .is_none());
        assert!(default_quantizer.temporal_selection.is_none());
        assert!(default_quantizer.phase_locked_pair_selection.is_none());
        assert!(default_quantizer.error_diffusion_selection.is_none());
        // The internally Pareto-verified default writer no longer pays for a
        // redundant final Fast comparison.
        assert_eq!(default_result.attempts, 1, "{default_result:?}");
        assert!(default_result
            .perceptual_report
            .as_ref()
            .is_some_and(|report| report.static_gradient_writer_recommended));
        assert_eq!(
            default_result
                .palette_report
                .as_ref()
                .map(|report| report.histogram_precision_bits),
            Some(6)
        );
        assert_eq!(default_result.output_frame_count, result.output_frame_count);
        assert_eq!(
            default_result
                .perceptual_report
                .as_ref()
                .map(|report| report.output_duration_ms),
            Some(perceptual.output_duration_ms)
        );
        assert_eq!(
            decode_media_rgba(
                &locate_ffmpeg().expect("locate FFmpeg for writer parity decode"),
                Path::new(&default_result.output_path),
            )
            .expect("decode default Rust writer"),
            decode_media_rgba(
                &locate_ffmpeg().expect("locate FFmpeg for regional decode"),
                Path::new(&result.output_path),
            )
            .expect("decode Rust regional output"),
            "the default promotion must preserve the verified experimental pixels"
        );

        let _ = fs::remove_file(default_result.output_path);
        let _ = fs::remove_file(result.output_path);
        let _ = fs::remove_dir_all(output_dir);
    }

