    #[test]
    #[ignore = "requires GIFP_LIVE_PHOTO_INPUT pointing to a real video"]
    fn real_live_photo_user_material_publishes_a_verified_pair() {
        let input = std::env::var_os("GIFP_LIVE_PHOTO_INPUT")
            .map(PathBuf::from)
            .expect("set GIFP_LIVE_PHOTO_INPUT to a real MP4 or MOV");
        assert!(
            input.is_file(),
            "Live Photo smoke input is missing: {input:?}"
        );
        let output_dir = isolated_smoke_dir("gifp-live-photo-user-material");
        fs::create_dir_all(&output_dir).expect("create Live Photo smoke output directory");

        let mut request = request_with_speed(1.0);
        request.input_path = input.to_string_lossy().to_string();
        request.output_dir = output_dir.to_string_lossy().to_string();
        request.output_format = "live_photo".to_string();
        request.generation_mode = "fast_gif".to_string();
        request.filter_style = "none".to_string();
        request.width = 320;
        request.fps = 12;
        let result = convert_animation_inner(request).expect("encode a real Live Photo pair");
        let bundle = PathBuf::from(&result.output_path);
        let live = result.live_photo.as_ref().expect("Live Photo report");

        assert_eq!(result.output_format, "live_photo", "{result:?}");
        assert!(bundle.is_dir(), "{result:?}");
        assert_eq!(
            bundle.extension().and_then(|value| value.to_str()),
            Some("pvt")
        );
        assert_eq!(live.compatibility_status, "locally_verified");
        assert_eq!(live.validation_scope, "local_contract");
        assert!(live.asset_identifier_verified && live.metadata_pairing_verified);
        let asset_identifier = live.asset_identifier.as_deref().expect("asset identifier");
        let report = verify_live_photo_pair(
            Path::new(&live.still_path),
            Path::new(&live.motion_path),
            asset_identifier,
        )
        .expect("verify published Live Photo resources again");
        assert!(report.pair_verified);
        assert_eq!(report.contract_sha256, live.contract_sha256);

        let mut resource_names = fs::read_dir(&bundle)
            .expect("read PVT resources")
            .map(|entry| {
                entry
                    .expect("read PVT resource")
                    .file_name()
                    .to_string_lossy()
                    .to_string()
            })
            .collect::<Vec<_>>();
        resource_names.sort();
        assert_eq!(
            resource_names.len(),
            3,
            "unexpected PVT resources: {resource_names:?}"
        );
        assert!(resource_names.iter().any(|name| name.ends_with(".JPG")));
        assert!(resource_names.iter().any(|name| name.ends_with(".MOV")));
        assert!(resource_names.iter().any(|name| name == "metadata.plist"));
        assert!(
            fs::read_dir(&output_dir)
                .expect("read Live Photo output directory")
                .filter_map(Result::ok)
                .all(|entry| !entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with(".gifp-live-stage-")),
            "Live Photo left a staging directory"
        );

        let _ = fs::remove_dir_all(output_dir);
    }

