    #[test]
    fn real_hard_cap_rejection_cleans_candidates_without_publishing_output() {
        let temp_scope = TestTempDirScope::begin();
        let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("workspace root")
            .to_path_buf();
        let input = std::env::var_os("GIFP_HARD_CAP_GUARD_INPUT")
            .map(PathBuf::from)
            .unwrap_or_else(|| root.join("public/preset-previews/perceptual.gif"));
        assert!(
            input.is_file(),
            "hard-cap guard input is missing: {input:?}"
        );
        let output_dir = isolated_smoke_dir("gifp-hard-cap-publish-guard");
        fs::create_dir_all(&output_dir).expect("create hard-cap guard output directory");
        let sentinel = output_dir.join("existing-output.gif");
        let sentinel_bytes = b"existing output must survive";
        fs::write(&sentinel, sentinel_bytes).expect("write existing output sentinel");

        let mut request = request_with_speed(1.0);
        request.input_path = input.to_string_lossy().to_string();
        request.output_dir = output_dir.to_string_lossy().to_string();
        request.width = 320;
        request.fps = 12;
        request.colors = 96;
        request.end_seconds = 1.5;
        request.generation_mode = "target_size".to_string();
        request.target_size_bytes = Some(1024);
        request.target_max_attempts = 1;
        request.target_constraint = "hard_cap".to_string();
        request.encoder = "ffmpeg_fast".to_string();

        let error = convert_animation_inner(request)
            .expect_err("a hard-cap miss must not publish an oversized output");
        let message = error.to_string();
        assert!(message.contains("no output was published"), "{message}");
        assert!(message.contains("within this search budget"), "{message}");
        assert_eq!(
            fs::read(&sentinel).expect("read existing output sentinel"),
            sentinel_bytes
        );
        assert_eq!(
            fs::read_dir(&output_dir)
                .expect("read guarded output directory")
                .filter_map(Result::ok)
                .count(),
            1,
            "hard-cap failure published an unexpected output"
        );
        temp_scope.assert_clean(
            "gifp-target-",
            "hard-cap failure leaked a target candidate directory",
        );

        let _ = fs::remove_dir_all(&output_dir);
    }

    #[test]
    fn real_target_size_orchestrator_smoke() {
        let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("workspace root")
            .to_path_buf();
        let input = root.join("public/preset-previews/perceptual.gif");
        let output_dir = isolated_smoke_dir("gifp-target-smoke");
        fs::create_dir_all(&output_dir).expect("create target smoke output directory");

        let mut request = request_with_speed(1.0);
        request.input_path = input.to_string_lossy().to_string();
        request.output_dir = output_dir.to_string_lossy().to_string();
        request.width = 320;
        request.fps = 12;
        request.colors = 96;
        request.generation_mode = "target_size".to_string();
        request.target_size_bytes = Some(256 * 1024);
        request.target_max_attempts = 6;
        request.encoder = "ffmpeg_fast".to_string();

        let result = convert_animation_inner(request).expect("run real target-size search");
        assert!(result.attempts >= 1 && result.attempts <= 6);
        assert!(result.size_bytes > 10_000);
        assert_eq!(result.backend_id, "ffmpeg.animation");
        assert!(result.palette_report.is_none(), "{result:?}");
        assert_eq!(result.target_size_bytes, Some(256 * 1024));
        assert!(result.size_bytes >= (256 * 1024 * 95 / 100), "{result:?}");
        assert!(result.size_bytes <= 256 * 1024, "{result:?}");
        assert!(matches!(
            result.status.as_str(),
            "target_exact" | "target_under"
        ));
        let optimizer = result
            .target_optimizer_report
            .as_ref()
            .unwrap_or_else(|| panic!("target optimizer report: {result:?}"));
        assert_eq!(optimizer.optimizer_id, "gifp.target_size.pareto.v6");
        assert_eq!(optimizer.constraint, "hard_cap");
        assert_eq!(optimizer.preference, "balanced");
        assert_eq!(
            optimizer.observations.len(),
            usize::from(optimizer.numeric_attempt_count)
        );
        assert!((3..=4).contains(&optimizer.route_attempt_count));
        assert_eq!(
            optimizer.route_observations.len(),
            usize::from(optimizer.route_attempt_count) + 1
        );
        assert_eq!(
            result.attempts,
            optimizer.numeric_attempt_count + optimizer.route_attempt_count
        );
        assert_eq!(optimizer.selected_route_id, "baseline");
        let timeline_route = optimizer
            .route_observations
            .iter()
            .find(|route| route.route_id == "perceptual_timeline")
            .unwrap_or_else(|| panic!("missing timeline route: {optimizer:?}"));
        assert_eq!(timeline_route.status, "encoded", "{optimizer:?}");
        assert!(timeline_route.timeline_verified, "{optimizer:?}");
        assert!(timeline_route.kept_frame_count.is_some(), "{optimizer:?}");
        assert_eq!(
            optimizer
                .route_observations
                .iter()
                .filter(|route| route.selected)
                .count(),
            1
        );
        assert_eq!(
            optimizer
                .observations
                .iter()
                .filter(|observation| observation.selected)
                .count(),
            1
        );
        assert!(
            optimizer
                .observations
                .iter()
                .any(
                    |observation| observation.attempt == optimizer.selected_attempt
                        && observation.selected
                        && observation.pareto_frontier
                ),
            "{optimizer:?}"
        );
        assert_eq!(optimizer.recommendations.len(), 3, "{optimizer:?}");
        let _ = fs::remove_file(result.output_path);
    }

    #[test]
    fn real_target_portfolio_keeps_three_explicit_preferences_and_outputs() {
        let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .expect("workspace root")
            .to_path_buf();
        let input = root.join("public/preset-previews/perceptual.gif");
        let output_dir = isolated_smoke_dir("gifp-target-portfolio-smoke");
        fs::create_dir_all(&output_dir).expect("create target portfolio directory");
        let profiles = [
            ("clarity", 320, 8, 128, 256 * 1024),
            ("smoothness", 240, 15, 96, 256 * 1024),
            ("smallest", 200, 6, 56, 184 * 1024),
        ];
        let mut results = Vec::new();

        for (preference, width, fps, colors, target) in profiles {
            let mut request = request_with_speed(1.0);
            request.input_path = input.to_string_lossy().to_string();
            request.output_dir = output_dir.to_string_lossy().to_string();
            request.width = width;
            request.fps = fps;
            request.colors = colors;
            request.generation_mode = "target_size".to_string();
            request.target_size_bytes = Some(target);
            request.target_max_attempts = 6;
            request.target_preference = preference.to_string();
            request.encoder = "ffmpeg_fast".to_string();

            let result = convert_animation_inner(request)
                .unwrap_or_else(|error| panic!("encode {preference} target candidate: {error}"));
            assert!(result.size_bytes <= target, "{preference}: {result:?}");
            let report = result
                .target_optimizer_report
                .as_ref()
                .unwrap_or_else(|| panic!("missing {preference} report: {result:?}"));
            assert_eq!(report.preference, preference);
            let timeline_route = report
                .route_observations
                .iter()
                .find(|route| route.route_id == "perceptual_timeline")
                .unwrap_or_else(|| panic!("missing {preference} timeline: {report:?}"));
            assert_eq!(timeline_route.status, "encoded", "{report:?}");
            assert!(timeline_route.timeline_verified, "{report:?}");
            let selected_route = report
                .route_observations
                .iter()
                .find(|route| route.selected)
                .unwrap_or_else(|| panic!("missing selected {preference} route: {report:?}"));
            match preference {
                "clarity" => {
                    let corrected_is_feasible = report.route_observations.iter().any(|route| {
                        route.route_id == "perceptual_reinvest_corrected" && route.under_target
                    });
                    let reinvest_is_feasible = report
                        .route_observations
                        .iter()
                        .any(|route| route.route_id == "perceptual_reinvest" && route.under_target);
                    let sierra_is_feasible = report
                        .route_observations
                        .iter()
                        .any(|route| route.route_id == "sierra_quality" && route.under_target);
                    assert_eq!(
                        selected_route.route_id,
                        if corrected_is_feasible {
                            "perceptual_reinvest_corrected"
                        } else if reinvest_is_feasible {
                            "perceptual_reinvest"
                        } else if sierra_is_feasible {
                            "sierra_quality"
                        } else {
                            "baseline"
                        },
                        "{report:?}"
                    );
                }
                "smoothness" => assert_eq!(selected_route.route_id, "baseline", "{report:?}"),
                "smallest" => assert_eq!(
                    selected_route.size_bytes,
                    report
                        .route_observations
                        .iter()
                        .filter_map(|route| route.size_bytes)
                        .min(),
                    "{report:?}"
                ),
                _ => unreachable!(),
            }
            results.push(result);
        }

        assert!(
            results.iter().enumerate().all(|(index, result)| results
                .iter()
                .skip(index + 1)
                .all(|other| result.output_path != other.output_path)),
            "portfolio outputs collided: {results:?}"
        );
        assert_eq!(
            results
                .iter()
                .map(|result| (result.output_width, result.output_fps, result.output_colors))
                .collect::<std::collections::HashSet<_>>()
                .len(),
            3,
            "portfolio parameters did not diverge: {results:?}"
        );

        for result in results {
            let _ = fs::remove_file(result.output_path);
        }
        let _ = fs::remove_dir_all(output_dir);
    }

