        let result = convert_animation_inner(request).expect("encode target timeline fixture");
        let optimizer = result
            .target_optimizer_report
            .as_ref()
            .unwrap_or_else(|| panic!("missing target timeline report: {result:?}"));
        assert_eq!(
            optimizer.selected_route_id, "perceptual_timeline",
            "{optimizer:?}"
        );
        let route = optimizer
            .route_observations
            .iter()
            .find(|route| route.selected)
            .unwrap_or_else(|| panic!("missing selected target timeline: {optimizer:?}"));
        assert!(route.timeline_verified, "{optimizer:?}");
        assert!(
            route.dropped_frame_count.is_some_and(|count| count > 0),
            "{optimizer:?}"
        );
        let perceptual = result
            .perceptual_report
            .as_ref()
            .unwrap_or_else(|| panic!("missing promoted perceptual report: {result:?}"));
        assert!(perceptual.aggregate_timeline_verified, "{result:?}");
        assert_eq!(result.backend_id, "rust.perceptual", "{result:?}");
        assert_eq!(
            result.output_frame_count,
            u64::from(perceptual.kept_frame_count),
            "{result:?}"
        );

        let _ = fs::remove_file(result.output_path);

        let mut clarity_request = request_with_speed(1.0);
        clarity_request.input_path = input.to_string_lossy().to_string();
        clarity_request.output_dir = output_dir.to_string_lossy().to_string();
