    #[test]
    fn local_template_tracker_follows_a_shifted_pattern() {
        let frame_width = 64;
        let frame_height = 48;
        let box_width = 12;
        let box_height = 10;
        let mut first = vec![0_u8; frame_width * frame_height];
        let mut shifted = vec![0_u8; frame_width * frame_height];
        for row in 0..box_height {
            for column in 0..box_width {
                let value = 30 + ((row * 31 + column * 17 + row * column * 3) % 210) as u8;
                first[(8 + row) * frame_width + 10 + column] = value;
                shifted[(13 + row) * frame_width + 17 + column] = value;
            }
        }
        let template = copy_gray_patch(&first, frame_width, 10, 8, box_width, box_height);
        let (x, y, confidence) = track_gray_patch(
            &template,
            &shifted,
            (frame_width, frame_height),
            10,
            8,
            box_width,
            box_height,
        );
        assert!(
            (x as isize - 17).abs() <= 1,
            "x={x}, confidence={confidence}"
        );
        assert!(
            (y as isize - 13).abs() <= 1,
            "y={y}, confidence={confidence}"
        );
        assert!(confidence >= 0.95, "confidence={confidence}");
    }

    #[test]
    fn tracked_labels_build_moving_ass_and_reserve_semantic_colors() {
        let label = tracked_effect_fixture("label", "订单 {A}\\B");
        let ass = build_tracked_overlay_ass(std::slice::from_ref(&label), (420, 236));
        assert!(ass.contains(r"\move("), "{ass}");
        assert!(ass.contains(r"订单 \{A\}\\B"), "{ass}");
        let anchors = tracked_effect_palette_anchors(&[
            label,
            tracked_effect_fixture("highlight", ""),
            tracked_effect_fixture("blackout", ""),
        ]);
        assert!(anchors.contains(&[67, 181, 175]));
        assert!(anchors.contains(&[242, 200, 106]));
        assert!(anchors.contains(&[0, 0, 0]));
    }

