        assert_eq!(tracking_sample_fps_for_range(20.0, 8, 240).unwrap(), 8);
        assert_eq!(tracking_sample_fps_for_range(60.0, 8, 240).unwrap(), 4);
        assert_eq!(tracking_sample_fps_for_range(120.0, 8, 240).unwrap(), 2);
